CREATE OR REPLACE FUNCTION truss.runtime_admit_operation(issued_ordinal bigint, kind text, definition_bytes bytea, input_bytes bytea, prestate_bytes bytea, candidate_bytes bytea, obligation_bytes bytea, group_bytes bytea)
 RETURNS TABLE(writer_xid text, ordinal text, context_hex text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  native_xid xid8;
  head_revision int;
  next_ordinal bigint;
  native_context bytea;
  item bytea;
  total_bytes bigint := 0;
BEGIN
  IF issued_ordinal IS NULL OR issued_ordinal < 0 THEN
    RAISE EXCEPTION 'invalid host-issued operation ordinal' USING ERRCODE='22023';
  END IF;
  -- This component observes at an invoker boundary. Never capture a nested
  -- definer owner as the selected operation actor. Full role OID/grammar and
  -- original public-entry custody remain separately qualified obligations.
  IF current_user::text IS DISTINCT FROM (CASE
      WHEN current_setting('role')='none' THEN session_user::text
      ELSE current_setting('role') END) THEN
    RAISE EXCEPTION 'original invoker actor boundary required' USING ERRCODE='55000';
  END IF;
  IF kind IS NULL OR kind NOT IN ('mutation','import','catalog-transform',
       'catalog-acceptance','home-migration','administrative-repair') THEN
    RAISE EXCEPTION 'unsupported operation kind' USING ERRCODE='22023';
  END IF;
  FOREACH item IN ARRAY ARRAY[definition_bytes,input_bytes,prestate_bytes,
      candidate_bytes,obligation_bytes,group_bytes] LOOP
    IF item IS NULL OR octet_length(item) NOT BETWEEN 1 AND 1048576 THEN
      RAISE EXCEPTION 'original artifact bound' USING ERRCODE='22023';
    END IF;
    total_bytes := total_bytes + octet_length(item);
  END LOOP;
  IF total_bytes > 4194304 THEN
    RAISE EXCEPTION 'operation artifact aggregate bound' USING ERRCODE='54000';
  END IF;
  -- Catalog exclusion precedes operation-registry and business locks.
  -- Never upgrade an earlier shared head admission in this internal profile.
  IF kind='catalog-acceptance' THEN
    IF EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.granted
        AND l.relation='truss.schema_head'::regclass AND l.mode IN ('RowShareLock','RowExclusiveLock'))
        AND NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.granted
          AND l.relation='truss.schema_head'::regclass AND l.mode IN ('ExclusiveLock','AccessExclusiveLock')) THEN
      RAISE EXCEPTION 'earlier shared head admission cannot upgrade to catalog exclusion' USING ERRCODE='55000';
    END IF;
    LOCK TABLE truss.schema_head IN EXCLUSIVE MODE;
  END IF;
  SELECT h.rev INTO STRICT head_revision FROM truss.schema_head h WHERE h.id=1 FOR SHARE;
  native_xid := pg_current_xact_id();
  IF EXISTS (SELECT 1 FROM truss.row_home_operation AS o
      WHERE o.original_writer_xid=native_xid AND o.phase<>'application_finalized') THEN
    RAISE EXCEPTION 'unfinished operation' USING ERRCODE='55000';
  END IF;
  -- Host custody owns nonreuse across rolled-back attempts (ADR-008).
  -- Native state independently rejects conflicts with surviving operations.
  IF EXISTS (SELECT 1 FROM truss.row_home_operation AS o
      WHERE o.original_writer_xid=native_xid AND o.operation_ordinal >= issued_ordinal) THEN
    RAISE EXCEPTION 'host-issued ordinal conflicts with surviving operation' USING ERRCODE='55000';
  END IF;
  next_ordinal := issued_ordinal;
  native_context := convert_to(jsonb_build_object(
    'interfaceVersion','truss-native-operation-context/0.2',
    'xid',native_xid::text,'ordinal',next_ordinal::text,
    'sessionUser',session_user::text,'actingUser',current_user::text,
    'actorRoleOid',(SELECT r.oid::text FROM pg_catalog.pg_roles r WHERE r.rolname=current_user),
    'sessionRoleOid',(SELECT r.oid::text FROM pg_catalog.pg_roles r WHERE r.rolname=session_user),
    'database',current_database(),'backendPid',pg_backend_pid()::text
  )::text,'UTF8');
  INSERT INTO truss.row_home_operation(original_writer_xid,operation_ordinal,
    operation_kind,phase,effect_generation,original_context_bytes,
    original_definition_bytes,original_input_bytes,original_prestate_bytes,
    admitted_candidate_bytes,effect_obligation_bytes,original_group_custody_bytes)
  VALUES(native_xid,next_ordinal,kind,'admitted',0,native_context,
    definition_bytes,input_bytes,prestate_bytes,candidate_bytes,obligation_bytes,group_bytes);
  RETURN QUERY SELECT native_xid::text,next_ordinal::text,encode(native_context,'hex');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_admit_operation_with_configuration_context(issued_ordinal bigint, kind text, definition_bytes bytea, input_bytes bytea, prestate_bytes bytea, candidate_bytes bytea, obligation_bytes bytea, group_bytes bytea, asserted_bytes bytea, capture_profile_bytes bytea, expected_installation text, expected_epoch text, expected_incarnation text, configuration_profile_bytes bytea)
 RETURNS TABLE(writer_xid text, ordinal text, context_hex text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  native_xid xid8;
  head_revision int;
  next_ordinal bigint;
  native_context bytea;
  epoch_capture record;
  configuration_sizes record;
  captured_configuration truss.installation_admission%ROWTYPE;
  item bytea;
  total_bytes bigint := 0;
BEGIN
  IF issued_ordinal IS NULL OR issued_ordinal < 0 THEN
    RAISE EXCEPTION 'invalid host-issued operation ordinal' USING ERRCODE='22023';
  END IF;
  -- This component observes at an invoker boundary. Never capture a nested
  -- definer owner as the selected operation actor. Full role OID/grammar and
  -- original public-entry custody remain separately qualified obligations.
  IF current_user::text IS DISTINCT FROM (CASE
      WHEN current_setting('role')='none' THEN session_user::text
      ELSE current_setting('role') END) THEN
    RAISE EXCEPTION 'original invoker actor boundary required' USING ERRCODE='55000';
  END IF;
  IF kind IS NULL OR kind NOT IN ('mutation','import','catalog-transform',
       'catalog-acceptance','home-migration','administrative-repair') THEN
    RAISE EXCEPTION 'unsupported operation kind' USING ERRCODE='22023';
  END IF;
  IF asserted_bytes IS NULL OR octet_length(asserted_bytes) NOT BETWEEN 1 AND 131072
    OR capture_profile_bytes IS NULL OR octet_length(capture_profile_bytes) NOT BETWEEN 1 AND 65536 THEN
    RAISE EXCEPTION 'original asserted capture bounds' USING ERRCODE='22023';
  END IF;
  FOREACH item IN ARRAY ARRAY[definition_bytes,input_bytes,prestate_bytes,
      candidate_bytes,obligation_bytes,group_bytes,asserted_bytes,capture_profile_bytes] LOOP
    IF item IS NULL OR octet_length(item) NOT BETWEEN 1 AND 1048576 THEN
      RAISE EXCEPTION 'original artifact bound' USING ERRCODE='22023';
    END IF;
    total_bytes := total_bytes + octet_length(item);
  END LOOP;
  IF total_bytes > 4194304 THEN
    RAISE EXCEPTION 'operation artifact aggregate bound' USING ERRCODE='54000';
  END IF;
  -- Lock/observe original current epoch before catalog/business admission.
  -- Expected values compare facts; trusted deployment admission is separate.
  SELECT * INTO STRICT epoch_capture FROM truss.runtime_lock_source_epoch(
    expected_installation,expected_epoch,expected_incarnation);
  total_bytes := total_bytes + (octet_length(epoch_capture.profile_hex)+octet_length(epoch_capture.evidence_hex))/2;
  IF total_bytes>4194304 THEN
    RAISE EXCEPTION 'original epoch artifact aggregate bound' USING ERRCODE='54000';
  END IF;
  -- Catalog exclusion precedes operation-registry and business locks.
  -- Never upgrade an earlier shared head admission in this internal profile.
  IF kind='catalog-acceptance' THEN
    IF EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.granted
        AND l.relation='truss.schema_head'::regclass AND l.mode IN ('RowShareLock','RowExclusiveLock'))
        AND NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.granted
          AND l.relation='truss.schema_head'::regclass AND l.mode IN ('ExclusiveLock','AccessExclusiveLock')) THEN
      RAISE EXCEPTION 'earlier shared head admission cannot upgrade to catalog exclusion' USING ERRCODE='55000';
    END IF;
    LOCK TABLE truss.schema_head IN EXCLUSIVE MODE;
  END IF;
  SELECT h.rev INTO STRICT head_revision FROM truss.schema_head h WHERE h.id=1 FOR SHARE;
  IF configuration_profile_bytes IS NULL OR octet_length(configuration_profile_bytes) NOT BETWEEN 1 AND 65536 THEN
    RAISE EXCEPTION 'original configuration profile bounds' USING ERRCODE='22023';
  END IF;
  SELECT octet_length(a.configuration_bytes)::bigint AS configuration,
    octet_length(a.selected_binding_bytes)::bigint AS binding,
    octet_length(a.installed_inventory_bytes)::bigint AS inventory
    INTO configuration_sizes FROM truss.installation_admission a WHERE a.head_id=1;
  IF NOT FOUND OR configuration_sizes.configuration<1 OR configuration_sizes.binding<1
    OR configuration_sizes.inventory<1 OR configuration_sizes.configuration+configuration_sizes.binding+configuration_sizes.inventory>16777216 THEN
    RAISE EXCEPTION 'original pre-effect configuration bounds' USING ERRCODE='55000';
  END IF;
  total_bytes:=total_bytes+configuration_sizes.configuration+configuration_sizes.binding+configuration_sizes.inventory+octet_length(configuration_profile_bytes);
  IF total_bytes>20971520 THEN
    RAISE EXCEPTION 'configuration operation aggregate bounds' USING ERRCODE='54000';
  END IF;
  SELECT a.* INTO STRICT captured_configuration FROM truss.installation_admission a WHERE a.head_id=1;
  IF captured_configuration.installation_id_utf8 IS DISTINCT FROM convert_to(epoch_capture.installation_id,'UTF8')
    OR captured_configuration.source_epoch_utf8 IS DISTINCT FROM convert_to(epoch_capture.source_epoch,'UTF8')
    OR captured_configuration.configuration_generation<0
    OR captured_configuration.key_reuse NOT IN ('forbid','allow')
    OR captured_configuration.journal_mode NOT IN ('engine','trigger') THEN
    RAISE EXCEPTION 'original pre-effect configuration correspondence' USING ERRCODE='55000';
  END IF;
  native_xid := pg_current_xact_id();
  IF EXISTS (SELECT 1 FROM truss.row_home_operation AS o
      WHERE o.original_writer_xid=native_xid AND o.phase<>'application_finalized') THEN
    RAISE EXCEPTION 'unfinished operation' USING ERRCODE='55000';
  END IF;
  -- Host custody owns nonreuse across rolled-back attempts (ADR-008).
  -- Native state independently rejects conflicts with surviving operations.
  IF EXISTS (SELECT 1 FROM truss.row_home_operation AS o
      WHERE o.original_writer_xid=native_xid AND o.operation_ordinal >= issued_ordinal) THEN
    RAISE EXCEPTION 'host-issued ordinal conflicts with surviving operation' USING ERRCODE='55000';
  END IF;
  next_ordinal := issued_ordinal;
  native_context := convert_to(jsonb_build_object(
    'interfaceVersion','truss-native-operation-context/0.4',
    'xid',native_xid::text,'ordinal',next_ordinal::text,
    'sessionUser',session_user::text,'actingUser',current_user::text,
    'actorRoleOid',(SELECT r.oid::text FROM pg_catalog.pg_roles r WHERE r.rolname=current_user),
    'sessionRoleOid',(SELECT r.oid::text FROM pg_catalog.pg_roles r WHERE r.rolname=session_user),
    'database',current_database(),'backendPid',pg_backend_pid()::text,
    'assertedOriginUtf8Hex',encode(asserted_bytes,'hex'),
    'assertedOriginCaptureProfileHex',encode(capture_profile_bytes,'hex'),
    'installationId',epoch_capture.installation_id,'sourceEpoch',epoch_capture.source_epoch,
    'targetIncarnation',epoch_capture.target_incarnation,
    'sourceEpochProfileHex',epoch_capture.profile_hex,
    'sourceEpochEvidenceHex',epoch_capture.evidence_hex
  )::text,'UTF8');
  IF octet_length(native_context)>1048576 THEN
    RAISE EXCEPTION 'original encoded context bound' USING ERRCODE='54000';
  END IF;
  IF total_bytes+octet_length(native_context)>20971520 THEN
    RAISE EXCEPTION 'configuration encoded operation aggregate bounds' USING ERRCODE='54000';
  END IF;
  INSERT INTO truss.row_home_operation(original_writer_xid,operation_ordinal,
    operation_kind,phase,effect_generation,original_context_bytes,
    original_definition_bytes,original_input_bytes,original_prestate_bytes,
    admitted_candidate_bytes,effect_obligation_bytes,original_group_custody_bytes)
  VALUES(native_xid,next_ordinal,kind,'admitted',0,native_context,
    definition_bytes,input_bytes,prestate_bytes,candidate_bytes,obligation_bytes,group_bytes);
  INSERT INTO truss.operation_configuration(original_writer_xid,operation_ordinal,
    installation_id,source_epoch,target_incarnation,configuration_generation,
    key_reuse,journal_mode,original_context_sha256,admission_profile_bytes,
    configuration_bytes,selected_binding_bytes,installed_inventory_bytes)
  VALUES(native_xid,next_ordinal,epoch_capture.installation_id,epoch_capture.source_epoch,
    epoch_capture.target_incarnation,captured_configuration.configuration_generation,
    captured_configuration.key_reuse,captured_configuration.journal_mode,sha256(native_context),
    configuration_profile_bytes,captured_configuration.configuration_bytes,
    captured_configuration.selected_binding_bytes,captured_configuration.installed_inventory_bytes);
  RETURN QUERY SELECT native_xid::text,next_ordinal::text,encode(native_context,'hex');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_canonical_string_bytes(original bytea)
 RETURNS bytea
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE validated bytea:=original; chunk bytea:=decode('22','hex'); chunks bytea[]:=ARRAY[]::bytea[];
 output bytea; piece bytea; expected bigint:=2; n int; i int; b int;
BEGIN
 IF original IS NULL THEN
  RAISE EXCEPTION 'bounded original string bytes required' USING ERRCODE='22023';
 END IF;
 IF octet_length(original)>65536 THEN RAISE EXCEPTION 'string source capacity' USING ERRCODE='54000'; END IF;
 n:=octet_length(original);
 -- PostgreSQL text excludes NUL. Replace only NUL in a validation copy; output
 -- below consumes original bytes and escapes every control, including NUL.
 IF n>0 THEN
  FOR i IN 0..n-1 LOOP
   b:=get_byte(original,i);
   expected:=expected+CASE WHEN b<32 THEN 6 WHEN b IN (34,92) THEN 2 ELSE 1 END;
   IF b=0 THEN validated:=set_byte(validated,i,32); END IF;
  END LOOP;
 END IF;
 PERFORM convert_from(validated,'UTF8');
 IF n>0 THEN
  FOR i IN 0..n-1 LOOP
   b:=get_byte(original,i);
   IF b<32 THEN piece:=convert_to(chr(92)||'u00'||lpad(to_hex(b),2,'0'),'UTF8');
   ELSIF b IN (34,92) THEN piece:=decode('5c','hex')||substr(original,i+1,1);
   ELSE piece:=substr(original,i+1,1); END IF;
   IF octet_length(chunk)+octet_length(piece)>65536 THEN
    chunks:=array_append(chunks,chunk); chunk:=decode('','hex');
   END IF;
   chunk:=chunk||piece;
  END LOOP;
 END IF;
 IF octet_length(chunk)=65536 THEN chunks:=array_append(chunks,chunk);chunk:=decode('','hex'); END IF;
 chunks:=array_append(chunks,chunk||decode('22','hex'));
 SELECT string_agg(value,decode('','hex') ORDER BY ordinal) INTO output FROM unnest(chunks) WITH ORDINALITY AS c(value,ordinal);
 IF octet_length(output)<>expected OR expected>393218 THEN
  RAISE EXCEPTION 'complete canonical string byte parity required' USING ERRCODE='55000';
 END IF;
 RETURN output;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_canonical_tree_bytes(tree jsonb)
 RETURNS bytea
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE tasks jsonb[]:=ARRAY[jsonb_build_object('node',tree,'depth','0')]; task jsonb;
 node jsonb; member jsonb; children jsonb; tag text; piece bytea; chunk bytea:=decode('','hex');
 chunks bytea[]:=ARRAY[]::bytea[]; output bytea; i int; depth int; steps int:=0; emitted bigint:=0;
BEGIN
 IF tree IS NULL THEN RAISE EXCEPTION 'inert tree required' USING ERRCODE='22023'; END IF;
 IF octet_length(tree::text)>4194304 THEN RAISE EXCEPTION 'tree input capacity' USING ERRCODE='54000'; END IF;
 WHILE cardinality(tasks)>0 LOOP
  steps:=steps+1;
  IF steps>32768 OR cardinality(tasks)>16384 THEN RAISE EXCEPTION 'tree task capacity' USING ERRCODE='54000'; END IF;
  task:=tasks[cardinality(tasks)];tasks:=tasks[1:cardinality(tasks)-1];piece:=decode('','hex');
  IF task ? 'emit' THEN piece:=decode(task->>'emit','hex');
  ELSIF task ? 'frame' THEN
   children:=task->'children';tag:=task->>'frame';i:=(task->>'index')::int;depth:=(task->>'depth')::int;
   IF i=jsonb_array_length(children) THEN piece:=decode(CASE WHEN tag='array' THEN '5d' ELSE '7d' END,'hex');
   ELSE
    member:=children->i;
    tasks:=array_append(tasks,jsonb_set(task,'{index}',to_jsonb((i+1)::text)));
    tasks:=array_append(tasks,jsonb_build_object('node',CASE WHEN tag='array' THEN member ELSE member->'node' END,'depth',(depth+1)::text));
    IF tag='object' THEN
     tasks:=array_append(tasks,jsonb_build_object('emit','3a'));
     tasks:=array_append(tasks,jsonb_build_object('node',jsonb_build_object('kind','string','utf8Hex',member->>'keyUtf8Hex'),'depth',(depth+1)::text));
    END IF;
    IF i>0 THEN piece:=decode('2c','hex'); END IF;
   END IF;
  ELSE
   node:=task->'node';depth:=(task->>'depth')::int;
   IF depth>256 THEN RAISE EXCEPTION 'tree depth capacity' USING ERRCODE='54000'; END IF;
   IF node IS NULL OR jsonb_typeof(node)<>'object' OR jsonb_typeof(node->'kind') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'inert node shape' USING ERRCODE='22023'; END IF;
   tag:=node->>'kind';
   IF tag='null' AND (SELECT count(*) FROM jsonb_object_keys(node))=1 THEN piece:=convert_to('null','UTF8');
   ELSIF tag='boolean' AND (SELECT count(*) FROM jsonb_object_keys(node))=2 AND jsonb_typeof(node->'value')='boolean' THEN piece:=convert_to(node->>'value','UTF8');
   ELSIF tag='string' AND (SELECT count(*) FROM jsonb_object_keys(node))=2 AND jsonb_typeof(node->'utf8Hex')='string' AND node->>'utf8Hex' ~ '^([0-9a-f]{2})*$' THEN piece:=truss.runtime_canonical_string_bytes(decode(node->>'utf8Hex','hex'));
   ELSIF tag IN ('array','object') AND (SELECT count(*) FROM jsonb_object_keys(node))=2 THEN
    children:=node->CASE WHEN tag='array' THEN 'items' ELSE 'members' END;
    IF jsonb_typeof(children) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'container inventory' USING ERRCODE='22023'; END IF;
    IF jsonb_array_length(children)>4096 THEN RAISE EXCEPTION 'container inventory capacity' USING ERRCODE='54000'; END IF;
    IF tag='object' THEN
     FOR member IN SELECT value FROM jsonb_array_elements(children) LOOP
      IF jsonb_typeof(member)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(member))<>2
       OR NOT member ?& ARRAY['keyUtf8Hex','node'] OR jsonb_typeof(member->'keyUtf8Hex') IS DISTINCT FROM 'string'
       OR member->>'keyUtf8Hex' !~ '^([0-9a-f]{2})*$' THEN RAISE EXCEPTION 'object member shape' USING ERRCODE='22023'; END IF;
      PERFORM truss.runtime_canonical_string_bytes(decode(member->>'keyUtf8Hex','hex'));
     END LOOP;
     IF (SELECT count(DISTINCT decode(value->>'keyUtf8Hex','hex')) FROM jsonb_array_elements(children))<>jsonb_array_length(children) THEN RAISE EXCEPTION 'duplicate original object key' USING ERRCODE='22023'; END IF;
     SELECT coalesce(jsonb_agg(value ORDER BY decode(value->>'keyUtf8Hex','hex')),'[]'::jsonb) INTO children FROM jsonb_array_elements(children);
    END IF;
    tasks:=array_append(tasks,jsonb_build_object('frame',tag,'children',children,'index','0','depth',depth::text));
    piece:=decode(CASE WHEN tag='array' THEN '5b' ELSE '7b' END,'hex');
   ELSE RAISE EXCEPTION 'unsupported inert node or extra content' USING ERRCODE='22023'; END IF;
  END IF;
  emitted:=emitted+octet_length(piece);
  IF emitted>4194304 THEN RAISE EXCEPTION 'complete tree output capacity' USING ERRCODE='54000'; END IF;
  WHILE octet_length(piece)>0 LOOP
   i:=least(65536-octet_length(chunk),octet_length(piece));chunk:=chunk||substr(piece,1,i);piece:=substr(piece,i+1);
   IF octet_length(chunk)=65536 THEN chunks:=array_append(chunks,chunk);chunk:=decode('','hex'); END IF;
  END LOOP;
 END LOOP;
 chunks:=array_append(chunks,chunk);
 SELECT string_agg(value,decode('','hex') ORDER BY ordinal) INTO output FROM unnest(chunks) WITH ORDINALITY AS c(value,ordinal);
 IF octet_length(output)<>emitted THEN RAISE EXCEPTION 'complete tree byte parity' USING ERRCODE='55000'; END IF;
 RETURN output;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_capture_catalog_finalizing_custody_candidate(w text, o text, g text, registration_identity text, original_registration bytea, lifecycle_policy bytea, index_policy bytea)
 RETURNS TABLE(writer_xid text, operation_ordinal text, effect_generation text, revision text, report_utf8_hex text, custody_record_hex text, scope text, accepted_report_qualified boolean, feed_qualified boolean)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO, YMD'
 SET "IntervalStyle" TO 'iso_8601'
 SET extra_float_digits TO '3'
 SET bytea_output TO 'hex'
 SET standard_conforming_strings TO 'on'
 SET quote_all_identifiers TO 'off'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; planned_op truss.row_home_operation%ROWTYPE;
 configuration truss.operation_configuration%ROWTYPE;
 revision_row truss.schema_rev%ROWTYPE; planned_report truss.catalog_acceptance_report%ROWTYPE;
 planned truss.catalog_revision_custody%ROWTYPE; returned truss.catalog_revision_custody%ROWTYPE;
 before_state jsonb; report_state jsonb; after_state jsonb; expected_state jsonb;
 produced record; profile bytea; profile_json jsonb; payload_profile bytea;
 original_documents bytea[]; document_record bytea; documents jsonb:='[]';
 original_configuration bytea; original_op bytea; original_revision bytea;
 original_bytes bigint; total_chunks bigint; context jsonb; clock_value timestamptz;
BEGIN
 PERFORM truss.runtime_require_catalog_finalization_composition_candidate(w,o,g);
 SELECT * INTO STRICT op FROM truss.row_home_operation t
  WHERE t.original_writer_xid=pg_current_xact_id_if_assigned() AND t.operation_ordinal::text=o FOR UPDATE;
 SELECT * INTO STRICT configuration FROM truss.operation_configuration t
  WHERE t.original_writer_xid=op.original_writer_xid AND t.operation_ordinal=op.operation_ordinal;
 context:=convert_from(op.original_context_bytes,'UTF8')::jsonb;
 IF EXISTS(SELECT 1 FROM truss.catalog_revision_custody) THEN
  RAISE EXCEPTION 'single original custody capture only' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT produced FROM truss.runtime_collect_custody_catalog_graph_candidate();
 before_state:=truss.runtime_capture_finalizing_completion_state_candidate(w,o,g);
 original_configuration:=record_send(configuration);
 -- Closure admission selects these originals from retained installation inventory.
 SELECT a.artifact_bytes INTO STRICT profile FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input'
   AND a.artifact_identity='packages/python/src/truss/_profiles/catalog-prerequisite-custody-capture-candidate.json';
 profile_json:=convert_from(profile,'UTF8')::jsonb;
 SELECT a.artifact_bytes INTO STRICT payload_profile FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input'
   AND a.artifact_identity=profile_json->'payloadProfile'->>'path';
 SELECT * INTO STRICT produced FROM truss.runtime_write_custody_catalog_report_candidate(
  w,o,g,registration_identity,original_registration,lifecycle_policy,index_policy);
 IF produced.writer_xid IS DISTINCT FROM w OR produced.operation_ordinal IS DISTINCT FROM o
  OR produced.effect_generation IS DISTINCT FROM (op.effect_generation+1)::text
  OR produced.scope IS DISTINCT FROM 'administrative_rollback_only_report_write'
  OR produced.accepted_report_qualified IS DISTINCT FROM false
  OR produced.report_utf8_hex IS NULL OR produced.revision_payload_utf8_hex IS NULL THEN
  RAISE EXCEPTION 'original report producer result required' USING ERRCODE='55000'; END IF;
 planned:=NULL;planned.original_writer_xid:=op.original_writer_xid;
 planned.operation_ordinal:=op.operation_ordinal;
 planned.capture_generation:=op.effect_generation+1;
 planned.original_revision:=(convert_from(decode(produced.revision_payload_utf8_hex,'hex'),'UTF8')::jsonb->>'revision')::int;
 planned_report.rev:=planned.original_revision;
 planned_report.report_bytes:=decode(produced.report_utf8_hex,'hex');
 planned_op:=op;planned_op.effect_generation:=planned.capture_generation;
 report_state:=truss.runtime_capture_finalizing_completion_state_candidate(w,o,produced.effect_generation);
 expected_state:=jsonb_set(before_state,'{stores,catalog_acceptance_report}',jsonb_build_array(encode(record_send(planned_report),'hex')));
 expected_state:=jsonb_set(expected_state,'{stores,row_home_operation}',jsonb_build_array(encode(record_send(planned_op),'hex')));
 IF report_state IS DISTINCT FROM expected_state THEN
