   'defaults',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.adnum),'[]'::jsonb) FROM pg_attrdef a WHERE a.adrelid=oid_value),
   'constraints',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.oid),'[]'::jsonb) FROM pg_constraint a WHERE a.conrelid=oid_value),
   'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_object('index',to_jsonb(a),'relation',to_jsonb(ic),'definition',pg_get_indexdef(a.indexrelid)) ORDER BY a.indexrelid),'[]'::jsonb) FROM pg_index a JOIN pg_class ic ON ic.oid=a.indexrelid WHERE a.indrelid=oid_value),
   'rules',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.oid),'[]'::jsonb) FROM pg_rewrite a WHERE a.ev_class=oid_value),
   'policies',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.oid),'[]'::jsonb) FROM pg_policy a WHERE a.polrelid=oid_value),
   'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('trigger',to_jsonb(a),'procedure',to_jsonb(p),'function',pg_get_functiondef(a.tgfoid)) ORDER BY a.oid),'[]'::jsonb) FROM pg_trigger a JOIN pg_proc p ON p.oid=a.tgfoid WHERE a.tgrelid=oid_value))
   INTO descriptor FROM pg_class c WHERE c.oid=oid_value;
  descriptors:=jsonb_set(descriptors,ARRAY[name],descriptor);
  IF octet_length(stores::text)+octet_length(descriptors::text)>33554432 THEN
   RAISE EXCEPTION 'configured completion retention capacity' USING ERRCODE='54000'; END IF;
 END LOOP;
 result:=jsonb_build_object('stores',stores,'descriptors',descriptors,'resources',resources,'metadataHex',encode(metadata,'hex'),
  'relations',(SELECT jsonb_agg(to_jsonb(c) ORDER BY c.oid) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='truss'),
  'routines',(SELECT jsonb_agg(jsonb_build_object('procedure',to_jsonb(p),'definition',pg_get_functiondef(p.oid)) ORDER BY p.oid) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='truss' AND p.prokind IN ('f','p')),
  'namespace',(SELECT to_jsonb(n) FROM pg_namespace n WHERE n.nspname='truss'),
  'inheritance',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.inhrelid,i.inhseqno),'[]'::jsonb) FROM pg_inherits i
   WHERE i.inhparent IN (SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='truss')
    OR i.inhrelid IN (SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='truss')));
 PERFORM truss.runtime_require_catalog_observation(w,o,g);
 PERFORM truss.runtime_require_operation_configuration_current(w,o,g);
 PERFORM truss.runtime_require_selected_archive_write_fence();
 IF octet_length(result::text)>33554432 THEN RAISE EXCEPTION 'configured completion total capacity' USING ERRCODE='54000'; END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_catalog_lineage(revision integer, category text, document_id text, module_id text, element_id text)
 RETURNS bytea
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE matches bigint;
BEGIN
 PERFORM truss.runtime_verify_catalog_document(revision,document_id);
 IF category='record' THEN
  SELECT count(*) INTO matches FROM truss.schema_doc d
   CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') m
   CROSS JOIN LATERAL jsonb_array_elements(m.value->'elements') e
   WHERE d.rev=revision AND d.doc_id=document_id AND m.value->>'id'=module_id
    AND e.value->>'id'=element_id AND e.value->>'kind'='record';
 ELSIF category='authored' THEN
  SELECT count(*) INTO matches FROM truss.schema_doc d
   CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') m
   CROSS JOIN LATERAL jsonb_array_elements(m.value->'relationships') e
   WHERE d.rev=revision AND d.doc_id=document_id AND m.value->>'id'=module_id AND e.value->>'id'=element_id;
 ELSE RAISE EXCEPTION 'unsupported lineage category' USING ERRCODE='22023'; END IF;
 IF matches<>1 THEN RAISE EXCEPTION 'unique original declaration required' USING ERRCODE='55000'; END IF;
 RETURN truss.runtime_lineage_bytes(category,document_id,module_id,element_id);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_catalog_report_map_origin_tree(original jsonb, depth integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result jsonb; children jsonb:='[]'::jsonb; child jsonb; mapped jsonb;
BEGIN
 IF original IS NULL OR depth IS NULL OR depth<0 OR depth>128 THEN RAISE EXCEPTION 'bounded tagged origin required' USING ERRCODE='22023'; END IF;
 CASE original->>'kind'
 WHEN 'null' THEN RETURN truss.runtime_catalog_report_native_tree(jsonb_build_object('kind','null'));
 WHEN 'boolean' THEN RETURN truss.runtime_catalog_report_native_tree(jsonb_build_object('kind','boolean','value',original->'value'));
 WHEN 'string' THEN
  result:=truss.runtime_catalog_report_native_tree(jsonb_build_object('kind','string'));
  RETURN jsonb_set(result,'{members}',result->'members'||jsonb_build_array(jsonb_build_object('keyUtf8Hex','74657874','node',original)));
 WHEN 'array' THEN
  FOR child IN SELECT value FROM jsonb_array_elements(original->'items') LOOP
   children:=children||jsonb_build_array(truss.runtime_catalog_report_map_origin_tree(child,depth+1)); END LOOP;
  result:=truss.runtime_catalog_report_native_tree(jsonb_build_object('kind','sequence'));
  RETURN jsonb_set(result,'{members}',result->'members'||jsonb_build_array(jsonb_build_object('keyUtf8Hex','6974656d73','node',jsonb_build_object('kind','array','items',children))));
 WHEN 'object' THEN
  FOR child IN SELECT value FROM jsonb_array_elements(original->'members') ORDER BY decode(value->>'keyUtf8Hex','hex') LOOP
   mapped:=jsonb_build_object('kind','object','members',jsonb_build_array(
    jsonb_build_object('keyUtf8Hex','6b6579','node',jsonb_build_object('kind','string','utf8Hex',child->>'keyUtf8Hex')),
    jsonb_build_object('keyUtf8Hex','76616c7565','node',truss.runtime_catalog_report_map_origin_tree(child->'node',depth+1))));
   children:=children||jsonb_build_array(mapped); END LOOP;
  result:=truss.runtime_catalog_report_native_tree(jsonb_build_object('kind','map'));
  RETURN jsonb_set(result,'{members}',result->'members'||jsonb_build_array(jsonb_build_object('keyUtf8Hex','656e7472696573','node',jsonb_build_object('kind','array','items',children))));
 ELSE RAISE EXCEPTION 'recognized tagged origin required' USING ERRCODE='22023'; END CASE;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_catalog_report_native_tree(value jsonb, depth integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE children jsonb:='[]'::jsonb; entry record; kind text;
BEGIN
 IF value IS NULL OR depth IS NULL OR depth<0 OR depth>128 THEN
  RAISE EXCEPTION 'bounded native report value required' USING ERRCODE='22023';
 END IF;
 kind:=jsonb_typeof(value);
 CASE kind
 WHEN 'null' THEN RETURN jsonb_build_object('kind','null');
 WHEN 'boolean' THEN RETURN jsonb_build_object('kind','boolean','value',value);
 WHEN 'string' THEN RETURN jsonb_build_object('kind','string','utf8Hex',encode(convert_to(value #>> '{}','UTF8'),'hex'));
 WHEN 'array' THEN
  IF jsonb_array_length(value)>4096 THEN RAISE EXCEPTION 'native report array capacity' USING ERRCODE='54000'; END IF;
  FOR entry IN SELECT x FROM jsonb_array_elements(value) x LOOP
   children:=children||jsonb_build_array(truss.runtime_catalog_report_native_tree(entry.x,depth+1));
  END LOOP;
  RETURN jsonb_build_object('kind','array','items',children);
 WHEN 'object' THEN
  IF (SELECT count(*) FROM jsonb_object_keys(value))>4096 THEN RAISE EXCEPTION 'native report object capacity' USING ERRCODE='54000'; END IF;
  FOR entry IN SELECT key,x FROM jsonb_each(value) e(key,x) LOOP
   children:=children||jsonb_build_array(jsonb_build_object('keyUtf8Hex',encode(convert_to(entry.key,'UTF8'),'hex'),
    'node',truss.runtime_catalog_report_native_tree(entry.x,depth+1)));
  END LOOP;
  RETURN jsonb_build_object('kind','object','members',children);
 ELSE RAISE EXCEPTION 'numeric-free native report value required' USING ERRCODE='22023';
 END CASE;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_catalog_report_original_tree(original bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE parsed record; p int;
BEGIN
 SELECT * INTO STRICT parsed FROM truss.runtime_catalog_report_parse_value(original,0,0);p:=parsed.next_at;
 WHILE p<octet_length(original) AND get_byte(original,p) IN (9,10,13,32) LOOP p:=p+1; END LOOP;
 IF p<>octet_length(original) THEN RAISE EXCEPTION 'one complete original JSON value required' USING ERRCODE='22023'; END IF;
 PERFORM truss.runtime_canonical_tree_bytes(parsed.tree);
 RETURN parsed.tree;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_catalog_report_parse_value(original bytea, start_at integer, depth integer)
 RETURNS TABLE(tree jsonb, next_at integer, node_count integer)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE p int:=start_at; n int:=octet_length(original); b int; escape int; code int; low int;
 raw bytea:=decode('','hex'); children jsonb:='[]'::jsonb; child record; key_node jsonb;
 count_nodes int:=1; kind text; closing int; key_hex text;
BEGIN
 IF original IS NULL OR n NOT BETWEEN 1 AND 1048576 OR p<0 OR depth<0 OR depth>128 THEN
  RAISE EXCEPTION 'bounded original JSON source required' USING ERRCODE='22023'; END IF;
 WHILE p<n AND get_byte(original,p) IN (9,10,13,32) LOOP p:=p+1; END LOOP;
 IF p>=n THEN RAISE EXCEPTION 'original JSON value required' USING ERRCODE='22023'; END IF;
 b:=get_byte(original,p);p:=p+1;
 IF b=34 THEN
  WHILE p<n LOOP
   b:=get_byte(original,p);p:=p+1;
   IF b=34 THEN
    PERFORM truss.runtime_canonical_string_bytes(raw);
    RETURN QUERY SELECT jsonb_build_object('kind','string','utf8Hex',encode(raw,'hex')),p,count_nodes; RETURN;
   ELSIF b<32 THEN RAISE EXCEPTION 'unescaped JSON control required to refuse' USING ERRCODE='22023';
   ELSIF b=92 THEN
    IF p>=n THEN RAISE EXCEPTION 'complete JSON escape required' USING ERRCODE='22023'; END IF;
    escape:=get_byte(original,p);p:=p+1;
    IF escape IN (34,47,92) THEN raw:=raw||set_byte(decode('00','hex'),0,escape);
    ELSIF escape IN (98,102,110,114,116) THEN
     raw:=raw||set_byte(decode('00','hex'),0,CASE escape WHEN 98 THEN 8 WHEN 102 THEN 12 WHEN 110 THEN 10 WHEN 114 THEN 13 ELSE 9 END);
    ELSIF escape=117 THEN
     IF p+4>n OR convert_from(substr(original,p+1,4),'UTF8') !~ '^[0-9a-fA-F]{4}$' THEN
      RAISE EXCEPTION 'four JSON hex digits required' USING ERRCODE='22023'; END IF;
     code:=get_byte(decode(convert_from(substr(original,p+1,4),'UTF8'),'hex'),0)*256
       +get_byte(decode(convert_from(substr(original,p+1,4),'UTF8'),'hex'),1);p:=p+4;
     IF code BETWEEN 55296 AND 56319 THEN
      IF p+6>n OR substr(original,p+1,2)<>decode('5c75','hex')
       OR convert_from(substr(original,p+3,4),'UTF8') !~ '^[0-9a-fA-F]{4}$' THEN
       RAISE EXCEPTION 'original JSON surrogate pair required' USING ERRCODE='22023'; END IF;
      low:=get_byte(decode(convert_from(substr(original,p+3,4),'UTF8'),'hex'),0)*256
       +get_byte(decode(convert_from(substr(original,p+3,4),'UTF8'),'hex'),1);p:=p+6;
      IF low NOT BETWEEN 56320 AND 57343 THEN RAISE EXCEPTION 'original JSON low surrogate required' USING ERRCODE='22023'; END IF;
      code:=65536+(code-55296)*1024+low-56320;
     ELSIF code BETWEEN 56320 AND 57343 THEN RAISE EXCEPTION 'unpaired JSON low surrogate' USING ERRCODE='22023'; END IF;
     IF code=0 THEN raw:=raw||decode('00','hex'); ELSE raw:=raw||convert_to(chr(code),'UTF8'); END IF;
    ELSE RAISE EXCEPTION 'recognized JSON escape required' USING ERRCODE='22023'; END IF;
   ELSE raw:=raw||set_byte(decode('00','hex'),0,b);
   END IF;
  END LOOP;
  RAISE EXCEPTION 'closed JSON string required' USING ERRCODE='22023';
 ELSIF b IN (91,123) THEN
  kind:=CASE b WHEN 91 THEN 'array' ELSE 'object' END;closing:=CASE b WHEN 91 THEN 93 ELSE 125 END;
  WHILE p<n AND get_byte(original,p) IN (9,10,13,32) LOOP p:=p+1; END LOOP;
  IF p<n AND get_byte(original,p)=closing THEN
   RETURN QUERY SELECT jsonb_build_object('kind',kind,CASE kind WHEN 'array' THEN 'items' ELSE 'members' END,children),p+1,count_nodes;RETURN;
  END IF;
  LOOP
   IF jsonb_array_length(children)>=4096 THEN RAISE EXCEPTION 'original JSON container capacity' USING ERRCODE='54000'; END IF;
   IF kind='object' THEN
    SELECT * INTO STRICT child FROM truss.runtime_catalog_report_parse_value(original,p,depth+1);
    IF child.tree->>'kind'<>'string' THEN RAISE EXCEPTION 'JSON object key required' USING ERRCODE='22023'; END IF;
    key_hex:=child.tree->>'utf8Hex';p:=child.next_at;count_nodes:=count_nodes+child.node_count;
    WHILE p<n AND get_byte(original,p) IN (9,10,13,32) LOOP p:=p+1; END LOOP;
    IF p>=n OR get_byte(original,p)<>58 THEN RAISE EXCEPTION 'JSON member colon required' USING ERRCODE='22023'; END IF;p:=p+1;
   END IF;
   SELECT * INTO STRICT child FROM truss.runtime_catalog_report_parse_value(original,p,depth+1);
   p:=child.next_at;count_nodes:=count_nodes+child.node_count;
   IF count_nodes>32768 THEN RAISE EXCEPTION 'original JSON node capacity' USING ERRCODE='54000'; END IF;
   children:=children||jsonb_build_array(CASE kind WHEN 'array' THEN child.tree
     ELSE jsonb_build_object('keyUtf8Hex',key_hex,'node',child.tree) END);
   WHILE p<n AND get_byte(original,p) IN (9,10,13,32) LOOP p:=p+1; END LOOP;
   IF p>=n THEN RAISE EXCEPTION 'closed JSON container required' USING ERRCODE='22023'; END IF;
   b:=get_byte(original,p);p:=p+1;
   IF b=closing THEN EXIT; END IF;
   IF b<>44 THEN RAISE EXCEPTION 'JSON member separator required' USING ERRCODE='22023'; END IF;
  END LOOP;
  RETURN QUERY SELECT jsonb_build_object('kind',kind,CASE kind WHEN 'array' THEN 'items' ELSE 'members' END,children),p,count_nodes;RETURN;
 ELSIF substr(original,p,4)=convert_to('null','UTF8') THEN
  RETURN QUERY SELECT jsonb_build_object('kind','null'),p+3,count_nodes;RETURN;
 ELSIF substr(original,p,4)=convert_to('true','UTF8') THEN
  RETURN QUERY SELECT jsonb_build_object('kind','boolean','value',true),p+3,count_nodes;RETURN;
 ELSIF substr(original,p,5)=convert_to('false','UTF8') THEN
  RETURN QUERY SELECT jsonb_build_object('kind','boolean','value',false),p+4,count_nodes;RETURN;
 ELSE RAISE EXCEPTION 'numeric-free original JSON token required' USING ERRCODE='22023'; END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_catalog_report_shape_matches(node jsonb, rule jsonb, registry jsonb, base_uri text, depth integer DEFAULT 0)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE branch jsonb; child jsonb; member jsonb; key_name text; pointer text; uri text;
 resolved jsonb; matches int:=0; raw bytea; length_chars int; i int; kind text;
BEGIN
 IF depth IS NULL OR depth<0 OR node IS NULL OR rule IS NULL THEN RETURN false; END IF;
 IF depth>256 THEN RAISE EXCEPTION 'selected report schema evaluation depth capacity' USING ERRCODE='54000'; END IF;
 IF jsonb_typeof(rule)='boolean' THEN RETURN rule='true'::jsonb; END IF;
 IF jsonb_typeof(rule)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(rule) k WHERE k<>ALL(ARRAY[
  '$schema','$id','$defs','$ref','title','description','type','properties','required','additionalProperties',
  'items','minItems','maxItems','minLength','maxLength','pattern','const','enum','oneOf','allOf','format'])) THEN
  RAISE EXCEPTION 'unsupported selected report shape vocabulary' USING ERRCODE='0A000'; END IF;
 IF rule ? '$ref' THEN
  uri:=split_part(rule->>'$ref','#',1); IF uri='' THEN uri:=base_uri; END IF;
  resolved:=registry->uri;pointer:=split_part(rule->>'$ref','#',2);
  IF pointer<>'' THEN
   IF left(pointer,1)<>'/' THEN RETURN false; END IF;
   FOREACH key_name IN ARRAY string_to_array(substr(pointer,2),'/') LOOP
    key_name:=replace(replace(key_name,'~1','/'),'~0','~');
    IF jsonb_typeof(resolved)='array' THEN
     IF key_name !~ '^(0|[1-9][0-9]*)$' OR length(key_name)>9 THEN RETURN false; END IF;
     resolved:=resolved->key_name::int;
    ELSE resolved:=resolved->key_name; END IF; END LOOP;
  END IF;
  IF NOT truss.runtime_catalog_report_shape_matches(node,resolved,registry,uri,depth+1) THEN RETURN false; END IF;
 END IF;
 IF rule ? 'oneOf' THEN
  FOR branch IN SELECT value FROM jsonb_array_elements(rule->'oneOf') LOOP
   IF truss.runtime_catalog_report_shape_matches(node,branch,registry,base_uri,depth+1) THEN matches:=matches+1; END IF; END LOOP;
  IF matches<>1 THEN RETURN false; END IF;
 END IF;
 IF rule ? 'allOf' THEN
  FOR branch IN SELECT value FROM jsonb_array_elements(rule->'allOf') LOOP
   IF NOT truss.runtime_catalog_report_shape_matches(node,branch,registry,base_uri,depth+1) THEN RETURN false; END IF; END LOOP;
 END IF;
 IF rule ? 'const' AND node IS DISTINCT FROM truss.runtime_catalog_report_native_tree(rule->'const') THEN RETURN false; END IF;
 IF rule ? 'enum' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(rule->'enum') e
  WHERE node=truss.runtime_catalog_report_native_tree(e)) THEN RETURN false; END IF;
 kind:=node->>'kind';
 IF rule ? 'type' AND rule->>'type' IS DISTINCT FROM kind THEN RETURN false; END IF;
 IF kind='object' THEN
  FOR branch IN SELECT value FROM jsonb_array_elements(coalesce(rule->'required','[]'::jsonb)) LOOP
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(node->'members') m WHERE m->>'keyUtf8Hex'=encode(convert_to(branch #>> '{}','UTF8'),'hex')) THEN RETURN false; END IF;
  END LOOP;
  FOR member IN SELECT value FROM jsonb_array_elements(node->'members') LOOP
   raw:=decode(member->>'keyUtf8Hex','hex');
   -- Schema property names are textual. An unmatched logical NUL key is an
   -- additional property; it is never decoded into PostgreSQL text.
   IF position(decode('00','hex') IN raw)>0 THEN
    IF rule->'additionalProperties'='false'::jsonb THEN RETURN false; END IF;CONTINUE;
   END IF;
   key_name:=convert_from(raw,'UTF8');branch:=rule->'properties'->key_name;
   IF branch IS NOT NULL THEN
    IF NOT truss.runtime_catalog_report_shape_matches(member->'node',branch,registry,base_uri,depth+1) THEN RETURN false; END IF;
   ELSIF rule->'additionalProperties'='false'::jsonb THEN RETURN false;
   ELSIF jsonb_typeof(rule->'additionalProperties')='object' THEN
    IF NOT truss.runtime_catalog_report_shape_matches(member->'node',rule->'additionalProperties',registry,base_uri,depth+1) THEN RETURN false; END IF;
   END IF;
  END LOOP;
 ELSIF kind='array' THEN
  IF rule ? 'minItems' AND jsonb_array_length(node->'items')<(rule->>'minItems')::int THEN RETURN false; END IF;
  IF rule ? 'maxItems' AND jsonb_array_length(node->'items')>(rule->>'maxItems')::int THEN RETURN false; END IF;
  IF rule ? 'items' THEN
   FOR child IN SELECT value FROM jsonb_array_elements(node->'items') LOOP
    IF NOT truss.runtime_catalog_report_shape_matches(child,rule->'items',registry,base_uri,depth+1) THEN RETURN false; END IF; END LOOP;
  END IF;
 ELSIF kind='string' THEN
  raw:=decode(node->>'utf8Hex','hex');length_chars:=0;
  IF octet_length(raw)>0 THEN
   FOR i IN 0..octet_length(raw)-1 LOOP IF get_byte(raw,i)<128 OR get_byte(raw,i)>=192 THEN length_chars:=length_chars+1; END IF;END LOOP;
  END IF;
  IF rule ? 'minLength' AND length_chars<(rule->>'minLength')::int THEN RETURN false; END IF;
  IF rule ? 'maxLength' AND length_chars>(rule->>'maxLength')::int THEN RETURN false; END IF;
  IF rule ? 'pattern' THEN
   IF position(decode('00','hex') IN raw)>0 THEN RETURN false; END IF;
   IF convert_from(raw,'UTF8') !~ (rule->>'pattern') THEN RETURN false; END IF;
  END IF;
 END IF;
 RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_collect_absent_binding_index_declarations(expected_writer text, expected_ordinal text, expected_generation text, revision integer, original_policy bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; input jsonb; documents jsonb;
 policy_source bytea:=convert_to($policy${
  "identity": "truss-absent-binding-index-declarations",
  "version": "0.1.0",
  "scope": "immutable_index_job_declarations_only",
  "governingRules": [
    "ADR-002-D2",
    "ADR-002-D11",
    "ADR-002-D12",
    "CONTRACT-003-pending-index-declarations"
  ],
  "sourceComponent": {
    "identity": "truss-qualified-property-layout-source",
    "version": "0.15",
    "sha256": "cc725df53f0d74e13bb51fda29603f8cafe8c0cee237667778566f81b33f5011"
  },
  "selection": {
    "binding": "absent",
    "transforms": "empty",
    "ingress": "native",
    "storageHome": "json"
  },
  "indexDeclarationSources": [
    "explicit_acceptance_binding"
  ],
  "documentExtensionAndQueryJobDeclarations": "none_in_this_policy",
  "absentBindingDeclarations": "empty",
  "baselineEnforcementIndexes": "excluded_from_catalog_jobs",
  "statisticsDeclarations": "outside_this_field",
  "unknownExtensionSemantics": "retained_and_separately_unresolved",
  "installedProfileAuthority": false,
  "readinessAuthority": false
}
$policy$,'UTF8');
BEGIN
 IF current_user IS DISTINCT FROM session_user OR NOT EXISTS(
  SELECT 1 FROM pg_roles r WHERE r.rolname=current_user AND r.rolsuper) THEN
  RAISE EXCEPTION 'administrative declaration observation only' USING ERRCODE='42501';
 END IF;
 IF original_policy IS DISTINCT FROM policy_source THEN
  RAISE EXCEPTION 'original selected declaration policy bytes required' USING ERRCODE='55000';
 END IF;
 PERFORM truss.runtime_require_catalog_observation(expected_writer,expected_ordinal,expected_generation);
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned();
 PERFORM truss.runtime_require_catalog_input(op.original_input_bytes);
 input:=convert_from(op.original_input_bytes,'UTF8')::jsonb;
 IF input->'binding' IS DISTINCT FROM '{"state":"absent"}'::jsonb
  OR input->'transforms' IS DISTINCT FROM '[]'::jsonb
  OR jsonb_typeof(input->'documents') IS DISTINCT FROM 'array'
  OR jsonb_array_length(input->'documents') NOT BETWEEN 1 AND 512
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(input->'documents') d
    WHERE d->'ingress' IS DISTINCT FROM '{"kind":"native"}'::jsonb) THEN
  RAISE EXCEPTION 'unselected index declaration source requires its original producer' USING ERRCODE='0A000';
 END IF;
 -- This producer is bound to the existing new-catalog native component. Its
 -- inventory/document procedures establish current source correspondence; they
 -- do not turn caller profile pins into installed profile authority.
 PERFORM * FROM truss.runtime_collect_new_catalog_inventory(revision);
 SELECT jsonb_agg(to_jsonb(d) ORDER BY d.ord::int) INTO documents
  FROM truss.runtime_collect_report_documents(revision) d;
 IF EXISTS(SELECT 1 FROM truss.prop_def d WHERE d.since_rev=revision AND d.home<>'json') THEN
  RAISE EXCEPTION 'selected absent-binding JSON source required' USING ERRCODE='0A000';
 END IF;
 PERFORM truss.runtime_require_catalog_observation(expected_writer,expected_ordinal,expected_generation);
 RETURN jsonb_build_object('scope','original_absent_binding_index_declarations_only',
  'policyHex',encode(policy_source,'hex'),'policySha256',encode(sha256(policy_source),'hex'),
  'inputHex',encode(op.original_input_bytes,'hex'),'writerXid',expected_writer,
  'operationOrdinal',expected_ordinal,'effectGeneration',expected_generation,
  'revision',revision::text,'documents',documents,'declaredJobs','[]'::jsonb,
  'installedProfileQualified',false,'readinessQualified',false);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_collect_catalog_admission_configuration(expected_writer_xid text, expected_operation_ordinal text, expected_effect_generation text, expected_configuration_profile_hex text)
 RETURNS TABLE(context_hex text, configuration_generation text, key_reuse text, journal_mode text, configuration_hex text, selected_binding_hex text, installed_inventory_hex text, configuration_sha256 text, selected_binding_sha256 text, installed_inventory_sha256 text, configuration_profile_hex text, configuration_profile_sha256 text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE original_context record; captured truss.operation_configuration%ROWTYPE;
BEGIN
 IF expected_configuration_profile_hex IS NULL
  OR octet_length(expected_configuration_profile_hex) NOT BETWEEN 2 AND 131072
  OR expected_configuration_profile_hex !~ '^([0-9a-f]{2})+$' THEN
  RAISE EXCEPTION 'bounded original configuration profile required' USING ERRCODE='22023';
 END IF;
 PERFORM truss.runtime_require_operation_configuration_current(
  expected_writer_xid,expected_operation_ordinal,expected_effect_generation);
 SELECT * INTO STRICT original_context FROM truss.runtime_collect_catalog_epoch_context(
  expected_writer_xid,expected_operation_ordinal,expected_effect_generation);
 SELECT c.* INTO STRICT captured FROM truss.operation_configuration c
  WHERE c.original_writer_xid=pg_current_xact_id_if_assigned()
   AND c.operation_ordinal::text=expected_operation_ordinal;
 IF encode(captured.admission_profile_bytes,'hex') IS DISTINCT FROM expected_configuration_profile_hex THEN
  RAISE EXCEPTION 'original configuration profile byte correspondence required' USING ERRCODE='55000';
 END IF;
 RETURN QUERY SELECT original_context.context_hex,captured.configuration_generation::text,
  captured.key_reuse,captured.journal_mode,encode(captured.configuration_bytes,'hex'),
  encode(captured.selected_binding_bytes,'hex'),encode(captured.installed_inventory_bytes,'hex'),
  encode(captured.configuration_sha256,'hex'),encode(captured.selected_binding_sha256,'hex'),
  encode(captured.installed_inventory_sha256,'hex'),encode(captured.admission_profile_bytes,'hex'),
  encode(sha256(captured.admission_profile_bytes),'hex');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_collect_catalog_epoch_context(expected_writer text, expected_ordinal text, expected_generation text)
 RETURNS TABLE(context_hex text, database_role text, login_role text, database_name text, backend_pid text, actor_role_oid text, login_role_oid text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; context jsonb; epoch_capture record;
BEGIN
 IF current_user::text IS DISTINCT FROM (CASE WHEN current_setting('role')='none'
  THEN session_user::text ELSE current_setting('role') END) THEN
  RAISE EXCEPTION 'original invoker actor boundary required' USING ERRCODE='55000';
 END IF;
 PERFORM truss.runtime_require_catalog_observation(expected_writer,expected_ordinal,expected_generation);
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.phase='admitted';
 context:=convert_from(op.original_context_bytes,'UTF8')::jsonb;
 IF jsonb_typeof(context)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(context))<>16
  OR NOT context ?& ARRAY['interfaceVersion','xid','ordinal','sessionUser','actingUser','database','backendPid','actorRoleOid','sessionRoleOid','assertedOriginUtf8Hex','assertedOriginCaptureProfileHex','installationId','sourceEpoch','targetIncarnation','sourceEpochProfileHex','sourceEpochEvidenceHex']
  OR EXISTS(SELECT 1 FROM jsonb_each(context) e WHERE jsonb_typeof(e.value)<>'string')
  OR context->>'interfaceVersion' IS DISTINCT FROM 'truss-native-operation-context/0.4'
  OR context->>'assertedOriginUtf8Hex' !~ '^([0-9a-f]{2})+$'
  OR octet_length(context->>'assertedOriginUtf8Hex') NOT BETWEEN 2 AND 262144
  OR context->>'assertedOriginCaptureProfileHex' !~ '^([0-9a-f]{2})+$'
  OR octet_length(context->>'assertedOriginCaptureProfileHex') NOT BETWEEN 2 AND 131072
  OR context->>'xid' IS DISTINCT FROM expected_writer OR context->>'ordinal' IS DISTINCT FROM expected_ordinal
  OR context->>'sessionUser' IS DISTINCT FROM session_user::text
  OR context->>'actingUser' IS DISTINCT FROM current_user::text
  OR context->>'actorRoleOid' IS DISTINCT FROM (SELECT r.oid::text FROM pg_catalog.pg_roles r WHERE r.rolname=current_user)
  OR context->>'sessionRoleOid' IS DISTINCT FROM (SELECT r.oid::text FROM pg_catalog.pg_roles r WHERE r.rolname=session_user)
  OR context->>'database' IS DISTINCT FROM current_database()
  OR context->>'backendPid' IS DISTINCT FROM pg_backend_pid()::text THEN
  RAISE EXCEPTION 'original native actor/context correspondence required' USING ERRCODE='55000';
 END IF;
 SELECT * INTO STRICT epoch_capture FROM truss.runtime_lock_source_epoch(
  context->>'installationId',context->>'sourceEpoch',context->>'targetIncarnation');
 IF context->>'sourceEpochProfileHex' IS DISTINCT FROM epoch_capture.profile_hex
  OR context->>'sourceEpochEvidenceHex' IS DISTINCT FROM epoch_capture.evidence_hex THEN
  RAISE EXCEPTION 'original captured epoch evidence correspondence required' USING ERRCODE='55000';
 END IF;
 RETURN QUERY SELECT encode(op.original_context_bytes,'hex'),context->>'actingUser',context->>'sessionUser',context->>'database',context->>'backendPid',context->>'actorRoleOid',context->>'sessionRoleOid';
END;
$function$

