CREATE OR REPLACE FUNCTION truss.runtime_collect_catalog_source_candidate(candidate_bytes bytea, declarations_bytes bytea)
 RETURNS TABLE(host_sources jsonb, original_report_evidence bytea, preparation_provenance jsonb)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE raw json; envelope jsonb; tree jsonb; evidence bytea;
 fields text[]:=ARRAY['umf','diagnostics','documentInterpretations','losses','extensions',
  'transformRegistrations','assertionEntries']; encoded bytea;
BEGIN
 IF candidate_bytes IS NULL OR declarations_bytes IS NULL
  OR octet_length(candidate_bytes) NOT BETWEEN 1 AND 1048576
  OR octet_length(declarations_bytes) NOT BETWEEN 1 AND 1048576 THEN
  RAISE EXCEPTION 'bounded original source candidate required' USING ERRCODE='22023';
 END IF;
 raw:=convert_from(candidate_bytes,'UTF8')::json;
 PERFORM truss.runtime_require_unique_source_json(raw);
 envelope:=raw::jsonb;
 IF jsonb_typeof(envelope) IS DISTINCT FROM 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(envelope))<>5
  OR NOT envelope ?& ARRAY['interfaceVersion','declarationsUtf8Hex','reportEvidenceUtf8Hex',
    'preparationProvenance','hostSources']
  OR envelope->>'interfaceVersion' IS DISTINCT FROM 'truss-catalog-source-candidate/0.1'
  OR jsonb_typeof(envelope->'declarationsUtf8Hex') IS DISTINCT FROM 'string'
  OR envelope->>'declarationsUtf8Hex' IS DISTINCT FROM encode(declarations_bytes,'hex')
  OR jsonb_typeof(envelope->'reportEvidenceUtf8Hex') IS DISTINCT FROM 'string'
  OR envelope->>'reportEvidenceUtf8Hex' !~ '^([0-9a-f]{2})+$'
  OR jsonb_typeof(envelope->'preparationProvenance') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'closed original source candidate required' USING ERRCODE='22023';
 END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(envelope->'preparationProvenance'))<>7
  OR NOT (envelope->'preparationProvenance') ?& ARRAY['owner_revision','owner_bundle_sha256',
    'acceptance_schema_sha256','release_manifest_sha256','runtime_version','scope','installation_profiles_verified']
  OR envelope->'preparationProvenance'->'installation_profiles_verified' IS DISTINCT FROM 'false'::jsonb
  OR envelope->'preparationProvenance'->>'scope' IS DISTINCT FROM 'original_umf_preparation_only'
  OR EXISTS(SELECT 1 FROM jsonb_each(envelope->'preparationProvenance') e
    WHERE e.key<>'installation_profiles_verified' AND (jsonb_typeof(e.value) IS DISTINCT FROM 'string' OR e.value #>> '{}'=''))
  OR EXISTS(SELECT 1 FROM unnest(ARRAY['owner_bundle_sha256','acceptance_schema_sha256','release_manifest_sha256']) k
    WHERE envelope->'preparationProvenance'->>k !~ '^[0-9a-f]{64}$') THEN
  RAISE EXCEPTION 'complete original preparation provenance required' USING ERRCODE='22023';
 END IF;
 tree:=envelope->'hostSources';
 IF tree->>'kind' IS DISTINCT FROM 'object' OR jsonb_typeof(tree->'members') IS DISTINCT FROM 'array'
  OR jsonb_array_length(tree->'members')<>7 THEN
  RAISE EXCEPTION 'complete source-only field inventory required' USING ERRCODE='22023';
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(tree->'members') m
  WHERE m->'node'->>'kind' IS DISTINCT FROM 'array'
   OR NOT EXISTS(SELECT 1 FROM unnest(fields) f
    WHERE m->>'keyUtf8Hex'=encode(convert_to(f,'UTF8'),'hex'))) THEN
  RAISE EXCEPTION 'native-owned or unknown source field' USING ERRCODE='22023';
 END IF;
 -- Codec validates all tagged metadata, scalar bytes and duplicate logical keys.
 encoded:=truss.runtime_canonical_tree_bytes(tree);
 evidence:=decode(envelope->>'reportEvidenceUtf8Hex','hex');
 -- Exact bytes are retained; no lossy jsonb interpretation of logical evidence.
 RETURN QUERY SELECT tree,evidence,envelope->'preparationProvenance';
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_collect_configured_catalog_graph()
 RETURNS TABLE(writer_xid text, operation_ordinal text, effect_generation text, empty_scope text, metadata_source text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; name text; relation_oid oid;
 kind "char"; populated boolean; filtered boolean; context jsonb; configuration truss.operation_configuration%ROWTYPE;
 metadata jsonb;
 metadata_names text[]:=ARRAY['source_epoch_registry','source_epoch_current','operation_configuration','installation_admission'];
 scope_names text[]:=ARRAY['object','edge','edge_limit','key_tombstone','record_source',
 'feed_consumer','journal','row_home_journal_stage','row_home_state','row_home_node',
 'row_home_scalar','row_home_touch','row_home_capacity','key_bucket_guard',
 'object_key_bucket','object_key_reservation_bucket','feed_tx','feed_member',
 'feed_prerequisite','feed_configuration_prerequisite','complete_feed_consumer',
 'complete_feed_administration_receipt','complete_feed_seed_attempt',
 'complete_feed_seed_artifact','key_lifecycle_history','key_migration_receipt',
 'request_receipt_route_guard','request_receipt','request_receipt_protection',
 'schema_change'];
BEGIN
 IF pg_catalog.current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'fresh statement snapshots required for empty graph evidence' USING ERRCODE='0A000';
 END IF;
 IF current_user IS DISTINCT FROM session_user OR NOT EXISTS(
  SELECT 1 FROM pg_roles r WHERE r.rolname=current_user AND r.rolsuper) THEN
  RAISE EXCEPTION 'administrative original visible graph profile required' USING ERRCODE='42501';
 END IF;
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.phase<>'application_finalized';
 IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted'
  OR (SELECT count(*) FROM truss.row_home_operation)<>1 THEN
  RAISE EXCEPTION 'one original fresh catalog operation required' USING ERRCODE='55000';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.granted
  AND l.relation='truss.schema_head'::regclass AND l.mode IN ('ExclusiveLock','AccessExclusiveLock')) THEN
  RAISE EXCEPTION 'original catalog exclusion required' USING ERRCODE='55000';
 END IF;
 -- Metadata is an explicit native correspondence producer, never an exemption
 -- selected by a caller flag. All application graph homes remain empty.
 SELECT * INTO STRICT configuration FROM truss.operation_configuration c
  WHERE c.original_writer_xid=op.original_writer_xid AND c.operation_ordinal=op.operation_ordinal;
 context:=convert_from(op.original_context_bytes,'UTF8')::jsonb;
 IF context->>'interfaceVersion' IS DISTINCT FROM 'truss-native-operation-context/0.4' THEN
  RAISE EXCEPTION 'original configured context required' USING ERRCODE='55000';
 END IF;
 PERFORM truss.runtime_require_operation_configuration_current(
  op.original_writer_xid::text,op.operation_ordinal::text,op.effect_generation::text);
 IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='truss' AND c.relkind IN ('r','p','f','v','m')
   AND NOT(c.relname=ANY(scope_names||metadata_names||ARRAY['setting','module_access','schema_rev',
    'schema_head','schema_doc','type_def','prop_def','key_def','rel_def','rel_endpoint',
    'row_home_operation','relationship_lineage','catalog_acceptance_report',
    'installation_marker','installation_archive','installation_admission']))) THEN
  RAISE EXCEPTION 'uncovered physical graph scope' USING ERRCODE='0A000';
 END IF;
 IF op.effect_generation=0 AND EXISTS(SELECT 1 FROM pg_locks l
  JOIN pg_class c ON c.oid=l.relation JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE l.pid=pg_backend_pid() AND l.granted AND l.mode IN ('RowExclusiveLock','ShareRowExclusiveLock','ExclusiveLock','AccessExclusiveLock')
   AND n.nspname='truss' AND c.relname=ANY(scope_names)) THEN
  RAISE EXCEPTION 'earlier graph writes cannot become an empty original start cut' USING ERRCODE='55000';
 END IF;
 -- First acquire every participating native relation lock, then inspect emptiness.
 -- NOWAIT refuses a competing raw writer instead of waiting/retrying.
 FOREACH name IN ARRAY scope_names||metadata_names LOOP
  relation_oid:=to_regclass(format('truss.%I',name));
  IF relation_oid IS NULL THEN
   RAISE EXCEPTION 'complete selected graph relation missing' USING ERRCODE='55000';
  END IF;
  EXECUTE format('LOCK TABLE truss.%I IN SHARE MODE NOWAIT',name);
  SELECT c.relkind,c.relrowsecurity INTO STRICT kind,filtered FROM pg_class c WHERE c.oid=relation_oid;
  IF filtered OR (name='journal' AND (kind<>'p' OR pg_get_partkeydef(relation_oid) IS DISTINCT FROM 'RANGE (at)'))
   OR (name<>'journal' AND kind<>'r')
   OR EXISTS(SELECT 1 FROM pg_inherits i WHERE i.inhparent=relation_oid OR i.inhrelid=relation_oid) THEN
   RAISE EXCEPTION 'selected ordinary graph and empty journal root topology required' USING ERRCODE='0A000';
  END IF;
 END LOOP;
 FOREACH name IN ARRAY scope_names LOOP
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM truss.%I)',name) INTO populated;
  IF populated THEN
   RAISE EXCEPTION 'nonempty graph needs original before/after effect report producer' USING ERRCODE='0A000';
  END IF;
 END LOOP;
 -- Acquire metadata table cuts before inspecting complete cardinality. The
 -- original current-context collector independently checks bytes/actor/epoch.
 IF (SELECT count(*) FROM truss.source_epoch_registry)<>1
  OR (SELECT count(*) FROM truss.source_epoch_current)<>1
  OR (SELECT count(*) FROM truss.operation_configuration)<>1
  OR (SELECT count(*) FROM truss.installation_admission)<>1
  OR NOT EXISTS(SELECT 1 FROM truss.source_epoch_registry r
    WHERE r.installation_id=configuration.installation_id AND r.source_epoch=configuration.source_epoch
     AND r.target_incarnation=configuration.target_incarnation AND r.transition_reason='initial'
     AND r.predecessor_epoch IS NULL AND encode(r.profile_bytes,'hex')=context->>'sourceEpochProfileHex'
     AND encode(r.evidence_bytes,'hex')=context->>'sourceEpochEvidenceHex'
     AND r.evidence_sha256=sha256(r.evidence_bytes))
  OR NOT EXISTS(SELECT 1 FROM truss.source_epoch_current c WHERE c.singleton_id=1
    AND c.installation_id=configuration.installation_id AND c.source_epoch=configuration.source_epoch) THEN
  RAISE EXCEPTION 'complete original first-installation metadata correspondence required' USING ERRCODE='55000';
 END IF;
 PERFORM truss.runtime_require_operation_configuration_current(
  op.original_writer_xid::text,op.operation_ordinal::text,op.effect_generation::text);
 metadata:=jsonb_build_object('interfaceVersion','truss-configured-catalog-metadata/0.1',
  'installationId',configuration.installation_id,'sourceEpoch',configuration.source_epoch,
  'targetIncarnation',configuration.target_incarnation,
  'configurationGeneration',configuration.configuration_generation::text,
  'contextSha256',encode(sha256(op.original_context_bytes),'hex'),
  'configurationSha256',encode(configuration.configuration_sha256,'hex'),
  'selectedBindingSha256',encode(configuration.selected_binding_sha256,'hex'),
  'installedInventorySha256',encode(configuration.installed_inventory_sha256,'hex'),
  'epochProfileSha256',encode(sha256(decode(context->>'sourceEpochProfileHex','hex')),'hex'),
  'epochEvidenceSha256',encode(sha256(decode(context->>'sourceEpochEvidenceHex','hex')),'hex'));
 RETURN QUERY SELECT op.original_writer_xid::text,op.operation_ordinal::text,
  op.effect_generation::text,jsonb_build_object('interfaceVersion','truss-configured-empty-graph/0.1',
   'businessRelations',to_jsonb(scope_names),'metadataUtf8Hex',encode(
    truss.runtime_capture_catalog_metadata_cut(op.original_writer_xid::text,op.operation_ordinal::text,op.effect_generation::text),'hex'))::text,metadata::text;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_collect_core_catalog_inventory_candidate(original_revision integer, allow_pending boolean)
 RETURNS TABLE(family text, identity jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; item record; matched record; inventory jsonb; original_relationship jsonb; expected_endpoints jsonb; actual_endpoints jsonb; original_field jsonb; original_key jsonb; original_properties int[]; original_owner truss.type_def%ROWTYPE; incomplete boolean; archived_documents jsonb;
BEGIN
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o WHERE
  o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.phase<>'application_finalized' FOR UPDATE;
 IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted' OR original_revision IS NULL OR original_revision<=0 THEN
  RAISE EXCEPTION 'original new catalog inventory admission required' USING ERRCODE='55000';
 END IF;
 LOCK TABLE truss.schema_head IN EXCLUSIVE MODE;
 IF EXISTS(SELECT 1 FROM truss.schema_head h WHERE h.rev>=original_revision) THEN
  RAISE EXCEPTION 'unpublished original revision required' USING ERRCODE='55000';
 END IF;
 SELECT jsonb_agg(jsonb_build_object('documentId',d.doc_id,'revision',d.doc_revision,'umfVersion',d.umf_version,'originalText',d.document,'validation',d.validation) ORDER BY d.ord)
  INTO archived_documents FROM truss.schema_doc d WHERE d.rev=original_revision;
 PERFORM truss.runtime_require_catalog_document_carrier(archived_documents);
 PERFORM * FROM truss.runtime_collect_report_documents(original_revision);
 PERFORM truss.runtime_verify_new_catalog_prestate(original_revision);
 IF EXISTS(SELECT 1 FROM truss.type_def t WHERE t.retired_rev=original_revision OR (t.definition_rev=original_revision AND t.since_rev<>original_revision))
  OR EXISTS(SELECT 1 FROM truss.prop_def p WHERE p.retired_rev=original_revision OR (p.definition_rev=original_revision AND p.since_rev<>original_revision))
  OR EXISTS(SELECT 1 FROM truss.key_def k WHERE k.retired_rev=original_revision OR (k.definition_rev=original_revision AND k.since_rev<>original_revision))
  OR EXISTS(SELECT 1 FROM truss.rel_def r WHERE r.retired_rev=original_revision OR (r.definition_rev=original_revision AND r.since_rev<>original_revision)) THEN
  RAISE EXCEPTION 'retained lifecycle requires complete effect collector' USING ERRCODE='0A000';
 END IF;
 IF allow_pending IS NULL OR EXISTS(SELECT 1 FROM truss.rel_def r WHERE r.since_rev=original_revision
  AND r.definition_source_kind NOT IN ('accepted_document','operation_binding')) THEN
  RAISE EXCEPTION 'unsupported new relationship source inventory required' USING ERRCODE='0A000';
 END IF;
 IF NOT allow_pending AND EXISTS(SELECT 1 FROM truss.rel_def r WHERE r.since_rev=original_revision AND r.definition_source_kind='operation_binding') THEN
  RAISE EXCEPTION 'unique original declaration required' USING ERRCODE='55000';
 END IF;
 WITH original_records AS (
  SELECT d.doc_id,m.value->>'id' AS module_id,r.value AS declaration
  FROM truss.schema_doc d CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') m
  CROSS JOIN LATERAL jsonb_array_elements(m.value->'elements') r
  WHERE d.rev=original_revision AND r.value->>'kind'='record'
 ) SELECT EXISTS(SELECT 1 FROM original_records r WHERE NOT EXISTS(
   SELECT 1 FROM truss.type_def t WHERE t.document_id=r.doc_id AND t.module=r.module_id AND t.element=r.declaration->>'id' AND t.since_rev=original_revision))
  OR EXISTS(SELECT 1 FROM original_records r CROSS JOIN LATERAL jsonb_array_elements(r.declaration->'members') f WHERE NOT EXISTS(
   SELECT 1 FROM truss.type_def t JOIN truss.prop_def p ON p.type_id=t.type_id WHERE t.document_id=r.doc_id AND t.module=r.module_id AND t.element=r.declaration->>'id'
    AND p.declaration_module=f.value->>'module' AND p.element=f.value->>'element' AND p.since_rev=original_revision))
  OR EXISTS(SELECT 1 FROM original_records r CROSS JOIN LATERAL jsonb_array_elements(r.declaration->'keys') k WHERE NOT EXISTS(
   SELECT 1 FROM truss.type_def t JOIN truss.key_def stored ON stored.type_id=t.type_id WHERE t.document_id=r.doc_id AND t.module=r.module_id AND t.element=r.declaration->>'id'
    AND stored.key_id=k.value->>'id' AND stored.since_rev=original_revision))
  OR EXISTS(SELECT 1 FROM truss.schema_doc d CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') m
   CROSS JOIN LATERAL jsonb_array_elements(m.value->'relationships') r WHERE d.rev=original_revision AND NOT EXISTS(
    SELECT 1 FROM truss.rel_def stored WHERE stored.document_id=d.doc_id AND stored.module=m.value->>'id' AND stored.rel_id=r.value->>'id' AND stored.since_rev=original_revision AND stored.definition_source_kind='accepted_document')) INTO incomplete;
 IF incomplete THEN RAISE EXCEPTION 'complete original new declaration inventory required' USING ERRCODE='55000'; END IF;
 FOR item IN SELECT t.* FROM truss.type_def t WHERE t.since_rev=original_revision LOOP
  SELECT * INTO STRICT matched FROM truss.runtime_match_record_identity(original_revision,item.document_id,item.module,item.element);
  IF matched.match_state<>'active' OR matched.storage_id<>item.type_id::text OR matched.creation_revision<>original_revision::text THEN
   RAISE EXCEPTION 'original new Record correspondence' USING ERRCODE='55000';
  END IF;
 END LOOP;
 FOR item IN SELECT p.* FROM truss.prop_def p WHERE p.since_rev=original_revision LOOP
  SELECT * INTO STRICT matched FROM truss.runtime_match_property_identity(original_revision,item.type_id,item.declaration_module,item.element);
  IF matched.match_state<>'active' OR matched.storage_id<>item.prop_id::text OR matched.creation_revision<>original_revision::text THEN
   RAISE EXCEPTION 'original new Field correspondence' USING ERRCODE='55000';
  END IF;
  SELECT t.* INTO STRICT original_owner FROM truss.type_def t WHERE t.type_id=item.type_id;
  SELECT f.value INTO STRICT original_field FROM truss.schema_doc d
   CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') m
   CROSS JOIN LATERAL jsonb_array_elements(m.value->'elements') f
   WHERE d.rev=original_revision AND d.doc_id=original_owner.document_id AND m.value->>'id'=item.declaration_module AND f.value->>'id'=item.element;
  IF item.name IS DISTINCT FROM original_field->>'name' OR item.scalar_type IS DISTINCT FROM original_field->>'scalarType'
   OR item.nullability IS DISTINCT FROM original_field->>'nullability' OR item.cardinality IS DISTINCT FROM original_field->>'cardinality'
   OR item.facets IS DISTINCT FROM original_field->'facets' OR item.item IS DISTINCT FROM original_field->'itemType'
   OR item.definition_rev IS DISTINCT FROM original_revision OR item.definition_document_id IS DISTINCT FROM original_owner.document_id
   OR item.definition_doc_ord IS DISTINCT FROM original_owner.doc_ord OR item.doc_ord IS DISTINCT FROM original_owner.doc_ord THEN
   RAISE EXCEPTION 'stored original Field definition correspondence' USING ERRCODE='55000';
  END IF;
 END LOOP;
 FOR item IN SELECT k.* FROM truss.key_def k WHERE k.since_rev=original_revision LOOP
  SELECT * INTO STRICT matched FROM truss.runtime_match_key_identity(original_revision,item.type_id,item.key_id);
  IF matched.match_state<>'active' OR matched.owner_type_id<>item.type_id::text OR matched.key_number<>item.key_num::text OR matched.creation_revision<>original_revision::text THEN
   RAISE EXCEPTION 'original new Key correspondence' USING ERRCODE='55000';
  END IF;
  SELECT t.* INTO STRICT original_owner FROM truss.type_def t WHERE t.type_id=item.type_id;
  SELECT k.value INTO STRICT original_key FROM truss.schema_doc d
   CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') m
   CROSS JOIN LATERAL jsonb_array_elements(m.value->'elements') r
   CROSS JOIN LATERAL jsonb_array_elements(r.value->'keys') k
   WHERE d.rev=original_revision AND d.doc_id=original_owner.document_id AND m.value->>'id'=original_owner.module AND r.value->>'id'=original_owner.element AND k.value->>'id'=item.key_id;
  SELECT array_agg(p.prop_id ORDER BY f.ordinality) INTO original_properties
   FROM jsonb_array_elements(original_key->'fields') WITH ORDINALITY f(value,ordinality)
   JOIN truss.prop_def p ON p.type_id=item.type_id AND p.declaration_module=f.value->>'module' AND p.element=f.value->>'element';
  IF cardinality(original_properties) IS DISTINCT FROM jsonb_array_length(original_key->'fields') OR item.prop_ids IS DISTINCT FROM original_properties
   OR item.is_primary IS DISTINCT FROM coalesce((original_key->>'primary')::boolean,false)
   OR item.definition_rev IS DISTINCT FROM original_revision OR item.definition_document_id IS DISTINCT FROM original_owner.document_id
   OR item.definition_doc_ord IS DISTINCT FROM original_owner.doc_ord THEN
   RAISE EXCEPTION 'stored original ordered Key definition correspondence' USING ERRCODE='55000';
  END IF;
 END LOOP;
 FOR item IN SELECT r.* FROM truss.rel_def r WHERE r.since_rev=original_revision AND r.definition_source_kind='accepted_document' LOOP
  SELECT * INTO STRICT matched FROM truss.runtime_match_relationship_identity(original_revision,item.document_id,item.module,item.rel_id);
  IF matched.match_state<>'active' OR matched.storage_id<>item.rel_type_id::text OR matched.creation_revision<>original_revision::text THEN
   RAISE EXCEPTION 'original new relationship correspondence' USING ERRCODE='55000';
  END IF;
  SELECT r.value INTO STRICT original_relationship FROM truss.schema_doc d
   CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') m
   CROSS JOIN LATERAL jsonb_array_elements(m.value->'relationships') r
   WHERE d.rev=original_revision AND d.doc_id=item.document_id AND m.value->>'id'=item.module AND r.value->>'id'=item.rel_id;
  IF item.name IS DISTINCT FROM original_relationship->>'name' OR item.source_min IS DISTINCT FROM (original_relationship->'sourceMultiplicity'->>'min')::int
   OR item.source_max IS DISTINCT FROM nullif(original_relationship->'sourceMultiplicity'->>'max','*')::int
   OR item.target_min IS DISTINCT FROM (original_relationship->'targetMultiplicity'->>'min')::int
   OR item.target_max IS DISTINCT FROM nullif(original_relationship->'targetMultiplicity'->>'max','*')::int
   OR item.lifecycle IS DISTINCT FROM original_relationship->>'targetLifecycle' OR item.directed IS DISTINCT FROM (original_relationship->>'directed')::boolean
   OR item.target_key IS DISTINCT FROM original_relationship->'target'->0->>'key'
   OR item.definition_rev IS DISTINCT FROM original_revision OR item.definition_document_id IS DISTINCT FROM item.document_id OR item.definition_doc_ord IS DISTINCT FROM item.doc_ord THEN
   RAISE EXCEPTION 'stored original relationship definition correspondence' USING ERRCODE='55000';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_array(source.type_id::text,target.type_id::text) ORDER BY source.type_id,target.type_id),'[]'::jsonb)
   INTO expected_endpoints FROM jsonb_array_elements(original_relationship->'source') s
   CROSS JOIN jsonb_array_elements(original_relationship->'target') t
   JOIN truss.type_def source ON source.document_id=item.document_id AND source.module=s.value->>'module' AND source.element=s.value->>'element'
   JOIN truss.type_def target ON target.document_id=item.document_id AND target.module=t.value->>'module' AND target.element=t.value->>'element';
  IF jsonb_array_length(expected_endpoints)<>jsonb_array_length(original_relationship->'source')*jsonb_array_length(original_relationship->'target') THEN
   RAISE EXCEPTION 'complete original endpoint resolution required' USING ERRCODE='55000';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_array(e.source_type::text,e.target_type::text) ORDER BY e.source_type,e.target_type),'[]'::jsonb)
   INTO actual_endpoints FROM truss.rel_endpoint e WHERE e.rel_type_id=item.rel_type_id;
  IF expected_endpoints<>actual_endpoints THEN
   RAISE EXCEPTION 'actual endpoint tuples differ from original authored endpoints' USING ERRCODE='55000';
  END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(jsonb_build_object('family',q.family,'identity',q.identity) ORDER BY q.family COLLATE "C",q.identity::text COLLATE "C"),'[]'::jsonb)
 INTO inventory FROM (
  SELECT 'type'::text AS family,jsonb_build_array(t.type_id::text,t.document_id,t.module,t.element) AS identity FROM truss.type_def t WHERE t.since_rev=original_revision
  UNION ALL SELECT 'property',jsonb_build_array(p.prop_id::text,p.type_id::text,p.declaration_module,p.element) FROM truss.prop_def p WHERE p.since_rev=original_revision
  UNION ALL SELECT 'key',jsonb_build_array(k.type_id::text,k.key_id,k.key_num::text) FROM truss.key_def k WHERE k.since_rev=original_revision
  UNION ALL SELECT 'relationship',jsonb_build_array(r.rel_type_id::text,r.document_id,r.module,r.rel_id) FROM truss.rel_def r WHERE r.since_rev=original_revision AND r.definition_source_kind='accepted_document'
  UNION ALL SELECT 'endpoint',jsonb_build_array(e.rel_type_id::text,e.source_type::text,e.target_type::text) FROM truss.rel_endpoint e JOIN truss.rel_def r ON r.rel_type_id=e.rel_type_id WHERE r.since_rev=original_revision AND r.definition_source_kind='accepted_document'
 ) q;
 IF jsonb_array_length(inventory)>16384 OR octet_length(inventory::text)>1048576 THEN
  RAISE EXCEPTION 'new catalog inventory component capacity exceeded' USING ERRCODE='54000';
 END IF;
 RETURN QUERY SELECT value->>'family',value->'identity' FROM jsonb_array_elements(inventory);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_collect_custody_catalog_graph_candidate()
 RETURNS TABLE(writer_xid text, operation_ordinal text, effect_generation text, empty_scope text, metadata_source text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; name text; relation_oid oid;
 kind "char"; populated boolean; filtered boolean; context jsonb; configuration truss.operation_configuration%ROWTYPE;
 metadata jsonb;
 metadata_names text[]:=ARRAY['source_epoch_registry','source_epoch_current','operation_configuration','installation_admission'];
 scope_names text[]:=ARRAY['object','edge','edge_limit','key_tombstone','record_source',
 'feed_consumer','journal','row_home_journal_stage','row_home_state','row_home_node',
 'row_home_scalar','row_home_touch','row_home_capacity','key_bucket_guard',
 'object_key_bucket','object_key_reservation_bucket','feed_tx','feed_member',
 'feed_prerequisite','feed_configuration_prerequisite','complete_feed_consumer',
 'complete_feed_administration_receipt','complete_feed_seed_attempt',
 'complete_feed_seed_artifact','key_lifecycle_history','key_migration_receipt',
 'catalog_revision_custody','request_receipt_route_guard','request_receipt','request_receipt_protection',
 'schema_change'];
BEGIN
 IF pg_catalog.current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'fresh statement snapshots required for empty graph evidence' USING ERRCODE='0A000';
 END IF;
 IF current_user IS DISTINCT FROM session_user OR NOT EXISTS(
  SELECT 1 FROM pg_roles r WHERE r.rolname=current_user AND r.rolsuper) THEN
  RAISE EXCEPTION 'administrative original visible graph profile required' USING ERRCODE='42501';
 END IF;
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.phase<>'application_finalized';
 IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted'
  OR (SELECT count(*) FROM truss.row_home_operation)<>1 THEN
  RAISE EXCEPTION 'one original fresh catalog operation required' USING ERRCODE='55000';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.granted
  AND l.relation='truss.schema_head'::regclass AND l.mode IN ('ExclusiveLock','AccessExclusiveLock')) THEN
  RAISE EXCEPTION 'original catalog exclusion required' USING ERRCODE='55000';
 END IF;
 -- Metadata is an explicit native correspondence producer, never an exemption
 -- selected by a caller flag. All application graph homes remain empty.
 SELECT * INTO STRICT configuration FROM truss.operation_configuration c
  WHERE c.original_writer_xid=op.original_writer_xid AND c.operation_ordinal=op.operation_ordinal;
 context:=convert_from(op.original_context_bytes,'UTF8')::jsonb;
 IF context->>'interfaceVersion' IS DISTINCT FROM 'truss-native-operation-context/0.4' THEN
  RAISE EXCEPTION 'original configured context required' USING ERRCODE='55000';
 END IF;
 PERFORM truss.runtime_require_operation_configuration_current(
  op.original_writer_xid::text,op.operation_ordinal::text,op.effect_generation::text);
 IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='truss' AND c.relkind IN ('r','p','f','v','m')
   AND NOT(c.relname=ANY(scope_names||metadata_names||ARRAY['setting','module_access','schema_rev',
    'schema_head','schema_doc','type_def','prop_def','key_def','rel_def','rel_endpoint',
    'row_home_operation','relationship_lineage','catalog_acceptance_report',
    'installation_marker','installation_archive','installation_admission']))) THEN
  RAISE EXCEPTION 'uncovered physical graph scope' USING ERRCODE='0A000';
 END IF;
 IF op.effect_generation=0 AND EXISTS(SELECT 1 FROM pg_locks l
  JOIN pg_class c ON c.oid=l.relation JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE l.pid=pg_backend_pid() AND l.granted AND l.mode IN ('RowExclusiveLock','ShareRowExclusiveLock','ExclusiveLock','AccessExclusiveLock')
   AND n.nspname='truss' AND c.relname=ANY(scope_names)) THEN
  RAISE EXCEPTION 'earlier graph writes cannot become an empty original start cut' USING ERRCODE='55000';
 END IF;
 -- First acquire every participating native relation lock, then inspect emptiness.
 -- NOWAIT refuses a competing raw writer instead of waiting/retrying.
 FOREACH name IN ARRAY scope_names||metadata_names LOOP
  relation_oid:=to_regclass(format('truss.%I',name));
  IF relation_oid IS NULL THEN
   RAISE EXCEPTION 'complete selected graph relation missing' USING ERRCODE='55000';
  END IF;
  EXECUTE format('LOCK TABLE truss.%I IN SHARE MODE NOWAIT',name);
  SELECT c.relkind,c.relrowsecurity INTO STRICT kind,filtered FROM pg_class c WHERE c.oid=relation_oid;
  IF filtered OR (name='journal' AND (kind<>'p' OR pg_get_partkeydef(relation_oid) IS DISTINCT FROM 'RANGE (at)'))
   OR (name<>'journal' AND kind<>'r')
   OR EXISTS(SELECT 1 FROM pg_inherits i WHERE i.inhparent=relation_oid OR i.inhrelid=relation_oid) THEN
   RAISE EXCEPTION 'selected ordinary graph and empty journal root topology required' USING ERRCODE='0A000';
  END IF;
 END LOOP;
 FOREACH name IN ARRAY scope_names LOOP
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM truss.%I)',name) INTO populated;
  IF populated THEN
   RAISE EXCEPTION 'nonempty graph needs original before/after effect report producer' USING ERRCODE='0A000';
  END IF;
 END LOOP;
 -- Acquire metadata table cuts before inspecting complete cardinality. The
 -- original current-context collector independently checks bytes/actor/epoch.
 IF (SELECT count(*) FROM truss.source_epoch_registry)<>1
  OR (SELECT count(*) FROM truss.source_epoch_current)<>1
  OR (SELECT count(*) FROM truss.operation_configuration)<>1
  OR (SELECT count(*) FROM truss.installation_admission)<>1
  OR NOT EXISTS(SELECT 1 FROM truss.source_epoch_registry r
    WHERE r.installation_id=configuration.installation_id AND r.source_epoch=configuration.source_epoch
     AND r.target_incarnation=configuration.target_incarnation AND r.transition_reason='initial'
     AND r.predecessor_epoch IS NULL AND encode(r.profile_bytes,'hex')=context->>'sourceEpochProfileHex'
     AND encode(r.evidence_bytes,'hex')=context->>'sourceEpochEvidenceHex'
     AND r.evidence_sha256=sha256(r.evidence_bytes))
  OR NOT EXISTS(SELECT 1 FROM truss.source_epoch_current c WHERE c.singleton_id=1
    AND c.installation_id=configuration.installation_id AND c.source_epoch=configuration.source_epoch) THEN
  RAISE EXCEPTION 'complete original first-installation metadata correspondence required' USING ERRCODE='55000';
 END IF;
 PERFORM truss.runtime_require_operation_configuration_current(
  op.original_writer_xid::text,op.operation_ordinal::text,op.effect_generation::text);
 metadata:=jsonb_build_object('interfaceVersion','truss-configured-catalog-metadata/0.1',
  'installationId',configuration.installation_id,'sourceEpoch',configuration.source_epoch,
  'targetIncarnation',configuration.target_incarnation,
  'configurationGeneration',configuration.configuration_generation::text,
  'contextSha256',encode(sha256(op.original_context_bytes),'hex'),
  'configurationSha256',encode(configuration.configuration_sha256,'hex'),
  'selectedBindingSha256',encode(configuration.selected_binding_sha256,'hex'),
  'installedInventorySha256',encode(configuration.installed_inventory_sha256,'hex'),
  'epochProfileSha256',encode(sha256(decode(context->>'sourceEpochProfileHex','hex')),'hex'),
  'epochEvidenceSha256',encode(sha256(decode(context->>'sourceEpochEvidenceHex','hex')),'hex'));
 RETURN QUERY SELECT op.original_writer_xid::text,op.operation_ordinal::text,
  op.effect_generation::text,jsonb_build_object('interfaceVersion','truss-configured-empty-graph/0.1',
   'businessRelations',to_jsonb(scope_names),'metadataUtf8Hex',encode(
    truss.runtime_capture_catalog_metadata_cut(op.original_writer_xid::text,op.operation_ordinal::text,op.effect_generation::text),'hex'))::text,metadata::text;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_collect_custody_catalog_lifecycle_candidate(expected_writer text, expected_ordinal text, expected_generation text, revision integer, original_policy bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; prestate jsonb; name text; expected_events bigint;
 policy_source bytea:=convert_to($policy${
  "identity": "truss-fresh-catalog-lifecycle",
  "version": "0.1.0",
  "selection": "first_revision_new_identities_only",
  "sourceComponentVersion": "0.15",
  "targetReportInterfaceVersion": "truss-acceptance-report/0.3.0-proposal",
  "governingRules": [
    "ADR-004",
    "CONTRACT-003-reactivation-inventory"
  ],
  "requiredOriginalState": "head_zero_empty_prior_catalog_and_history",
  "eventPlan": "insert_only_complete_source_bijection",
  "reactivations": "empty_after_original_absence_and_event_verification",
  "installedProfileAuthority": false
}
$policy$,'UTF8');
BEGIN
 IF current_user IS DISTINCT FROM session_user OR NOT EXISTS(
  SELECT 1 FROM pg_roles r WHERE r.rolname=current_user AND r.rolsuper) THEN
  RAISE EXCEPTION 'administrative lifecycle observation only' USING ERRCODE='42501';
 END IF;
 IF original_policy IS DISTINCT FROM policy_source THEN
  RAISE EXCEPTION 'original fresh lifecycle policy required' USING ERRCODE='55000';
 END IF;
 PERFORM truss.runtime_require_catalog_observation(expected_writer,expected_ordinal,expected_generation);
 PERFORM truss.runtime_require_catalog_lifecycle_observers();
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned();
 prestate:=convert_from(op.original_prestate_bytes,'UTF8')::jsonb;
 IF prestate->>'interfaceVersion' IS DISTINCT FROM 'truss-native-catalog-prestate/0.1'
  OR prestate->'head'->>'rev' IS DISTINCT FROM '0' OR revision IS DISTINCT FROM 1 THEN
  RAISE EXCEPTION 'original fresh lifecycle prestate required' USING ERRCODE='0A000';
 END IF;
 IF jsonb_typeof(prestate->'revisions') IS DISTINCT FROM 'array'
  OR jsonb_array_length(prestate->'revisions')<>1
  OR prestate->'revisions'->0->>'rev' IS DISTINCT FROM '0' THEN
  RAISE EXCEPTION 'only original bootstrap revision permitted' USING ERRCODE='0A000';
 END IF;
 FOREACH name IN ARRAY ARRAY['documents','types','properties','keys','keyHistory',
 'relationships','relationshipLineage','endpoints','reports'] LOOP
  IF prestate->name IS DISTINCT FROM '[]'::jsonb THEN
   RAISE EXCEPTION 'complete empty original lifecycle inventory required' USING ERRCODE='0A000';
  END IF;
 END LOOP;
 -- Original inventory producer independently matches all source/identity families.
 PERFORM * FROM truss.runtime_collect_new_catalog_inventory(revision);
 PERFORM truss.runtime_verify_new_catalog_prestate(revision);
 IF convert_from(op.original_context_bytes,'UTF8')::jsonb->>'interfaceVersion'='truss-native-operation-context/0.4' THEN
  PERFORM * FROM truss.runtime_collect_custody_catalog_graph_candidate();
 ELSE
  PERFORM * FROM truss.runtime_collect_empty_catalog_graph();
 END IF;
 IF EXISTS(SELECT 1 FROM truss.schema_change) OR EXISTS(SELECT 1 FROM truss.key_lifecycle_history)
  OR EXISTS(SELECT 1 FROM truss.catalog_acceptance_report) THEN
  RAISE EXCEPTION 'unexpected lifecycle history or publication' USING ERRCODE='55000';
 END IF;
 SELECT (SELECT count(*) FROM truss.schema_rev WHERE rev=revision)+(SELECT count(*) FROM truss.schema_doc)
  +(SELECT count(*) FROM truss.type_def)+(SELECT count(*) FROM truss.prop_def)
  +(SELECT count(*) FROM truss.key_def)+(SELECT count(*) FROM truss.rel_def)
  +(SELECT count(*) FROM truss.relationship_lineage)+(SELECT count(*) FROM truss.rel_endpoint)
 INTO expected_events;
 IF op.effect_generation IS DISTINCT FROM expected_events THEN
  RAISE EXCEPTION 'original insert-only lifecycle event plan required' USING ERRCODE='55000';
 END IF;
 PERFORM truss.runtime_require_catalog_observation(expected_writer,expected_ordinal,expected_generation);
 RETURN jsonb_build_object('scope','original_fresh_catalog_lifecycle_only',
  'policyHex',encode(policy_source,'hex'),'inputHex',encode(op.original_input_bytes,'hex'),
  'writerXid',expected_writer,'operationOrdinal',expected_ordinal,'effectGeneration',expected_generation,
  'revision',revision::text,'expectedInsertEvents',expected_events::text,
  'lifecycleProfile',jsonb_build_object('identity','truss-fresh-catalog-lifecycle','version','0.1.0','sha256',encode(sha256(policy_source),'hex')),
  'reactivations','[]'::jsonb,'acceptedReportQualified',false);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_collect_empty_catalog_graph()
 RETURNS TABLE(writer_xid text, operation_ordinal text, effect_generation text, empty_scope text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; name text; relation_oid oid;
 kind "char"; populated boolean; filtered boolean; metadata bytea; configured boolean:=false;
 scope_names text[]:=ARRAY['object','edge','edge_limit','key_tombstone','record_source',
 'feed_consumer','journal','row_home_journal_stage','row_home_state','row_home_node',
 'row_home_scalar','row_home_touch','row_home_capacity','key_bucket_guard',
 'object_key_bucket','object_key_reservation_bucket','feed_tx','feed_member',
 'feed_prerequisite','feed_configuration_prerequisite','complete_feed_consumer',
 'complete_feed_administration_receipt','complete_feed_seed_attempt',
 'complete_feed_seed_artifact','key_lifecycle_history','key_migration_receipt',
 'request_receipt_route_guard','request_receipt','request_receipt_protection',
 'schema_change'];
BEGIN
 IF pg_catalog.current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'fresh statement snapshots required for empty graph evidence' USING ERRCODE='0A000';
 END IF;
 IF current_user IS DISTINCT FROM session_user OR NOT EXISTS(
  SELECT 1 FROM pg_roles r WHERE r.rolname=current_user AND r.rolsuper) THEN
  RAISE EXCEPTION 'administrative original visible graph profile required' USING ERRCODE='42501';
 END IF;
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.phase<>'application_finalized';
 IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted'
  OR (SELECT count(*) FROM truss.row_home_operation)<>1 THEN
  RAISE EXCEPTION 'one original fresh catalog operation required' USING ERRCODE='55000';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.granted
  AND l.relation='truss.schema_head'::regclass AND l.mode IN ('ExclusiveLock','AccessExclusiveLock')) THEN
  RAISE EXCEPTION 'original catalog exclusion required' USING ERRCODE='55000';
 END IF;
 -- Source-epoch fixtures must be a complete empty pair. Populated installed
 -- epochs need their original authority producer; they cannot be exempted.
 IF (to_regclass('truss.source_epoch_current') IS NULL)
    IS DISTINCT FROM (to_regclass('truss.source_epoch_registry') IS NULL) THEN
  RAISE EXCEPTION 'complete source epoch relation pair required' USING ERRCODE='55000';
 END IF;
 IF convert_from(op.original_context_bytes,'UTF8')::jsonb->>'interfaceVersion'
   ='truss-native-operation-context/0.4' THEN
  configured:=true;
  metadata:=truss.runtime_capture_catalog_metadata_cut(op.original_writer_xid::text,
   op.operation_ordinal::text,op.effect_generation::text);
 ELSIF to_regclass('truss.source_epoch_current') IS NOT NULL THEN
  scope_names:=scope_names||ARRAY['source_epoch_registry','source_epoch_current'];
 END IF;
 IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='truss' AND c.relkind IN ('r','p','f','v','m')
   AND NOT(c.relname=ANY(scope_names||ARRAY['setting','module_access','schema_rev',
    'schema_head','schema_doc','type_def','prop_def','key_def','rel_def','rel_endpoint',
    'row_home_operation','relationship_lineage','catalog_acceptance_report',
    'installation_marker','installation_archive','installation_admission']||
    CASE WHEN configured THEN ARRAY['source_epoch_registry','source_epoch_current','operation_configuration']
     ELSE ARRAY[]::text[] END))) THEN
  RAISE EXCEPTION 'uncovered physical graph scope' USING ERRCODE='0A000';
 END IF;
 IF op.effect_generation=0 AND EXISTS(SELECT 1 FROM pg_locks l
  JOIN pg_class c ON c.oid=l.relation JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE l.pid=pg_backend_pid() AND l.granted AND l.mode IN ('RowExclusiveLock','ShareRowExclusiveLock','ExclusiveLock','AccessExclusiveLock')
   AND n.nspname='truss' AND c.relname=ANY(scope_names)) THEN
  RAISE EXCEPTION 'earlier graph writes cannot become an empty original start cut' USING ERRCODE='55000';
 END IF;
 -- First acquire every participating native relation lock, then inspect emptiness.
 -- NOWAIT refuses a competing raw writer instead of waiting/retrying.
 FOREACH name IN ARRAY scope_names LOOP
  relation_oid:=to_regclass(format('truss.%I',name));
  IF relation_oid IS NULL THEN
   RAISE EXCEPTION 'complete selected graph relation missing' USING ERRCODE='55000';
  END IF;
  EXECUTE format('LOCK TABLE truss.%I IN SHARE MODE NOWAIT',name);
  SELECT c.relkind,c.relrowsecurity INTO STRICT kind,filtered FROM pg_class c WHERE c.oid=relation_oid;
  IF filtered OR (name='journal' AND (kind<>'p' OR pg_get_partkeydef(relation_oid) IS DISTINCT FROM 'RANGE (at)'))
   OR (name<>'journal' AND kind<>'r')
   OR EXISTS(SELECT 1 FROM pg_inherits i WHERE i.inhparent=relation_oid OR i.inhrelid=relation_oid) THEN
   RAISE EXCEPTION 'selected ordinary graph and empty journal root topology required' USING ERRCODE='0A000';
  END IF;
 END LOOP;
 FOREACH name IN ARRAY scope_names LOOP
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM truss.%I)',name) INTO populated;
  IF populated THEN
   RAISE EXCEPTION 'nonempty graph needs original before/after effect report producer' USING ERRCODE='0A000';
  END IF;
 END LOOP;
 RETURN QUERY SELECT op.original_writer_xid::text,op.operation_ordinal::text,
  op.effect_generation::text,CASE WHEN configured THEN
   jsonb_build_object('interfaceVersion','truss-configured-empty-graph/0.1',
    'businessRelations',to_jsonb(scope_names),'metadataUtf8Hex',encode(metadata,'hex'))::text
   ELSE to_jsonb(scope_names)::text END;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_collect_finalizing_catalog_business_scope_candidate()
 RETURNS TABLE(writer_xid text, operation_ordinal text, effect_generation text, empty_scope text, metadata_source text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; name text; relation_oid oid;
 kind "char"; populated boolean; filtered boolean; context jsonb; configuration truss.operation_configuration%ROWTYPE;
 metadata jsonb;
 metadata_names text[]:=ARRAY['source_epoch_registry','source_epoch_current','operation_configuration','installation_admission','feed_tx','feed_member','feed_prerequisite','feed_configuration_prerequisite','catalog_revision_custody'];
 scope_names text[]:=ARRAY['object','edge','edge_limit','key_tombstone','record_source',
 'feed_consumer','journal','row_home_journal_stage','row_home_state','row_home_node',
 'row_home_scalar','row_home_touch','row_home_capacity','key_bucket_guard',
 'object_key_bucket','object_key_reservation_bucket',
 'complete_feed_consumer',
 'complete_feed_administration_receipt','complete_feed_seed_attempt',
 'complete_feed_seed_artifact','key_lifecycle_history','key_migration_receipt',
 'request_receipt_route_guard','request_receipt','request_receipt_protection',
 'schema_change'];
BEGIN
 IF pg_catalog.current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'fresh statement snapshots required for empty graph evidence' USING ERRCODE='0A000';
 END IF;
 IF current_user IS DISTINCT FROM session_user OR NOT EXISTS(
  SELECT 1 FROM pg_roles r WHERE r.rolname=current_user AND r.rolsuper) THEN
  RAISE EXCEPTION 'administrative original visible graph profile required' USING ERRCODE='42501';
 END IF;
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.phase<>'application_finalized';
 IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted'
  OR (SELECT count(*) FROM truss.row_home_operation)<>1 THEN
  RAISE EXCEPTION 'one original fresh catalog operation required' USING ERRCODE='55000';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.granted
  AND l.relation='truss.schema_head'::regclass AND l.mode IN ('ExclusiveLock','AccessExclusiveLock')) THEN
  RAISE EXCEPTION 'original catalog exclusion required' USING ERRCODE='55000';
 END IF;
 -- Metadata is an explicit native correspondence producer, never an exemption
 -- selected by a caller flag. All application graph homes remain empty.
 SELECT * INTO STRICT configuration FROM truss.operation_configuration c
  WHERE c.original_writer_xid=op.original_writer_xid AND c.operation_ordinal=op.operation_ordinal;
 context:=convert_from(op.original_context_bytes,'UTF8')::jsonb;
 IF context->>'interfaceVersion' IS DISTINCT FROM 'truss-native-operation-context/0.4' THEN
  RAISE EXCEPTION 'original configured context required' USING ERRCODE='55000';
 END IF;
 PERFORM truss.runtime_require_operation_configuration_current(
  op.original_writer_xid::text,op.operation_ordinal::text,op.effect_generation::text);
 IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='truss' AND c.relkind IN ('r','p','f','v','m')
   AND NOT(c.relname=ANY(scope_names||metadata_names||ARRAY['setting','module_access','schema_rev',
    'schema_head','schema_doc','type_def','prop_def','key_def','rel_def','rel_endpoint',
    'row_home_operation','relationship_lineage','catalog_acceptance_report',
    'installation_marker','installation_archive','installation_admission']))) THEN
  RAISE EXCEPTION 'uncovered physical graph scope' USING ERRCODE='0A000';
 END IF;
 IF op.effect_generation=0 AND EXISTS(SELECT 1 FROM pg_locks l
  JOIN pg_class c ON c.oid=l.relation JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE l.pid=pg_backend_pid() AND l.granted AND l.mode IN ('RowExclusiveLock','ShareRowExclusiveLock','ExclusiveLock','AccessExclusiveLock')
   AND n.nspname='truss' AND c.relname=ANY(scope_names)) THEN
  RAISE EXCEPTION 'earlier graph writes cannot become an empty original start cut' USING ERRCODE='55000';
 END IF;
 -- First acquire every participating native relation lock, then inspect emptiness.
 -- NOWAIT refuses a competing raw writer instead of waiting/retrying.
 FOREACH name IN ARRAY scope_names||metadata_names LOOP
  relation_oid:=to_regclass(format('truss.%I',name));
  IF relation_oid IS NULL THEN
   RAISE EXCEPTION 'complete selected graph relation missing' USING ERRCODE='55000';
  END IF;
  EXECUTE format('LOCK TABLE truss.%I IN SHARE MODE NOWAIT',name);
  SELECT c.relkind,c.relrowsecurity INTO STRICT kind,filtered FROM pg_class c WHERE c.oid=relation_oid;
  IF filtered OR (name='journal' AND (kind<>'p' OR pg_get_partkeydef(relation_oid) IS DISTINCT FROM 'RANGE (at)'))
   OR (name<>'journal' AND kind<>'r')
   OR EXISTS(SELECT 1 FROM pg_inherits i WHERE i.inhparent=relation_oid OR i.inhrelid=relation_oid) THEN
   RAISE EXCEPTION 'selected ordinary graph and empty journal root topology required' USING ERRCODE='0A000';
  END IF;
 END LOOP;
 FOREACH name IN ARRAY scope_names LOOP
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM truss.%I)',name) INTO populated;
  IF populated THEN
   RAISE EXCEPTION 'nonempty graph needs original before/after effect report producer' USING ERRCODE='0A000';
  END IF;
 END LOOP;
 -- Acquire metadata table cuts before inspecting complete cardinality. The
 -- original current-context collector independently checks bytes/actor/epoch.
 IF (SELECT count(*) FROM truss.source_epoch_registry)<>1
  OR (SELECT count(*) FROM truss.source_epoch_current)<>1
  OR (SELECT count(*) FROM truss.operation_configuration)<>1
  OR (SELECT count(*) FROM truss.installation_admission)<>1
  OR NOT EXISTS(SELECT 1 FROM truss.source_epoch_registry r
    WHERE r.installation_id=configuration.installation_id AND r.source_epoch=configuration.source_epoch
     AND r.target_incarnation=configuration.target_incarnation AND r.transition_reason='initial'
     AND r.predecessor_epoch IS NULL AND encode(r.profile_bytes,'hex')=context->>'sourceEpochProfileHex'
     AND encode(r.evidence_bytes,'hex')=context->>'sourceEpochEvidenceHex'
     AND r.evidence_sha256=sha256(r.evidence_bytes))
  OR NOT EXISTS(SELECT 1 FROM truss.source_epoch_current c WHERE c.singleton_id=1
    AND c.installation_id=configuration.installation_id AND c.source_epoch=configuration.source_epoch) THEN
  RAISE EXCEPTION 'complete original first-installation metadata correspondence required' USING ERRCODE='55000';
 END IF;
 PERFORM truss.runtime_require_operation_configuration_current(
  op.original_writer_xid::text,op.operation_ordinal::text,op.effect_generation::text);
 metadata:=jsonb_build_object('interfaceVersion','truss-configured-catalog-metadata/0.1',
  'installationId',configuration.installation_id,'sourceEpoch',configuration.source_epoch,
  'targetIncarnation',configuration.target_incarnation,
  'configurationGeneration',configuration.configuration_generation::text,
  'contextSha256',encode(sha256(op.original_context_bytes),'hex'),
  'configurationSha256',encode(configuration.configuration_sha256,'hex'),
  'selectedBindingSha256',encode(configuration.selected_binding_sha256,'hex'),
  'installedInventorySha256',encode(configuration.installed_inventory_sha256,'hex'),
  'epochProfileSha256',encode(sha256(decode(context->>'sourceEpochProfileHex','hex')),'hex'),
  'epochEvidenceSha256',encode(sha256(decode(context->>'sourceEpochEvidenceHex','hex')),'hex'));
 RETURN QUERY SELECT op.original_writer_xid::text,op.operation_ordinal::text,
  op.effect_generation::text,jsonb_build_object('interfaceVersion','truss-configured-empty-graph/0.1',
   'businessRelations',to_jsonb(scope_names),'metadataUtf8Hex',encode(
    truss.runtime_capture_catalog_metadata_cut(op.original_writer_xid::text,op.operation_ordinal::text,op.effect_generation::text),'hex'))::text,metadata::text;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_collect_fresh_catalog_lifecycle(expected_writer text, expected_ordinal text, expected_generation text, revision integer, original_policy bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; prestate jsonb; name text; expected_events bigint;
 policy_source bytea:=convert_to($policy${
  "identity": "truss-fresh-catalog-lifecycle",
  "version": "0.1.0",
  "selection": "first_revision_new_identities_only",
  "sourceComponentVersion": "0.15",
  "targetReportInterfaceVersion": "truss-acceptance-report/0.3.0-proposal",
  "governingRules": [
    "ADR-004",
    "CONTRACT-003-reactivation-inventory"
  ],
  "requiredOriginalState": "head_zero_empty_prior_catalog_and_history",
  "eventPlan": "insert_only_complete_source_bijection",
  "reactivations": "empty_after_original_absence_and_event_verification",
  "installedProfileAuthority": false
}
$policy$,'UTF8');
BEGIN
 IF current_user IS DISTINCT FROM session_user OR NOT EXISTS(
  SELECT 1 FROM pg_roles r WHERE r.rolname=current_user AND r.rolsuper) THEN
  RAISE EXCEPTION 'administrative lifecycle observation only' USING ERRCODE='42501';
 END IF;
 IF original_policy IS DISTINCT FROM policy_source THEN
  RAISE EXCEPTION 'original fresh lifecycle policy required' USING ERRCODE='55000';
 END IF;
 PERFORM truss.runtime_require_catalog_observation(expected_writer,expected_ordinal,expected_generation);
 PERFORM truss.runtime_require_catalog_lifecycle_observers();
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned();
 prestate:=convert_from(op.original_prestate_bytes,'UTF8')::jsonb;
 IF prestate->>'interfaceVersion' IS DISTINCT FROM 'truss-native-catalog-prestate/0.1'
  OR prestate->'head'->>'rev' IS DISTINCT FROM '0' OR revision IS DISTINCT FROM 1 THEN
  RAISE EXCEPTION 'original fresh lifecycle prestate required' USING ERRCODE='0A000';
 END IF;
 IF jsonb_typeof(prestate->'revisions') IS DISTINCT FROM 'array'
  OR jsonb_array_length(prestate->'revisions')<>1
  OR prestate->'revisions'->0->>'rev' IS DISTINCT FROM '0' THEN
  RAISE EXCEPTION 'only original bootstrap revision permitted' USING ERRCODE='0A000';
 END IF;
 FOREACH name IN ARRAY ARRAY['documents','types','properties','keys','keyHistory',
 'relationships','relationshipLineage','endpoints','reports'] LOOP
  IF prestate->name IS DISTINCT FROM '[]'::jsonb THEN
   RAISE EXCEPTION 'complete empty original lifecycle inventory required' USING ERRCODE='0A000';
  END IF;
 END LOOP;
 -- Original inventory producer independently matches all source/identity families.
 PERFORM * FROM truss.runtime_collect_new_catalog_inventory(revision);
 PERFORM truss.runtime_verify_new_catalog_prestate(revision);
 IF convert_from(op.original_context_bytes,'UTF8')::jsonb->>'interfaceVersion'='truss-native-operation-context/0.4' THEN
  PERFORM * FROM truss.runtime_collect_configured_catalog_graph();
 ELSE
  PERFORM * FROM truss.runtime_collect_empty_catalog_graph();
 END IF;
 IF EXISTS(SELECT 1 FROM truss.schema_change) OR EXISTS(SELECT 1 FROM truss.key_lifecycle_history)
  OR EXISTS(SELECT 1 FROM truss.catalog_acceptance_report) THEN
  RAISE EXCEPTION 'unexpected lifecycle history or publication' USING ERRCODE='55000';
 END IF;
 SELECT (SELECT count(*) FROM truss.schema_rev WHERE rev=revision)+(SELECT count(*) FROM truss.schema_doc)
  +(SELECT count(*) FROM truss.type_def)+(SELECT count(*) FROM truss.prop_def)
  +(SELECT count(*) FROM truss.key_def)+(SELECT count(*) FROM truss.rel_def)
  +(SELECT count(*) FROM truss.relationship_lineage)+(SELECT count(*) FROM truss.rel_endpoint)
 INTO expected_events;
 IF op.effect_generation IS DISTINCT FROM expected_events THEN
  RAISE EXCEPTION 'original insert-only lifecycle event plan required' USING ERRCODE='55000';
 END IF;
 PERFORM truss.runtime_require_catalog_observation(expected_writer,expected_ordinal,expected_generation);
 RETURN jsonb_build_object('scope','original_fresh_catalog_lifecycle_only',
  'policyHex',encode(policy_source,'hex'),'inputHex',encode(op.original_input_bytes,'hex'),
  'writerXid',expected_writer,'operationOrdinal',expected_ordinal,'effectGeneration',expected_generation,
  'revision',revision::text,'expectedInsertEvents',expected_events::text,
  'lifecycleProfile',jsonb_build_object('identity','truss-fresh-catalog-lifecycle','version','0.1.0','sha256',encode(sha256(policy_source),'hex')),
  'reactivations','[]'::jsonb,'acceptedReportQualified',false);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_collect_new_catalog_inventory(original_revision integer)
 RETURNS TABLE(family text, identity jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; original_input jsonb;
BEGIN
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.phase<>'application_finalized' FOR UPDATE;
 IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted' THEN
  RAISE EXCEPTION 'original complete catalog inventory admission required' USING ERRCODE='55000';
 END IF;
 original_input:=convert_from(op.original_input_bytes,'UTF8')::jsonb;
 IF original_input->>'interfaceVersion' IS DISTINCT FROM 'truss-acceptance-input/0.1.0'
  OR original_input->'binding' IS DISTINCT FROM jsonb_build_object('state','absent') THEN
  RAISE EXCEPTION 'registered binding effect inventory required' USING ERRCODE='0A000';
 END IF;
 RETURN QUERY SELECT * FROM truss.runtime_collect_new_core_catalog_inventory(original_revision);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_collect_report_documents(original_revision integer)
 RETURNS TABLE(doc_id text, doc_revision text, content_sha256 text, ord text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; source truss.schema_doc%ROWTYPE;
 count_documents bigint; distinct_documents bigint; first_ordinal int; last_ordinal int;
 total_bytes bigint;
BEGIN
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned()
   AND o.phase<>'application_finalized' FOR UPDATE;
 IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted'
   OR original_revision IS NULL OR original_revision<=0 THEN
  RAISE EXCEPTION 'original positive catalog admission required' USING ERRCODE='55000';
 END IF;
 LOCK TABLE truss.schema_head IN EXCLUSIVE MODE;
 IF NOT EXISTS(SELECT 1 FROM truss.schema_rev r WHERE r.rev=original_revision) THEN
  RAISE EXCEPTION 'original revision archive required' USING ERRCODE='55000';
 END IF;
 SELECT count(*),count(DISTINCT d.doc_id COLLATE "C"),min(d.ord),max(d.ord),
  coalesce(sum(octet_length(d.document)::bigint),0)
 INTO count_documents,distinct_documents,first_ordinal,last_ordinal,total_bytes
 FROM truss.schema_doc d WHERE d.rev=original_revision;
 IF count_documents>512 OR total_bytes>4194304 THEN
  RAISE EXCEPTION 'report document archive capacity exceeded' USING ERRCODE='54000';
 END IF;
 IF count_documents=0 OR distinct_documents<>count_documents
  OR first_ordinal<>0 OR last_ordinal::bigint<>count_documents-1 THEN
  RAISE EXCEPTION 'complete unique ordered document archive required' USING ERRCODE='55000';
 END IF;
 -- Complete preflight precedes result emission; no caller-supplied document inventory.
 FOR source IN SELECT d.* FROM truss.schema_doc d
  WHERE d.rev=original_revision ORDER BY d.ord LOOP
  IF source.doc_id IS NULL OR octet_length(source.doc_id) NOT BETWEEN 1 AND 4096
   OR source.doc_revision IS NULL OR octet_length(source.doc_revision) NOT BETWEEN 1 AND 4096 THEN
   RAISE EXCEPTION 'bounded original report document metadata required' USING ERRCODE='55000';
  END IF;
  PERFORM truss.runtime_verify_catalog_document(original_revision,source.doc_id);
 END LOOP;
 RETURN QUERY SELECT d.doc_id,d.doc_revision,d.content_sha256,d.ord::text
  FROM truss.schema_doc d WHERE d.rev=original_revision ORDER BY d.ord;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_finalize_original_catalog_feed_candidate(w text, o text, g text)
 RETURNS TABLE(tree_bytes_hex text, wire_bytes_hex text, semantic_sha256_hex text, membership_generation text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO, YMD'
 SET bytea_output TO 'hex'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; cfg truss.operation_configuration%ROWTYPE;
 custody truss.catalog_revision_custody%ROWTYPE; parent truss.feed_tx%ROWTYPE;
 member truss.feed_member%ROWTYPE; expected_member truss.feed_member%ROWTYPE;
 expected_parent truss.feed_tx%ROWTYPE; docrow truss.feed_prerequisite%ROWTYPE;
 cfgrow truss.feed_configuration_prerequisite%ROWTYPE;
 cfgplan truss.feed_configuration_prerequisite%ROWTYPE;
 context jsonb; input jsonb; recipe jsonb; original bytea; sources jsonb:='{}'::jsonb;
 definition bytea; cfg_profile bytea; manifest record; returned record;
 name text; identity text; document jsonb; doc_identity text; seen jsonb:='{}'::jsonb;
 before_state jsonb; after_state jsonb; expected_state jsonb; expected_docs bytea[]:=ARRAY[]::bytea[];
 actual_docs bytea[]; cfg_capsule jsonb; cfg_artifact bytea; address bigint:=0; finalized boolean;
 expected_return jsonb; clear_return jsonb; original_custody bytea; original_operation bytea; original_configuration bytea; recipe_bytes bytea;
BEGIN
 -- This composition guard must be independently selected with the new complete
 -- roster/definition before parent creation. Old rosters are not reinterpreted.
 PERFORM truss.runtime_require_catalog_finalization_composition_candidate(w,o,g);
 SELECT * INTO STRICT op FROM truss.row_home_operation t WHERE t.original_writer_xid=pg_current_xact_id_if_assigned()
  AND t.operation_ordinal::text=o FOR UPDATE NOWAIT;
 SELECT * INTO STRICT cfg FROM truss.operation_configuration t WHERE t.original_writer_xid=op.original_writer_xid AND t.operation_ordinal=op.operation_ordinal FOR SHARE NOWAIT;
 SELECT * INTO STRICT custody FROM truss.catalog_revision_custody t WHERE t.original_writer_xid=op.original_writer_xid AND t.operation_ordinal=op.operation_ordinal FOR SHARE NOWAIT;
 original_custody:=record_send(custody);original_operation:=record_send(op);original_configuration:=record_send(cfg);context:=convert_from(op.original_context_bytes,'UTF8')::jsonb;
 IF op.effect_generation::text IS DISTINCT FROM g OR custody.capture_generation::text IS DISTINCT FROM g
  OR op.original_writer_xid::text IS DISTINCT FROM w OR cfg.source_epoch IS DISTINCT FROM context->>'sourceEpoch'
  OR cfg.installation_id IS DISTINCT FROM context->>'installationId'
  OR (SELECT count(*) FROM truss.row_home_operation)<>1 OR (SELECT count(*) FROM truss.catalog_revision_custody)<>1
  OR (SELECT count(*) FROM truss.schema_head)<>1 OR NOT EXISTS(SELECT 1 FROM truss.schema_head WHERE id=1 AND rev=0) THEN
  RAISE EXCEPTION 'single original pending catalog scope required' USING ERRCODE='55000'; END IF;
 PERFORM truss.runtime_require_finalizing_custody_correspondence_candidate(w,o,g);
 PERFORM truss.runtime_collect_finalizing_catalog_business_scope_candidate();
 LOCK TABLE truss.feed_tx,truss.feed_member,truss.feed_prerequisite,truss.feed_configuration_prerequisite IN SHARE ROW EXCLUSIVE MODE NOWAIT;
 LOCK TABLE truss.installation_archive IN SHARE MODE NOWAIT;
 PERFORM truss.runtime_require_selected_archive_write_fence();
 identity:='packages/python/src/truss/_profiles/catalog-feed-finalization-candidate.json';
 SELECT a.artifact_bytes INTO STRICT recipe_bytes FROM truss.installation_archive a
  WHERE a.installation_id=cfg.installation_id AND a.artifact_role='input' AND a.artifact_identity=identity
  AND a.artifact_sha256=sha256(a.artifact_bytes) AND a.artifact_identity_sha256=sha256(convert_to(a.artifact_identity,'UTF8'));
 -- The entry guard pins this exact recipe and all dependency bytes independently.
 recipe:=convert_from(recipe_bytes,'UTF8')::jsonb;
 definition:=decode(recipe->>'manifestDefinitionHex','hex');
 cfg_profile:=decode(recipe->>'configurationProfileHex','hex');
 FOREACH name IN ARRAY ARRAY['clear-parent','clear-member','assign-ordinal','publish-manifest'] LOOP
  identity:=recipe->'sources'->name->>'path';
  SELECT a.artifact_bytes INTO STRICT original FROM truss.installation_archive a
   WHERE a.installation_id=cfg.installation_id AND a.artifact_role='input' AND a.artifact_identity=identity
   AND a.artifact_sha256=sha256(a.artifact_bytes) AND encode(a.artifact_sha256,'hex')=recipe->'sources'->name->>'sha256'
   AND a.artifact_identity_sha256=sha256(convert_to(a.artifact_identity,'UTF8'));
  IF octet_length(original)>16384 THEN RAISE EXCEPTION 'finalization statement capacity' USING ERRCODE='54000'; END IF;
  sources:=sources||jsonb_build_object(name,convert_from(original,'UTF8'));
 END LOOP;
 SELECT * INTO STRICT parent FROM truss.feed_tx;
 SELECT * INTO STRICT member FROM truss.feed_member;
 before_state:=truss.runtime_capture_finalizing_completion_state_candidate(w,o,g);expected_state:=before_state;
 cfg_capsule:=jsonb_build_object('installationId',cfg.installation_id,'sourceEpoch',cfg.source_epoch,
  'targetIncarnation',cfg.target_incarnation,'generation',cfg.configuration_generation::text,
  'keyReuse',cfg.key_reuse,'journalMode',cfg.journal_mode,'admissionProfileHex',encode(cfg.admission_profile_bytes,'hex'),
  'configurationHex',encode(cfg.configuration_bytes,'hex'),'bindingHex',encode(cfg.selected_binding_bytes,'hex'),
  'inventoryHex',encode(cfg.installed_inventory_bytes,'hex'));
 SELECT * INTO STRICT manifest FROM truss.runtime_original_catalog_manifest_candidate(
  op.original_input_bytes,custody.original_revision::text,op.original_writer_xid::text,
  jsonb_build_object('sourceEpoch',cfg.source_epoch,'feedProfile',recipe->>'feedProfile',
   'scopeIdentity','administrative_single_original_operation_fresh_catalog_rollback_only'),
  definition,custody.original_payload_profile_bytes,custody.original_payload_bytes,
  convert_to(cfg_capsule::text,'UTF8'),cfg_profile);
 cfg_artifact:=decode((convert_from(manifest.manifest_bytes,'UTF8')::jsonb->'configurationPrerequisites'->0->'artifact'->>'bytesBase64'),'base64');
 expected_member.source_epoch:=cfg.source_epoch;expected_member.feed_profile:=recipe->>'feedProfile';
 expected_member.original_writer_xid:=op.original_writer_xid;expected_member.registration_address:=1;
 expected_member.fact_kind:='revision';expected_member.original_fact_key_bytes:=custody.original_fact_key_bytes;
 expected_member.original_fact_key_profile_bytes:=custody.original_fact_key_profile_bytes;
 expected_member.original_payload_bytes:=custody.original_payload_bytes;
 expected_member.original_payload_profile_bytes:=custody.original_payload_profile_bytes;
 expected_member.original_payload_sha256:=sha256(custody.original_payload_bytes);
 expected_member.original_owner_context_bytes:=custody.original_owner_context_bytes;
 expected_member.original_write_at:=custody.original_write_at;expected_member.original_fact_clock_bytes:=custody.original_fact_clock_bytes;
 -- Independently reconstruct every document prerequisite in original registration order.
 input:=convert_from(op.original_input_bytes,'UTF8')::jsonb;
 FOR document IN SELECT value FROM jsonb_array_elements(input->'documents') LOOP
  doc_identity:=document->'artifact'->>'identity';
  IF seen ? doc_identity THEN CONTINUE; END IF;
  seen:=seen||jsonb_build_object(doc_identity,true);address:=address+1;
  docrow:=NULL;docrow.source_epoch:=cfg.source_epoch;docrow.feed_profile:=recipe->>'feedProfile';
  docrow.original_writer_xid:=op.original_writer_xid;docrow.prerequisite_address:=address;
  docrow.original_revision:=custody.original_revision;
  docrow.original_artifact_identity_bytes:=convert_to(doc_identity,'UTF8');
  docrow.original_definition_bytes:=decode(document->'artifact'->>'bytesBase64','base64');
  docrow.original_definition_profile_bytes:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(document->'umfProfile'));
  docrow.original_definition_sha256:=sha256(docrow.original_definition_bytes);
  docrow.original_owner_context_bytes:=custody.original_owner_context_bytes;
  expected_docs:=array_append(expected_docs,record_send(docrow));
 END LOOP;
 SELECT array_agg(record_send(p) ORDER BY p.prerequisite_address) INTO actual_docs FROM truss.feed_prerequisite p;
 cfgplan.source_epoch:=cfg.source_epoch;cfgplan.feed_profile:=recipe->>'feedProfile';cfgplan.original_writer_xid:=op.original_writer_xid;
 cfgplan.configuration_address:=1;cfgplan.original_installation_identity_bytes:=convert_to(cfg.installation_id,'UTF8');
 cfgplan.original_configuration_generation:=cfg.configuration_generation;
 cfgplan.original_configuration_profile_bytes:=cfg_profile;cfgplan.original_configuration_bytes:=cfg_artifact;
 cfgplan.original_producer_inventory_bytes:=cfg.installed_inventory_bytes;cfgplan.original_configuration_sha256:=sha256(cfg_artifact);
 cfgplan.original_owner_context_bytes:=custody.original_owner_context_bytes;
 SELECT * INTO STRICT cfgrow FROM truss.feed_configuration_prerequisite;
 expected_parent.source_epoch:=cfg.source_epoch;expected_parent.feed_profile:=recipe->>'feedProfile';
 expected_parent.original_writer_xid:=op.original_writer_xid;expected_parent.registration_counter:=1;
 expected_parent.prerequisite_registration_counter:=address;expected_parent.configuration_registration_counter:=1;
 expected_parent.membership_generation:=address+2;expected_parent.original_context_bytes:=op.original_context_bytes;
 expected_parent.manifest_profile_bytes:=definition;
 finalized:=parent.finalized_generation IS NOT NULL;
 IF finalized THEN
  expected_parent.finalized_generation:=address+2;expected_parent.manifest_bytes:=manifest.tree_bytes;
  expected_parent.manifest_sha256:=manifest.semantic_sha256;expected_member.delivery_ordinal:=0;
 END IF;
 IF (SELECT count(*) FROM truss.feed_tx)<>1 OR (SELECT count(*) FROM truss.feed_member)<>1
  OR (SELECT count(*) FROM truss.feed_configuration_prerequisite)<>1
  OR record_send(parent) IS DISTINCT FROM record_send(expected_parent)
  OR record_send(member) IS DISTINCT FROM record_send(expected_member)
  OR record_send(cfgrow) IS DISTINCT FROM record_send(cfgplan) OR actual_docs IS DISTINCT FROM expected_docs THEN
  RAISE EXCEPTION 'complete original feed registration correspondence required' USING ERRCODE='55000'; END IF;
 -- All originals and current full records passed before the first publication effect.
 expected_parent.finalized_generation:=NULL;expected_parent.manifest_bytes:=NULL;expected_parent.manifest_sha256:=NULL;
 clear_return:=jsonb_build_object('source_epoch',cfg.source_epoch,'feed_profile',expected_parent.feed_profile,
  'original_writer_xid',w,'membership_generation',(address+2)::text,'finalized_generation',NULL,'manifest_bytes_hex',NULL,'manifest_sha256_hex',NULL);
 EXECUTE sources->>'clear-parent' INTO STRICT returned USING cfg.source_epoch,expected_parent.feed_profile,address+2;
 IF to_jsonb(returned) IS DISTINCT FROM clear_return OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(expected_parent)) THEN
  RAISE EXCEPTION 'full original parent clear correspondence required' USING ERRCODE='55000'; END IF;
 expected_state:=jsonb_set(expected_state,'{stores,feed_tx}',jsonb_build_array(encode(record_send(expected_parent),'hex')));
 after_state:=truss.runtime_capture_finalizing_completion_state_candidate(w,o,g);
 IF after_state IS DISTINCT FROM expected_state THEN RAISE EXCEPTION 'complete parent clear state delta required' USING ERRCODE='55000'; END IF;
 expected_member.delivery_ordinal:=NULL;
 expected_return:=jsonb_build_object('source_epoch',cfg.source_epoch,'feed_profile',expected_parent.feed_profile,
  'original_writer_xid',w,'registration_address','1','delivery_ordinal',NULL);
 EXECUTE sources->>'clear-member' INTO STRICT returned USING cfg.source_epoch,expected_parent.feed_profile;
 IF to_jsonb(returned) IS DISTINCT FROM expected_return OR NOT EXISTS(SELECT 1 FROM truss.feed_member t WHERE record_send(t)=record_send(expected_member)) THEN
  RAISE EXCEPTION 'full original member clear correspondence required' USING ERRCODE='55000'; END IF;
 expected_state:=jsonb_set(expected_state,'{stores,feed_member}',jsonb_build_array(encode(record_send(expected_member),'hex')));
 after_state:=truss.runtime_capture_finalizing_completion_state_candidate(w,o,g);
 IF after_state IS DISTINCT FROM expected_state THEN RAISE EXCEPTION 'complete member clear state delta required' USING ERRCODE='55000'; END IF;
 EXECUTE sources->>'assign-ordinal' INTO STRICT returned USING cfg.source_epoch,expected_parent.feed_profile,address+2,1::bigint,0::bigint;
 expected_return:=jsonb_set(expected_return,'{delivery_ordinal}','"0"');expected_member.delivery_ordinal:=0;
 IF to_jsonb(returned) IS DISTINCT FROM expected_return OR NOT EXISTS(SELECT 1 FROM truss.feed_member t WHERE record_send(t)=record_send(expected_member)) THEN
  RAISE EXCEPTION 'full original member ordinal correspondence required' USING ERRCODE='55000'; END IF;
 expected_state:=jsonb_set(expected_state,'{stores,feed_member}',jsonb_build_array(encode(record_send(expected_member),'hex')));
 after_state:=truss.runtime_capture_finalizing_completion_state_candidate(w,o,g);
 IF after_state IS DISTINCT FROM expected_state THEN RAISE EXCEPTION 'complete member ordinal state delta required' USING ERRCODE='55000'; END IF;
 EXECUTE sources->>'publish-manifest' INTO STRICT returned USING cfg.source_epoch,expected_parent.feed_profile,address+2,manifest.tree_bytes,manifest.semantic_sha256;
 expected_parent.finalized_generation:=address+2;expected_parent.manifest_bytes:=manifest.tree_bytes;expected_parent.manifest_sha256:=manifest.semantic_sha256;
 expected_return:=jsonb_set(jsonb_set(jsonb_set(clear_return,'{finalized_generation}',to_jsonb((address+2)::text)),
  '{manifest_bytes_hex}',to_jsonb(encode(manifest.tree_bytes,'hex'))),'{manifest_sha256_hex}',to_jsonb(encode(manifest.semantic_sha256,'hex')));
 IF to_jsonb(returned) IS DISTINCT FROM expected_return OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(expected_parent)) THEN
  RAISE EXCEPTION 'full original manifest publication correspondence required' USING ERRCODE='55000'; END IF;
 PERFORM truss.runtime_require_catalog_finalization_composition_candidate(w,o,g);
 after_state:=truss.runtime_capture_finalizing_completion_state_candidate(w,o,g);
 expected_state:=jsonb_set(expected_state,'{stores,feed_tx}',jsonb_build_array(encode(record_send(expected_parent),'hex')));
 expected_state:=jsonb_set(expected_state,'{stores,feed_member}',jsonb_build_array(encode(record_send(expected_member),'hex')));
 IF after_state IS DISTINCT FROM expected_state
  OR (SELECT count(*) FROM truss.row_home_operation)<>1 OR NOT EXISTS(SELECT 1 FROM truss.row_home_operation t WHERE record_send(t)=original_operation)
  OR (SELECT count(*) FROM truss.operation_configuration)<>1 OR NOT EXISTS(SELECT 1 FROM truss.operation_configuration t WHERE record_send(t)=original_configuration)
  OR (SELECT count(*) FROM truss.catalog_revision_custody)<>1 OR NOT EXISTS(SELECT 1 FROM truss.catalog_revision_custody t WHERE record_send(t)=original_custody)
  OR (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(expected_parent))
  OR (SELECT count(*) FROM truss.feed_member)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_member t WHERE record_send(t)=record_send(expected_member))
  OR (SELECT count(*) FROM truss.feed_configuration_prerequisite)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_configuration_prerequisite t WHERE record_send(t)=record_send(cfgplan))
  OR (SELECT array_agg(record_send(p) ORDER BY p.prerequisite_address) FROM truss.feed_prerequisite p) IS DISTINCT FROM expected_docs THEN
  RAISE EXCEPTION 'complete finalization state delta required' USING ERRCODE='55000'; END IF;
 RETURN QUERY SELECT encode(manifest.tree_bytes,'hex'),encode(manifest.manifest_bytes,'hex'),encode(manifest.semantic_sha256,'hex'),(address+2)::text;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_guard_operation_originals()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP<>'UPDATE' THEN RAISE EXCEPTION 'operation removal requires original retention admission' USING ERRCODE='55000'; END IF;
 IF OLD.phase='application_finalized' OR OLD.original_writer_xid IS DISTINCT FROM pg_current_xact_id_if_assigned()
  OR ROW(NEW.original_writer_xid,NEW.operation_ordinal,NEW.operation_kind,NEW.original_context_bytes,NEW.original_definition_bytes,NEW.original_input_bytes,NEW.original_prestate_bytes,NEW.admitted_candidate_bytes,NEW.effect_obligation_bytes,NEW.original_group_custody_bytes)
   IS DISTINCT FROM ROW(OLD.original_writer_xid,OLD.operation_ordinal,OLD.operation_kind,OLD.original_context_bytes,OLD.original_definition_bytes,OLD.original_input_bytes,OLD.original_prestate_bytes,OLD.admitted_candidate_bytes,OLD.effect_obligation_bytes,OLD.original_group_custody_bytes) THEN
  RAISE EXCEPTION 'original operation identity and artifact bytes are immutable' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_lineage_bytes(category text, document_id text, module_id text, element_id text)
 RETURNS bytea
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE d text:=truss.runtime_lineage_quote(document_id); m text:=truss.runtime_lineage_quote(module_id);
 e text:=truss.runtime_lineage_quote(element_id); payload text; profile text;
BEGIN
 IF category='record' THEN
  profile:='truss-type-lineage/0.1.0'; payload:='['||d||','||m||','||e||']';
 ELSIF category='authored' THEN
  profile:='truss-relationship-lineage-bytes/0.1.0';
  payload:='{"category":"authored","relationship":{"document":'||d||',"element":'||e||',"module":'||m||'}}';
 ELSE RAISE EXCEPTION 'unsupported lineage category' USING ERRCODE='22023'; END IF;
 RETURN convert_to('truss-canonical/0.1.0'||chr(10)||profile||chr(10)||payload,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_lineage_quote(value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result text := '"'; ch text; point int; i int;
BEGIN
 IF value IS NULL OR octet_length(value) NOT BETWEEN 1 AND 65536 THEN
  RAISE EXCEPTION 'bounded original identity required' USING ERRCODE='22023';
 END IF;
 FOR i IN 1..length(value) LOOP
  ch:=substr(value,i,1); point:=ascii(ch);
  IF point<32 THEN result:=result || chr(92) || 'u00' || lpad(to_hex(point),2,'0');
  ELSIF ch='"' OR ch=chr(92) THEN result:=result || chr(92) || ch;
  ELSE result:=result || ch; END IF;
 END LOOP;
 RETURN result || '"';
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_lock_source_epoch(expected_installation text, expected_epoch text, expected_incarnation text)
 RETURNS TABLE(installation_id text, source_epoch text, target_incarnation text, profile_hex text, evidence_hex text, evidence_sha256 text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE pointer truss.source_epoch_current%ROWTYPE;
 epoch truss.source_epoch_registry%ROWTYPE;
BEGIN
 IF current_user::text IS DISTINCT FROM (CASE WHEN current_setting('role')='none'
  THEN session_user::text ELSE current_setting('role') END) THEN
  RAISE EXCEPTION 'original invoker epoch boundary required' USING ERRCODE='55000';
 END IF;
 IF expected_installation IS NULL OR expected_epoch IS NULL OR expected_incarnation IS NULL
  OR octet_length(expected_installation) NOT BETWEEN 1 AND 1024
  OR octet_length(expected_epoch) NOT BETWEEN 1 AND 256
  OR octet_length(expected_incarnation) NOT BETWEEN 1 AND 1024 THEN
  RAISE EXCEPTION 'bounded original epoch comparison required' USING ERRCODE='55000';
 END IF;
 SELECT c.* INTO pointer FROM truss.source_epoch_current c WHERE c.singleton_id=1 FOR SHARE;
 IF NOT FOUND OR pointer.installation_id IS DISTINCT FROM expected_installation
  OR pointer.source_epoch IS DISTINCT FROM expected_epoch THEN
  RAISE EXCEPTION 'current source epoch correspondence required' USING ERRCODE='55000';
 END IF;
 SELECT r.* INTO epoch FROM truss.source_epoch_registry r
  WHERE r.installation_id=pointer.installation_id AND r.source_epoch=pointer.source_epoch;
 IF NOT FOUND OR epoch.target_incarnation IS DISTINCT FROM expected_incarnation
  OR epoch.evidence_sha256 IS DISTINCT FROM sha256(epoch.evidence_bytes) THEN
  RAISE EXCEPTION 'original epoch evidence correspondence required' USING ERRCODE='55000';
 END IF;
 RETURN QUERY SELECT epoch.installation_id,epoch.source_epoch,epoch.target_incarnation,
  encode(epoch.profile_bytes,'hex'),encode(epoch.evidence_bytes,'hex'),encode(epoch.evidence_sha256,'hex');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_manifest_artifact_tree_bytes_candidate(tree jsonb, original_documents bytea[], original_configuration bytea)
 RETURNS bytea
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE tasks jsonb[]:=ARRAY[jsonb_build_object('node',tree,'depth','0','path','root')]; task jsonb;
 node jsonb; member jsonb; children jsonb; tag text; piece bytea; chunk bytea:=decode('','hex');
 chunks bytea[]:=ARRAY[]::bytea[]; output bytea; i int; depth int; steps int:=0; emitted bigint:=0; configuration_base64 bytea; document_base64 bytea[]:=ARRAY[]::bytea[]; document_seen int[]; configuration_seen int:=0; original_document bytea; original_total bigint:=0; artifact_index int; expected_base64 bytea;
BEGIN
 IF original_documents IS NULL OR array_ndims(original_documents)<>1 OR array_lower(original_documents,1)<>1
  OR cardinality(original_documents) NOT BETWEEN 1 AND 512 OR original_configuration IS NULL
  OR octet_length(original_configuration) NOT BETWEEN 1 AND 4194304 THEN
  RAISE EXCEPTION 'bounded complete original manifest artifacts required' USING ERRCODE='54000'; END IF;
 FOREACH original_document IN ARRAY original_documents LOOP
  IF original_document IS NULL OR octet_length(original_document) NOT BETWEEN 1 AND 1048576 THEN
   RAISE EXCEPTION 'bounded original document required' USING ERRCODE='54000'; END IF;
  original_total:=original_total+octet_length(original_document);
 END LOOP;
 IF original_total>1048576 THEN RAISE EXCEPTION 'aggregate original document capacity' USING ERRCODE='54000'; END IF;
 FOREACH original_document IN ARRAY original_documents LOOP
  document_base64:=array_append(document_base64,convert_to(replace(encode(original_document,'base64'),chr(10),''),'UTF8'));
 END LOOP;
 document_seen:=array_fill(0,ARRAY[cardinality(original_documents)]);
 configuration_base64:=convert_to(replace(encode(original_configuration,'base64'),chr(10),''),'UTF8');
 IF tree IS NULL THEN RAISE EXCEPTION 'inert tree required' USING ERRCODE='22023'; END IF;
 IF octet_length(tree::text)>25165824 THEN RAISE EXCEPTION 'tree input capacity' USING ERRCODE='54000'; END IF;
 WHILE cardinality(tasks)>0 LOOP
  steps:=steps+1;
  IF steps>32768 OR cardinality(tasks)>16384 THEN RAISE EXCEPTION 'tree task capacity' USING ERRCODE='54000'; END IF;
  task:=tasks[cardinality(tasks)];tasks:=tasks[1:cardinality(tasks)-1];piece:=decode('','hex');
  IF task ? 'emit' THEN piece:=decode(task->>'emit','hex');
  ELSIF task ? 'frame' THEN
   children:=task->'children';tag:=task->>'frame';i:=(task->>'index')::int;depth:=(task->>'depth')::int;
   IF i=jsonb_array_length(children) THEN piece:=decode(CASE WHEN tag='array' THEN '5d' ELSE '7d' END,'hex');
   ELSE
    member:=children->i;
    tasks:=array_append(tasks,jsonb_set(task,'{index}',to_jsonb((i+1)::text)));
    tasks:=array_append(tasks,jsonb_build_object('node',CASE WHEN tag='array' THEN member ELSE member->'node' END,'depth',(depth+1)::text, 'path',CASE
     WHEN tag='object' AND task->>'path'='root' AND member->>'keyUtf8Hex'='70726572657175697369746573' THEN 'catalogList'
     WHEN tag='object' AND task->>'path'='root' AND member->>'keyUtf8Hex'='636f6e66696775726174696f6e50726572657175697369746573' THEN 'configurationList'
     WHEN tag='array' AND task->>'path'='catalogList' THEN 'catalog:'||i::text
     WHEN tag='array' AND task->>'path'='configurationList' THEN 'configuration:'||i::text
     WHEN tag='object' AND task->>'path' LIKE 'catalog:%' AND member->>'keyUtf8Hex'='6172746966616374' THEN 'catalogArtifact:'||split_part(task->>'path',':',2)
     WHEN tag='object' AND task->>'path'='configuration:0' AND member->>'keyUtf8Hex'='6172746966616374' THEN 'configurationArtifact'
     WHEN tag='object' AND task->>'path' LIKE 'catalogArtifact:%' AND member->>'keyUtf8Hex'='6279746573426173653634' THEN 'catalogBytes:'||split_part(task->>'path',':',2)
     WHEN tag='object' AND task->>'path'='configurationArtifact' AND member->>'keyUtf8Hex'='6279746573426173653634' THEN 'configurationBytes'
     ELSE 'other' END));
    IF tag='object' THEN
     tasks:=array_append(tasks,jsonb_build_object('emit','3a'));
     tasks:=array_append(tasks,jsonb_build_object('node',jsonb_build_object('kind','string','utf8Hex',member->>'keyUtf8Hex'),'depth',(depth+1)::text));
    END IF;
    IF i>0 THEN piece:=decode('2c','hex'); END IF;
   END IF;
  ELSE
   node:=task->'node';depth:=(task->>'depth')::int;
   IF depth>256 THEN RAISE EXCEPTION 'tree depth capacity' USING ERRCODE='54000'; END IF;
   IF node IS NULL OR jsonb_typeof(node)<>'object' OR jsonb_typeof(node->'kind') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'inert node shape' USING ERRCODE='22023'; END IF;
   tag:=node->>'kind';
   IF task->>'path'='root' AND tag IS DISTINCT FROM 'object'
    OR task->>'path' IN ('catalogList','configurationList') AND tag IS DISTINCT FROM 'array'
    OR (task->>'path' LIKE 'catalog:%' OR task->>'path' LIKE 'configuration:%'
     OR task->>'path' LIKE 'catalogArtifact:%' OR task->>'path'='configurationArtifact') AND tag IS DISTINCT FROM 'object'
    OR (task->>'path' LIKE 'catalogBytes:%' OR task->>'path'='configurationBytes') AND tag IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'closed original manifest artifact path kind required' USING ERRCODE='22023'; END IF;
   IF tag='null' AND (SELECT count(*) FROM jsonb_object_keys(node))=1 THEN piece:=convert_to('null','UTF8');
   ELSIF tag='boolean' AND (SELECT count(*) FROM jsonb_object_keys(node))=2 AND jsonb_typeof(node->'value')='boolean' THEN piece:=convert_to(node->>'value','UTF8');
   ELSIF tag='string' AND (SELECT count(*) FROM jsonb_object_keys(node))=2 AND jsonb_typeof(node->'utf8Hex')='string' AND node->>'utf8Hex' ~ '^([0-9a-f]{2})*$' THEN
    IF task->>'path' LIKE 'catalogBytes:%' OR task->>'path'='configurationBytes' THEN
     IF task->>'path'='configurationBytes' THEN expected_base64:=configuration_base64;configuration_seen:=configuration_seen+1;
     ELSE
      artifact_index:=split_part(task->>'path',':',2)::int+1;
      IF artifact_index NOT BETWEEN 1 AND cardinality(document_base64) THEN
       RAISE EXCEPTION 'original document slot correspondence required' USING ERRCODE='55000'; END IF;
      expected_base64:=document_base64[artifact_index];document_seen[artifact_index]:=document_seen[artifact_index]+1;
     END IF;
     IF decode(node->>'utf8Hex','hex') IS DISTINCT FROM expected_base64 THEN
      RAISE EXCEPTION 'exact original manifest artifact base64 required' USING ERRCODE='55000'; END IF;
     piece:=decode('22','hex')||expected_base64||decode('22','hex');
    ELSE piece:=truss.runtime_canonical_string_bytes(decode(node->>'utf8Hex','hex')); END IF;
   ELSIF tag IN ('array','object') AND (SELECT count(*) FROM jsonb_object_keys(node))=2 THEN
    children:=node->CASE WHEN tag='array' THEN 'items' ELSE 'members' END;
    IF jsonb_typeof(children) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'container inventory' USING ERRCODE='22023'; END IF;
    IF task->>'path'='catalogList' AND jsonb_array_length(children)<>cardinality(original_documents)
     OR task->>'path'='configurationList' AND jsonb_array_length(children)<>1 THEN
     RAISE EXCEPTION 'complete exact manifest artifact array cardinality required' USING ERRCODE='55000'; END IF;
    IF jsonb_array_length(children)>4096 THEN RAISE EXCEPTION 'container inventory capacity' USING ERRCODE='54000'; END IF;
    IF tag='object' THEN
     FOR member IN SELECT value FROM jsonb_array_elements(children) LOOP
      IF jsonb_typeof(member)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(member))<>2
       OR NOT member ?& ARRAY['keyUtf8Hex','node'] OR jsonb_typeof(member->'keyUtf8Hex') IS DISTINCT FROM 'string'
       OR member->>'keyUtf8Hex' !~ '^([0-9a-f]{2})*$' THEN RAISE EXCEPTION 'object member shape' USING ERRCODE='22023'; END IF;
      PERFORM truss.runtime_canonical_string_bytes(decode(member->>'keyUtf8Hex','hex'));
     END LOOP;
     IF (SELECT count(DISTINCT decode(value->>'keyUtf8Hex','hex')) FROM jsonb_array_elements(children))<>jsonb_array_length(children) THEN RAISE EXCEPTION 'duplicate original object key' USING ERRCODE='22023'; END IF;
     SELECT coalesce(jsonb_agg(value ORDER BY decode(value->>'keyUtf8Hex','hex')),'[]'::jsonb) INTO children FROM jsonb_array_elements(children);
    END IF;
    tasks:=array_append(tasks,jsonb_build_object('frame',tag,'children',children,'index','0','depth',depth::text,'path',coalesce(task->>'path','other')));
    piece:=decode(CASE WHEN tag='array' THEN '5b' ELSE '7b' END,'hex');
   ELSE RAISE EXCEPTION 'unsupported inert node or extra content' USING ERRCODE='22023'; END IF;
  END IF;
  emitted:=emitted+octet_length(piece);
  IF emitted>8388608 THEN RAISE EXCEPTION 'complete tree output capacity' USING ERRCODE='54000'; END IF;
  WHILE octet_length(piece)>0 LOOP
   i:=least(65536-octet_length(chunk),octet_length(piece));chunk:=chunk||substr(piece,1,i);piece:=substr(piece,i+1);
   IF octet_length(chunk)=65536 THEN chunks:=array_append(chunks,chunk);chunk:=decode('','hex'); END IF;
  END LOOP;
 END LOOP;
 chunks:=array_append(chunks,chunk);
 SELECT string_agg(value,decode('','hex') ORDER BY ordinal) INTO output FROM unnest(chunks) WITH ORDINALITY AS c(value,ordinal);
 IF configuration_seen<>1 OR EXISTS(SELECT 1 FROM unnest(document_seen) n WHERE n<>1) THEN
  RAISE EXCEPTION 'one exact slot for every original manifest artifact required' USING ERRCODE='55000'; END IF;
 IF octet_length(output)<>emitted THEN RAISE EXCEPTION 'complete tree byte parity' USING ERRCODE='55000'; END IF;
 RETURN output;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_match_key_identity(revision integer, owner_id integer, key_identity text)
 RETURNS TABLE(match_state text, owner_type_id text, key_number text, creation_revision text, retirement_revision text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; owner truss.type_def%ROWTYPE;
 retained truss.key_def%ROWTYPE; source_count bigint;
BEGIN
 SELECT * INTO STRICT op FROM truss.row_home_operation o WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.phase<>'application_finalized' FOR UPDATE;
 IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted' THEN RAISE EXCEPTION 'original catalog admission required' USING ERRCODE='55000'; END IF;
 LOCK TABLE truss.schema_head IN EXCLUSIVE MODE;
 SELECT t.* INTO STRICT owner FROM truss.type_def t WHERE t.type_id=owner_id FOR SHARE;
 PERFORM truss.runtime_catalog_lineage(revision,'record',owner.document_id,owner.module,owner.element);
 SELECT count(*) INTO source_count FROM truss.schema_doc d
  CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') m
  CROSS JOIN LATERAL jsonb_array_elements(m.value->'elements') r
  CROSS JOIN LATERAL jsonb_array_elements(r.value->'keys') k
  WHERE d.rev=revision AND d.doc_id=owner.document_id AND m.value->>'id'=owner.module
   AND r.value->>'id'=owner.element AND r.value->>'kind'='record' AND k.value->>'id'=key_identity;
 IF source_count<>1 THEN RAISE EXCEPTION 'unique original owner key required' USING ERRCODE='55000'; END IF;
 SELECT k.* INTO retained FROM truss.key_def k WHERE k.type_id=owner_id AND k.key_id COLLATE "C"=key_identity COLLATE "C" FOR SHARE;
 IF NOT FOUND THEN RETURN QUERY SELECT 'new'::text,owner_id::text,NULL::text,NULL::text,NULL::text; RETURN; END IF;
 IF retained.definition_source_kind IS DISTINCT FROM 'accepted_document' THEN
  RAISE EXCEPTION 'source kind requires its own admitted original interpreter' USING ERRCODE='0A000';
 END IF;
 PERFORM truss.runtime_verify_catalog_document(retained.definition_rev,retained.definition_document_id);
 SELECT count(*) INTO source_count FROM truss.schema_doc d
  CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') m
  CROSS JOIN LATERAL jsonb_array_elements(m.value->'elements') r
  CROSS JOIN LATERAL jsonb_array_elements(r.value->'keys') k
  WHERE d.rev=retained.definition_rev AND d.ord=retained.definition_doc_ord
   AND d.doc_id=retained.definition_document_id AND d.doc_id=owner.document_id
   AND m.value->>'id'=owner.module AND r.value->>'id'=owner.element AND r.value->>'kind'='record'
   AND k.value->>'id'=retained.key_id;
 IF source_count<>1 THEN RAISE EXCEPTION 'retained original owner key source required' USING ERRCODE='55000'; END IF;
 RETURN QUERY SELECT CASE WHEN retained.retired_rev IS NULL THEN 'active' ELSE 'retired' END,
  retained.type_id::text,retained.key_num::text,retained.since_rev::text,retained.retired_rev::text;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_match_property_identity(revision integer, owner_id integer, field_module text, field_element text)
 RETURNS TABLE(match_state text, storage_id text, creation_revision text, retirement_revision text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; owner truss.type_def%ROWTYPE;
 retained truss.prop_def%ROWTYPE; source_count bigint;
BEGIN
 SELECT * INTO STRICT op FROM truss.row_home_operation o WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.phase<>'application_finalized' FOR UPDATE;
 IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted' THEN RAISE EXCEPTION 'original catalog admission required' USING ERRCODE='55000'; END IF;
 LOCK TABLE truss.schema_head IN EXCLUSIVE MODE;
 SELECT t.* INTO STRICT owner FROM truss.type_def t WHERE t.type_id=owner_id FOR SHARE;
 PERFORM truss.runtime_catalog_lineage(revision,'record',owner.document_id,owner.module,owner.element);
 SELECT count(*) INTO source_count FROM truss.schema_doc d
  CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') m
  CROSS JOIN LATERAL jsonb_array_elements(m.value->'elements') r
  CROSS JOIN LATERAL jsonb_array_elements(r.value->'members') member
  CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') fm
  CROSS JOIN LATERAL jsonb_array_elements(fm.value->'elements') f
  WHERE d.rev=revision AND d.doc_id=owner.document_id AND m.value->>'id'=owner.module
   AND r.value->>'id'=owner.element AND r.value->>'kind'='record'
   AND member.value->>'module'=field_module AND member.value->>'element'=field_element
   AND fm.value->>'id'=field_module AND f.value->>'id'=field_element AND f.value->>'kind'='field';
 IF source_count<>1 THEN RAISE EXCEPTION 'unique original owner Field membership required' USING ERRCODE='55000'; END IF;
 SELECT p.* INTO retained FROM truss.prop_def p WHERE p.type_id=owner_id
  AND p.declaration_module COLLATE "C"=field_module COLLATE "C" AND p.element COLLATE "C"=field_element COLLATE "C" FOR SHARE;
 IF NOT FOUND THEN RETURN QUERY SELECT 'new'::text,NULL::text,NULL::text,NULL::text; RETURN; END IF;
 IF retained.definition_source_kind IS DISTINCT FROM 'accepted_document' THEN
  RAISE EXCEPTION 'source kind requires its own admitted original interpreter' USING ERRCODE='0A000';
 END IF;
 PERFORM truss.runtime_verify_catalog_document(retained.definition_rev,retained.definition_document_id);
 SELECT count(*) INTO source_count FROM truss.schema_doc d
  CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') m
  CROSS JOIN LATERAL jsonb_array_elements(m.value->'elements') f
  CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') om
  CROSS JOIN LATERAL jsonb_array_elements(om.value->'elements') r
  CROSS JOIN LATERAL jsonb_array_elements(r.value->'members') member
  WHERE d.rev=retained.definition_rev AND d.ord=retained.definition_doc_ord
   AND d.doc_id=retained.definition_document_id AND d.doc_id=owner.document_id
   AND m.value->>'id'=retained.declaration_module AND f.value->>'id'=retained.element AND f.value->>'kind'='field'
   AND om.value->>'id'=owner.module AND r.value->>'id'=owner.element AND r.value->>'kind'='record'
   AND member.value->>'module'=retained.declaration_module AND member.value->>'element'=retained.element;
 IF source_count<>1 THEN RAISE EXCEPTION 'retained original Field source correspondence required' USING ERRCODE='55000'; END IF;
 RETURN QUERY SELECT CASE WHEN retained.retired_rev IS NULL THEN 'active' ELSE 'retired' END,
  retained.prop_id::text,retained.since_rev::text,retained.retired_rev::text;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_match_record_identity(revision integer, document_id text, module_id text, element_id text)
 RETURNS TABLE(match_state text, storage_id text, creation_revision text, retirement_revision text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; retained truss.type_def%ROWTYPE; original bytea;
BEGIN
 SELECT * INTO STRICT op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.phase<>'application_finalized' FOR UPDATE;
 IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted' THEN
  RAISE EXCEPTION 'original catalog admission required' USING ERRCODE='55000';
 END IF;
 LOCK TABLE truss.schema_head IN EXCLUSIVE MODE;
 original:=truss.runtime_catalog_lineage(revision,'record',document_id,module_id,element_id);
 SELECT t.* INTO retained FROM truss.type_def t
  WHERE t.document_id COLLATE "C"=runtime_match_record_identity.document_id COLLATE "C"
   AND t.module COLLATE "C"=runtime_match_record_identity.module_id COLLATE "C" AND t.element COLLATE "C"=runtime_match_record_identity.element_id COLLATE "C" FOR SHARE;
 IF NOT FOUND THEN
  RETURN QUERY SELECT 'new'::text,NULL::text,NULL::text,NULL::text; RETURN;
 END IF;
 IF retained.definition_source_kind IS DISTINCT FROM 'accepted_document' THEN
  RAISE EXCEPTION 'source kind requires its own admitted original interpreter' USING ERRCODE='0A000';
 END IF;
 IF retained.kind<>'record' OR retained.provisional
   OR retained.lineage_profile COLLATE "C"<>'truss-type-lineage/0.1.0' COLLATE "C"
   OR retained.lineage_bytes IS DISTINCT FROM original
   OR truss.runtime_catalog_lineage(retained.definition_rev,'record',retained.definition_document_id,retained.module,retained.element) IS DISTINCT FROM original THEN
  RAISE EXCEPTION 'retained original lineage correspondence required' USING ERRCODE='55000';
 END IF;
 RETURN QUERY SELECT CASE WHEN retained.retired_rev IS NULL THEN 'active' ELSE 'retired' END,
  retained.type_id::text,retained.since_rev::text,retained.retired_rev::text;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_match_relationship_identity(revision integer, document_id text, module_id text, element_id text)
 RETURNS TABLE(match_state text, storage_id text, creation_revision text, retirement_revision text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; retained truss.rel_def%ROWTYPE;
 lineage truss.relationship_lineage%ROWTYPE; original bytea;
BEGIN
 SELECT * INTO STRICT op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.phase<>'application_finalized' FOR UPDATE;
 IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted' THEN
  RAISE EXCEPTION 'original catalog admission required' USING ERRCODE='55000';
 END IF;
 LOCK TABLE truss.schema_head IN EXCLUSIVE MODE;
 original:=truss.runtime_catalog_lineage(revision,'authored',document_id,module_id,element_id);
 SELECT r.* INTO retained FROM truss.rel_def r
  WHERE r.document_id COLLATE "C"=runtime_match_relationship_identity.document_id COLLATE "C"
   AND r.module COLLATE "C"=runtime_match_relationship_identity.module_id COLLATE "C"
   AND r.rel_id COLLATE "C"=runtime_match_relationship_identity.element_id COLLATE "C" FOR SHARE;
 IF NOT FOUND THEN RETURN QUERY SELECT 'new'::text,NULL::text,NULL::text,NULL::text; RETURN; END IF;
 IF retained.definition_source_kind IS DISTINCT FROM 'accepted_document' THEN
  RAISE EXCEPTION 'source kind requires its own admitted original interpreter' USING ERRCODE='0A000';
 END IF;
 SELECT l.* INTO lineage FROM truss.relationship_lineage l WHERE l.rel_type_id=retained.rel_type_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'missing original relationship lineage' USING ERRCODE='55000'; END IF;
 IF retained.composition OR lineage.lineage_category COLLATE "C"<>'authored' COLLATE "C"
   OR lineage.identity_profile COLLATE "C"<>'truss-relationship-lineage-bytes/0.1.0' COLLATE "C"
   OR lineage.original_identity_bytes IS DISTINCT FROM original
   OR truss.runtime_catalog_lineage(retained.definition_rev,'authored',retained.definition_document_id,retained.module,retained.rel_id) IS DISTINCT FROM original THEN
  RAISE EXCEPTION 'retained original relationship correspondence required' USING ERRCODE='55000';
 END IF;
 RETURN QUERY SELECT CASE WHEN retained.retired_rev IS NULL THEN 'active' ELSE 'retired' END,
  retained.rel_type_id::text,retained.since_rev::text,retained.retired_rev::text;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_observe_catalog_generation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; planned truss.row_home_operation%ROWTYPE;
 observed truss.row_home_operation%ROWTYPE; actual_xid xid8:=pg_current_xact_id_if_assigned();
BEGIN
 IF TG_LEVEL<>'ROW' OR TG_WHEN<>'AFTER' OR TG_OP NOT IN ('INSERT','UPDATE','DELETE')
  OR TG_TABLE_SCHEMA<>'truss' OR TG_NARGS<>0 OR actual_xid IS NULL OR TG_TABLE_NAME NOT IN ('schema_rev','schema_doc','type_def','prop_def','key_def','key_lifecycle_history','rel_def','rel_endpoint','relationship_lineage','catalog_acceptance_report','schema_head','catalog_binding_archive') THEN
  RAISE EXCEPTION 'original registered catalog event required' USING ERRCODE='55000';
 END IF;
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o WHERE o.original_writer_xid=actual_xid AND o.phase<>'application_finalized' FOR UPDATE;
 IF op.operation_kind<>'catalog-acceptance' OR op.phase NOT IN ('admitted','effects_ready','row_sealed') OR NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.granted
   AND l.relation='truss.schema_head'::regclass AND l.mode IN ('ExclusiveLock','AccessExclusiveLock')) THEN
  RAISE EXCEPTION 'original catalog acceptance exclusion required' USING ERRCODE='55000';
 END IF;
 IF op.effect_generation=9223372036854775807 THEN RAISE EXCEPTION 'catalog generation exhausted' USING ERRCODE='54000'; END IF;
 planned:=op;
 planned.effect_generation:=op.effect_generation+1;
 planned.phase:='admitted';
 planned.readiness_generation:=NULL;
 planned.sealed_generation:=NULL;
 planned.application_generation:=NULL;
 planned.application_result_bytes:=NULL;
 UPDATE truss.row_home_operation o SET effect_generation=planned.effect_generation,phase=planned.phase,
  readiness_generation=NULL,sealed_generation=NULL,application_generation=NULL,application_result_bytes=NULL
  WHERE o.original_writer_xid=actual_xid AND o.operation_ordinal=op.operation_ordinal
   AND o IS NOT DISTINCT FROM op
  RETURNING o.* INTO STRICT observed;
 IF observed IS DISTINCT FROM planned THEN
  RAISE EXCEPTION 'catalog generation update correspondence required' USING ERRCODE='55000';
 END IF;
 SELECT o.* INTO STRICT observed FROM truss.row_home_operation o
  WHERE o.original_writer_xid=actual_xid AND o.operation_ordinal=op.operation_ordinal;
 IF observed IS DISTINCT FROM planned THEN
  RAISE EXCEPTION 'catalog generation final readback correspondence required' USING ERRCODE='55000';
 END IF;
 RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_operation_commit_barrier()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
  IF TG_LEVEL<>'ROW' OR TG_WHEN<>'AFTER' OR TG_TABLE_SCHEMA<>'truss'
      OR TG_TABLE_NAME<>'row_home_operation' OR TG_NARGS<>0 THEN
    RAISE EXCEPTION 'unregistered operation commit event' USING ERRCODE='55000';
  END IF;
  RAISE EXCEPTION 'complete runtime finalizer is not installed' USING ERRCODE='55000';
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_original_catalog_manifest_candidate(original_input_bytes bytea, revision_text text, xid_text text, feed_context jsonb, manifest_definition bytea, payload_profile bytea, original_payload bytea, configuration_bytes bytea, configuration_profile bytea)
 RETURNS TABLE(tree_bytes bytea, manifest_bytes bytea, semantic_sha256 bytea)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE original_input jsonb; configuration jsonb; definition jsonb; profile jsonb; cfg_profile jsonb; document jsonb; artifact jsonb;
 seen jsonb:='{}'::jsonb; prerequisites jsonb:='[]'::jsonb; documents bytea[]:=ARRAY[]::bytea[];
 original bytea; raw bytea; association jsonb; configuration_artifact bytea;
 generation text; identity text; tree jsonb; cfg_tree jsonb; field text; chunks jsonb; pos int;
 total bigint:=0; document_count int:=0;
BEGIN
 IF original_input_bytes IS NULL OR octet_length(original_input_bytes) NOT BETWEEN 1 AND 1048576
  OR configuration_bytes IS NULL OR octet_length(configuration_bytes) NOT BETWEEN 1 AND 8388608 THEN
  RAISE EXCEPTION 'bounded original input/configuration required' USING ERRCODE='54000'; END IF;
 IF NOT (convert_from(original_input_bytes,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS)
  OR NOT (convert_from(configuration_bytes,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) THEN
  RAISE EXCEPTION 'duplicate-preserving original input/configuration admission required' USING ERRCODE='22023'; END IF;
 -- JSONB conversion explicitly refuses NUL rather than silently normalizing it.
 original_input:=convert_from(original_input_bytes,'UTF8')::jsonb;
 configuration:=convert_from(configuration_bytes,'UTF8')::jsonb;
 IF revision_text IS NULL OR revision_text !~ '^[1-9][0-9]*$' OR length(revision_text)>10
  OR revision_text::numeric>2147483647 OR xid_text IS NULL OR xid_text !~ '^[1-9][0-9]*$'
  OR length(xid_text)>20 OR xid_text::numeric>18446744073709551615 THEN
  RAISE EXCEPTION 'canonical native original coordinates required' USING ERRCODE='22023'; END IF;
 IF manifest_definition IS NULL OR octet_length(manifest_definition) NOT BETWEEN 1 AND 65536
  OR payload_profile IS NULL OR octet_length(payload_profile) NOT BETWEEN 1 AND 65536
  OR configuration_profile IS NULL OR octet_length(configuration_profile) NOT BETWEEN 1 AND 65536
  OR original_payload IS NULL OR octet_length(original_payload) NOT BETWEEN 1 AND 4194304 THEN
  RAISE EXCEPTION 'bounded complete original profile/payload required' USING ERRCODE='54000'; END IF;
 IF NOT (convert_from(payload_profile,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS)
  OR NOT (convert_from(configuration_profile,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) THEN
  RAISE EXCEPTION 'original profile unique keys required' USING ERRCODE='22023'; END IF;
 definition:=convert_from(manifest_definition,'UTF8')::jsonb;
 profile:=convert_from(payload_profile,'UTF8')::jsonb;cfg_profile:=convert_from(configuration_profile,'UTF8')::jsonb;
 IF EXISTS(SELECT 1 FROM jsonb_each(profile) WHERE key IN ('identity','version') AND (jsonb_typeof(value)<>'string' OR value #>> '{}'=''))
  OR NOT profile ?& ARRAY['identity','version']
  OR EXISTS(SELECT 1 FROM jsonb_each(cfg_profile) WHERE key IN ('identity','version') AND (jsonb_typeof(value)<>'string' OR value #>> '{}'=''))
  OR NOT cfg_profile ?& ARRAY['identity','version'] THEN
  RAISE EXCEPTION 'complete original profile identities required' USING ERRCODE='22023'; END IF;
 IF manifest_definition IS DISTINCT FROM truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(definition))
  OR definition->>'identity' IS DISTINCT FROM 'truss-administrative-single-catalog-manifest'
  OR definition->>'version' IS DISTINCT FROM '0.4.0-original-artifact-codec-candidate'
  OR encode(sha256(manifest_definition),'hex')<>'03264a3097e3632aecc69393a9ad96e036f35ef7c1044aa68a3ea575168813f5' THEN
  RAISE EXCEPTION 'exact selected original manifest definition required' USING ERRCODE='55000'; END IF;
 IF encode(sha256(payload_profile),'hex') IS DISTINCT FROM definition->'payloadDefinitionArtifact'->>'sha256' THEN
  RAISE EXCEPTION 'exact selected payload definition required' USING ERRCODE='55000'; END IF;
 IF jsonb_typeof(feed_context) IS DISTINCT FROM 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(feed_context))<>3
  OR NOT feed_context ?& ARRAY['sourceEpoch','feedProfile','scopeIdentity']
  OR EXISTS(SELECT 1 FROM jsonb_each(feed_context) WHERE jsonb_typeof(value)<>'string' OR value #>> '{}'='') THEN
  RAISE EXCEPTION 'closed original feed context required' USING ERRCODE='22023'; END IF;
 IF feed_context->>'scopeIdentity' IS DISTINCT FROM definition->'feedContext'->>'scopeIdentity' THEN
  RAISE EXCEPTION 'exact selected manifest scope required' USING ERRCODE='55000'; END IF;
 IF jsonb_typeof(original_input->'documents') IS DISTINCT FROM 'array'
  OR jsonb_array_length(original_input->'documents') NOT BETWEEN 1 AND 512 THEN
  RAISE EXCEPTION 'complete bounded original documents required' USING ERRCODE='54000'; END IF;
 FOR document IN SELECT value FROM jsonb_array_elements(original_input->'documents') LOOP
  artifact:=document->'artifact';identity:=artifact->>'identity';
  IF jsonb_typeof(artifact) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(artifact))<>3
   OR NOT artifact ?& ARRAY['identity','bytesBase64','sha256'] OR identity IS NULL OR identity=''
   OR jsonb_typeof(artifact->'identity')<>'string' OR jsonb_typeof(artifact->'bytesBase64')<>'string'
   OR jsonb_typeof(artifact->'sha256')<>'string' THEN
   RAISE EXCEPTION 'closed original document artifact required' USING ERRCODE='22023'; END IF;
  original:=decode(artifact->>'bytesBase64','base64');total:=total+octet_length(original);
  IF octet_length(original)<1 OR total>1048576 THEN RAISE EXCEPTION 'original document aggregate capacity' USING ERRCODE='54000'; END IF;
  IF replace(encode(original,'base64'),chr(10),'') IS DISTINCT FROM artifact->>'bytesBase64'
   OR encode(sha256(original),'hex') IS DISTINCT FROM artifact->>'sha256' THEN
   RAISE EXCEPTION 'complete original artifact bytes/digest correspondence required' USING ERRCODE='55000'; END IF;
  IF jsonb_typeof(document->'umfProfile') IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'original UMF profile pin required' USING ERRCODE='22023'; END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(document->'umfProfile'))<>3
   OR NOT (document->'umfProfile') ?& ARRAY['identity','version','sha256']
   OR EXISTS(SELECT 1 FROM jsonb_each(document->'umfProfile') WHERE jsonb_typeof(value)<>'string' OR value #>> '{}'='')
   OR document->'umfProfile'->>'sha256' !~ '^[0-9a-f]{64}$' THEN
   RAISE EXCEPTION 'closed exact original UMF profile pin required' USING ERRCODE='22023'; END IF;
  association:=jsonb_build_object('artifact',artifact,'profile',encode(truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(document->'umfProfile')),'hex'));
  IF seen ? identity THEN
   IF seen->identity IS DISTINCT FROM association THEN RAISE EXCEPTION 'conflicting original document identity' USING ERRCODE='55000'; END IF;
  ELSE seen:=seen||jsonb_build_object(identity,association); END IF;
 END LOOP;
 FOR identity,association IN SELECT key,value FROM jsonb_each(seen) ORDER BY convert_to(key,'UTF8') LOOP
  prerequisites:=prerequisites||jsonb_build_array(jsonb_build_object('revision',revision_text,'artifact',association->'artifact'));
  documents:=array_append(documents,decode(association->'artifact'->>'bytesBase64','base64'));
 END LOOP;
 IF NOT configuration ?& ARRAY['installationId','sourceEpoch','targetIncarnation','generation','keyReuse','journalMode','admissionProfileHex','configurationHex','bindingHex','inventoryHex']
  OR (SELECT count(*) FROM jsonb_object_keys(configuration))<>10
  OR EXISTS(SELECT 1 FROM jsonb_each(configuration) WHERE jsonb_typeof(value)<>'string' OR value #>> '{}'='') THEN
  RAISE EXCEPTION 'closed original configuration capsule required' USING ERRCODE='22023'; END IF;
 IF configuration->>'keyReuse' NOT IN ('forbid','allow') OR configuration->>'journalMode' NOT IN ('engine','trigger') THEN
  RAISE EXCEPTION 'selected mutation configuration enums required' USING ERRCODE='22023'; END IF;
 generation:=configuration->>'generation';
 IF generation IS NULL OR generation !~ '^(0|[1-9][0-9]*)$' OR length(generation)>19
  OR generation::numeric>9223372036854775807 OR configuration->>'sourceEpoch' IS DISTINCT FROM feed_context->>'sourceEpoch' THEN
  RAISE EXCEPTION 'original generation/epoch correspondence required' USING ERRCODE='22023'; END IF;
 cfg_tree:=jsonb_build_object('installation',configuration->'installationId','sourceEpoch',configuration->'sourceEpoch',
  'targetIncarnation',configuration->'targetIncarnation','generation',generation,
  'keyReuse',configuration->'keyReuse','journalMode',configuration->'journalMode');
 FOREACH field IN ARRAY ARRAY['admissionProfile','configuration','binding','inventory'] LOOP
  IF jsonb_typeof(configuration->(field||'Hex')) IS DISTINCT FROM 'string'
   OR configuration->>(field||'Hex') !~ '^([0-9a-f]{2})+$'
   OR length(configuration->>(field||'Hex'))>1572864 THEN RAISE EXCEPTION 'bounded original configuration bytes required' USING ERRCODE='54000'; END IF;
  raw:=decode(configuration->>(field||'Hex'),'hex');chunks:='[]'::jsonb;pos:=1;
  WHILE pos<=octet_length(raw) LOOP chunks:=chunks||jsonb_build_array(encode(substr(raw,pos,32768),'hex'));pos:=pos+32768; END LOOP;
  cfg_tree:=cfg_tree||jsonb_build_object(field||'HexChunks',chunks);
 END LOOP;
 configuration_artifact:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(cfg_tree));
 identity:='truss.candidate.generation-configuration/0.1.0/'||encode(convert_to(configuration->>'sourceEpoch','UTF8'),'hex')||'/'||encode(convert_to(configuration->>'installationId','UTF8'),'hex')||'/'||generation;
 tree:=jsonb_build_object('interfaceVersion','truss-feed-transaction/0.2.0','context',feed_context,'xid',xid_text,
  'manifestProfile',jsonb_build_object('identity',definition->'identity','version',definition->'version','sha256',encode(sha256(manifest_definition),'hex')),
  'configurationPrerequisites',jsonb_build_array(jsonb_build_object('configuration',jsonb_build_object(
   'generation',generation,'keyReuse',configuration->'keyReuse','journalMode',configuration->'journalMode',
   'configurationProfile',jsonb_build_object('identity',cfg_profile->'identity','version',cfg_profile->'version','sha256',encode(sha256(configuration_profile),'hex')),
   'installedProducerInventorySha256',encode(sha256(decode(configuration->>'inventoryHex','hex')),'hex'),
   'sourceEpoch',configuration->'sourceEpoch','installationId',configuration->'installationId'),
   'artifact',jsonb_build_object('identity',identity,'bytesBase64',replace(encode(configuration_artifact,'base64'),chr(10),''),'sha256',encode(sha256(configuration_artifact),'hex')))),
  'members',jsonb_build_array(jsonb_build_object('ordinal','0','key',jsonb_build_object('kind','revision','revision',revision_text),
   'payloadProfile',jsonb_build_object('identity',profile->'identity','version',profile->'version','sha256',encode(sha256(payload_profile),'hex')),
   'payloadSha256',encode(sha256(original_payload),'hex'))),'prerequisites',prerequisites);
 tree_bytes:=truss.runtime_manifest_artifact_tree_bytes_candidate(truss.runtime_catalog_report_native_tree(tree),documents,configuration_artifact);
 semantic_sha256:=sha256(convert_to('truss-canonical/0.1.0'||chr(10)||'truss-feed-manifest/0.2.0'||chr(10),'UTF8')||tree_bytes);
 tree:=tree||jsonb_build_object('manifestSha256',encode(semantic_sha256,'hex'));
 manifest_bytes:=truss.runtime_manifest_artifact_tree_bytes_candidate(truss.runtime_catalog_report_native_tree(tree),documents,configuration_artifact);
 RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_register_catalog_and_head_candidate(w text, o text, g text, registration_identity text, original_registration bytea, lifecycle_policy bytea, index_policy bytea)
 RETURNS TABLE(writer_xid text, operation_ordinal text, effect_generation text, revision text, report_utf8_hex text, scope text, accepted_report_qualified boolean, feed_qualified boolean)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE produced record; before_state jsonb; after_state jsonb; expected_state jsonb;
 op truss.row_home_operation%ROWTYPE; planned_op truss.row_home_operation%ROWTYPE;
 old_head truss.schema_head%ROWTYPE; planned_head truss.schema_head%ROWTYPE; returned_head truss.schema_head%ROWTYPE;
 rev int; input jsonb;
BEGIN
 SELECT * INTO STRICT produced FROM truss.runtime_register_catalog_prerequisites_candidate(w,o,g,registration_identity,original_registration,lifecycle_policy,index_policy);
 SELECT t.* INTO STRICT op FROM truss.row_home_operation t WHERE t.original_writer_xid=pg_current_xact_id_if_assigned() AND t.operation_ordinal::text=o;
 input:=convert_from(op.original_input_bytes,'UTF8')::jsonb;
 IF input->'binding' IS DISTINCT FROM jsonb_build_object('state','absent') OR input->'transforms' IS DISTINCT FROM '[]'::jsonb
  OR EXISTS(SELECT 1 FROM truss.rel_def WHERE definition_source_kind='operation_binding') THEN
  RAISE EXCEPTION 'unsupported pending binding or promotion completion' USING ERRCODE='0A000'; END IF;
 rev:=(convert_from(decode(produced.revision_payload_utf8_hex,'hex'),'UTF8')::jsonb->>'revision')::int;
 IF produced.effect_generation IS DISTINCT FROM op.effect_generation::text OR op.effect_generation=9223372036854775807 THEN
  RAISE EXCEPTION 'original bounded head generation required' USING ERRCODE='55000'; END IF;
 before_state:=truss.runtime_capture_configured_completion_state_candidate(w,o,produced.effect_generation);
 SELECT h.* INTO STRICT old_head FROM truss.schema_head h WHERE h.id=1;
 IF (SELECT count(*) FROM truss.schema_head)<>1 OR old_head.rev IS DISTINCT FROM 0 OR rev<>1 THEN
  RAISE EXCEPTION 'selected fresh original head transition required' USING ERRCODE='55000'; END IF;
 planned_head:=old_head;planned_head.rev:=rev;
 planned_op:=op;planned_op.effect_generation:=op.effect_generation+1;planned_op.phase:='admitted';
 planned_op.readiness_generation:=NULL;planned_op.sealed_generation:=NULL;
 planned_op.application_generation:=NULL;planned_op.application_result_bytes:=NULL;
 UPDATE truss.schema_head h SET rev=planned_head.rev WHERE h.id=old_head.id AND h IS NOT DISTINCT FROM old_head RETURNING h.* INTO STRICT returned_head;
 IF record_send(returned_head) IS DISTINCT FROM record_send(planned_head) THEN
  RAISE EXCEPTION 'complete head RETURNING correspondence required' USING ERRCODE='55000'; END IF;
 after_state:=truss.runtime_capture_configured_completion_state_candidate(w,o,planned_op.effect_generation::text);
 expected_state:=jsonb_set(before_state,ARRAY['stores','schema_head'],jsonb_build_array(encode(record_send(planned_head),'hex')));
 expected_state:=jsonb_set(expected_state,ARRAY['stores','row_home_operation'],jsonb_build_array(encode(record_send(planned_op),'hex')));
 IF after_state IS DISTINCT FROM expected_state THEN RAISE EXCEPTION 'complete configured post-head correspondence required' USING ERRCODE='55000'; END IF;
 RETURN QUERY SELECT w,o,planned_op.effect_generation::text,rev::text,produced.report_utf8_hex,
  'administrative_rollback_only_configured_head'::text,false,false;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_register_catalog_prerequisites_candidate(w text, o text, g text, registration_identity text, original_registration bytea, lifecycle_policy bytea, index_policy bytea)
 RETURNS TABLE(writer_xid text, operation_ordinal text, effect_generation text, report_utf8_hex text, revision_payload_utf8_hex text, document_prerequisites text, configuration_prerequisites text, membership_generation text, scope text, accepted_report_qualified boolean, feed_qualified boolean)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; cfg truss.operation_configuration%ROWTYPE;
 parent truss.feed_tx%ROWTYPE; doc truss.schema_doc%ROWTYPE; planned_doc truss.feed_prerequisite%ROWTYPE;
 planned_cfg truss.feed_configuration_prerequisite%ROWTYPE;
 recipe_bytes bytea; recipe jsonb; sources jsonb:='{}'; name text; identity text; original bytea;
 report record; returned record; before_state jsonb; after_state jsonb; revision int;
 document_profile bytea; configuration_profile bytea; owner_bytes bytea; artifact bytea;
 original_input jsonb; original_document jsonb; seen jsonb:='{}'; doc_identity text; document_ordinal int:=0;
 expected_docs bytea[]:=ARRAY[]::bytea[]; actual_docs bytea[]; expected_parent jsonb; expected_row jsonb;
BEGIN
 PERFORM truss.runtime_require_catalog_observation(w,o,g);
 SELECT t.* INTO STRICT op FROM truss.row_home_operation t
  WHERE t.original_writer_xid=pg_current_xact_id_if_assigned() AND t.operation_ordinal::text=o;
 identity:='packages/python/src/truss/_profiles/catalog-prerequisite-registration-candidate.json';
 LOCK TABLE truss.installation_archive IN SHARE MODE NOWAIT;
 PERFORM truss.runtime_require_selected_archive_write_fence();
 IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=(convert_from(op.original_context_bytes,'UTF8')::jsonb->>'installationId')
  AND a.artifact_role='input' AND a.artifact_identity=identity)<>1 THEN RAISE EXCEPTION 'unique prerequisite recipe required' USING ERRCODE='55000'; END IF;
 SELECT a.artifact_bytes INTO STRICT recipe_bytes FROM truss.installation_archive a
  WHERE a.installation_id=(convert_from(op.original_context_bytes,'UTF8')::jsonb->>'installationId') AND a.artifact_role='input' AND a.artifact_identity=identity
   AND a.artifact_sha256=sha256(a.artifact_bytes) AND a.artifact_sha256=decode('293bce5ba248e558319eba57ecfe3b5f683d6d89b58033003e33b6aad38cde73','hex')
   AND a.artifact_identity_sha256=sha256(convert_to(a.artifact_identity,'UTF8'));
 recipe:=convert_from(recipe_bytes,'UTF8')::jsonb;
 FOREACH name IN ARRAY ARRAY['catalog-reserve','configuration-reserve','catalog-insert','configuration-insert'] LOOP
  identity:=recipe->'sources'->name->>'path';
  IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=(convert_from(op.original_context_bytes,'UTF8')::jsonb->>'installationId')
   AND a.artifact_role='input' AND a.artifact_identity=identity)<>1 THEN RAISE EXCEPTION 'unique prerequisite statement source required' USING ERRCODE='55000'; END IF;
  SELECT a.artifact_bytes INTO STRICT original FROM truss.installation_archive a
   WHERE a.installation_id=(convert_from(op.original_context_bytes,'UTF8')::jsonb->>'installationId') AND a.artifact_role='input' AND a.artifact_identity=identity
    AND a.artifact_sha256=sha256(a.artifact_bytes) AND encode(a.artifact_sha256,'hex')=recipe->'sources'->name->>'sha256'
    AND a.artifact_identity_sha256=sha256(convert_to(a.artifact_identity,'UTF8'));
  IF octet_length(original)>16384 THEN RAISE EXCEPTION 'prerequisite statement capacity' USING ERRCODE='54000'; END IF;
  sources:=sources||jsonb_build_object(name,convert_from(original,'UTF8'));
 END LOOP;
 original_input:=convert_from(op.original_input_bytes,'UTF8')::jsonb;
 PERFORM truss.runtime_require_catalog_input(op.original_input_bytes);
 IF jsonb_array_length(original_input->'documents') NOT BETWEEN 1 AND 512 THEN RAISE EXCEPTION 'bounded original document inventory required' USING ERRCODE='54000'; END IF;
 configuration_profile:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(recipe->'configurationProfile'));
 -- The unchanged producer supplies originals and validates the first-use empty cut.
 SELECT * INTO STRICT report FROM truss.runtime_write_report_register_revision_wide_candidate(w,o,g,registration_identity,original_registration,lifecycle_policy,index_policy);
 revision:=(convert_from(decode(report.revision_payload_utf8_hex,'hex'),'UTF8')::jsonb->>'revision')::int;
 SELECT t.* INTO STRICT parent FROM truss.feed_tx t;
 SELECT m.original_owner_context_bytes INTO STRICT owner_bytes FROM truss.feed_member m;
 SELECT c.* INTO STRICT cfg FROM truss.operation_configuration c WHERE c.original_writer_xid=op.original_writer_xid AND c.operation_ordinal=op.operation_ordinal;
 before_state:=truss.runtime_capture_configured_prerequisite_state_candidate(w,o,report.effect_generation);
 IF (SELECT count(*) FROM truss.schema_doc d WHERE d.rev=revision) NOT BETWEEN 1 AND 512 THEN RAISE EXCEPTION 'complete bounded document prerequisites required' USING ERRCODE='54000'; END IF;
 -- Generation content excludes operation xid/ordinal/context digest and clocks.
 artifact:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'installation',cfg.installation_id,'sourceEpoch',cfg.source_epoch,'targetIncarnation',cfg.target_incarnation,
  'generation',cfg.configuration_generation::text,'keyReuse',cfg.key_reuse,'journalMode',cfg.journal_mode,
  'admissionProfileHexChunks',truss.runtime_registration_original_hex_chunks(cfg.admission_profile_bytes),
  'configurationHexChunks',truss.runtime_registration_original_hex_chunks(cfg.configuration_bytes),
  'bindingHexChunks',truss.runtime_registration_original_hex_chunks(cfg.selected_binding_bytes),
  'inventoryHexChunks',truss.runtime_registration_original_hex_chunks(cfg.installed_inventory_bytes))));
 IF octet_length(artifact)>4194304 THEN RAISE EXCEPTION 'generation artifact capacity' USING ERRCODE='54000'; END IF;
 FOR doc IN SELECT d.* FROM truss.schema_doc d WHERE d.rev=revision ORDER BY d.ord LOOP
  planned_doc.source_epoch:=parent.source_epoch;planned_doc.feed_profile:=parent.feed_profile;planned_doc.original_writer_xid:=parent.original_writer_xid;
  planned_doc.prerequisite_address:=parent.prerequisite_registration_counter+1;planned_doc.original_revision:=revision;
  original_document:=original_input->'documents'->document_ordinal;document_ordinal:=document_ordinal+1;
  IF original_document->>'documentId' IS DISTINCT FROM doc.doc_id OR original_document->>'documentRevision' IS DISTINCT FROM doc.doc_revision THEN
   RAISE EXCEPTION 'original document ordering and identity required' USING ERRCODE='55000'; END IF;
  doc_identity:=original_document->'artifact'->>'identity';
  planned_doc.original_artifact_identity_bytes:=convert_to(doc_identity,'UTF8');
  planned_doc.original_definition_bytes:=decode(original_document->'artifact'->>'bytesBase64','base64');
  document_profile:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(original_document->'umfProfile'));
  planned_doc.original_definition_profile_bytes:=document_profile;
  IF planned_doc.original_definition_bytes IS DISTINCT FROM convert_to(doc.document,'UTF8') THEN RAISE EXCEPTION 'complete original document bytes required' USING ERRCODE='55000'; END IF;
  IF seen ? doc_identity THEN
   IF seen->doc_identity IS DISTINCT FROM jsonb_build_object('bytes',encode(planned_doc.original_definition_bytes,'hex'),'profile',encode(document_profile,'hex')) THEN
    RAISE EXCEPTION 'conflicting original document artifact identity' USING ERRCODE='55000'; END IF;
   CONTINUE;
  END IF;
  seen:=seen||jsonb_build_object(doc_identity,jsonb_build_object('bytes',encode(planned_doc.original_definition_bytes,'hex'),'profile',encode(document_profile,'hex')));
  planned_doc.original_definition_sha256:=sha256(planned_doc.original_definition_bytes);planned_doc.original_owner_context_bytes:=owner_bytes;
  IF encode(planned_doc.original_definition_sha256,'hex') IS DISTINCT FROM doc.content_sha256 THEN RAISE EXCEPTION 'original document bytes digest correspondence required' USING ERRCODE='55000'; END IF;
  EXECUTE sources->>'catalog-reserve' INTO STRICT returned USING parent.source_epoch,parent.feed_profile,parent.prerequisite_registration_counter,parent.membership_generation,parent.original_context_bytes,parent.manifest_profile_bytes;
  parent.prerequisite_registration_counter:=parent.prerequisite_registration_counter+1;parent.membership_generation:=parent.membership_generation+1;
  IF to_jsonb(returned) IS DISTINCT FROM jsonb_build_object('source_epoch',parent.source_epoch,'feed_profile',parent.feed_profile,'original_writer_xid',parent.original_writer_xid::text,'registration_counter',parent.registration_counter::text,'prerequisite_registration_counter',parent.prerequisite_registration_counter::text,'configuration_registration_counter',parent.configuration_registration_counter::text,'membership_generation',parent.membership_generation::text,'finalized_generation',parent.finalized_generation::text,'original_context_bytes_hex',encode(parent.original_context_bytes,'hex'),'manifest_profile_bytes_hex',encode(parent.manifest_profile_bytes,'hex'),'manifest_bytes_hex',encode(parent.manifest_bytes,'hex'),'manifest_sha256_hex',encode(parent.manifest_sha256,'hex')) THEN RAISE EXCEPTION 'complete catalog reservation RETURNING correspondence required' USING ERRCODE='55000'; END IF;
  IF (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(parent)) THEN RAISE EXCEPTION 'complete catalog reservation correspondence required' USING ERRCODE='55000'; END IF;
  EXECUTE sources->>'catalog-insert' INTO STRICT returned USING parent.source_epoch,parent.feed_profile,parent.prerequisite_registration_counter,parent.membership_generation,
   planned_doc.original_revision,planned_doc.original_artifact_identity_bytes,planned_doc.original_definition_bytes,document_profile,planned_doc.original_definition_sha256,owner_bytes,parent.original_context_bytes,parent.manifest_profile_bytes;
 IF to_jsonb(returned) IS DISTINCT FROM jsonb_build_object('source_epoch',planned_doc.source_epoch,'feed_profile',planned_doc.feed_profile,'original_writer_xid',planned_doc.original_writer_xid::text,'prerequisite_address',planned_doc.prerequisite_address::text,'original_revision',planned_doc.original_revision::text,'original_artifact_identity_bytes_hex',encode(planned_doc.original_artifact_identity_bytes,'hex'),'original_definition_bytes_hex',encode(planned_doc.original_definition_bytes,'hex'),'original_definition_profile_bytes_hex',encode(planned_doc.original_definition_profile_bytes,'hex'),'original_definition_sha256_hex',encode(planned_doc.original_definition_sha256,'hex'),'original_owner_context_bytes_hex',encode(planned_doc.original_owner_context_bytes,'hex')) THEN RAISE EXCEPTION 'complete prerequisite INSERT RETURNING correspondence required' USING ERRCODE='55000'; END IF;
  IF NOT EXISTS(SELECT 1 FROM truss.feed_prerequisite p WHERE record_send(p)=record_send(planned_doc)) THEN RAISE EXCEPTION 'complete original document prerequisite correspondence required' USING ERRCODE='55000'; END IF;
  expected_docs:=array_append(expected_docs,record_send(planned_doc));
 END LOOP;
 planned_cfg.source_epoch:=parent.source_epoch;planned_cfg.feed_profile:=parent.feed_profile;planned_cfg.original_writer_xid:=parent.original_writer_xid;
 planned_cfg.configuration_address:=1;planned_cfg.original_installation_identity_bytes:=convert_to(cfg.installation_id,'UTF8');
 planned_cfg.original_configuration_generation:=cfg.configuration_generation;planned_cfg.original_configuration_profile_bytes:=configuration_profile;
 planned_cfg.original_configuration_bytes:=artifact;planned_cfg.original_producer_inventory_bytes:=cfg.installed_inventory_bytes;
 planned_cfg.original_configuration_sha256:=sha256(artifact);planned_cfg.original_owner_context_bytes:=owner_bytes;
 EXECUTE sources->>'configuration-reserve' INTO STRICT returned USING parent.source_epoch,parent.feed_profile,parent.configuration_registration_counter,parent.membership_generation,parent.original_context_bytes,parent.manifest_profile_bytes;
 parent.configuration_registration_counter:=1;parent.membership_generation:=parent.membership_generation+1;
 IF to_jsonb(returned) IS DISTINCT FROM jsonb_build_object('source_epoch',parent.source_epoch,'feed_profile',parent.feed_profile,'original_writer_xid',parent.original_writer_xid::text,'registration_counter',parent.registration_counter::text,'prerequisite_registration_counter',parent.prerequisite_registration_counter::text,'configuration_registration_counter',parent.configuration_registration_counter::text,'membership_generation',parent.membership_generation::text,'finalized_generation',parent.finalized_generation::text,'original_context_bytes_hex',encode(parent.original_context_bytes,'hex'),'manifest_profile_bytes_hex',encode(parent.manifest_profile_bytes,'hex'),'manifest_bytes_hex',encode(parent.manifest_bytes,'hex'),'manifest_sha256_hex',encode(parent.manifest_sha256,'hex')) THEN RAISE EXCEPTION 'complete configuration reservation RETURNING correspondence required' USING ERRCODE='55000'; END IF;
 IF (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(parent)) THEN RAISE EXCEPTION 'complete configuration reservation correspondence required' USING ERRCODE='55000'; END IF;
 EXECUTE sources->>'configuration-insert' INTO STRICT returned USING parent.source_epoch,parent.feed_profile,1::bigint,parent.membership_generation,
  planned_cfg.original_installation_identity_bytes,planned_cfg.original_configuration_generation,configuration_profile,artifact,cfg.installed_inventory_bytes,sha256(artifact),owner_bytes,parent.original_context_bytes,parent.manifest_profile_bytes;
 IF to_jsonb(returned) IS DISTINCT FROM jsonb_build_object('source_epoch',planned_cfg.source_epoch,'feed_profile',planned_cfg.feed_profile,'original_writer_xid',planned_cfg.original_writer_xid::text,'configuration_address',planned_cfg.configuration_address::text,'original_installation_identity_bytes_hex',encode(planned_cfg.original_installation_identity_bytes,'hex'),'original_configuration_generation',planned_cfg.original_configuration_generation::text,'original_configuration_profile_bytes_hex',encode(planned_cfg.original_configuration_profile_bytes,'hex'),'original_configuration_bytes_hex',encode(planned_cfg.original_configuration_bytes,'hex'),'original_producer_inventory_bytes_hex',encode(planned_cfg.original_producer_inventory_bytes,'hex'),'original_configuration_sha256_hex',encode(planned_cfg.original_configuration_sha256,'hex'),'original_owner_context_bytes_hex',encode(planned_cfg.original_owner_context_bytes,'hex')) THEN RAISE EXCEPTION 'complete prerequisite INSERT RETURNING correspondence required' USING ERRCODE='55000'; END IF;
 after_state:=truss.runtime_capture_configured_prerequisite_state_candidate(w,o,report.effect_generation);
 SELECT array_agg(record_send(p) ORDER BY p.prerequisite_address) INTO actual_docs FROM truss.feed_prerequisite p;
 IF document_ordinal<>jsonb_array_length(original_input->'documents') THEN RAISE EXCEPTION 'complete original prerequisite document inventory required' USING ERRCODE='55000'; END IF;
 IF after_state IS DISTINCT FROM before_state OR actual_docs IS DISTINCT FROM expected_docs
  OR (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(parent))
  OR (SELECT count(*) FROM truss.feed_configuration_prerequisite)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_configuration_prerequisite p WHERE record_send(p)=record_send(planned_cfg)) THEN
  RAISE EXCEPTION 'complete configured prerequisite registration delta required' USING ERRCODE='55000'; END IF;
 RETURN QUERY SELECT w,o,report.effect_generation,report.report_utf8_hex,report.revision_payload_utf8_hex,
  parent.prerequisite_registration_counter::text,'1'::text,parent.membership_generation::text,
  'administrative_single_original_fresh_catalog_rollback_only'::text,false,false;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_register_catalog_revision_custody_candidate(w text, o text, g text)
 RETURNS TABLE(writer_xid text, operation_ordinal text, effect_generation text, parent_record_hex text, member_record_hex text, scope text, feed_qualified boolean)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO, YMD'
 SET "IntervalStyle" TO 'iso_8601'
 SET extra_float_digits TO '3'
 SET bytea_output TO 'hex'
 SET standard_conforming_strings TO 'on'
 SET quote_all_identifiers TO 'off'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; custody truss.catalog_revision_custody%ROWTYPE;
 original_custody bytea; before_state jsonb; after_state jsonb; expected_state jsonb;
 planned_parent truss.feed_tx%ROWTYPE; planned_member truss.feed_member%ROWTYPE;
 returned record; expected_snapshot jsonb; context jsonb; profile jsonb; profile_bytes bytea;
 source_sql jsonb:='{}'; source_name text; identity text; raw bytea;
 payload bytea; payload_profile bytea; key_profile bytea; owner_bytes bytea;
 revision_row truss.schema_rev%ROWTYPE; configuration truss.operation_configuration%ROWTYPE;
 original_report bytea; expected_payload bytea; revision_tree jsonb; origin jsonb; journal_envelope jsonb;
 input jsonb; report_identity text; original_documents bytea[]; document_record bytea;
 documents jsonb:='[]'; original_configuration bytea; original_op bytea; original_revision bytea;
 original_bytes bigint; total_chunks bigint; expected_owner bytea;
 manifest_bytes bytea; clock_bytes bytea; original_write_at timestamptz; revision int;
BEGIN
 PERFORM truss.runtime_require_catalog_registration_composition_candidate(w,o,g);
 SELECT * INTO STRICT op FROM truss.row_home_operation t WHERE t.original_writer_xid=pg_current_xact_id_if_assigned()
  AND t.operation_ordinal::text=o FOR UPDATE;
 IF (SELECT count(*) FROM truss.catalog_revision_custody t
  WHERE t.original_writer_xid=op.original_writer_xid AND t.operation_ordinal=op.operation_ordinal)<>1 THEN
  RAISE EXCEPTION 'unique original custody for current operation required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT custody FROM truss.catalog_revision_custody t WHERE t.original_writer_xid=op.original_writer_xid
  AND t.operation_ordinal=op.operation_ordinal FOR SHARE NOWAIT;
 IF (SELECT count(*) FROM truss.row_home_operation)<>1 OR (SELECT count(*) FROM truss.catalog_revision_custody)<>1
  OR custody.capture_generation::text IS DISTINCT FROM g OR op.effect_generation::text IS DISTINCT FROM g
  OR (SELECT count(*) FROM truss.schema_head)<>1 OR NOT EXISTS(SELECT 1 FROM truss.schema_head h WHERE h.id=1 AND h.rev=0)
  OR NOT EXISTS(SELECT 1 FROM truss.schema_rev r WHERE r.rev=custody.original_revision)
  OR NOT EXISTS(SELECT 1 FROM truss.catalog_acceptance_report r WHERE r.rev=custody.original_revision) THEN
  RAISE EXCEPTION 'single current original unpublished catalog custody required' USING ERRCODE='55000'; END IF;
 original_custody:=record_send(custody);context:=convert_from(op.original_context_bytes,'UTF8')::jsonb;
 before_state:=truss.runtime_capture_configured_completion_state_candidate(w,o,g);
 IF before_state->'stores'->'feed_tx' IS DISTINCT FROM '[]'::jsonb
  OR before_state->'stores'->'feed_member' IS DISTINCT FROM '[]'::jsonb
  OR before_state->'stores'->'feed_prerequisite' IS DISTINCT FROM '[]'::jsonb
  OR before_state->'stores'->'feed_configuration_prerequisite' IS DISTINCT FROM '[]'::jsonb THEN
  RAISE EXCEPTION 'single initial custody registration only' USING ERRCODE='55000'; END IF;
 LOCK TABLE truss.installation_archive IN SHARE MODE NOWAIT;
 PERFORM truss.runtime_require_selected_archive_write_fence();
 identity:='packages/python/src/truss/_profiles/catalog-custody-registration-candidate.json';
 IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=context->>'installationId'
  AND a.artifact_role='input' AND a.artifact_identity=identity)<>1 THEN
  RAISE EXCEPTION 'unique original custody registration recipe required' USING ERRCODE='55000'; END IF;
 SELECT a.artifact_bytes INTO STRICT profile_bytes FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=identity
  AND a.artifact_sha256=sha256(a.artifact_bytes) AND encode(a.artifact_sha256,'hex')='8561e275de278b019e7c20628ec98630d77d2011d2967556f614f09e1647793f'
  AND a.artifact_identity_sha256=sha256(convert_to(identity,'UTF8'));
 IF octet_length(profile_bytes)>65536 THEN RAISE EXCEPTION 'recipe capacity' USING ERRCODE='54000'; END IF;
 profile:=convert_from(profile_bytes,'UTF8')::jsonb;
 FOREACH source_name IN ARRAY ARRAY['create','reserve','insert','producer','payload'] LOOP
  IF source_name='producer' THEN identity:=profile->'custodyProducer'->>'path';
  ELSIF source_name='payload' THEN identity:=profile->'payloadProfile'->>'path';
  ELSE identity:=profile->'sources'->source_name->>'path';END IF;
  IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=context->>'installationId'
   AND a.artifact_role='input' AND a.artifact_identity=identity)<>1 THEN
   RAISE EXCEPTION 'unique original selected registration artifact required' USING ERRCODE='55000'; END IF;
  SELECT a.artifact_bytes INTO STRICT raw FROM truss.installation_archive a
   WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=identity
   AND a.artifact_sha256=sha256(a.artifact_bytes) AND a.artifact_identity_sha256=sha256(convert_to(identity,'UTF8'))
   AND encode(a.artifact_sha256,'hex')=CASE source_name WHEN 'producer' THEN profile->'custodyProducer'->>'sha256'
    WHEN 'payload' THEN profile->'payloadProfile'->>'sha256' ELSE profile->'sources'->source_name->>'sha256' END;
  IF source_name='producer' THEN
   IF raw IS DISTINCT FROM custody.original_producer_profile_bytes THEN RAISE EXCEPTION 'original custody producer required' USING ERRCODE='55000'; END IF;
  ELSIF source_name='payload' THEN
   IF raw IS DISTINCT FROM custody.original_payload_profile_bytes THEN RAISE EXCEPTION 'original custody payload profile required' USING ERRCODE='55000'; END IF;
  ELSE
   IF octet_length(raw)>16384 THEN RAISE EXCEPTION 'statement capacity' USING ERRCODE='54000';END IF;
   source_sql:=source_sql||jsonb_build_object(source_name,convert_from(raw,'UTF8'));
  END IF;
 END LOOP;
 revision:=custody.original_revision;payload:=custody.original_payload_bytes;payload_profile:=custody.original_payload_profile_bytes;
 key_profile:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(profile->'keyProfile'));
 IF key_profile IS DISTINCT FROM custody.original_fact_key_profile_bytes
  OR custody.original_fact_key_bytes IS DISTINCT FROM truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(jsonb_build_object('kind','revision','revision',revision::text))) THEN
  RAISE EXCEPTION 'original revision key profile correspondence required' USING ERRCODE='55000'; END IF;
 owner_bytes:=custody.original_owner_context_bytes;
 manifest_bytes:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(profile->'manifestProfile'));
 IF octet_length(custody.original_producer_profile_bytes)>65536
  OR octet_length(custody.original_fact_key_bytes)>65536 OR octet_length(custody.original_fact_key_profile_bytes)>65536
  OR octet_length(custody.original_payload_bytes)>4194304 OR octet_length(custody.original_payload_profile_bytes)>65536
  OR octet_length(custody.original_owner_context_bytes)>16777216 OR octet_length(custody.original_fact_clock_bytes)>65536
  OR NOT isfinite(custody.original_write_at)
  OR extract(year FROM custody.original_write_at AT TIME ZONE 'UTC') NOT BETWEEN 1 AND 9999 THEN
  RAISE EXCEPTION 'bounded finite original custody required' USING ERRCODE='54000'; END IF;
 clock_bytes:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'profile',profile->'clockProfile','originalWriteAt',to_char(custody.original_write_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))));
 IF clock_bytes IS DISTINCT FROM custody.original_fact_clock_bytes THEN
  RAISE EXCEPTION 'original retained clock profile and timestamp correspondence required' USING ERRCODE='55000'; END IF;
 -- Read-only independent correspondence; the registered bytes remain custody originals.
 SELECT * INTO STRICT revision_row FROM truss.schema_rev r WHERE r.rev=revision;
 SELECT r.report_bytes INTO STRICT original_report FROM truss.catalog_acceptance_report r WHERE r.rev=revision;
 IF (SELECT count(*) FROM truss.catalog_acceptance_report)<>1
  OR NOT isfinite(revision_row.accepted_at)
  OR extract(year FROM revision_row.accepted_at AT TIME ZONE 'UTC') NOT BETWEEN 1 AND 9999
  OR octet_length(original_report)>786432 OR octet_length(op.original_input_bytes)>1048576 THEN
  RAISE EXCEPTION 'bounded finite original report and revision required' USING ERRCODE='55000'; END IF;
 input:=convert_from(op.original_input_bytes,'UTF8')::jsonb;
 origin:=truss.runtime_catalog_report_original_tree(decode(context->>'assertedOriginUtf8Hex','hex'));
 IF truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(revision_row.origin))
  IS DISTINCT FROM truss.runtime_canonical_tree_bytes(origin) THEN
  RAISE EXCEPTION 'original retained revision origin correspondence required' USING ERRCODE='55000'; END IF;
 journal_envelope:=truss.runtime_catalog_report_native_tree(jsonb_build_object('databaseRole',context->>'actingUser'));
 journal_envelope:=jsonb_set(journal_envelope,'{members}',journal_envelope->'members'||jsonb_build_array(
  jsonb_build_object('keyUtf8Hex','6173736572746564','node',truss.runtime_catalog_report_map_origin_tree(origin))));
 report_identity:='truss.candidate.catalog-report/'||encode(convert_to(context->>'installationId','UTF8'),'hex')
  ||'/'||encode(convert_to(context->>'sourceEpoch','UTF8'),'hex')||'/'||revision::text;
 revision_tree:=truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'interfaceVersion','truss-feed-revision/0.1.0','revision',revision::text,
  'acceptedAt',to_char(revision_row.accepted_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'input',input,'report',jsonb_build_object('identity',report_identity,
   'bytesBase64',replace(encode(original_report,'base64'),chr(10),''),'sha256',encode(sha256(original_report),'hex'))));
 revision_tree:=jsonb_set(revision_tree,'{members}',revision_tree->'members'||jsonb_build_array(
  jsonb_build_object('keyUtf8Hex','6f726967696e','node',journal_envelope)));
 IF octet_length(revision_tree::text)>4194304 THEN RAISE EXCEPTION 'revision comparison tree capacity' USING ERRCODE='54000';END IF;
 expected_payload:=truss.runtime_revision_report_tree_bytes_wide_candidate(revision_tree,original_report);
 IF expected_payload IS DISTINCT FROM custody.original_payload_bytes THEN
  RAISE EXCEPTION 'original retained report and revision payload correspondence required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT configuration FROM truss.operation_configuration t
  WHERE t.original_writer_xid=op.original_writer_xid AND t.operation_ordinal=op.operation_ordinal;
 original_configuration:=record_send(configuration);original_op:=record_send(op);original_revision:=record_send(revision_row);
 SELECT array_agg(record_send(d) ORDER BY d.ord) INTO original_documents FROM truss.schema_doc d WHERE d.rev=revision;
 IF original_documents IS NULL OR cardinality(original_documents) NOT BETWEEN 1 AND 512 THEN
  RAISE EXCEPTION 'complete original document custody required' USING ERRCODE='55000'; END IF;
 original_bytes:=octet_length(original_configuration)::bigint+octet_length(original_op)::bigint+
  octet_length(op.original_context_bytes)::bigint+octet_length(original_revision)::bigint;
 total_chunks:=((octet_length(original_configuration)+32767)/32768)+((octet_length(original_op)+32767)/32768)+
  ((octet_length(op.original_context_bytes)+32767)/32768)+((octet_length(original_revision)+32767)/32768);
 FOREACH document_record IN ARRAY original_documents LOOP
  IF document_record IS NULL THEN RAISE EXCEPTION 'original document bytes required' USING ERRCODE='55000'; END IF;
  original_bytes:=original_bytes+octet_length(document_record)::bigint;
  total_chunks:=total_chunks+((octet_length(document_record)+32767)/32768);
 END LOOP;
 IF original_bytes>786432 OR total_chunks>1024 THEN RAISE EXCEPTION 'original custody codec capacity' USING ERRCODE='54000'; END IF;
 FOREACH document_record IN ARRAY original_documents LOOP
  documents:=documents||jsonb_build_array(truss.runtime_registration_original_hex_chunks(document_record));
 END LOOP;
 expected_owner:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'scope','administrative_single_original_operation_fresh_catalog_rollback_only',
  'originalConfigurationRecordHexChunks',truss.runtime_registration_original_hex_chunks(original_configuration),
  'originalOperationRecordHexChunks',truss.runtime_registration_original_hex_chunks(original_op),
  'originalContextHexChunks',truss.runtime_registration_original_hex_chunks(op.original_context_bytes),
  'originalRevisionRecordHexChunks',truss.runtime_registration_original_hex_chunks(original_revision),
  'originalDocumentRecordHexChunks',documents)));
 IF expected_owner IS DISTINCT FROM custody.original_owner_context_bytes THEN
  RAISE EXCEPTION 'original retained owner record correspondence required' USING ERRCODE='55000'; END IF;
 planned_parent.source_epoch:=context->>'sourceEpoch';planned_parent.feed_profile:=profile->>'identity';
 planned_parent.original_writer_xid:=op.original_writer_xid;planned_parent.registration_counter:=0;
 planned_parent.prerequisite_registration_counter:=0;planned_parent.configuration_registration_counter:=0;
 planned_parent.membership_generation:=0;planned_parent.original_context_bytes:=op.original_context_bytes;
 planned_parent.manifest_profile_bytes:=manifest_bytes;
 EXECUTE source_sql->>'create' INTO STRICT returned USING planned_parent.source_epoch,planned_parent.feed_profile,op.original_context_bytes,manifest_bytes;
 expected_snapshot:=jsonb_build_object('source_epoch',planned_parent.source_epoch,'feed_profile',planned_parent.feed_profile,
  'original_writer_xid',op.original_writer_xid::text,'registration_counter','0','prerequisite_registration_counter','0',
  'configuration_registration_counter','0','membership_generation','0','finalized_generation',NULL,
  'original_context_bytes_hex',encode(op.original_context_bytes,'hex'),'manifest_profile_bytes_hex',encode(manifest_bytes,'hex'),
  'manifest_bytes_hex',NULL,'manifest_sha256_hex',NULL);
 IF to_jsonb(returned) IS DISTINCT FROM expected_snapshot
  OR (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(planned_parent)) THEN
  RAISE EXCEPTION 'original pending parent insert readback required' USING ERRCODE='55000'; END IF;
 planned_parent.registration_counter:=1;planned_parent.membership_generation:=1;
 EXECUTE source_sql->>'reserve' INTO STRICT returned USING planned_parent.source_epoch,planned_parent.feed_profile,0::bigint,0::bigint,op.original_context_bytes,manifest_bytes;
 expected_snapshot:=jsonb_set(jsonb_set(expected_snapshot,'{registration_counter}','"1"'),'{membership_generation}','"1"');
 IF to_jsonb(returned) IS DISTINCT FROM expected_snapshot
  OR (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(planned_parent)) THEN
  RAISE EXCEPTION 'original parent reservation readback required' USING ERRCODE='55000'; END IF;
 planned_member.source_epoch:=planned_parent.source_epoch;planned_member.feed_profile:=planned_parent.feed_profile;
 planned_member.original_writer_xid:=op.original_writer_xid;planned_member.registration_address:=1;
 planned_member.fact_kind:='revision';planned_member.original_fact_key_bytes:=custody.original_fact_key_bytes;
 planned_member.original_fact_key_profile_bytes:=key_profile;planned_member.original_payload_bytes:=payload;
 planned_member.original_payload_profile_bytes:=payload_profile;planned_member.original_payload_sha256:=sha256(payload);
 planned_member.original_owner_context_bytes:=owner_bytes;
 -- Preserve the original custody clock; registration never samples a new clock.
 original_write_at:=custody.original_write_at;
 IF NOT isfinite(original_write_at) OR extract(year FROM original_write_at AT TIME ZONE 'UTC') NOT BETWEEN 1 AND 9999 THEN
  RAISE EXCEPTION 'finite native member write clock required' USING ERRCODE='55000'; END IF;
 clock_bytes:=custody.original_fact_clock_bytes;
 planned_member.original_write_at:=original_write_at;planned_member.original_fact_clock_bytes:=clock_bytes;
 EXECUTE source_sql->>'insert' INTO STRICT returned USING planned_parent.source_epoch,planned_parent.feed_profile,1::bigint,1::bigint,
  'revision',planned_member.original_fact_key_bytes,key_profile,payload,payload_profile,sha256(payload),owner_bytes,
  original_write_at,clock_bytes,op.original_context_bytes,manifest_bytes;
 expected_snapshot:=jsonb_build_object('source_epoch',planned_member.source_epoch,'feed_profile',planned_member.feed_profile,
  'original_writer_xid',op.original_writer_xid::text,'registration_address','1','fact_kind','revision',
  'original_fact_key_bytes_hex',encode(planned_member.original_fact_key_bytes,'hex'),'original_fact_key_profile_bytes_hex',encode(key_profile,'hex'),
  'original_payload_bytes_hex',encode(payload,'hex'),'original_payload_profile_bytes_hex',encode(payload_profile,'hex'),
  'original_payload_sha256_hex',encode(sha256(payload),'hex'),'original_owner_context_bytes_hex',encode(owner_bytes,'hex'),
  'original_write_at',original_write_at::text,'original_fact_clock_bytes_hex',encode(clock_bytes,'hex'),'delivery_ordinal',NULL);
 IF to_jsonb(returned) IS DISTINCT FROM expected_snapshot THEN
  RAISE EXCEPTION 'original revision member returned snapshot required' USING ERRCODE='55000'; END IF;
 PERFORM truss.runtime_require_catalog_registration_composition_candidate(w,o,g);
 after_state:=truss.runtime_capture_configured_completion_state_candidate(w,o,g);
 expected_state:=jsonb_set(before_state,'{stores,feed_tx}',jsonb_build_array(encode(record_send(planned_parent),'hex')));
 expected_state:=jsonb_set(expected_state,'{stores,feed_member}',jsonb_build_array(encode(record_send(planned_member),'hex')));
 IF after_state IS DISTINCT FROM expected_state OR NOT EXISTS(SELECT 1 FROM truss.catalog_revision_custody t
  WHERE record_send(t)=original_custody) THEN
  RAISE EXCEPTION 'complete independent original custody registration delta required' USING ERRCODE='55000'; END IF;
 RETURN QUERY SELECT w,o,g,encode(record_send(planned_parent),'hex'),encode(record_send(planned_member),'hex'),
  'administrative_rollback_only_pending_custody_feed'::text,false;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_register_custody_catalog_prerequisites_candidate(w text, o text, g text)
 RETURNS TABLE(writer_xid text, operation_ordinal text, effect_generation text, report_utf8_hex text, revision_payload_utf8_hex text, document_prerequisites text, configuration_prerequisites text, membership_generation text, scope text, accepted_report_qualified boolean, feed_qualified boolean)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO, YMD'
 SET "IntervalStyle" TO 'iso_8601'
 SET extra_float_digits TO '3'
 SET bytea_output TO 'hex'
 SET standard_conforming_strings TO 'on'
 SET quote_all_identifiers TO 'off'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; cfg truss.operation_configuration%ROWTYPE;
 parent truss.feed_tx%ROWTYPE; doc truss.schema_doc%ROWTYPE; planned_doc truss.feed_prerequisite%ROWTYPE;
 planned_cfg truss.feed_configuration_prerequisite%ROWTYPE;
 recipe_bytes bytea; recipe jsonb; sources jsonb:='{}'; name text; identity text; original bytea;
 report record; custody truss.catalog_revision_custody%ROWTYPE; original_custody bytea; report_bytes bytea; expected_state jsonb; expected_doc_rows jsonb; returned record; before_state jsonb; after_state jsonb; revision int;
 document_profile bytea; configuration_profile bytea; owner_bytes bytea; artifact bytea;
 original_input jsonb; original_document jsonb; seen jsonb:='{}'; doc_identity text; document_ordinal int:=0;
 doc_plan truss.feed_prerequisite[]:=ARRAY[]::truss.feed_prerequisite[]; unique_documents bigint:=0;
 expected_docs bytea[]:=ARRAY[]::bytea[]; actual_docs bytea[]; expected_parent jsonb; expected_row jsonb;
BEGIN
 PERFORM truss.runtime_require_catalog_prerequisite_composition_candidate(w,o,g);
 SELECT t.* INTO STRICT op FROM truss.row_home_operation t
  WHERE t.original_writer_xid=pg_current_xact_id_if_assigned() AND t.operation_ordinal::text=o;
 identity:='packages/python/src/truss/_profiles/catalog-custody-prerequisite-registration-candidate.json';
 LOCK TABLE truss.installation_archive IN SHARE MODE NOWAIT;
 PERFORM truss.runtime_require_selected_archive_write_fence();
 IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=(convert_from(op.original_context_bytes,'UTF8')::jsonb->>'installationId')
  AND a.artifact_role='input' AND a.artifact_identity=identity)<>1 THEN RAISE EXCEPTION 'unique prerequisite recipe required' USING ERRCODE='55000'; END IF;
 SELECT a.artifact_bytes INTO STRICT recipe_bytes FROM truss.installation_archive a
  WHERE a.installation_id=(convert_from(op.original_context_bytes,'UTF8')::jsonb->>'installationId') AND a.artifact_role='input' AND a.artifact_identity=identity
   AND a.artifact_sha256=sha256(a.artifact_bytes) AND a.artifact_sha256=decode('bf260c6c411be0f61903c45b581e73e7871a676808a8f324f29b481439de32d2','hex')
   AND a.artifact_identity_sha256=sha256(convert_to(a.artifact_identity,'UTF8'));
 recipe:=convert_from(recipe_bytes,'UTF8')::jsonb;
 FOREACH name IN ARRAY ARRAY['catalog-reserve','configuration-reserve','catalog-insert','configuration-insert'] LOOP
  identity:=recipe->'sources'->name->>'path';
  IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=(convert_from(op.original_context_bytes,'UTF8')::jsonb->>'installationId')
   AND a.artifact_role='input' AND a.artifact_identity=identity)<>1 THEN RAISE EXCEPTION 'unique prerequisite statement source required' USING ERRCODE='55000'; END IF;
  SELECT a.artifact_bytes INTO STRICT original FROM truss.installation_archive a
   WHERE a.installation_id=(convert_from(op.original_context_bytes,'UTF8')::jsonb->>'installationId') AND a.artifact_role='input' AND a.artifact_identity=identity
    AND a.artifact_sha256=sha256(a.artifact_bytes) AND encode(a.artifact_sha256,'hex')=recipe->'sources'->name->>'sha256'
    AND a.artifact_identity_sha256=sha256(convert_to(a.artifact_identity,'UTF8'));
  IF octet_length(original)>16384 THEN RAISE EXCEPTION 'prerequisite statement capacity' USING ERRCODE='54000'; END IF;
  sources:=sources||jsonb_build_object(name,convert_from(original,'UTF8'));
 END LOOP;
 original_input:=convert_from(op.original_input_bytes,'UTF8')::jsonb;
 PERFORM truss.runtime_require_catalog_input(op.original_input_bytes);
 IF jsonb_array_length(original_input->'documents') NOT BETWEEN 1 AND 512 THEN RAISE EXCEPTION 'bounded original document inventory required' USING ERRCODE='54000'; END IF;
 configuration_profile:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(recipe->'configurationProfile'));
 -- The sole registrar validates and copies already retained originals.
 SELECT * INTO STRICT report FROM truss.runtime_register_prerequisite_revision_custody_candidate(w,o,g);
 IF report.writer_xid IS DISTINCT FROM w OR report.operation_ordinal IS DISTINCT FROM o
  OR report.effect_generation IS DISTINCT FROM g OR report.feed_qualified IS DISTINCT FROM false
  OR report.scope IS DISTINCT FROM 'administrative_rollback_only_pending_custody_feed' THEN
  RAISE EXCEPTION 'original pending custody registration required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT custody FROM truss.catalog_revision_custody t WHERE t.original_writer_xid=op.original_writer_xid
  AND t.operation_ordinal=op.operation_ordinal FOR SHARE NOWAIT;
 original_custody:=record_send(custody);revision:=custody.original_revision;
 SELECT r.report_bytes INTO STRICT report_bytes FROM truss.catalog_acceptance_report r WHERE r.rev=revision;
 SELECT t.* INTO STRICT parent FROM truss.feed_tx t;
 IF record_send(parent) IS DISTINCT FROM decode(report.parent_record_hex,'hex')
  OR parent.registration_counter IS DISTINCT FROM 1::bigint
  OR parent.prerequisite_registration_counter IS DISTINCT FROM 0::bigint
  OR parent.configuration_registration_counter IS DISTINCT FROM 0::bigint
  OR parent.membership_generation IS DISTINCT FROM 1::bigint
  OR parent.finalized_generation IS NOT NULL OR parent.manifest_bytes IS NOT NULL OR parent.manifest_sha256 IS NOT NULL
  OR (SELECT count(*) FROM truss.feed_member)<>1
  OR NOT EXISTS(SELECT 1 FROM truss.feed_member m WHERE record_send(m)=decode(report.member_record_hex,'hex')
   AND m.delivery_ordinal IS NULL) THEN
  RAISE EXCEPTION 'original pending registrar parent and member correspondence required' USING ERRCODE='55000'; END IF;
 owner_bytes:=custody.original_owner_context_bytes;
 SELECT c.* INTO STRICT cfg FROM truss.operation_configuration c WHERE c.original_writer_xid=op.original_writer_xid AND c.operation_ordinal=op.operation_ordinal;
 before_state:=truss.runtime_capture_configured_completion_state_candidate(w,o,report.effect_generation);
 IF (SELECT count(*) FROM truss.schema_doc d WHERE d.rev=revision) NOT BETWEEN 1 AND 512 THEN RAISE EXCEPTION 'complete bounded document prerequisites required' USING ERRCODE='54000'; END IF;
 -- Generation content excludes operation xid/ordinal/context digest and clocks.
 artifact:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'installation',cfg.installation_id,'sourceEpoch',cfg.source_epoch,'targetIncarnation',cfg.target_incarnation,
  'generation',cfg.configuration_generation::text,'keyReuse',cfg.key_reuse,'journalMode',cfg.journal_mode,
  'admissionProfileHexChunks',truss.runtime_registration_original_hex_chunks(cfg.admission_profile_bytes),
  'configurationHexChunks',truss.runtime_registration_original_hex_chunks(cfg.configuration_bytes),
  'bindingHexChunks',truss.runtime_registration_original_hex_chunks(cfg.selected_binding_bytes),
  'inventoryHexChunks',truss.runtime_registration_original_hex_chunks(cfg.installed_inventory_bytes))));
 IF octet_length(artifact)>4194304 THEN RAISE EXCEPTION 'generation artifact capacity' USING ERRCODE='54000'; END IF;
 FOR doc IN SELECT d.* FROM truss.schema_doc d WHERE d.rev=revision ORDER BY d.ord LOOP
  planned_doc.source_epoch:=parent.source_epoch;planned_doc.feed_profile:=parent.feed_profile;planned_doc.original_writer_xid:=parent.original_writer_xid;
  planned_doc.prerequisite_address:=unique_documents+1;planned_doc.original_revision:=revision;
  original_document:=original_input->'documents'->document_ordinal;document_ordinal:=document_ordinal+1;
  IF original_document->>'documentId' IS DISTINCT FROM doc.doc_id OR original_document->>'documentRevision' IS DISTINCT FROM doc.doc_revision THEN
   RAISE EXCEPTION 'original document ordering and identity required' USING ERRCODE='55000'; END IF;
  doc_identity:=original_document->'artifact'->>'identity';
  planned_doc.original_artifact_identity_bytes:=convert_to(doc_identity,'UTF8');
  planned_doc.original_definition_bytes:=decode(original_document->'artifact'->>'bytesBase64','base64');
  document_profile:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(original_document->'umfProfile'));
  planned_doc.original_definition_profile_bytes:=document_profile;
  IF planned_doc.original_definition_bytes IS DISTINCT FROM convert_to(doc.document,'UTF8') THEN RAISE EXCEPTION 'complete original document bytes required' USING ERRCODE='55000'; END IF;
  IF seen ? doc_identity THEN
   IF seen->doc_identity IS DISTINCT FROM jsonb_build_object('bytes',encode(planned_doc.original_definition_bytes,'hex'),'profile',encode(document_profile,'hex')) THEN
    RAISE EXCEPTION 'conflicting original document artifact identity' USING ERRCODE='55000'; END IF;
   CONTINUE;
  END IF;
  seen:=seen||jsonb_build_object(doc_identity,jsonb_build_object('bytes',encode(planned_doc.original_definition_bytes,'hex'),'profile',encode(document_profile,'hex')));
  planned_doc.original_definition_sha256:=sha256(planned_doc.original_definition_bytes);planned_doc.original_owner_context_bytes:=owner_bytes;
  IF encode(planned_doc.original_definition_sha256,'hex') IS DISTINCT FROM doc.content_sha256 THEN RAISE EXCEPTION 'original document bytes digest correspondence required' USING ERRCODE='55000'; END IF;
  unique_documents:=unique_documents+1;doc_plan:=array_append(doc_plan,planned_doc);
 END LOOP;
 planned_cfg.source_epoch:=parent.source_epoch;planned_cfg.feed_profile:=parent.feed_profile;planned_cfg.original_writer_xid:=parent.original_writer_xid;
 planned_cfg.configuration_address:=1;planned_cfg.original_installation_identity_bytes:=convert_to(cfg.installation_id,'UTF8');
 planned_cfg.original_configuration_generation:=cfg.configuration_generation;planned_cfg.original_configuration_profile_bytes:=configuration_profile;
 planned_cfg.original_configuration_bytes:=artifact;planned_cfg.original_producer_inventory_bytes:=cfg.installed_inventory_bytes;
 planned_cfg.original_configuration_sha256:=sha256(artifact);planned_cfg.original_owner_context_bytes:=owner_bytes;
 IF document_ordinal<>jsonb_array_length(original_input->'documents') OR unique_documents NOT BETWEEN 1 AND 512 THEN
  RAISE EXCEPTION 'complete original prerequisite plan required' USING ERRCODE='55000'; END IF;
 FOREACH planned_doc IN ARRAY doc_plan LOOP
  document_profile:=planned_doc.original_definition_profile_bytes;
  EXECUTE sources->>'catalog-reserve' INTO STRICT returned USING parent.source_epoch,parent.feed_profile,parent.prerequisite_registration_counter,parent.membership_generation,parent.original_context_bytes,parent.manifest_profile_bytes;
  parent.prerequisite_registration_counter:=parent.prerequisite_registration_counter+1;parent.membership_generation:=parent.membership_generation+1;
  IF to_jsonb(returned) IS DISTINCT FROM jsonb_build_object('source_epoch',parent.source_epoch,'feed_profile',parent.feed_profile,'original_writer_xid',parent.original_writer_xid::text,'registration_counter',parent.registration_counter::text,'prerequisite_registration_counter',parent.prerequisite_registration_counter::text,'configuration_registration_counter',parent.configuration_registration_counter::text,'membership_generation',parent.membership_generation::text,'finalized_generation',parent.finalized_generation::text,'original_context_bytes_hex',encode(parent.original_context_bytes,'hex'),'manifest_profile_bytes_hex',encode(parent.manifest_profile_bytes,'hex'),'manifest_bytes_hex',encode(parent.manifest_bytes,'hex'),'manifest_sha256_hex',encode(parent.manifest_sha256,'hex')) THEN RAISE EXCEPTION 'complete catalog reservation RETURNING correspondence required' USING ERRCODE='55000'; END IF;
  IF (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(parent)) THEN RAISE EXCEPTION 'complete catalog reservation correspondence required' USING ERRCODE='55000'; END IF;
  EXECUTE sources->>'catalog-insert' INTO STRICT returned USING parent.source_epoch,parent.feed_profile,parent.prerequisite_registration_counter,parent.membership_generation,
   planned_doc.original_revision,planned_doc.original_artifact_identity_bytes,planned_doc.original_definition_bytes,document_profile,planned_doc.original_definition_sha256,owner_bytes,parent.original_context_bytes,parent.manifest_profile_bytes;
 IF to_jsonb(returned) IS DISTINCT FROM jsonb_build_object('source_epoch',planned_doc.source_epoch,'feed_profile',planned_doc.feed_profile,'original_writer_xid',planned_doc.original_writer_xid::text,'prerequisite_address',planned_doc.prerequisite_address::text,'original_revision',planned_doc.original_revision::text,'original_artifact_identity_bytes_hex',encode(planned_doc.original_artifact_identity_bytes,'hex'),'original_definition_bytes_hex',encode(planned_doc.original_definition_bytes,'hex'),'original_definition_profile_bytes_hex',encode(planned_doc.original_definition_profile_bytes,'hex'),'original_definition_sha256_hex',encode(planned_doc.original_definition_sha256,'hex'),'original_owner_context_bytes_hex',encode(planned_doc.original_owner_context_bytes,'hex')) THEN RAISE EXCEPTION 'complete prerequisite INSERT RETURNING correspondence required' USING ERRCODE='55000'; END IF;
  IF NOT EXISTS(SELECT 1 FROM truss.feed_prerequisite p WHERE record_send(p)=record_send(planned_doc)) THEN RAISE EXCEPTION 'complete original document prerequisite correspondence required' USING ERRCODE='55000'; END IF;
  expected_docs:=array_append(expected_docs,record_send(planned_doc));
 END LOOP;
 EXECUTE sources->>'configuration-reserve' INTO STRICT returned USING parent.source_epoch,parent.feed_profile,parent.configuration_registration_counter,parent.membership_generation,parent.original_context_bytes,parent.manifest_profile_bytes;
 parent.configuration_registration_counter:=1;parent.membership_generation:=parent.membership_generation+1;
 IF to_jsonb(returned) IS DISTINCT FROM jsonb_build_object('source_epoch',parent.source_epoch,'feed_profile',parent.feed_profile,'original_writer_xid',parent.original_writer_xid::text,'registration_counter',parent.registration_counter::text,'prerequisite_registration_counter',parent.prerequisite_registration_counter::text,'configuration_registration_counter',parent.configuration_registration_counter::text,'membership_generation',parent.membership_generation::text,'finalized_generation',parent.finalized_generation::text,'original_context_bytes_hex',encode(parent.original_context_bytes,'hex'),'manifest_profile_bytes_hex',encode(parent.manifest_profile_bytes,'hex'),'manifest_bytes_hex',encode(parent.manifest_bytes,'hex'),'manifest_sha256_hex',encode(parent.manifest_sha256,'hex')) THEN RAISE EXCEPTION 'complete configuration reservation RETURNING correspondence required' USING ERRCODE='55000'; END IF;
 IF (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(parent)) THEN RAISE EXCEPTION 'complete configuration reservation correspondence required' USING ERRCODE='55000'; END IF;
 EXECUTE sources->>'configuration-insert' INTO STRICT returned USING parent.source_epoch,parent.feed_profile,1::bigint,parent.membership_generation,
  planned_cfg.original_installation_identity_bytes,planned_cfg.original_configuration_generation,configuration_profile,artifact,cfg.installed_inventory_bytes,sha256(artifact),owner_bytes,parent.original_context_bytes,parent.manifest_profile_bytes;
 IF to_jsonb(returned) IS DISTINCT FROM jsonb_build_object('source_epoch',planned_cfg.source_epoch,'feed_profile',planned_cfg.feed_profile,'original_writer_xid',planned_cfg.original_writer_xid::text,'configuration_address',planned_cfg.configuration_address::text,'original_installation_identity_bytes_hex',encode(planned_cfg.original_installation_identity_bytes,'hex'),'original_configuration_generation',planned_cfg.original_configuration_generation::text,'original_configuration_profile_bytes_hex',encode(planned_cfg.original_configuration_profile_bytes,'hex'),'original_configuration_bytes_hex',encode(planned_cfg.original_configuration_bytes,'hex'),'original_producer_inventory_bytes_hex',encode(planned_cfg.original_producer_inventory_bytes,'hex'),'original_configuration_sha256_hex',encode(planned_cfg.original_configuration_sha256,'hex'),'original_owner_context_bytes_hex',encode(planned_cfg.original_owner_context_bytes,'hex')) THEN RAISE EXCEPTION 'complete prerequisite INSERT RETURNING correspondence required' USING ERRCODE='55000'; END IF;
 PERFORM truss.runtime_require_catalog_prerequisite_composition_candidate(w,o,g);
 after_state:=truss.runtime_capture_configured_completion_state_candidate(w,o,report.effect_generation);
 SELECT array_agg(record_send(p) ORDER BY p.prerequisite_address) INTO actual_docs FROM truss.feed_prerequisite p;
 IF document_ordinal<>jsonb_array_length(original_input->'documents') THEN RAISE EXCEPTION 'complete original prerequisite document inventory required' USING ERRCODE='55000'; END IF;
 SELECT coalesce(jsonb_agg(encode(v,'hex') ORDER BY encode(v,'hex') COLLATE "C"),'[]'::jsonb)
  INTO expected_doc_rows FROM unnest(expected_docs) v;
 expected_state:=jsonb_set(before_state,'{stores,feed_tx}',jsonb_build_array(encode(record_send(parent),'hex')));
 expected_state:=jsonb_set(expected_state,'{stores,feed_prerequisite}',expected_doc_rows);
 expected_state:=jsonb_set(expected_state,'{stores,feed_configuration_prerequisite}',jsonb_build_array(encode(record_send(planned_cfg),'hex')));
 IF parent.registration_counter IS DISTINCT FROM 1::bigint
  OR parent.prerequisite_registration_counter IS DISTINCT FROM unique_documents
  OR parent.configuration_registration_counter IS DISTINCT FROM 1::bigint
  OR parent.membership_generation IS DISTINCT FROM unique_documents+2
  OR parent.finalized_generation IS NOT NULL OR parent.manifest_bytes IS NOT NULL OR parent.manifest_sha256 IS NOT NULL
  OR after_state IS DISTINCT FROM expected_state OR actual_docs IS DISTINCT FROM expected_docs
  OR NOT EXISTS(SELECT 1 FROM truss.catalog_revision_custody t WHERE record_send(t)=original_custody)
  OR (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(parent))
  OR (SELECT count(*) FROM truss.feed_configuration_prerequisite)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_configuration_prerequisite p WHERE record_send(p)=record_send(planned_cfg)) THEN
  RAISE EXCEPTION 'complete configured prerequisite registration delta required' USING ERRCODE='55000'; END IF;
 RETURN QUERY SELECT w,o,report.effect_generation,encode(report_bytes,'hex'),encode(custody.original_payload_bytes,'hex'),
  parent.prerequisite_registration_counter::text,'1'::text,parent.membership_generation::text,
  'administrative_single_original_fresh_catalog_rollback_only'::text,false,false;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_register_finalizing_catalog_and_head_candidate(w text, o text, g text)
 RETURNS TABLE(writer_xid text, operation_ordinal text, effect_generation text, revision text, report_utf8_hex text, scope text, accepted_report_qualified boolean, feed_qualified boolean)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO, YMD'
 SET "IntervalStyle" TO 'iso_8601'
 SET extra_float_digits TO '3'
 SET bytea_output TO 'hex'
 SET standard_conforming_strings TO 'on'
 SET quote_all_identifiers TO 'off'
AS $function$
DECLARE produced record; before_state jsonb; after_state jsonb; expected_state jsonb;
 op truss.row_home_operation%ROWTYPE; planned_op truss.row_home_operation%ROWTYPE;
 old_head truss.schema_head%ROWTYPE; planned_head truss.schema_head%ROWTYPE; returned_head truss.schema_head%ROWTYPE;
 custody truss.catalog_revision_custody%ROWTYPE; original_custody bytea;
 rev int; input jsonb; configuration truss.operation_configuration%ROWTYPE; original_configuration bytea;
 finalized_feed jsonb; finalization record; table_name text; actual_rows jsonb;
BEGIN
 SELECT * INTO STRICT produced FROM truss.runtime_register_finalizing_catalog_prerequisites_candidate(w,o,g);
 IF produced.writer_xid IS DISTINCT FROM w OR produced.operation_ordinal IS DISTINCT FROM o
  OR produced.effect_generation IS DISTINCT FROM g OR produced.accepted_report_qualified IS DISTINCT FROM false
  OR produced.feed_qualified IS DISTINCT FROM false THEN
  RAISE EXCEPTION 'original custody prerequisite completion required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT finalization FROM truss.runtime_finalize_original_catalog_feed_candidate(w,o,g);
 finalized_feed:='{}'::jsonb;
 FOREACH table_name IN ARRAY ARRAY['feed_tx','feed_member','feed_prerequisite','feed_configuration_prerequisite'] LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(encode(record_send(t),''hex'') ORDER BY encode(record_send(t),''hex'') COLLATE "C"),''[]''::jsonb) FROM ONLY truss.%I t',table_name) INTO actual_rows;
  finalized_feed:=jsonb_set(finalized_feed,ARRAY[table_name],actual_rows);
 END LOOP;
 IF (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t
  WHERE encode(t.manifest_bytes,'hex')=finalization.tree_bytes_hex AND encode(t.manifest_sha256,'hex')=finalization.semantic_sha256_hex
  AND t.finalized_generation::text=finalization.membership_generation) THEN
  RAISE EXCEPTION 'original finalization result required before head' USING ERRCODE='55000'; END IF;
 SELECT t.* INTO STRICT op FROM truss.row_home_operation t WHERE t.original_writer_xid=pg_current_xact_id_if_assigned() AND t.operation_ordinal::text=o;
 SELECT * INTO STRICT custody FROM truss.catalog_revision_custody t WHERE t.original_writer_xid=op.original_writer_xid AND t.operation_ordinal=op.operation_ordinal;
 original_custody:=record_send(custody);rev:=custody.original_revision;
 SELECT * INTO STRICT configuration FROM truss.operation_configuration t WHERE t.original_writer_xid=op.original_writer_xid AND t.operation_ordinal=op.operation_ordinal;
 original_configuration:=record_send(configuration);
 input:=convert_from(op.original_input_bytes,'UTF8')::jsonb;
 IF input->'binding' IS DISTINCT FROM jsonb_build_object('state','absent') OR input->'transforms' IS DISTINCT FROM '[]'::jsonb
  OR EXISTS(SELECT 1 FROM truss.rel_def WHERE definition_source_kind='operation_binding') THEN
  RAISE EXCEPTION 'unsupported pending binding or promotion completion' USING ERRCODE='0A000'; END IF;
 IF produced.effect_generation IS DISTINCT FROM op.effect_generation::text OR op.effect_generation=9223372036854775807 THEN
  RAISE EXCEPTION 'original bounded head generation required' USING ERRCODE='55000'; END IF;
 before_state:=truss.runtime_capture_finalizing_completion_state_candidate(w,o,g);
 FOREACH table_name IN ARRAY ARRAY['feed_tx','feed_member','feed_prerequisite','feed_configuration_prerequisite'] LOOP
  IF before_state->'stores'->table_name IS DISTINCT FROM finalized_feed->table_name THEN
   RAISE EXCEPTION 'pre-head collector changed original finalized feed' USING ERRCODE='55000'; END IF;
 END LOOP;
 SELECT h.* INTO STRICT old_head FROM truss.schema_head h WHERE h.id=1;
 IF (SELECT count(*) FROM truss.schema_head)<>1 OR old_head.rev IS DISTINCT FROM 0 OR rev<>1 THEN
  RAISE EXCEPTION 'selected fresh original head transition required' USING ERRCODE='55000'; END IF;
 planned_head:=old_head;planned_head.rev:=rev;
 planned_op:=op;planned_op.effect_generation:=op.effect_generation+1;planned_op.phase:='admitted';
 planned_op.readiness_generation:=NULL;planned_op.sealed_generation:=NULL;
 planned_op.application_generation:=NULL;planned_op.application_result_bytes:=NULL;
 UPDATE truss.schema_head h SET rev=planned_head.rev WHERE h.id=old_head.id AND h IS NOT DISTINCT FROM old_head RETURNING h.* INTO STRICT returned_head;
 IF record_send(returned_head) IS DISTINCT FROM record_send(planned_head) THEN
  RAISE EXCEPTION 'complete head RETURNING correspondence required' USING ERRCODE='55000'; END IF;
 PERFORM truss.runtime_require_catalog_finalization_composition_candidate(w,o,planned_op.effect_generation::text);
 after_state:=truss.runtime_capture_finalizing_completion_state_candidate(w,o,planned_op.effect_generation::text);
 expected_state:=jsonb_set(before_state,'{stores,schema_head}',jsonb_build_array(encode(record_send(planned_head),'hex')));
 expected_state:=jsonb_set(expected_state,'{stores,row_home_operation}',jsonb_build_array(encode(record_send(planned_op),'hex')));
 FOREACH table_name IN ARRAY ARRAY['feed_tx','feed_member','feed_prerequisite','feed_configuration_prerequisite'] LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(encode(record_send(t),''hex'') ORDER BY encode(record_send(t),''hex'') COLLATE "C"),''[]''::jsonb) FROM ONLY truss.%I t',table_name) INTO actual_rows;
  IF actual_rows IS DISTINCT FROM finalized_feed->table_name THEN RAISE EXCEPTION 'post-head original finalized feed changed' USING ERRCODE='55000'; END IF;
 END LOOP;
 IF after_state IS DISTINCT FROM expected_state
  OR (SELECT count(*) FROM truss.schema_head)<>1 OR NOT EXISTS(SELECT 1 FROM truss.schema_head t WHERE record_send(t)=record_send(planned_head))
  OR (SELECT count(*) FROM truss.row_home_operation)<>1 OR NOT EXISTS(SELECT 1 FROM truss.row_home_operation t WHERE record_send(t)=record_send(planned_op))
  OR (SELECT count(*) FROM truss.operation_configuration)<>1 OR NOT EXISTS(SELECT 1 FROM truss.operation_configuration t WHERE record_send(t)=original_configuration)
  OR (SELECT count(*) FROM truss.catalog_revision_custody)<>1 OR NOT EXISTS(SELECT 1 FROM truss.catalog_revision_custody t WHERE record_send(t)=original_custody) THEN
  RAISE EXCEPTION 'complete original custody post-head correspondence required' USING ERRCODE='55000'; END IF;
 RETURN QUERY SELECT w,o,planned_op.effect_generation::text,rev::text,produced.report_utf8_hex,
  'administrative_rollback_only_custody_configured_head'::text,false,false;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_register_finalizing_catalog_prerequisites_candidate(w text, o text, g text)
 RETURNS TABLE(writer_xid text, operation_ordinal text, effect_generation text, report_utf8_hex text, revision_payload_utf8_hex text, document_prerequisites text, configuration_prerequisites text, membership_generation text, scope text, accepted_report_qualified boolean, feed_qualified boolean)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO, YMD'
 SET "IntervalStyle" TO 'iso_8601'
 SET extra_float_digits TO '3'
 SET bytea_output TO 'hex'
 SET standard_conforming_strings TO 'on'
 SET quote_all_identifiers TO 'off'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; cfg truss.operation_configuration%ROWTYPE;
 parent truss.feed_tx%ROWTYPE; doc truss.schema_doc%ROWTYPE; planned_doc truss.feed_prerequisite%ROWTYPE;
 planned_cfg truss.feed_configuration_prerequisite%ROWTYPE;
 recipe_bytes bytea; recipe jsonb; sources jsonb:='{}'; name text; identity text; original bytea;
 report record; custody truss.catalog_revision_custody%ROWTYPE; original_custody bytea; report_bytes bytea; expected_state jsonb; expected_doc_rows jsonb; returned record; before_state jsonb; after_state jsonb; revision int;
 document_profile bytea; configuration_profile bytea; owner_bytes bytea; artifact bytea;
 original_input jsonb; original_document jsonb; seen jsonb:='{}'; doc_identity text; document_ordinal int:=0;
 doc_plan truss.feed_prerequisite[]:=ARRAY[]::truss.feed_prerequisite[]; unique_documents bigint:=0;
 expected_docs bytea[]:=ARRAY[]::bytea[]; actual_docs bytea[]; expected_parent jsonb; expected_row jsonb;
BEGIN
 PERFORM truss.runtime_require_catalog_finalization_composition_candidate(w,o,g);
 SELECT t.* INTO STRICT op FROM truss.row_home_operation t
  WHERE t.original_writer_xid=pg_current_xact_id_if_assigned() AND t.operation_ordinal::text=o;
 identity:='packages/python/src/truss/_profiles/catalog-finalizing-custody-prerequisite-registration-candidate.json';
 LOCK TABLE truss.installation_archive IN SHARE MODE NOWAIT;
 PERFORM truss.runtime_require_selected_archive_write_fence();
 IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=(convert_from(op.original_context_bytes,'UTF8')::jsonb->>'installationId')
  AND a.artifact_role='input' AND a.artifact_identity=identity)<>1 THEN RAISE EXCEPTION 'unique prerequisite recipe required' USING ERRCODE='55000'; END IF;
 SELECT a.artifact_bytes INTO STRICT recipe_bytes FROM truss.installation_archive a
  WHERE a.installation_id=(convert_from(op.original_context_bytes,'UTF8')::jsonb->>'installationId') AND a.artifact_role='input' AND a.artifact_identity=identity
   AND a.artifact_sha256=sha256(a.artifact_bytes) AND a.artifact_sha256=decode('5939823612bff7115d2f247161f9f06f5ed95443ee5960df95e443953337b040','hex')
   AND a.artifact_identity_sha256=sha256(convert_to(a.artifact_identity,'UTF8'));
 recipe:=convert_from(recipe_bytes,'UTF8')::jsonb;
 FOREACH name IN ARRAY ARRAY['catalog-reserve','configuration-reserve','catalog-insert','configuration-insert'] LOOP
  identity:=recipe->'sources'->name->>'path';
  IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=(convert_from(op.original_context_bytes,'UTF8')::jsonb->>'installationId')
   AND a.artifact_role='input' AND a.artifact_identity=identity)<>1 THEN RAISE EXCEPTION 'unique prerequisite statement source required' USING ERRCODE='55000'; END IF;
  SELECT a.artifact_bytes INTO STRICT original FROM truss.installation_archive a
   WHERE a.installation_id=(convert_from(op.original_context_bytes,'UTF8')::jsonb->>'installationId') AND a.artifact_role='input' AND a.artifact_identity=identity
    AND a.artifact_sha256=sha256(a.artifact_bytes) AND encode(a.artifact_sha256,'hex')=recipe->'sources'->name->>'sha256'
    AND a.artifact_identity_sha256=sha256(convert_to(a.artifact_identity,'UTF8'));
  IF octet_length(original)>16384 THEN RAISE EXCEPTION 'prerequisite statement capacity' USING ERRCODE='54000'; END IF;
  sources:=sources||jsonb_build_object(name,convert_from(original,'UTF8'));
 END LOOP;
 original_input:=convert_from(op.original_input_bytes,'UTF8')::jsonb;
 PERFORM truss.runtime_require_catalog_input(op.original_input_bytes);
 IF jsonb_array_length(original_input->'documents') NOT BETWEEN 1 AND 512 THEN RAISE EXCEPTION 'bounded original document inventory required' USING ERRCODE='54000'; END IF;
 configuration_profile:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(recipe->'configurationProfile'));
 -- The sole registrar validates and copies already retained originals.
 SELECT * INTO STRICT report FROM truss.runtime_register_finalizing_revision_custody_candidate(w,o,g);
 IF report.writer_xid IS DISTINCT FROM w OR report.operation_ordinal IS DISTINCT FROM o
  OR report.effect_generation IS DISTINCT FROM g OR report.feed_qualified IS DISTINCT FROM false
  OR report.scope IS DISTINCT FROM 'administrative_rollback_only_pending_custody_feed' THEN
  RAISE EXCEPTION 'original pending custody registration required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT custody FROM truss.catalog_revision_custody t WHERE t.original_writer_xid=op.original_writer_xid
  AND t.operation_ordinal=op.operation_ordinal FOR SHARE NOWAIT;
 original_custody:=record_send(custody);revision:=custody.original_revision;
 SELECT r.report_bytes INTO STRICT report_bytes FROM truss.catalog_acceptance_report r WHERE r.rev=revision;
 SELECT t.* INTO STRICT parent FROM truss.feed_tx t;
 IF record_send(parent) IS DISTINCT FROM decode(report.parent_record_hex,'hex')
  OR parent.registration_counter IS DISTINCT FROM 1::bigint
  OR parent.prerequisite_registration_counter IS DISTINCT FROM 0::bigint
  OR parent.configuration_registration_counter IS DISTINCT FROM 0::bigint
  OR parent.membership_generation IS DISTINCT FROM 1::bigint
  OR parent.finalized_generation IS NOT NULL OR parent.manifest_bytes IS NOT NULL OR parent.manifest_sha256 IS NOT NULL
  OR (SELECT count(*) FROM truss.feed_member)<>1
  OR NOT EXISTS(SELECT 1 FROM truss.feed_member m WHERE record_send(m)=decode(report.member_record_hex,'hex')
   AND m.delivery_ordinal IS NULL) THEN
  RAISE EXCEPTION 'original pending registrar parent and member correspondence required' USING ERRCODE='55000'; END IF;
 owner_bytes:=custody.original_owner_context_bytes;
 SELECT c.* INTO STRICT cfg FROM truss.operation_configuration c WHERE c.original_writer_xid=op.original_writer_xid AND c.operation_ordinal=op.operation_ordinal;
 before_state:=truss.runtime_capture_finalizing_completion_state_candidate(w,o,report.effect_generation);
 IF (SELECT count(*) FROM truss.schema_doc d WHERE d.rev=revision) NOT BETWEEN 1 AND 512 THEN RAISE EXCEPTION 'complete bounded document prerequisites required' USING ERRCODE='54000'; END IF;
 -- Generation content excludes operation xid/ordinal/context digest and clocks.
 artifact:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'installation',cfg.installation_id,'sourceEpoch',cfg.source_epoch,'targetIncarnation',cfg.target_incarnation,
  'generation',cfg.configuration_generation::text,'keyReuse',cfg.key_reuse,'journalMode',cfg.journal_mode,
  'admissionProfileHexChunks',truss.runtime_registration_original_hex_chunks(cfg.admission_profile_bytes),
  'configurationHexChunks',truss.runtime_registration_original_hex_chunks(cfg.configuration_bytes),
  'bindingHexChunks',truss.runtime_registration_original_hex_chunks(cfg.selected_binding_bytes),
  'inventoryHexChunks',truss.runtime_registration_original_hex_chunks(cfg.installed_inventory_bytes))));
 IF octet_length(artifact)>4194304 THEN RAISE EXCEPTION 'generation artifact capacity' USING ERRCODE='54000'; END IF;
 FOR doc IN SELECT d.* FROM truss.schema_doc d WHERE d.rev=revision ORDER BY d.ord LOOP
  planned_doc.source_epoch:=parent.source_epoch;planned_doc.feed_profile:=parent.feed_profile;planned_doc.original_writer_xid:=parent.original_writer_xid;
  planned_doc.prerequisite_address:=unique_documents+1;planned_doc.original_revision:=revision;
  original_document:=original_input->'documents'->document_ordinal;document_ordinal:=document_ordinal+1;
  IF original_document->>'documentId' IS DISTINCT FROM doc.doc_id OR original_document->>'documentRevision' IS DISTINCT FROM doc.doc_revision THEN
   RAISE EXCEPTION 'original document ordering and identity required' USING ERRCODE='55000'; END IF;
  doc_identity:=original_document->'artifact'->>'identity';
  planned_doc.original_artifact_identity_bytes:=convert_to(doc_identity,'UTF8');
  planned_doc.original_definition_bytes:=decode(original_document->'artifact'->>'bytesBase64','base64');
  document_profile:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(original_document->'umfProfile'));
  planned_doc.original_definition_profile_bytes:=document_profile;
  IF planned_doc.original_definition_bytes IS DISTINCT FROM convert_to(doc.document,'UTF8') THEN RAISE EXCEPTION 'complete original document bytes required' USING ERRCODE='55000'; END IF;
  IF seen ? doc_identity THEN
   IF seen->doc_identity IS DISTINCT FROM jsonb_build_object('bytes',encode(planned_doc.original_definition_bytes,'hex'),'profile',encode(document_profile,'hex')) THEN
    RAISE EXCEPTION 'conflicting original document artifact identity' USING ERRCODE='55000'; END IF;
   CONTINUE;
  END IF;
  seen:=seen||jsonb_build_object(doc_identity,jsonb_build_object('bytes',encode(planned_doc.original_definition_bytes,'hex'),'profile',encode(document_profile,'hex')));
  planned_doc.original_definition_sha256:=sha256(planned_doc.original_definition_bytes);planned_doc.original_owner_context_bytes:=owner_bytes;
  IF encode(planned_doc.original_definition_sha256,'hex') IS DISTINCT FROM doc.content_sha256 THEN RAISE EXCEPTION 'original document bytes digest correspondence required' USING ERRCODE='55000'; END IF;
  unique_documents:=unique_documents+1;doc_plan:=array_append(doc_plan,planned_doc);
 END LOOP;
 planned_cfg.source_epoch:=parent.source_epoch;planned_cfg.feed_profile:=parent.feed_profile;planned_cfg.original_writer_xid:=parent.original_writer_xid;
 planned_cfg.configuration_address:=1;planned_cfg.original_installation_identity_bytes:=convert_to(cfg.installation_id,'UTF8');
 planned_cfg.original_configuration_generation:=cfg.configuration_generation;planned_cfg.original_configuration_profile_bytes:=configuration_profile;
 planned_cfg.original_configuration_bytes:=artifact;planned_cfg.original_producer_inventory_bytes:=cfg.installed_inventory_bytes;
 planned_cfg.original_configuration_sha256:=sha256(artifact);planned_cfg.original_owner_context_bytes:=owner_bytes;
 IF document_ordinal<>jsonb_array_length(original_input->'documents') OR unique_documents NOT BETWEEN 1 AND 512 THEN
  RAISE EXCEPTION 'complete original prerequisite plan required' USING ERRCODE='55000'; END IF;
 FOREACH planned_doc IN ARRAY doc_plan LOOP
  document_profile:=planned_doc.original_definition_profile_bytes;
  EXECUTE sources->>'catalog-reserve' INTO STRICT returned USING parent.source_epoch,parent.feed_profile,parent.prerequisite_registration_counter,parent.membership_generation,parent.original_context_bytes,parent.manifest_profile_bytes;
  parent.prerequisite_registration_counter:=parent.prerequisite_registration_counter+1;parent.membership_generation:=parent.membership_generation+1;
  IF to_jsonb(returned) IS DISTINCT FROM jsonb_build_object('source_epoch',parent.source_epoch,'feed_profile',parent.feed_profile,'original_writer_xid',parent.original_writer_xid::text,'registration_counter',parent.registration_counter::text,'prerequisite_registration_counter',parent.prerequisite_registration_counter::text,'configuration_registration_counter',parent.configuration_registration_counter::text,'membership_generation',parent.membership_generation::text,'finalized_generation',parent.finalized_generation::text,'original_context_bytes_hex',encode(parent.original_context_bytes,'hex'),'manifest_profile_bytes_hex',encode(parent.manifest_profile_bytes,'hex'),'manifest_bytes_hex',encode(parent.manifest_bytes,'hex'),'manifest_sha256_hex',encode(parent.manifest_sha256,'hex')) THEN RAISE EXCEPTION 'complete catalog reservation RETURNING correspondence required' USING ERRCODE='55000'; END IF;
  IF (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(parent)) THEN RAISE EXCEPTION 'complete catalog reservation correspondence required' USING ERRCODE='55000'; END IF;
  EXECUTE sources->>'catalog-insert' INTO STRICT returned USING parent.source_epoch,parent.feed_profile,parent.prerequisite_registration_counter,parent.membership_generation,
   planned_doc.original_revision,planned_doc.original_artifact_identity_bytes,planned_doc.original_definition_bytes,document_profile,planned_doc.original_definition_sha256,owner_bytes,parent.original_context_bytes,parent.manifest_profile_bytes;
 IF to_jsonb(returned) IS DISTINCT FROM jsonb_build_object('source_epoch',planned_doc.source_epoch,'feed_profile',planned_doc.feed_profile,'original_writer_xid',planned_doc.original_writer_xid::text,'prerequisite_address',planned_doc.prerequisite_address::text,'original_revision',planned_doc.original_revision::text,'original_artifact_identity_bytes_hex',encode(planned_doc.original_artifact_identity_bytes,'hex'),'original_definition_bytes_hex',encode(planned_doc.original_definition_bytes,'hex'),'original_definition_profile_bytes_hex',encode(planned_doc.original_definition_profile_bytes,'hex'),'original_definition_sha256_hex',encode(planned_doc.original_definition_sha256,'hex'),'original_owner_context_bytes_hex',encode(planned_doc.original_owner_context_bytes,'hex')) THEN RAISE EXCEPTION 'complete prerequisite INSERT RETURNING correspondence required' USING ERRCODE='55000'; END IF;
  IF NOT EXISTS(SELECT 1 FROM truss.feed_prerequisite p WHERE record_send(p)=record_send(planned_doc)) THEN RAISE EXCEPTION 'complete original document prerequisite correspondence required' USING ERRCODE='55000'; END IF;
  expected_docs:=array_append(expected_docs,record_send(planned_doc));
 END LOOP;
 EXECUTE sources->>'configuration-reserve' INTO STRICT returned USING parent.source_epoch,parent.feed_profile,parent.configuration_registration_counter,parent.membership_generation,parent.original_context_bytes,parent.manifest_profile_bytes;
 parent.configuration_registration_counter:=1;parent.membership_generation:=parent.membership_generation+1;
 IF to_jsonb(returned) IS DISTINCT FROM jsonb_build_object('source_epoch',parent.source_epoch,'feed_profile',parent.feed_profile,'original_writer_xid',parent.original_writer_xid::text,'registration_counter',parent.registration_counter::text,'prerequisite_registration_counter',parent.prerequisite_registration_counter::text,'configuration_registration_counter',parent.configuration_registration_counter::text,'membership_generation',parent.membership_generation::text,'finalized_generation',parent.finalized_generation::text,'original_context_bytes_hex',encode(parent.original_context_bytes,'hex'),'manifest_profile_bytes_hex',encode(parent.manifest_profile_bytes,'hex'),'manifest_bytes_hex',encode(parent.manifest_bytes,'hex'),'manifest_sha256_hex',encode(parent.manifest_sha256,'hex')) THEN RAISE EXCEPTION 'complete configuration reservation RETURNING correspondence required' USING ERRCODE='55000'; END IF;
 IF (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(parent)) THEN RAISE EXCEPTION 'complete configuration reservation correspondence required' USING ERRCODE='55000'; END IF;
 EXECUTE sources->>'configuration-insert' INTO STRICT returned USING parent.source_epoch,parent.feed_profile,1::bigint,parent.membership_generation,
  planned_cfg.original_installation_identity_bytes,planned_cfg.original_configuration_generation,configuration_profile,artifact,cfg.installed_inventory_bytes,sha256(artifact),owner_bytes,parent.original_context_bytes,parent.manifest_profile_bytes;
 IF to_jsonb(returned) IS DISTINCT FROM jsonb_build_object('source_epoch',planned_cfg.source_epoch,'feed_profile',planned_cfg.feed_profile,'original_writer_xid',planned_cfg.original_writer_xid::text,'configuration_address',planned_cfg.configuration_address::text,'original_installation_identity_bytes_hex',encode(planned_cfg.original_installation_identity_bytes,'hex'),'original_configuration_generation',planned_cfg.original_configuration_generation::text,'original_configuration_profile_bytes_hex',encode(planned_cfg.original_configuration_profile_bytes,'hex'),'original_configuration_bytes_hex',encode(planned_cfg.original_configuration_bytes,'hex'),'original_producer_inventory_bytes_hex',encode(planned_cfg.original_producer_inventory_bytes,'hex'),'original_configuration_sha256_hex',encode(planned_cfg.original_configuration_sha256,'hex'),'original_owner_context_bytes_hex',encode(planned_cfg.original_owner_context_bytes,'hex')) THEN RAISE EXCEPTION 'complete prerequisite INSERT RETURNING correspondence required' USING ERRCODE='55000'; END IF;
 PERFORM truss.runtime_require_catalog_finalization_composition_candidate(w,o,g);
 after_state:=truss.runtime_capture_finalizing_completion_state_candidate(w,o,report.effect_generation);
 SELECT array_agg(record_send(p) ORDER BY p.prerequisite_address) INTO actual_docs FROM truss.feed_prerequisite p;
 IF document_ordinal<>jsonb_array_length(original_input->'documents') THEN RAISE EXCEPTION 'complete original prerequisite document inventory required' USING ERRCODE='55000'; END IF;
 SELECT coalesce(jsonb_agg(encode(v,'hex') ORDER BY encode(v,'hex') COLLATE "C"),'[]'::jsonb)
  INTO expected_doc_rows FROM unnest(expected_docs) v;
 expected_state:=jsonb_set(before_state,'{stores,feed_tx}',jsonb_build_array(encode(record_send(parent),'hex')));
 expected_state:=jsonb_set(expected_state,'{stores,feed_prerequisite}',expected_doc_rows);
 expected_state:=jsonb_set(expected_state,'{stores,feed_configuration_prerequisite}',jsonb_build_array(encode(record_send(planned_cfg),'hex')));
 IF parent.registration_counter IS DISTINCT FROM 1::bigint
  OR parent.prerequisite_registration_counter IS DISTINCT FROM unique_documents
  OR parent.configuration_registration_counter IS DISTINCT FROM 1::bigint
  OR parent.membership_generation IS DISTINCT FROM unique_documents+2
  OR parent.finalized_generation IS NOT NULL OR parent.manifest_bytes IS NOT NULL OR parent.manifest_sha256 IS NOT NULL
  OR after_state IS DISTINCT FROM expected_state OR actual_docs IS DISTINCT FROM expected_docs
  OR NOT EXISTS(SELECT 1 FROM truss.catalog_revision_custody t WHERE record_send(t)=original_custody)
  OR (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(parent))
  OR (SELECT count(*) FROM truss.feed_configuration_prerequisite)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_configuration_prerequisite p WHERE record_send(p)=record_send(planned_cfg)) THEN
  RAISE EXCEPTION 'complete configured prerequisite registration delta required' USING ERRCODE='55000'; END IF;
 RETURN QUERY SELECT w,o,report.effect_generation,encode(report_bytes,'hex'),encode(custody.original_payload_bytes,'hex'),
  parent.prerequisite_registration_counter::text,'1'::text,parent.membership_generation::text,
  'administrative_single_original_fresh_catalog_rollback_only'::text,false,false;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_register_finalizing_revision_custody_candidate(w text, o text, g text)
 RETURNS TABLE(writer_xid text, operation_ordinal text, effect_generation text, parent_record_hex text, member_record_hex text, scope text, feed_qualified boolean)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO, YMD'
 SET "IntervalStyle" TO 'iso_8601'
 SET extra_float_digits TO '3'
 SET bytea_output TO 'hex'
 SET standard_conforming_strings TO 'on'
 SET quote_all_identifiers TO 'off'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; custody truss.catalog_revision_custody%ROWTYPE;
 original_custody bytea; before_state jsonb; after_state jsonb; expected_state jsonb;
 planned_parent truss.feed_tx%ROWTYPE; planned_member truss.feed_member%ROWTYPE;
 returned record; expected_snapshot jsonb; context jsonb; profile jsonb; profile_bytes bytea;
 source_sql jsonb:='{}'; source_name text; identity text; raw bytea;
 payload bytea; payload_profile bytea; key_profile bytea; owner_bytes bytea;
 revision_row truss.schema_rev%ROWTYPE; configuration truss.operation_configuration%ROWTYPE;
 original_report bytea; expected_payload bytea; revision_tree jsonb; origin jsonb; journal_envelope jsonb;
 input jsonb; report_identity text; original_documents bytea[]; document_record bytea;
 documents jsonb:='[]'; original_configuration bytea; original_op bytea; original_revision bytea;
 original_bytes bigint; total_chunks bigint; expected_owner bytea;
 manifest_bytes bytea; clock_bytes bytea; original_write_at timestamptz; revision int;
BEGIN
 PERFORM truss.runtime_require_catalog_finalization_composition_candidate(w,o,g);
 SELECT * INTO STRICT op FROM truss.row_home_operation t WHERE t.original_writer_xid=pg_current_xact_id_if_assigned()
  AND t.operation_ordinal::text=o FOR UPDATE;
 IF (SELECT count(*) FROM truss.catalog_revision_custody t
  WHERE t.original_writer_xid=op.original_writer_xid AND t.operation_ordinal=op.operation_ordinal)<>1 THEN
  RAISE EXCEPTION 'unique original custody for current operation required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT custody FROM truss.catalog_revision_custody t WHERE t.original_writer_xid=op.original_writer_xid
  AND t.operation_ordinal=op.operation_ordinal FOR SHARE NOWAIT;
 IF (SELECT count(*) FROM truss.row_home_operation)<>1 OR (SELECT count(*) FROM truss.catalog_revision_custody)<>1
  OR custody.capture_generation::text IS DISTINCT FROM g OR op.effect_generation::text IS DISTINCT FROM g
  OR (SELECT count(*) FROM truss.schema_head)<>1 OR NOT EXISTS(SELECT 1 FROM truss.schema_head h WHERE h.id=1 AND h.rev=0)
  OR NOT EXISTS(SELECT 1 FROM truss.schema_rev r WHERE r.rev=custody.original_revision)
  OR NOT EXISTS(SELECT 1 FROM truss.catalog_acceptance_report r WHERE r.rev=custody.original_revision) THEN
  RAISE EXCEPTION 'single current original unpublished catalog custody required' USING ERRCODE='55000'; END IF;
 original_custody:=record_send(custody);context:=convert_from(op.original_context_bytes,'UTF8')::jsonb;
 before_state:=truss.runtime_capture_finalizing_completion_state_candidate(w,o,g);
 IF before_state->'stores'->'feed_tx' IS DISTINCT FROM '[]'::jsonb
  OR before_state->'stores'->'feed_member' IS DISTINCT FROM '[]'::jsonb
  OR before_state->'stores'->'feed_prerequisite' IS DISTINCT FROM '[]'::jsonb
  OR before_state->'stores'->'feed_configuration_prerequisite' IS DISTINCT FROM '[]'::jsonb THEN
  RAISE EXCEPTION 'single initial custody registration only' USING ERRCODE='55000'; END IF;
 LOCK TABLE truss.installation_archive IN SHARE MODE NOWAIT;
 PERFORM truss.runtime_require_selected_archive_write_fence();
 identity:='packages/python/src/truss/_profiles/catalog-finalizing-custody-registration-candidate.json';
 IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=context->>'installationId'
  AND a.artifact_role='input' AND a.artifact_identity=identity)<>1 THEN
  RAISE EXCEPTION 'unique original custody registration recipe required' USING ERRCODE='55000'; END IF;
 SELECT a.artifact_bytes INTO STRICT profile_bytes FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=identity
  AND a.artifact_sha256=sha256(a.artifact_bytes) AND encode(a.artifact_sha256,'hex')='0706da4b4387b49834d095f2fbdc3dfb3ba4bb4e3ac22e7c0afdb64c7429e73b'
  AND a.artifact_identity_sha256=sha256(convert_to(identity,'UTF8'));
 IF octet_length(profile_bytes)>65536 THEN RAISE EXCEPTION 'recipe capacity' USING ERRCODE='54000'; END IF;
 profile:=convert_from(profile_bytes,'UTF8')::jsonb;
 FOREACH source_name IN ARRAY ARRAY['create','reserve','insert','producer','payload'] LOOP
  IF source_name='producer' THEN identity:=profile->'custodyProducer'->>'path';
  ELSIF source_name='payload' THEN identity:=profile->'payloadProfile'->>'path';
  ELSE identity:=profile->'sources'->source_name->>'path';END IF;
  IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=context->>'installationId'
   AND a.artifact_role='input' AND a.artifact_identity=identity)<>1 THEN
   RAISE EXCEPTION 'unique original selected registration artifact required' USING ERRCODE='55000'; END IF;
  SELECT a.artifact_bytes INTO STRICT raw FROM truss.installation_archive a
   WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=identity
   AND a.artifact_sha256=sha256(a.artifact_bytes) AND a.artifact_identity_sha256=sha256(convert_to(identity,'UTF8'))
   AND encode(a.artifact_sha256,'hex')=CASE source_name WHEN 'producer' THEN profile->'custodyProducer'->>'sha256'
    WHEN 'payload' THEN profile->'payloadProfile'->>'sha256' ELSE profile->'sources'->source_name->>'sha256' END;
  IF source_name='producer' THEN
   IF raw IS DISTINCT FROM custody.original_producer_profile_bytes THEN RAISE EXCEPTION 'original custody producer required' USING ERRCODE='55000'; END IF;
  ELSIF source_name='payload' THEN
   IF raw IS DISTINCT FROM custody.original_payload_profile_bytes THEN RAISE EXCEPTION 'original custody payload profile required' USING ERRCODE='55000'; END IF;
  ELSE
   IF octet_length(raw)>16384 THEN RAISE EXCEPTION 'statement capacity' USING ERRCODE='54000';END IF;
   source_sql:=source_sql||jsonb_build_object(source_name,convert_from(raw,'UTF8'));
  END IF;
 END LOOP;
 revision:=custody.original_revision;payload:=custody.original_payload_bytes;payload_profile:=custody.original_payload_profile_bytes;
 key_profile:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(profile->'keyProfile'));
 IF key_profile IS DISTINCT FROM custody.original_fact_key_profile_bytes
  OR custody.original_fact_key_bytes IS DISTINCT FROM truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(jsonb_build_object('kind','revision','revision',revision::text))) THEN
  RAISE EXCEPTION 'original revision key profile correspondence required' USING ERRCODE='55000'; END IF;
 owner_bytes:=custody.original_owner_context_bytes;
 manifest_bytes:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(profile->'manifestProfile'));
 IF octet_length(custody.original_producer_profile_bytes)>65536
  OR octet_length(custody.original_fact_key_bytes)>65536 OR octet_length(custody.original_fact_key_profile_bytes)>65536
  OR octet_length(custody.original_payload_bytes)>4194304 OR octet_length(custody.original_payload_profile_bytes)>65536
  OR octet_length(custody.original_owner_context_bytes)>16777216 OR octet_length(custody.original_fact_clock_bytes)>65536
  OR NOT isfinite(custody.original_write_at)
  OR extract(year FROM custody.original_write_at AT TIME ZONE 'UTC') NOT BETWEEN 1 AND 9999 THEN
  RAISE EXCEPTION 'bounded finite original custody required' USING ERRCODE='54000'; END IF;
 clock_bytes:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'profile',profile->'clockProfile','originalWriteAt',to_char(custody.original_write_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))));
 IF clock_bytes IS DISTINCT FROM custody.original_fact_clock_bytes THEN
  RAISE EXCEPTION 'original retained clock profile and timestamp correspondence required' USING ERRCODE='55000'; END IF;
 -- Read-only independent correspondence; the registered bytes remain custody originals.
 SELECT * INTO STRICT revision_row FROM truss.schema_rev r WHERE r.rev=revision;
 SELECT r.report_bytes INTO STRICT original_report FROM truss.catalog_acceptance_report r WHERE r.rev=revision;
 IF (SELECT count(*) FROM truss.catalog_acceptance_report)<>1
  OR NOT isfinite(revision_row.accepted_at)
  OR extract(year FROM revision_row.accepted_at AT TIME ZONE 'UTC') NOT BETWEEN 1 AND 9999
  OR octet_length(original_report)>786432 OR octet_length(op.original_input_bytes)>1048576 THEN
  RAISE EXCEPTION 'bounded finite original report and revision required' USING ERRCODE='55000'; END IF;
 input:=convert_from(op.original_input_bytes,'UTF8')::jsonb;
 origin:=truss.runtime_catalog_report_original_tree(decode(context->>'assertedOriginUtf8Hex','hex'));
 IF truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(revision_row.origin))
  IS DISTINCT FROM truss.runtime_canonical_tree_bytes(origin) THEN
  RAISE EXCEPTION 'original retained revision origin correspondence required' USING ERRCODE='55000'; END IF;
 journal_envelope:=truss.runtime_catalog_report_native_tree(jsonb_build_object('databaseRole',context->>'actingUser'));
 journal_envelope:=jsonb_set(journal_envelope,'{members}',journal_envelope->'members'||jsonb_build_array(
  jsonb_build_object('keyUtf8Hex','6173736572746564','node',truss.runtime_catalog_report_map_origin_tree(origin))));
 report_identity:='truss.candidate.catalog-report/'||encode(convert_to(context->>'installationId','UTF8'),'hex')
  ||'/'||encode(convert_to(context->>'sourceEpoch','UTF8'),'hex')||'/'||revision::text;
 revision_tree:=truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'interfaceVersion','truss-feed-revision/0.1.0','revision',revision::text,
  'acceptedAt',to_char(revision_row.accepted_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'input',input,'report',jsonb_build_object('identity',report_identity,
   'bytesBase64',replace(encode(original_report,'base64'),chr(10),''),'sha256',encode(sha256(original_report),'hex'))));
 revision_tree:=jsonb_set(revision_tree,'{members}',revision_tree->'members'||jsonb_build_array(
  jsonb_build_object('keyUtf8Hex','6f726967696e','node',journal_envelope)));
 IF octet_length(revision_tree::text)>4194304 THEN RAISE EXCEPTION 'revision comparison tree capacity' USING ERRCODE='54000';END IF;
 expected_payload:=truss.runtime_revision_report_tree_bytes_wide_candidate(revision_tree,original_report);
 IF expected_payload IS DISTINCT FROM custody.original_payload_bytes THEN
  RAISE EXCEPTION 'original retained report and revision payload correspondence required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT configuration FROM truss.operation_configuration t
  WHERE t.original_writer_xid=op.original_writer_xid AND t.operation_ordinal=op.operation_ordinal;
 original_configuration:=record_send(configuration);original_op:=record_send(op);original_revision:=record_send(revision_row);
 SELECT array_agg(record_send(d) ORDER BY d.ord) INTO original_documents FROM truss.schema_doc d WHERE d.rev=revision;
 IF original_documents IS NULL OR cardinality(original_documents) NOT BETWEEN 1 AND 512 THEN
  RAISE EXCEPTION 'complete original document custody required' USING ERRCODE='55000'; END IF;
 original_bytes:=octet_length(original_configuration)::bigint+octet_length(original_op)::bigint+
  octet_length(op.original_context_bytes)::bigint+octet_length(original_revision)::bigint;
 total_chunks:=((octet_length(original_configuration)+32767)/32768)+((octet_length(original_op)+32767)/32768)+
  ((octet_length(op.original_context_bytes)+32767)/32768)+((octet_length(original_revision)+32767)/32768);
 FOREACH document_record IN ARRAY original_documents LOOP
  IF document_record IS NULL THEN RAISE EXCEPTION 'original document bytes required' USING ERRCODE='55000'; END IF;
  original_bytes:=original_bytes+octet_length(document_record)::bigint;
  total_chunks:=total_chunks+((octet_length(document_record)+32767)/32768);
 END LOOP;
 IF original_bytes>786432 OR total_chunks>1024 THEN RAISE EXCEPTION 'original custody codec capacity' USING ERRCODE='54000'; END IF;
 FOREACH document_record IN ARRAY original_documents LOOP
  documents:=documents||jsonb_build_array(truss.runtime_registration_original_hex_chunks(document_record));
 END LOOP;
 expected_owner:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'scope','administrative_single_original_operation_fresh_catalog_rollback_only',
  'originalConfigurationRecordHexChunks',truss.runtime_registration_original_hex_chunks(original_configuration),
  'originalOperationRecordHexChunks',truss.runtime_registration_original_hex_chunks(original_op),
  'originalContextHexChunks',truss.runtime_registration_original_hex_chunks(op.original_context_bytes),
  'originalRevisionRecordHexChunks',truss.runtime_registration_original_hex_chunks(original_revision),
  'originalDocumentRecordHexChunks',documents)));
 IF expected_owner IS DISTINCT FROM custody.original_owner_context_bytes THEN
  RAISE EXCEPTION 'original retained owner record correspondence required' USING ERRCODE='55000'; END IF;
 planned_parent.source_epoch:=context->>'sourceEpoch';planned_parent.feed_profile:=profile->>'identity';
 planned_parent.original_writer_xid:=op.original_writer_xid;planned_parent.registration_counter:=0;
 planned_parent.prerequisite_registration_counter:=0;planned_parent.configuration_registration_counter:=0;
 planned_parent.membership_generation:=0;planned_parent.original_context_bytes:=op.original_context_bytes;
 planned_parent.manifest_profile_bytes:=manifest_bytes;
 EXECUTE source_sql->>'create' INTO STRICT returned USING planned_parent.source_epoch,planned_parent.feed_profile,op.original_context_bytes,manifest_bytes;
 expected_snapshot:=jsonb_build_object('source_epoch',planned_parent.source_epoch,'feed_profile',planned_parent.feed_profile,
  'original_writer_xid',op.original_writer_xid::text,'registration_counter','0','prerequisite_registration_counter','0',
  'configuration_registration_counter','0','membership_generation','0','finalized_generation',NULL,
  'original_context_bytes_hex',encode(op.original_context_bytes,'hex'),'manifest_profile_bytes_hex',encode(manifest_bytes,'hex'),
  'manifest_bytes_hex',NULL,'manifest_sha256_hex',NULL);
 IF to_jsonb(returned) IS DISTINCT FROM expected_snapshot
  OR (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(planned_parent)) THEN
  RAISE EXCEPTION 'original pending parent insert readback required' USING ERRCODE='55000'; END IF;
 planned_parent.registration_counter:=1;planned_parent.membership_generation:=1;
 EXECUTE source_sql->>'reserve' INTO STRICT returned USING planned_parent.source_epoch,planned_parent.feed_profile,0::bigint,0::bigint,op.original_context_bytes,manifest_bytes;
 expected_snapshot:=jsonb_set(jsonb_set(expected_snapshot,'{registration_counter}','"1"'),'{membership_generation}','"1"');
 IF to_jsonb(returned) IS DISTINCT FROM expected_snapshot
  OR (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(planned_parent)) THEN
  RAISE EXCEPTION 'original parent reservation readback required' USING ERRCODE='55000'; END IF;
 planned_member.source_epoch:=planned_parent.source_epoch;planned_member.feed_profile:=planned_parent.feed_profile;
 planned_member.original_writer_xid:=op.original_writer_xid;planned_member.registration_address:=1;
 planned_member.fact_kind:='revision';planned_member.original_fact_key_bytes:=custody.original_fact_key_bytes;
 planned_member.original_fact_key_profile_bytes:=key_profile;planned_member.original_payload_bytes:=payload;
 planned_member.original_payload_profile_bytes:=payload_profile;planned_member.original_payload_sha256:=sha256(payload);
 planned_member.original_owner_context_bytes:=owner_bytes;
 -- Preserve the original custody clock; registration never samples a new clock.
 original_write_at:=custody.original_write_at;
 IF NOT isfinite(original_write_at) OR extract(year FROM original_write_at AT TIME ZONE 'UTC') NOT BETWEEN 1 AND 9999 THEN
  RAISE EXCEPTION 'finite native member write clock required' USING ERRCODE='55000'; END IF;
 clock_bytes:=custody.original_fact_clock_bytes;
 planned_member.original_write_at:=original_write_at;planned_member.original_fact_clock_bytes:=clock_bytes;
 EXECUTE source_sql->>'insert' INTO STRICT returned USING planned_parent.source_epoch,planned_parent.feed_profile,1::bigint,1::bigint,
  'revision',planned_member.original_fact_key_bytes,key_profile,payload,payload_profile,sha256(payload),owner_bytes,
  original_write_at,clock_bytes,op.original_context_bytes,manifest_bytes;
 expected_snapshot:=jsonb_build_object('source_epoch',planned_member.source_epoch,'feed_profile',planned_member.feed_profile,
  'original_writer_xid',op.original_writer_xid::text,'registration_address','1','fact_kind','revision',
  'original_fact_key_bytes_hex',encode(planned_member.original_fact_key_bytes,'hex'),'original_fact_key_profile_bytes_hex',encode(key_profile,'hex'),
  'original_payload_bytes_hex',encode(payload,'hex'),'original_payload_profile_bytes_hex',encode(payload_profile,'hex'),
  'original_payload_sha256_hex',encode(sha256(payload),'hex'),'original_owner_context_bytes_hex',encode(owner_bytes,'hex'),
  'original_write_at',original_write_at::text,'original_fact_clock_bytes_hex',encode(clock_bytes,'hex'),'delivery_ordinal',NULL);
 IF to_jsonb(returned) IS DISTINCT FROM expected_snapshot THEN
  RAISE EXCEPTION 'original revision member returned snapshot required' USING ERRCODE='55000'; END IF;
 PERFORM truss.runtime_require_catalog_finalization_composition_candidate(w,o,g);
 after_state:=truss.runtime_capture_finalizing_completion_state_candidate(w,o,g);
 expected_state:=jsonb_set(before_state,'{stores,feed_tx}',jsonb_build_array(encode(record_send(planned_parent),'hex')));
 expected_state:=jsonb_set(expected_state,'{stores,feed_member}',jsonb_build_array(encode(record_send(planned_member),'hex')));
 IF after_state IS DISTINCT FROM expected_state OR NOT EXISTS(SELECT 1 FROM truss.catalog_revision_custody t
  WHERE record_send(t)=original_custody) THEN
  RAISE EXCEPTION 'complete independent original custody registration delta required' USING ERRCODE='55000'; END IF;
 RETURN QUERY SELECT w,o,g,encode(record_send(planned_parent),'hex'),encode(record_send(planned_member),'hex'),
  'administrative_rollback_only_pending_custody_feed'::text,false;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_register_prerequisite_revision_custody_candidate(w text, o text, g text)
 RETURNS TABLE(writer_xid text, operation_ordinal text, effect_generation text, parent_record_hex text, member_record_hex text, scope text, feed_qualified boolean)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO, YMD'
 SET "IntervalStyle" TO 'iso_8601'
 SET extra_float_digits TO '3'
 SET bytea_output TO 'hex'
 SET standard_conforming_strings TO 'on'
 SET quote_all_identifiers TO 'off'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; custody truss.catalog_revision_custody%ROWTYPE;
 original_custody bytea; before_state jsonb; after_state jsonb; expected_state jsonb;
 planned_parent truss.feed_tx%ROWTYPE; planned_member truss.feed_member%ROWTYPE;
 returned record; expected_snapshot jsonb; context jsonb; profile jsonb; profile_bytes bytea;
 source_sql jsonb:='{}'; source_name text; identity text; raw bytea;
 payload bytea; payload_profile bytea; key_profile bytea; owner_bytes bytea;
 revision_row truss.schema_rev%ROWTYPE; configuration truss.operation_configuration%ROWTYPE;
 original_report bytea; expected_payload bytea; revision_tree jsonb; origin jsonb; journal_envelope jsonb;
 input jsonb; report_identity text; original_documents bytea[]; document_record bytea;
 documents jsonb:='[]'; original_configuration bytea; original_op bytea; original_revision bytea;
 original_bytes bigint; total_chunks bigint; expected_owner bytea;
 manifest_bytes bytea; clock_bytes bytea; original_write_at timestamptz; revision int;
BEGIN
 PERFORM truss.runtime_require_catalog_prerequisite_composition_candidate(w,o,g);
 SELECT * INTO STRICT op FROM truss.row_home_operation t WHERE t.original_writer_xid=pg_current_xact_id_if_assigned()
  AND t.operation_ordinal::text=o FOR UPDATE;
 IF (SELECT count(*) FROM truss.catalog_revision_custody t
  WHERE t.original_writer_xid=op.original_writer_xid AND t.operation_ordinal=op.operation_ordinal)<>1 THEN
  RAISE EXCEPTION 'unique original custody for current operation required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT custody FROM truss.catalog_revision_custody t WHERE t.original_writer_xid=op.original_writer_xid
  AND t.operation_ordinal=op.operation_ordinal FOR SHARE NOWAIT;
 IF (SELECT count(*) FROM truss.row_home_operation)<>1 OR (SELECT count(*) FROM truss.catalog_revision_custody)<>1
  OR custody.capture_generation::text IS DISTINCT FROM g OR op.effect_generation::text IS DISTINCT FROM g
  OR (SELECT count(*) FROM truss.schema_head)<>1 OR NOT EXISTS(SELECT 1 FROM truss.schema_head h WHERE h.id=1 AND h.rev=0)
  OR NOT EXISTS(SELECT 1 FROM truss.schema_rev r WHERE r.rev=custody.original_revision)
  OR NOT EXISTS(SELECT 1 FROM truss.catalog_acceptance_report r WHERE r.rev=custody.original_revision) THEN
  RAISE EXCEPTION 'single current original unpublished catalog custody required' USING ERRCODE='55000'; END IF;
 original_custody:=record_send(custody);context:=convert_from(op.original_context_bytes,'UTF8')::jsonb;
 before_state:=truss.runtime_capture_configured_completion_state_candidate(w,o,g);
 IF before_state->'stores'->'feed_tx' IS DISTINCT FROM '[]'::jsonb
  OR before_state->'stores'->'feed_member' IS DISTINCT FROM '[]'::jsonb
  OR before_state->'stores'->'feed_prerequisite' IS DISTINCT FROM '[]'::jsonb
  OR before_state->'stores'->'feed_configuration_prerequisite' IS DISTINCT FROM '[]'::jsonb THEN
  RAISE EXCEPTION 'single initial custody registration only' USING ERRCODE='55000'; END IF;
 LOCK TABLE truss.installation_archive IN SHARE MODE NOWAIT;
 PERFORM truss.runtime_require_selected_archive_write_fence();
 identity:='packages/python/src/truss/_profiles/catalog-prerequisite-custody-registration-candidate.json';
 IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=context->>'installationId'
  AND a.artifact_role='input' AND a.artifact_identity=identity)<>1 THEN
  RAISE EXCEPTION 'unique original custody registration recipe required' USING ERRCODE='55000'; END IF;
 SELECT a.artifact_bytes INTO STRICT profile_bytes FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=identity
  AND a.artifact_sha256=sha256(a.artifact_bytes) AND encode(a.artifact_sha256,'hex')='d981f6a17e54873c781eeece986dbc93a47a7a2ce3460e38d710f13ea0edcaa8'
  AND a.artifact_identity_sha256=sha256(convert_to(identity,'UTF8'));
 IF octet_length(profile_bytes)>65536 THEN RAISE EXCEPTION 'recipe capacity' USING ERRCODE='54000'; END IF;
 profile:=convert_from(profile_bytes,'UTF8')::jsonb;
 FOREACH source_name IN ARRAY ARRAY['create','reserve','insert','producer','payload'] LOOP
  IF source_name='producer' THEN identity:=profile->'custodyProducer'->>'path';
  ELSIF source_name='payload' THEN identity:=profile->'payloadProfile'->>'path';
  ELSE identity:=profile->'sources'->source_name->>'path';END IF;
  IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=context->>'installationId'
   AND a.artifact_role='input' AND a.artifact_identity=identity)<>1 THEN
   RAISE EXCEPTION 'unique original selected registration artifact required' USING ERRCODE='55000'; END IF;
  SELECT a.artifact_bytes INTO STRICT raw FROM truss.installation_archive a
   WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=identity
   AND a.artifact_sha256=sha256(a.artifact_bytes) AND a.artifact_identity_sha256=sha256(convert_to(identity,'UTF8'))
   AND encode(a.artifact_sha256,'hex')=CASE source_name WHEN 'producer' THEN profile->'custodyProducer'->>'sha256'
    WHEN 'payload' THEN profile->'payloadProfile'->>'sha256' ELSE profile->'sources'->source_name->>'sha256' END;
  IF source_name='producer' THEN
   IF raw IS DISTINCT FROM custody.original_producer_profile_bytes THEN RAISE EXCEPTION 'original custody producer required' USING ERRCODE='55000'; END IF;
  ELSIF source_name='payload' THEN
   IF raw IS DISTINCT FROM custody.original_payload_profile_bytes THEN RAISE EXCEPTION 'original custody payload profile required' USING ERRCODE='55000'; END IF;
  ELSE
   IF octet_length(raw)>16384 THEN RAISE EXCEPTION 'statement capacity' USING ERRCODE='54000';END IF;
   source_sql:=source_sql||jsonb_build_object(source_name,convert_from(raw,'UTF8'));
  END IF;
 END LOOP;
 revision:=custody.original_revision;payload:=custody.original_payload_bytes;payload_profile:=custody.original_payload_profile_bytes;
 key_profile:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(profile->'keyProfile'));
 IF key_profile IS DISTINCT FROM custody.original_fact_key_profile_bytes
  OR custody.original_fact_key_bytes IS DISTINCT FROM truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(jsonb_build_object('kind','revision','revision',revision::text))) THEN
  RAISE EXCEPTION 'original revision key profile correspondence required' USING ERRCODE='55000'; END IF;
 owner_bytes:=custody.original_owner_context_bytes;
 manifest_bytes:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(profile->'manifestProfile'));
 IF octet_length(custody.original_producer_profile_bytes)>65536
  OR octet_length(custody.original_fact_key_bytes)>65536 OR octet_length(custody.original_fact_key_profile_bytes)>65536
  OR octet_length(custody.original_payload_bytes)>4194304 OR octet_length(custody.original_payload_profile_bytes)>65536
  OR octet_length(custody.original_owner_context_bytes)>16777216 OR octet_length(custody.original_fact_clock_bytes)>65536
  OR NOT isfinite(custody.original_write_at)
  OR extract(year FROM custody.original_write_at AT TIME ZONE 'UTC') NOT BETWEEN 1 AND 9999 THEN
  RAISE EXCEPTION 'bounded finite original custody required' USING ERRCODE='54000'; END IF;
 clock_bytes:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'profile',profile->'clockProfile','originalWriteAt',to_char(custody.original_write_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))));
 IF clock_bytes IS DISTINCT FROM custody.original_fact_clock_bytes THEN
  RAISE EXCEPTION 'original retained clock profile and timestamp correspondence required' USING ERRCODE='55000'; END IF;
 -- Read-only independent correspondence; the registered bytes remain custody originals.
 SELECT * INTO STRICT revision_row FROM truss.schema_rev r WHERE r.rev=revision;
 SELECT r.report_bytes INTO STRICT original_report FROM truss.catalog_acceptance_report r WHERE r.rev=revision;
 IF (SELECT count(*) FROM truss.catalog_acceptance_report)<>1
  OR NOT isfinite(revision_row.accepted_at)
  OR extract(year FROM revision_row.accepted_at AT TIME ZONE 'UTC') NOT BETWEEN 1 AND 9999
  OR octet_length(original_report)>786432 OR octet_length(op.original_input_bytes)>1048576 THEN
  RAISE EXCEPTION 'bounded finite original report and revision required' USING ERRCODE='55000'; END IF;
 input:=convert_from(op.original_input_bytes,'UTF8')::jsonb;
 origin:=truss.runtime_catalog_report_original_tree(decode(context->>'assertedOriginUtf8Hex','hex'));
 IF truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(revision_row.origin))
  IS DISTINCT FROM truss.runtime_canonical_tree_bytes(origin) THEN
  RAISE EXCEPTION 'original retained revision origin correspondence required' USING ERRCODE='55000'; END IF;
 journal_envelope:=truss.runtime_catalog_report_native_tree(jsonb_build_object('databaseRole',context->>'actingUser'));
 journal_envelope:=jsonb_set(journal_envelope,'{members}',journal_envelope->'members'||jsonb_build_array(
  jsonb_build_object('keyUtf8Hex','6173736572746564','node',truss.runtime_catalog_report_map_origin_tree(origin))));
 report_identity:='truss.candidate.catalog-report/'||encode(convert_to(context->>'installationId','UTF8'),'hex')
  ||'/'||encode(convert_to(context->>'sourceEpoch','UTF8'),'hex')||'/'||revision::text;
 revision_tree:=truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'interfaceVersion','truss-feed-revision/0.1.0','revision',revision::text,
  'acceptedAt',to_char(revision_row.accepted_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'input',input,'report',jsonb_build_object('identity',report_identity,
   'bytesBase64',replace(encode(original_report,'base64'),chr(10),''),'sha256',encode(sha256(original_report),'hex'))));
 revision_tree:=jsonb_set(revision_tree,'{members}',revision_tree->'members'||jsonb_build_array(
  jsonb_build_object('keyUtf8Hex','6f726967696e','node',journal_envelope)));
 IF octet_length(revision_tree::text)>4194304 THEN RAISE EXCEPTION 'revision comparison tree capacity' USING ERRCODE='54000';END IF;
 expected_payload:=truss.runtime_revision_report_tree_bytes_wide_candidate(revision_tree,original_report);
 IF expected_payload IS DISTINCT FROM custody.original_payload_bytes THEN
  RAISE EXCEPTION 'original retained report and revision payload correspondence required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT configuration FROM truss.operation_configuration t
  WHERE t.original_writer_xid=op.original_writer_xid AND t.operation_ordinal=op.operation_ordinal;
 original_configuration:=record_send(configuration);original_op:=record_send(op);original_revision:=record_send(revision_row);
 SELECT array_agg(record_send(d) ORDER BY d.ord) INTO original_documents FROM truss.schema_doc d WHERE d.rev=revision;
 IF original_documents IS NULL OR cardinality(original_documents) NOT BETWEEN 1 AND 512 THEN
  RAISE EXCEPTION 'complete original document custody required' USING ERRCODE='55000'; END IF;
 original_bytes:=octet_length(original_configuration)::bigint+octet_length(original_op)::bigint+
  octet_length(op.original_context_bytes)::bigint+octet_length(original_revision)::bigint;
 total_chunks:=((octet_length(original_configuration)+32767)/32768)+((octet_length(original_op)+32767)/32768)+
  ((octet_length(op.original_context_bytes)+32767)/32768)+((octet_length(original_revision)+32767)/32768);
 FOREACH document_record IN ARRAY original_documents LOOP
  IF document_record IS NULL THEN RAISE EXCEPTION 'original document bytes required' USING ERRCODE='55000'; END IF;
  original_bytes:=original_bytes+octet_length(document_record)::bigint;
  total_chunks:=total_chunks+((octet_length(document_record)+32767)/32768);
 END LOOP;
 IF original_bytes>786432 OR total_chunks>1024 THEN RAISE EXCEPTION 'original custody codec capacity' USING ERRCODE='54000'; END IF;
 FOREACH document_record IN ARRAY original_documents LOOP
  documents:=documents||jsonb_build_array(truss.runtime_registration_original_hex_chunks(document_record));
 END LOOP;
 expected_owner:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'scope','administrative_single_original_operation_fresh_catalog_rollback_only',
  'originalConfigurationRecordHexChunks',truss.runtime_registration_original_hex_chunks(original_configuration),
  'originalOperationRecordHexChunks',truss.runtime_registration_original_hex_chunks(original_op),
  'originalContextHexChunks',truss.runtime_registration_original_hex_chunks(op.original_context_bytes),
  'originalRevisionRecordHexChunks',truss.runtime_registration_original_hex_chunks(original_revision),
  'originalDocumentRecordHexChunks',documents)));
 IF expected_owner IS DISTINCT FROM custody.original_owner_context_bytes THEN
  RAISE EXCEPTION 'original retained owner record correspondence required' USING ERRCODE='55000'; END IF;
 planned_parent.source_epoch:=context->>'sourceEpoch';planned_parent.feed_profile:=profile->>'identity';
 planned_parent.original_writer_xid:=op.original_writer_xid;planned_parent.registration_counter:=0;
 planned_parent.prerequisite_registration_counter:=0;planned_parent.configuration_registration_counter:=0;
 planned_parent.membership_generation:=0;planned_parent.original_context_bytes:=op.original_context_bytes;
 planned_parent.manifest_profile_bytes:=manifest_bytes;
 EXECUTE source_sql->>'create' INTO STRICT returned USING planned_parent.source_epoch,planned_parent.feed_profile,op.original_context_bytes,manifest_bytes;
 expected_snapshot:=jsonb_build_object('source_epoch',planned_parent.source_epoch,'feed_profile',planned_parent.feed_profile,
  'original_writer_xid',op.original_writer_xid::text,'registration_counter','0','prerequisite_registration_counter','0',
  'configuration_registration_counter','0','membership_generation','0','finalized_generation',NULL,
  'original_context_bytes_hex',encode(op.original_context_bytes,'hex'),'manifest_profile_bytes_hex',encode(manifest_bytes,'hex'),
  'manifest_bytes_hex',NULL,'manifest_sha256_hex',NULL);
 IF to_jsonb(returned) IS DISTINCT FROM expected_snapshot
  OR (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(planned_parent)) THEN
  RAISE EXCEPTION 'original pending parent insert readback required' USING ERRCODE='55000'; END IF;
 planned_parent.registration_counter:=1;planned_parent.membership_generation:=1;
 EXECUTE source_sql->>'reserve' INTO STRICT returned USING planned_parent.source_epoch,planned_parent.feed_profile,0::bigint,0::bigint,op.original_context_bytes,manifest_bytes;
 expected_snapshot:=jsonb_set(jsonb_set(expected_snapshot,'{registration_counter}','"1"'),'{membership_generation}','"1"');
 IF to_jsonb(returned) IS DISTINCT FROM expected_snapshot
  OR (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(planned_parent)) THEN
  RAISE EXCEPTION 'original parent reservation readback required' USING ERRCODE='55000'; END IF;
 planned_member.source_epoch:=planned_parent.source_epoch;planned_member.feed_profile:=planned_parent.feed_profile;
 planned_member.original_writer_xid:=op.original_writer_xid;planned_member.registration_address:=1;
 planned_member.fact_kind:='revision';planned_member.original_fact_key_bytes:=custody.original_fact_key_bytes;
 planned_member.original_fact_key_profile_bytes:=key_profile;planned_member.original_payload_bytes:=payload;
 planned_member.original_payload_profile_bytes:=payload_profile;planned_member.original_payload_sha256:=sha256(payload);
 planned_member.original_owner_context_bytes:=owner_bytes;
 -- Preserve the original custody clock; registration never samples a new clock.
 original_write_at:=custody.original_write_at;
 IF NOT isfinite(original_write_at) OR extract(year FROM original_write_at AT TIME ZONE 'UTC') NOT BETWEEN 1 AND 9999 THEN
  RAISE EXCEPTION 'finite native member write clock required' USING ERRCODE='55000'; END IF;
 clock_bytes:=custody.original_fact_clock_bytes;
 planned_member.original_write_at:=original_write_at;planned_member.original_fact_clock_bytes:=clock_bytes;
 EXECUTE source_sql->>'insert' INTO STRICT returned USING planned_parent.source_epoch,planned_parent.feed_profile,1::bigint,1::bigint,
  'revision',planned_member.original_fact_key_bytes,key_profile,payload,payload_profile,sha256(payload),owner_bytes,
  original_write_at,clock_bytes,op.original_context_bytes,manifest_bytes;
 expected_snapshot:=jsonb_build_object('source_epoch',planned_member.source_epoch,'feed_profile',planned_member.feed_profile,
  'original_writer_xid',op.original_writer_xid::text,'registration_address','1','fact_kind','revision',
  'original_fact_key_bytes_hex',encode(planned_member.original_fact_key_bytes,'hex'),'original_fact_key_profile_bytes_hex',encode(key_profile,'hex'),
  'original_payload_bytes_hex',encode(payload,'hex'),'original_payload_profile_bytes_hex',encode(payload_profile,'hex'),
  'original_payload_sha256_hex',encode(sha256(payload),'hex'),'original_owner_context_bytes_hex',encode(owner_bytes,'hex'),
  'original_write_at',original_write_at::text,'original_fact_clock_bytes_hex',encode(clock_bytes,'hex'),'delivery_ordinal',NULL);
 IF to_jsonb(returned) IS DISTINCT FROM expected_snapshot THEN
  RAISE EXCEPTION 'original revision member returned snapshot required' USING ERRCODE='55000'; END IF;
 PERFORM truss.runtime_require_catalog_prerequisite_composition_candidate(w,o,g);
 after_state:=truss.runtime_capture_configured_completion_state_candidate(w,o,g);
 expected_state:=jsonb_set(before_state,'{stores,feed_tx}',jsonb_build_array(encode(record_send(planned_parent),'hex')));
 expected_state:=jsonb_set(expected_state,'{stores,feed_member}',jsonb_build_array(encode(record_send(planned_member),'hex')));
 IF after_state IS DISTINCT FROM expected_state OR NOT EXISTS(SELECT 1 FROM truss.catalog_revision_custody t
  WHERE record_send(t)=original_custody) THEN
  RAISE EXCEPTION 'complete independent original custody registration delta required' USING ERRCODE='55000'; END IF;
 RETURN QUERY SELECT w,o,g,encode(record_send(planned_parent),'hex'),encode(record_send(planned_member),'hex'),
  'administrative_rollback_only_pending_custody_feed'::text,false;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_registration_original_hex_chunks(original bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE n int; pos int:=1; chunks jsonb:='[]'::jsonb;
BEGIN
 IF original IS NULL OR octet_length(original) NOT BETWEEN 1 AND 786432 THEN
  RAISE EXCEPTION 'bounded original registration byte custody required' USING ERRCODE='54000'; END IF;
 n:=octet_length(original);
 WHILE pos<=n LOOP
  chunks:=chunks||jsonb_build_array(encode(substring(original FROM pos FOR 32768),'hex'));
  pos:=pos+32768;
 END LOOP;
 RETURN chunks;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_require_catalog_custody_composition_candidate(w text, o text, g text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO, YMD'
 SET "IntervalStyle" TO 'iso_8601'
 SET extra_float_digits TO '3'
 SET bytea_output TO 'hex'
 SET standard_conforming_strings TO 'on'
 SET quote_all_identifiers TO 'off'
AS $function$
DECLARE configuration truss.operation_configuration%ROWTYPE; inventory jsonb; context jsonb;
 raw_manifest bytea; manifest jsonb; resource jsonb; artifact bytea; resource_length bigint;
 total_resource_bytes bigint:=0; expected_paths text[]; selected_paths text[];
 relation_oid oid; target_descriptor jsonb; expected_collector jsonb; actual_collector text;
 actual_routines jsonb; actual_schema jsonb; routine_json jsonb; declaration_bytes bigint:=0;
BEGIN
 PERFORM truss.runtime_require_catalog_observation(w,o,g);
 PERFORM truss.runtime_require_operation_configuration_current(w,o,g);
 LOCK TABLE truss.installation_archive IN SHARE MODE NOWAIT;
 PERFORM truss.runtime_require_selected_archive_write_fence();
 SELECT c.* INTO STRICT configuration FROM truss.operation_configuration c
  WHERE c.original_writer_xid=pg_current_xact_id_if_assigned() AND c.operation_ordinal::text=o;
 SELECT convert_from(t.original_context_bytes,'UTF8')::jsonb INTO STRICT context FROM truss.row_home_operation t
  WHERE t.original_writer_xid=configuration.original_writer_xid AND t.operation_ordinal=configuration.operation_ordinal;
 IF octet_length(configuration.installed_inventory_bytes)>8192 THEN
  RAISE EXCEPTION 'bounded original custody inventory required' USING ERRCODE='54000'; END IF;
 IF NOT(convert_from(configuration.installed_inventory_bytes,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) THEN
  RAISE EXCEPTION 'original unique custody inventory required' USING ERRCODE='55000'; END IF;
 inventory:=convert_from(configuration.installed_inventory_bytes,'UTF8')::jsonb;
 IF (SELECT count(*) FROM jsonb_object_keys(inventory))<>4
  OR NOT inventory ?& ARRAY['interfaceVersion','scope','referenceManifest','custodyDescriptorSha256']
  OR inventory->>'interfaceVersion' IS DISTINCT FROM 'truss-catalog-custody-installation-inventory/0.2-candidate'
  OR inventory->>'scope' IS DISTINCT FROM 'administrative_rollback_only_catalog_custody'
  OR jsonb_typeof(inventory->'referenceManifest') IS DISTINCT FROM 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(inventory->'referenceManifest'))<>2
  OR NOT inventory->'referenceManifest' ?& ARRAY['identity','sha256']
  OR inventory->'referenceManifest'->>'identity' IS DISTINCT FROM 'truss.catalog-custody-independent-reference/0.1-candidate'
  OR jsonb_typeof(inventory->'referenceManifest'->'sha256') IS DISTINCT FROM 'string'
  OR inventory->'referenceManifest'->>'sha256' !~ '^[0-9a-f]{64}$'
  OR jsonb_typeof(inventory->'custodyDescriptorSha256') IS DISTINCT FROM 'string'
  OR inventory->>'custodyDescriptorSha256' !~ '^[0-9a-f]{64}$'
  OR current_setting('server_version_num') IS DISTINCT FROM '170011' THEN
  RAISE EXCEPTION 'closed original PostgreSQL17 custody inventory required' USING ERRCODE='55000'; END IF;
 IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=context->>'installationId'
  AND a.artifact_role='input' AND a.artifact_identity=inventory->'referenceManifest'->>'identity')<>1 THEN
  RAISE EXCEPTION 'unique original independent reference required' USING ERRCODE='55000'; END IF;
 SELECT octet_length(a.artifact_bytes)::bigint INTO STRICT resource_length FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input'
   AND a.artifact_identity=inventory->'referenceManifest'->>'identity';
 IF resource_length NOT BETWEEN 1 AND 4194304 THEN RAISE EXCEPTION 'reference manifest capacity' USING ERRCODE='54000'; END IF;
 total_resource_bytes:=resource_length;
 SELECT a.artifact_bytes INTO STRICT raw_manifest FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input'
   AND a.artifact_identity=inventory->'referenceManifest'->>'identity'
   AND a.artifact_identity_sha256=sha256(convert_to(a.artifact_identity,'UTF8'))
   AND a.artifact_sha256=sha256(a.artifact_bytes)
   AND a.artifact_sha256=decode(inventory->'referenceManifest'->>'sha256','hex') FOR SHARE NOWAIT;
 IF NOT(convert_from(raw_manifest,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) THEN
  RAISE EXCEPTION 'original unique independent reference required' USING ERRCODE='55000'; END IF;
 manifest:=convert_from(raw_manifest,'UTF8')::jsonb;
 IF (SELECT count(*) FROM jsonb_object_keys(manifest))<>7
  OR NOT manifest ?& ARRAY['interfaceVersion','scope','nativeVersion','sourceFiles','resources','routines','custodySchema']
  OR manifest->>'interfaceVersion' IS DISTINCT FROM 'truss-catalog-custody-independent-reference/0.1-candidate'
  OR manifest->>'scope' IS DISTINCT FROM 'administrative_rollback_only_catalog_custody'
  OR manifest->>'nativeVersion' IS DISTINCT FROM '170011'
  OR jsonb_typeof(manifest->'sourceFiles') IS DISTINCT FROM 'array'
  OR jsonb_array_length(manifest->'sourceFiles') NOT BETWEEN 1 AND 128
  OR jsonb_typeof(manifest->'resources') IS DISTINCT FROM 'array'
  OR jsonb_array_length(manifest->'resources')<>30
  OR jsonb_typeof(manifest->'routines') IS DISTINCT FROM 'array'
  OR jsonb_array_length(manifest->'routines') NOT BETWEEN 1 AND 1024
  OR jsonb_typeof(manifest->'custodySchema') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'complete independently compiled reference required' USING ERRCODE='55000'; END IF;
 -- Original compiler source receipt is metadata, not a target-produced proof.
 FOR resource IN SELECT * FROM jsonb_array_elements(manifest->'sourceFiles') LOOP
  IF jsonb_typeof(resource) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(resource))<>2
   OR NOT resource ?& ARRAY['path','sha256'] OR jsonb_typeof(resource->'path') IS DISTINCT FROM 'string'
   OR octet_length(resource->>'path') NOT BETWEEN 1 AND 4096 OR jsonb_typeof(resource->'sha256') IS DISTINCT FROM 'string'
   OR resource->>'sha256' !~ '^[0-9a-f]{64}$' THEN
   RAISE EXCEPTION 'closed original compiler source pin required' USING ERRCODE='55000'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(manifest->'sourceFiles') s GROUP BY s->>'path' HAVING count(*)<>1) THEN
  RAISE EXCEPTION 'unique original compiler sources required' USING ERRCODE='55000'; END IF;
 -- Fixed adjunct path closure is generated from the owner composition roster.
 expected_paths:=ARRAY[
 'docs/helix/02-design/contracts/catalog-revision-custody-storage-v0.1.proposal.umf.json',
 'docs/helix/02-design/models/truss-layout-core-structural-0.9.proposal.umf.json',
 'docs/helix/04-build/evidence/catalog-revision-custody-storage.owner-export.sql',
 'packages/postgresql/native/catalog-custody/configured-graph.sql','packages/postgresql/native/catalog-custody/configured-graph.umf.json',
