 IF actual_routines IS DISTINCT FROM manifest->'routines' OR actual_schema IS DISTINCT FROM manifest->'custodySchema' THEN
  RAISE EXCEPTION 'complete independent original routine and schema correspondence required' USING ERRCODE='55000'; END IF;
 target_descriptor:=truss.runtime_collect_catalog_custody_target_descriptor_candidate();
 IF encode(sha256(convert_to(target_descriptor::text,'UTF8')),'hex') IS DISTINCT FROM inventory->>'custodyDescriptorSha256' THEN
  RAISE EXCEPTION 'original admitted target descriptor required' USING ERRCODE='55000'; END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_require_catalog_input(original_input bytea)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE;
BEGIN
 IF original_input IS NULL OR octet_length(original_input) NOT BETWEEN 1 AND 1048576 THEN
  RAISE EXCEPTION 'original complete input bytes required' USING ERRCODE='22023';
 END IF;
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.phase<>'application_finalized' FOR UPDATE;
 IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted' OR op.original_input_bytes IS DISTINCT FROM original_input THEN
  RAISE EXCEPTION 'prepared input differs from original admitted complete bytes' USING ERRCODE='55000';
 END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_require_catalog_observation(expected_writer_xid text, expected_ordinal text, expected_generation text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; actual_xid xid8:=pg_current_xact_id_if_assigned();
BEGIN
 IF expected_writer_xid IS NULL OR expected_ordinal IS NULL OR expected_generation IS NULL
  OR octet_length(expected_writer_xid) NOT BETWEEN 1 AND 20
  OR octet_length(expected_ordinal) NOT BETWEEN 1 AND 19 OR octet_length(expected_generation) NOT BETWEEN 1 AND 19 THEN
  RAISE EXCEPTION 'bounded original catalog observation tuple required' USING ERRCODE='55000';
 END IF;
 IF expected_writer_xid !~ '^[1-9][0-9]{0,19}$' OR expected_ordinal !~ '^(0|[1-9][0-9]{0,18})$'
  OR expected_generation !~ '^(0|[1-9][0-9]{0,18})$' OR actual_xid IS NULL OR actual_xid::text<>expected_writer_xid THEN
  RAISE EXCEPTION 'original native transaction observation required' USING ERRCODE='55000';
 END IF;
 SELECT o.* INTO op FROM truss.row_home_operation o WHERE o.original_writer_xid=actual_xid AND o.phase<>'application_finalized' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'original unfinished catalog operation required' USING ERRCODE='55000'; END IF;
 IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted' OR op.operation_ordinal::text<>expected_ordinal OR op.effect_generation::text<>expected_generation
  OR NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.granted AND l.relation='truss.schema_head'::regclass AND l.mode IN ('ExclusiveLock','AccessExclusiveLock')) THEN
  RAISE EXCEPTION 'catalog observation stale or unrelated' USING ERRCODE='55000';
 END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_require_empty_provisional_catalog(original_revision integer)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
 -- Require the original unfinished catalog operation, exact source carrier and head exclusion.
 PERFORM * FROM truss.runtime_collect_report_documents(original_revision);
 -- Include retained rows too. No new-only or role-filtered subset can prove global emptiness.
 IF EXISTS(SELECT 1 FROM truss.type_def t WHERE t.provisional) THEN
  RAISE EXCEPTION 'complete nonempty provisional report producer required' USING ERRCODE='0A000';
 END IF;
 RETURN '0'::text;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_require_finalizing_custody_correspondence_candidate(w text, o text, g text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO, YMD'
 SET "IntervalStyle" TO 'iso_8601'
 SET extra_float_digits TO '3'
 SET bytea_output TO 'hex'
 SET standard_conforming_strings TO 'on'
 SET quote_all_identifiers TO 'off'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; custody truss.catalog_revision_custody%ROWTYPE;
 original_custody bytea; before_state jsonb; after_state jsonb; expected_state jsonb;
 planned_parent truss.feed_tx%ROWTYPE; planned_member truss.feed_member%ROWTYPE;
 returned record; expected_snapshot jsonb; context jsonb; profile jsonb; profile_bytes bytea;
 source_sql jsonb:='{}'; source_name text; identity text; raw bytea;
 payload bytea; payload_profile bytea; key_profile bytea; owner_bytes bytea;
 revision_row truss.schema_rev%ROWTYPE; configuration truss.operation_configuration%ROWTYPE;
 original_report bytea; expected_payload bytea; revision_tree jsonb; origin jsonb; journal_envelope jsonb;
 input jsonb; report_identity text; original_documents bytea[]; document_record bytea;
 documents jsonb:='[]'; original_configuration bytea; original_op bytea; original_revision bytea;
 original_bytes bigint; total_chunks bigint; expected_owner bytea;
 manifest_bytes bytea; clock_bytes bytea; original_write_at timestamptz; revision int;
BEGIN
 PERFORM truss.runtime_require_catalog_finalization_composition_candidate(w,o,g);
 SELECT * INTO STRICT op FROM truss.row_home_operation t WHERE t.original_writer_xid=pg_current_xact_id_if_assigned()
  AND t.operation_ordinal::text=o FOR UPDATE;
 IF (SELECT count(*) FROM truss.catalog_revision_custody t
  WHERE t.original_writer_xid=op.original_writer_xid AND t.operation_ordinal=op.operation_ordinal)<>1 THEN
  RAISE EXCEPTION 'unique original custody for current operation required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT custody FROM truss.catalog_revision_custody t WHERE t.original_writer_xid=op.original_writer_xid
  AND t.operation_ordinal=op.operation_ordinal FOR SHARE NOWAIT;
 IF (SELECT count(*) FROM truss.row_home_operation)<>1 OR (SELECT count(*) FROM truss.catalog_revision_custody)<>1
  OR custody.capture_generation::text IS DISTINCT FROM g OR op.effect_generation::text IS DISTINCT FROM g
  OR (SELECT count(*) FROM truss.schema_head)<>1 OR NOT EXISTS(SELECT 1 FROM truss.schema_head h WHERE h.id=1 AND h.rev=0)
  OR NOT EXISTS(SELECT 1 FROM truss.schema_rev r WHERE r.rev=custody.original_revision)
  OR NOT EXISTS(SELECT 1 FROM truss.catalog_acceptance_report r WHERE r.rev=custody.original_revision) THEN
  RAISE EXCEPTION 'single current original unpublished catalog custody required' USING ERRCODE='55000'; END IF;
 original_custody:=record_send(custody);context:=convert_from(op.original_context_bytes,'UTF8')::jsonb;
 before_state:=truss.runtime_capture_finalizing_completion_state_candidate(w,o,g);
 LOCK TABLE truss.installation_archive IN SHARE MODE NOWAIT;
 PERFORM truss.runtime_require_selected_archive_write_fence();
 identity:='packages/python/src/truss/_profiles/catalog-finalizing-custody-registration-candidate.json';
 IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=context->>'installationId'
  AND a.artifact_role='input' AND a.artifact_identity=identity)<>1 THEN
  RAISE EXCEPTION 'unique original custody registration recipe required' USING ERRCODE='55000'; END IF;
 SELECT a.artifact_bytes INTO STRICT profile_bytes FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=identity
  AND a.artifact_sha256=sha256(a.artifact_bytes) AND encode(a.artifact_sha256,'hex')='0706da4b4387b49834d095f2fbdc3dfb3ba4bb4e3ac22e7c0afdb64c7429e73b'
  AND a.artifact_identity_sha256=sha256(convert_to(identity,'UTF8'));
 IF octet_length(profile_bytes)>65536 THEN RAISE EXCEPTION 'recipe capacity' USING ERRCODE='54000'; END IF;
 profile:=convert_from(profile_bytes,'UTF8')::jsonb;
 FOREACH source_name IN ARRAY ARRAY['create','reserve','insert','producer','payload'] LOOP
  IF source_name='producer' THEN identity:=profile->'custodyProducer'->>'path';
  ELSIF source_name='payload' THEN identity:=profile->'payloadProfile'->>'path';
  ELSE identity:=profile->'sources'->source_name->>'path';END IF;
  IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=context->>'installationId'
   AND a.artifact_role='input' AND a.artifact_identity=identity)<>1 THEN
   RAISE EXCEPTION 'unique original selected registration artifact required' USING ERRCODE='55000'; END IF;
  SELECT a.artifact_bytes INTO STRICT raw FROM truss.installation_archive a
   WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=identity
   AND a.artifact_sha256=sha256(a.artifact_bytes) AND a.artifact_identity_sha256=sha256(convert_to(identity,'UTF8'))
   AND encode(a.artifact_sha256,'hex')=CASE source_name WHEN 'producer' THEN profile->'custodyProducer'->>'sha256'
    WHEN 'payload' THEN profile->'payloadProfile'->>'sha256' ELSE profile->'sources'->source_name->>'sha256' END;
  IF source_name='producer' THEN
   IF raw IS DISTINCT FROM custody.original_producer_profile_bytes THEN RAISE EXCEPTION 'original custody producer required' USING ERRCODE='55000'; END IF;
  ELSIF source_name='payload' THEN
   IF raw IS DISTINCT FROM custody.original_payload_profile_bytes THEN RAISE EXCEPTION 'original custody payload profile required' USING ERRCODE='55000'; END IF;
  ELSE
   IF octet_length(raw)>16384 THEN RAISE EXCEPTION 'statement capacity' USING ERRCODE='54000';END IF;
   source_sql:=source_sql||jsonb_build_object(source_name,convert_from(raw,'UTF8'));
  END IF;
 END LOOP;
 revision:=custody.original_revision;payload:=custody.original_payload_bytes;payload_profile:=custody.original_payload_profile_bytes;
 key_profile:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(profile->'keyProfile'));
 IF key_profile IS DISTINCT FROM custody.original_fact_key_profile_bytes
  OR custody.original_fact_key_bytes IS DISTINCT FROM truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(jsonb_build_object('kind','revision','revision',revision::text))) THEN
  RAISE EXCEPTION 'original revision key profile correspondence required' USING ERRCODE='55000'; END IF;
 owner_bytes:=custody.original_owner_context_bytes;
 manifest_bytes:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(profile->'manifestProfile'));
 IF octet_length(custody.original_producer_profile_bytes)>65536
  OR octet_length(custody.original_fact_key_bytes)>65536 OR octet_length(custody.original_fact_key_profile_bytes)>65536
  OR octet_length(custody.original_payload_bytes)>4194304 OR octet_length(custody.original_payload_profile_bytes)>65536
  OR octet_length(custody.original_owner_context_bytes)>16777216 OR octet_length(custody.original_fact_clock_bytes)>65536
  OR NOT isfinite(custody.original_write_at)
  OR extract(year FROM custody.original_write_at AT TIME ZONE 'UTC') NOT BETWEEN 1 AND 9999 THEN
  RAISE EXCEPTION 'bounded finite original custody required' USING ERRCODE='54000'; END IF;
 clock_bytes:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'profile',profile->'clockProfile','originalWriteAt',to_char(custody.original_write_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))));
 IF clock_bytes IS DISTINCT FROM custody.original_fact_clock_bytes THEN
  RAISE EXCEPTION 'original retained clock profile and timestamp correspondence required' USING ERRCODE='55000'; END IF;
 -- Read-only independent correspondence; the registered bytes remain custody originals.
 SELECT * INTO STRICT revision_row FROM truss.schema_rev r WHERE r.rev=revision;
 SELECT r.report_bytes INTO STRICT original_report FROM truss.catalog_acceptance_report r WHERE r.rev=revision;
 IF (SELECT count(*) FROM truss.catalog_acceptance_report)<>1
  OR NOT isfinite(revision_row.accepted_at)
  OR extract(year FROM revision_row.accepted_at AT TIME ZONE 'UTC') NOT BETWEEN 1 AND 9999
  OR octet_length(original_report)>786432 OR octet_length(op.original_input_bytes)>1048576 THEN
  RAISE EXCEPTION 'bounded finite original report and revision required' USING ERRCODE='55000'; END IF;
 input:=convert_from(op.original_input_bytes,'UTF8')::jsonb;
 origin:=truss.runtime_catalog_report_original_tree(decode(context->>'assertedOriginUtf8Hex','hex'));
 IF truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(revision_row.origin))
  IS DISTINCT FROM truss.runtime_canonical_tree_bytes(origin) THEN
  RAISE EXCEPTION 'original retained revision origin correspondence required' USING ERRCODE='55000'; END IF;
 journal_envelope:=truss.runtime_catalog_report_native_tree(jsonb_build_object('databaseRole',context->>'actingUser'));
 journal_envelope:=jsonb_set(journal_envelope,'{members}',journal_envelope->'members'||jsonb_build_array(
  jsonb_build_object('keyUtf8Hex','6173736572746564','node',truss.runtime_catalog_report_map_origin_tree(origin))));
 report_identity:='truss.candidate.catalog-report/'||encode(convert_to(context->>'installationId','UTF8'),'hex')
  ||'/'||encode(convert_to(context->>'sourceEpoch','UTF8'),'hex')||'/'||revision::text;
 revision_tree:=truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'interfaceVersion','truss-feed-revision/0.1.0','revision',revision::text,
  'acceptedAt',to_char(revision_row.accepted_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'input',input,'report',jsonb_build_object('identity',report_identity,
   'bytesBase64',replace(encode(original_report,'base64'),chr(10),''),'sha256',encode(sha256(original_report),'hex'))));
 revision_tree:=jsonb_set(revision_tree,'{members}',revision_tree->'members'||jsonb_build_array(
  jsonb_build_object('keyUtf8Hex','6f726967696e','node',journal_envelope)));
 IF octet_length(revision_tree::text)>4194304 THEN RAISE EXCEPTION 'revision comparison tree capacity' USING ERRCODE='54000';END IF;
 expected_payload:=truss.runtime_revision_report_tree_bytes_wide_candidate(revision_tree,original_report);
 IF expected_payload IS DISTINCT FROM custody.original_payload_bytes THEN
  RAISE EXCEPTION 'original retained report and revision payload correspondence required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT configuration FROM truss.operation_configuration t
  WHERE t.original_writer_xid=op.original_writer_xid AND t.operation_ordinal=op.operation_ordinal;
 original_configuration:=record_send(configuration);original_op:=record_send(op);original_revision:=record_send(revision_row);
 SELECT array_agg(record_send(d) ORDER BY d.ord) INTO original_documents FROM truss.schema_doc d WHERE d.rev=revision;
 IF original_documents IS NULL OR cardinality(original_documents) NOT BETWEEN 1 AND 512 THEN
  RAISE EXCEPTION 'complete original document custody required' USING ERRCODE='55000'; END IF;
 original_bytes:=octet_length(original_configuration)::bigint+octet_length(original_op)::bigint+
  octet_length(op.original_context_bytes)::bigint+octet_length(original_revision)::bigint;
 total_chunks:=((octet_length(original_configuration)+32767)/32768)+((octet_length(original_op)+32767)/32768)+
  ((octet_length(op.original_context_bytes)+32767)/32768)+((octet_length(original_revision)+32767)/32768);
 FOREACH document_record IN ARRAY original_documents LOOP
  IF document_record IS NULL THEN RAISE EXCEPTION 'original document bytes required' USING ERRCODE='55000'; END IF;
  original_bytes:=original_bytes+octet_length(document_record)::bigint;
  total_chunks:=total_chunks+((octet_length(document_record)+32767)/32768);
 END LOOP;
 IF original_bytes>786432 OR total_chunks>1024 THEN RAISE EXCEPTION 'original custody codec capacity' USING ERRCODE='54000'; END IF;
 FOREACH document_record IN ARRAY original_documents LOOP
  documents:=documents||jsonb_build_array(truss.runtime_registration_original_hex_chunks(document_record));
 END LOOP;
 expected_owner:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'scope','administrative_single_original_operation_fresh_catalog_rollback_only',
  'originalConfigurationRecordHexChunks',truss.runtime_registration_original_hex_chunks(original_configuration),
  'originalOperationRecordHexChunks',truss.runtime_registration_original_hex_chunks(original_op),
  'originalContextHexChunks',truss.runtime_registration_original_hex_chunks(op.original_context_bytes),
  'originalRevisionRecordHexChunks',truss.runtime_registration_original_hex_chunks(original_revision),
  'originalDocumentRecordHexChunks',documents)));
 IF expected_owner IS DISTINCT FROM custody.original_owner_context_bytes THEN
  RAISE EXCEPTION 'original retained owner record correspondence required' USING ERRCODE='55000'; END IF;
 RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_require_operation_configuration_current(expected_writer_xid text, expected_operation_ordinal text, expected_effect_generation text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE original_context record; context jsonb;
 captured truss.operation_configuration%ROWTYPE;
 current_configuration truss.installation_admission%ROWTYPE;
 sizes record;
BEGIN
 SELECT * INTO STRICT original_context FROM truss.runtime_collect_catalog_epoch_context(
  expected_writer_xid,expected_operation_ordinal,expected_effect_generation);
 context:=convert_from(decode(original_context.context_hex,'hex'),'UTF8')::jsonb;
 PERFORM 1 FROM truss.schema_head h WHERE h.id=1 FOR SHARE;
 SELECT c.* INTO captured FROM truss.operation_configuration c
  WHERE c.original_writer_xid=pg_current_xact_id_if_assigned()
   AND c.operation_ordinal::text=expected_operation_ordinal;
 IF NOT FOUND THEN RAISE EXCEPTION 'original configuration capsule required' USING ERRCODE='55000'; END IF;
 SELECT octet_length(a.configuration_bytes)::bigint AS configuration,
  octet_length(a.selected_binding_bytes)::bigint AS binding,
  octet_length(a.installed_inventory_bytes)::bigint AS inventory
 INTO sizes FROM truss.installation_admission a WHERE a.head_id=1;
 IF NOT FOUND OR sizes.configuration<1 OR sizes.binding<1 OR sizes.inventory<1
  OR sizes.configuration+sizes.binding+sizes.inventory>16777216 THEN
  RAISE EXCEPTION 'bounded current configuration required' USING ERRCODE='55000';
 END IF;
 SELECT a.* INTO current_configuration FROM truss.installation_admission a WHERE a.head_id=1;
 IF NOT FOUND OR captured.installation_id IS DISTINCT FROM context->>'installationId'
  OR captured.source_epoch IS DISTINCT FROM context->>'sourceEpoch'
  OR captured.target_incarnation IS DISTINCT FROM context->>'targetIncarnation'
  OR captured.original_context_sha256 IS DISTINCT FROM sha256(decode(original_context.context_hex,'hex'))
  OR current_configuration.installation_id_utf8 IS DISTINCT FROM convert_to(captured.installation_id,'UTF8')
  OR current_configuration.source_epoch_utf8 IS DISTINCT FROM convert_to(captured.source_epoch,'UTF8')
  OR current_configuration.configuration_generation IS DISTINCT FROM captured.configuration_generation
  OR current_configuration.key_reuse IS DISTINCT FROM captured.key_reuse
  OR current_configuration.journal_mode IS DISTINCT FROM captured.journal_mode
  OR current_configuration.configuration_bytes IS DISTINCT FROM captured.configuration_bytes
  OR current_configuration.selected_binding_bytes IS DISTINCT FROM captured.selected_binding_bytes
  OR current_configuration.installed_inventory_bytes IS DISTINCT FROM captured.installed_inventory_bytes THEN
  RAISE EXCEPTION 'current configuration differs from original admission capsule' USING ERRCODE='55000';
 END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_require_unique_source_json(original json)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE pending json[]:=ARRAY[original]; depths int[]:=ARRAY[0];
 node json; member record; depth int; steps int:=1; children int;
BEGIN
 WHILE cardinality(pending)>0 LOOP
  node:=pending[cardinality(pending)];depth:=depths[cardinality(depths)];
  pending:=pending[1:cardinality(pending)-1];depths:=depths[1:cardinality(depths)-1];
  IF depth>128 THEN RAISE EXCEPTION 'source carrier depth capacity' USING ERRCODE='54000'; END IF;
  IF steps>32768 THEN RAISE EXCEPTION 'source carrier work capacity' USING ERRCODE='54000'; END IF;
  IF json_typeof(node)='object' THEN
   SELECT count(*) INTO children FROM json_each(node);
   IF children>4096 OR steps+children>32768 THEN
    RAISE EXCEPTION 'source carrier enqueue capacity' USING ERRCODE='54000'; END IF;
   steps:=steps+children;
   IF (SELECT count(*)<>count(DISTINCT key COLLATE "C") FROM json_each(node)) THEN
    RAISE EXCEPTION 'duplicate source carrier member' USING ERRCODE='22023';
   END IF;
   FOR member IN SELECT value FROM json_each(node) LOOP
    pending:=array_append(pending,member.value);depths:=array_append(depths,depth+1); END LOOP;
  ELSIF json_typeof(node)='array' THEN
   children:=json_array_length(node);
   IF children>4096 OR steps+children>32768 THEN
    RAISE EXCEPTION 'source carrier enqueue capacity' USING ERRCODE='54000'; END IF;
   steps:=steps+children;
   FOR member IN SELECT value FROM json_array_elements(node) LOOP
    pending:=array_append(pending,member.value);depths:=array_append(depths,depth+1); END LOOP;
  END IF;
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_revision_report_tree_bytes_wide_candidate(tree jsonb, original_report bytea)
 RETURNS bytea
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE tasks jsonb[]:=ARRAY[jsonb_build_object('node',tree,'depth','0','path','root')]; task jsonb;
 node jsonb; member jsonb; children jsonb; tag text; piece bytea; chunk bytea:=decode('','hex');
 chunks bytea[]:=ARRAY[]::bytea[]; output bytea; i int; depth int; steps int:=0; emitted bigint:=0; report_base64 bytea; report_seen int:=0;
BEGIN
 IF original_report IS NULL OR octet_length(original_report) NOT BETWEEN 1 AND 786432 THEN RAISE EXCEPTION 'wide original report capacity' USING ERRCODE='54000'; END IF;
 report_base64:=convert_to(replace(encode(original_report,'base64'),chr(10),''),'UTF8');
 IF octet_length(report_base64)>1048576 THEN RAISE EXCEPTION 'wide base64 report capacity' USING ERRCODE='54000'; END IF;
 IF tree IS NULL THEN RAISE EXCEPTION 'inert tree required' USING ERRCODE='22023'; END IF;
 IF octet_length(tree::text)>4194304 THEN RAISE EXCEPTION 'tree input capacity' USING ERRCODE='54000'; END IF;
 WHILE cardinality(tasks)>0 LOOP
  steps:=steps+1;
  IF steps>32768 OR cardinality(tasks)>16384 THEN RAISE EXCEPTION 'tree task capacity' USING ERRCODE='54000'; END IF;
  task:=tasks[cardinality(tasks)];tasks:=tasks[1:cardinality(tasks)-1];piece:=decode('','hex');
  IF task ? 'emit' THEN piece:=decode(task->>'emit','hex');
  ELSIF task ? 'frame' THEN
   children:=task->'children';tag:=task->>'frame';i:=(task->>'index')::int;depth:=(task->>'depth')::int;
   IF i=jsonb_array_length(children) THEN piece:=decode(CASE WHEN tag='array' THEN '5d' ELSE '7d' END,'hex');
   ELSE
    member:=children->i;
    tasks:=array_append(tasks,jsonb_set(task,'{index}',to_jsonb((i+1)::text)));
    tasks:=array_append(tasks,jsonb_build_object('node',CASE WHEN tag='array' THEN member ELSE member->'node' END,'depth',(depth+1)::text,'path',CASE WHEN tag='object' AND task->>'path'='root' AND member->>'keyUtf8Hex'='7265706f7274' THEN 'report' WHEN tag='object' AND task->>'path'='report' AND member->>'keyUtf8Hex'='6279746573426173653634' THEN 'reportArtifact' ELSE 'other' END));
    IF tag='object' THEN
     tasks:=array_append(tasks,jsonb_build_object('emit','3a'));
     tasks:=array_append(tasks,jsonb_build_object('node',jsonb_build_object('kind','string','utf8Hex',member->>'keyUtf8Hex'),'depth',(depth+1)::text));
    END IF;
    IF i>0 THEN piece:=decode('2c','hex'); END IF;
   END IF;
  ELSE
   node:=task->'node';depth:=(task->>'depth')::int;
   IF depth>256 THEN RAISE EXCEPTION 'tree depth capacity' USING ERRCODE='54000'; END IF;
   IF node IS NULL OR jsonb_typeof(node)<>'object' OR jsonb_typeof(node->'kind') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'inert node shape' USING ERRCODE='22023'; END IF;
   tag:=node->>'kind';
   IF tag='null' AND (SELECT count(*) FROM jsonb_object_keys(node))=1 THEN piece:=convert_to('null','UTF8');
   ELSIF tag='boolean' AND (SELECT count(*) FROM jsonb_object_keys(node))=2 AND jsonb_typeof(node->'value')='boolean' THEN piece:=convert_to(node->>'value','UTF8');
   ELSIF tag='string' AND (SELECT count(*) FROM jsonb_object_keys(node))=2 AND jsonb_typeof(node->'utf8Hex')='string' AND node->>'utf8Hex' ~ '^([0-9a-f]{2})*$' THEN
    IF task->>'path'='reportArtifact' THEN
     IF decode(node->>'utf8Hex','hex') IS DISTINCT FROM report_base64 THEN RAISE EXCEPTION 'same original report base64 required' USING ERRCODE='55000'; END IF;
     report_seen:=report_seen+1;piece:=decode('22','hex')||report_base64||decode('22','hex');
    ELSE piece:=truss.runtime_canonical_string_bytes(decode(node->>'utf8Hex','hex')); END IF;
   ELSIF tag IN ('array','object') AND (SELECT count(*) FROM jsonb_object_keys(node))=2 THEN
    children:=node->CASE WHEN tag='array' THEN 'items' ELSE 'members' END;
    IF jsonb_typeof(children) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'container inventory' USING ERRCODE='22023'; END IF;
    IF jsonb_array_length(children)>4096 THEN RAISE EXCEPTION 'container inventory capacity' USING ERRCODE='54000'; END IF;
    IF tag='object' THEN
     FOR member IN SELECT value FROM jsonb_array_elements(children) LOOP
      IF jsonb_typeof(member)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(member))<>2
       OR NOT member ?& ARRAY['keyUtf8Hex','node'] OR jsonb_typeof(member->'keyUtf8Hex') IS DISTINCT FROM 'string'
       OR member->>'keyUtf8Hex' !~ '^([0-9a-f]{2})*$' THEN RAISE EXCEPTION 'object member shape' USING ERRCODE='22023'; END IF;
      PERFORM truss.runtime_canonical_string_bytes(decode(member->>'keyUtf8Hex','hex'));
     END LOOP;
     IF (SELECT count(DISTINCT decode(value->>'keyUtf8Hex','hex')) FROM jsonb_array_elements(children))<>jsonb_array_length(children) THEN RAISE EXCEPTION 'duplicate original object key' USING ERRCODE='22023'; END IF;
     SELECT coalesce(jsonb_agg(value ORDER BY decode(value->>'keyUtf8Hex','hex')),'[]'::jsonb) INTO children FROM jsonb_array_elements(children);
    END IF;
    tasks:=array_append(tasks,jsonb_build_object('frame',tag,'children',children,'index','0','depth',depth::text,'path',coalesce(task->>'path','other')));
    piece:=decode(CASE WHEN tag='array' THEN '5b' ELSE '7b' END,'hex');
   ELSE RAISE EXCEPTION 'unsupported inert node or extra content' USING ERRCODE='22023'; END IF;
  END IF;
  emitted:=emitted+octet_length(piece);
  IF emitted>4194304 THEN RAISE EXCEPTION 'complete tree output capacity' USING ERRCODE='54000'; END IF;
  WHILE octet_length(piece)>0 LOOP
   i:=least(65536-octet_length(chunk),octet_length(piece));chunk:=chunk||substr(piece,1,i);piece:=substr(piece,i+1);
   IF octet_length(chunk)=65536 THEN chunks:=array_append(chunks,chunk);chunk:=decode('','hex'); END IF;
  END LOOP;
 END LOOP;
 chunks:=array_append(chunks,chunk);
 SELECT string_agg(value,decode('','hex') ORDER BY ordinal) INTO output FROM unnest(chunks) WITH ORDINALITY AS c(value,ordinal);
 IF report_seen<>1 THEN RAISE EXCEPTION 'one original revision report artifact slot required' USING ERRCODE='55000'; END IF;
 IF octet_length(output)<>emitted THEN RAISE EXCEPTION 'complete tree byte parity' USING ERRCODE='55000'; END IF;
 RETURN output;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_select_catalog_report_release(expected_writer text, expected_ordinal text, expected_generation text, expected_configuration_profile_hex text)
 RETURNS TABLE(policy_hex text, policy_sha256 text, configuration_generation text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE captured record; original_json json; configuration jsonb; choice json;
 context jsonb; archived bytea; archived_digest bytea; identity_digest bytea; matches bigint;
 configuration_profile bytea:=convert_to($configuration${
