      "sha256": "c3f2645d6af8465366b49332d62cf696ee58acebf826e4abd5aa9de33aa7497d"
    },
    {
      "path": "docs/helix/02-design/contracts/bindings/acceptance-input-decoder-resource-v0.1.candidate.json",
      "sha256": "79a9d77371cd2c1b6a06cee8f996c4d5f5a0d830c1dedad7002ea63e3f24157b"
    },
    {
      "path": "docs/helix/02-design/contracts/bindings/operation-arbitration-resource-v0.1.candidate.json",
      "sha256": "1468bf2b27153be99958b53d0244c09c36e22755d41819037f44531ac9060e36"
    },
    {
      "path": "docs/helix/02-design/contracts/bindings/feed-finalization-resource-v0.1.proposal.json",
      "sha256": "e560fb142e536b603d37b90b4dbaee5cb69c74bdbe9a2b58cb789df560965ebc"
    },
    {
      "path": "packages/python/src/truss/_profiles/catalog-report-configuration.json",
      "sha256": "441bff53c4cbc08ff9975f083d896b95a80ae6921d3a0bee244f3eb3502e99b9"
    }
  ],
  "resourceInterpretation": "Pinned specifications; complete installed implementation and shared accounting required before protected use"
}
$release$,'UTF8');
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed'
  OR current_setting('transaction_read_only') IS DISTINCT FROM 'off' THEN
  RAISE EXCEPTION 'fresh read committed read-write release selection required' USING ERRCODE='55000';
 END IF;
 IF expected_configuration_profile_hex IS DISTINCT FROM encode(configuration_profile,'hex') THEN
  RAISE EXCEPTION 'recognized configuration profile required' USING ERRCODE='0A000';
 END IF;
 SELECT * INTO STRICT captured FROM truss.runtime_collect_catalog_admission_configuration(
  expected_writer,expected_ordinal,expected_generation,expected_configuration_profile_hex);
 original_json:=convert_from(decode(captured.configuration_hex,'hex'),'UTF8')::json;
 IF json_typeof(original_json) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'selected catalog report configuration required' USING ERRCODE='0A000';
 END IF;
 IF (SELECT count(*) FROM json_each(original_json))<>2
  OR (SELECT count(DISTINCT key COLLATE pg_catalog."C") FROM json_each(original_json))<>2 THEN
  RAISE EXCEPTION 'closed unambiguous catalog report configuration required' USING ERRCODE='0A000';
 END IF;
 configuration:=original_json::jsonb;
 IF NOT configuration ?& ARRAY['interfaceVersion','catalogReportRelease']
  OR configuration->>'interfaceVersion' IS DISTINCT FROM 'truss-catalog-report-configuration/0.1' THEN
  RAISE EXCEPTION 'recognized catalog report configuration required' USING ERRCODE='0A000';
 END IF;
 choice:=original_json->'catalogReportRelease';
 IF json_typeof(choice) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'closed release artifact selection required' USING ERRCODE='0A000';
 END IF;
 IF (SELECT count(*) FROM json_each(choice))<>2
  OR (SELECT count(DISTINCT key COLLATE pg_catalog."C") FROM json_each(choice))<>2
  OR NOT choice::jsonb ?& ARRAY['artifactIdentity','sha256']
  OR json_typeof(choice->'artifactIdentity') IS DISTINCT FROM 'string'
  OR json_typeof(choice->'sha256') IS DISTINCT FROM 'string'
  OR choice->>'artifactIdentity' COLLATE pg_catalog."C" IS DISTINCT FROM 'truss.catalog-report-release/0.1.0'
  OR choice->>'sha256' COLLATE pg_catalog."C" IS DISTINCT FROM encode(sha256(release_bytes),'hex') THEN
  RAISE EXCEPTION 'exact selected catalog report release required' USING ERRCODE='0A000';
 END IF;
 context:=convert_from(decode(captured.context_hex,'hex'),'UTF8')::jsonb;
 -- Row locks cannot fence a new matching archive row. SHARE excludes all
 -- concurrent INSERT/UPDATE/DELETE/TRUNCATE and archive DDL through transaction
 -- end (or rollback across acquisition). Same-writer changes still require the
 -- original host lifecycle and protected dispatcher; this is not PA authority.
 -- Refuse conflicting writers immediately, including competing lock upgrades.
 LOCK TABLE truss.installation_archive IN SHARE MODE NOWAIT;
 SELECT count(*) INTO matches FROM truss.installation_archive a
 WHERE convert_to(a.installation_id,'UTF8')=convert_to(context->>'installationId','UTF8')
  AND a.artifact_role COLLATE pg_catalog."C"='input'
  AND convert_to(a.artifact_identity,'UTF8')=convert_to('truss.catalog-report-release/0.1.0','UTF8');
 IF matches<>1 THEN
  RAISE EXCEPTION 'unique original report release archive required' USING ERRCODE='55000';
 END IF;
 SELECT a.artifact_bytes,a.artifact_sha256,a.artifact_identity_sha256
 INTO STRICT archived,archived_digest,identity_digest FROM truss.installation_archive a
 WHERE convert_to(a.installation_id,'UTF8')=convert_to(context->>'installationId','UTF8')
  AND a.artifact_role COLLATE pg_catalog."C"='input'
  AND convert_to(a.artifact_identity,'UTF8')=convert_to('truss.catalog-report-release/0.1.0','UTF8')
 FOR SHARE NOWAIT;
 IF archived IS DISTINCT FROM release_bytes
  OR archived_digest IS DISTINCT FROM sha256(release_bytes)
  OR identity_digest IS DISTINCT FROM sha256(convert_to('truss.catalog-report-release/0.1.0','UTF8')) THEN
  RAISE EXCEPTION 'original complete report release bytes required' USING ERRCODE='55000';
 END IF;
 PERFORM truss.runtime_require_operation_configuration_current(
  expected_writer,expected_ordinal,expected_generation);
 IF (SELECT count(*) FROM truss.installation_archive a
  WHERE convert_to(a.installation_id,'UTF8')=convert_to(context->>'installationId','UTF8')
   AND a.artifact_role COLLATE pg_catalog."C"='input'
   AND convert_to(a.artifact_identity,'UTF8')=convert_to('truss.catalog-report-release/0.1.0','UTF8'))<>1
  OR NOT EXISTS(SELECT 1 FROM truss.installation_archive a
   WHERE convert_to(a.installation_id,'UTF8')=convert_to(context->>'installationId','UTF8')
    AND a.artifact_role COLLATE pg_catalog."C"='input'
    AND convert_to(a.artifact_identity,'UTF8')=convert_to('truss.catalog-report-release/0.1.0','UTF8')
    AND a.artifact_bytes=release_bytes AND a.artifact_sha256=sha256(release_bytes)
    AND a.artifact_identity_sha256=sha256(convert_to(a.artifact_identity,'UTF8'))) THEN
  RAISE EXCEPTION 'current unique release archive correspondence required' USING ERRCODE='55000';
 END IF;
 -- Recheck verifies the retained row under the native archive table cut.
 -- It does not confer authenticated capture, all-source or final-release authority.
 RETURN QUERY SELECT encode(archived,'hex'),encode(sha256(archived),'hex'),captured.configuration_generation;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_select_catalog_report_resources(expected_writer text, expected_ordinal text, expected_generation text, expected_configuration_profile_hex text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE selected record; context jsonb; policy jsonb; item jsonb; row record;
 manifest jsonb:='[]'::jsonb; total bigint:=0; matches bigint;
BEGIN
 -- This original selector acquires the archive table cut before any lookup.
 SELECT * INTO STRICT selected FROM truss.runtime_select_catalog_report_release(
  expected_writer,expected_ordinal,expected_generation,expected_configuration_profile_hex);
 SELECT convert_from(o.original_context_bytes,'UTF8')::jsonb INTO STRICT context
 FROM truss.row_home_operation o WHERE o.original_writer_xid=pg_current_xact_id_if_assigned()
  AND o.operation_ordinal::text=expected_ordinal AND o.phase='admitted';
 policy:=convert_from(decode(selected.policy_hex,'hex'),'UTF8')::jsonb;
 IF jsonb_typeof(policy->'resources') IS DISTINCT FROM 'array'
  OR jsonb_array_length(policy->'resources') NOT BETWEEN 1 AND 256
  OR (SELECT count(DISTINCT convert_to(r->>'path','UTF8')) FROM jsonb_array_elements(policy->'resources') r)
       <>jsonb_array_length(policy->'resources') THEN
  RAISE EXCEPTION 'complete unambiguous original report resource declarations required' USING ERRCODE='55000';
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(policy->'resources') LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(item))<>2
   OR NOT item ?& ARRAY['path','sha256'] OR jsonb_typeof(item->'path') IS DISTINCT FROM 'string'
   OR octet_length(item->>'path') NOT BETWEEN 1 AND 4096
   OR jsonb_typeof(item->'sha256') IS DISTINCT FROM 'string' OR item->>'sha256' !~ '^[0-9a-f]{64}$' THEN
   RAISE EXCEPTION 'closed original report resource declaration required' USING ERRCODE='55000';
  END IF;
  SELECT count(*) INTO matches FROM truss.installation_archive a
   WHERE convert_to(a.installation_id,'UTF8')=convert_to(context->>'installationId','UTF8')
    AND a.artifact_role COLLATE pg_catalog."C"='input'
    AND convert_to(a.artifact_identity,'UTF8')=convert_to(item->>'path','UTF8');
  IF matches<>1 THEN
   RAISE EXCEPTION 'unique original report resource archive required' USING ERRCODE='55000';
  END IF;
  -- Preflight the retained byte sizes before materializing and hashing the row.
  SELECT a.archive_row_id,octet_length(a.artifact_bytes)::bigint AS size INTO STRICT row
   FROM truss.installation_archive a WHERE convert_to(a.installation_id,'UTF8')=convert_to(context->>'installationId','UTF8')
    AND a.artifact_role COLLATE pg_catalog."C"='input'
    AND convert_to(a.artifact_identity,'UTF8')=convert_to(item->>'path','UTF8') FOR SHARE NOWAIT;
  IF row.size NOT BETWEEN 1 AND 1048576 OR total+row.size>4194304 THEN
   RAISE EXCEPTION 'original report resource retained byte capacity exceeded' USING ERRCODE='54000';
  END IF;
  total:=total+row.size;
  IF NOT EXISTS(SELECT 1 FROM truss.installation_archive a WHERE a.archive_row_id=row.archive_row_id
   AND a.artifact_sha256=decode(item->>'sha256','hex') AND a.artifact_sha256=sha256(a.artifact_bytes)
   AND a.artifact_identity_sha256=sha256(convert_to(item->>'path','UTF8'))) THEN
   RAISE EXCEPTION 'original report resource digest correspondence required' USING ERRCODE='55000';
  END IF;
  manifest:=manifest||jsonb_build_array(jsonb_build_object('path',item->>'path',
   'sha256',item->>'sha256','archiveRowId',row.archive_row_id::text,'bytes',row.size::text));
 END LOOP;
 PERFORM truss.runtime_require_operation_configuration_current(expected_writer,expected_ordinal,expected_generation);
 RETURN jsonb_build_object('interfaceVersion','truss-catalog-report-resources/0.1',
  'scope','original_declared_archive_inputs_only','writerXid',expected_writer,
  'operationOrdinal',expected_ordinal,'configurationGeneration',selected.configuration_generation,
  'releaseSha256',selected.policy_sha256,'resources',manifest,'totalBytes',total::text);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_stage_catalog_admitted(issued_ordinal bigint, definition_bytes bytea, input_bytes bytea, candidate_bytes bytea, obligation_bytes bytea, group_bytes bytea, documents_bytes bytea, declarations_bytes bytea, origin_bytes bytea, original_prestate bytea, original_context bytea)
 RETURNS TABLE(writer_xid text, ordinal text, context_hex text, provisional_result_hex text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
 item bytea; total_bytes bigint:=0; input jsonb; declarations jsonb;
 documents jsonb; origin jsonb; prestate bytea; admitted record;
 doc jsonb; rec jsonb; field jsonb; key jsonb; rel jsonb;
 types jsonb; properties jsonb; candidates jsonb; relationships jsonb:='[]'::jsonb; revision int;
 owner_id int; components int[]; source_ids int[]; target_ids int[];
 result jsonb; original_result bytea; final_generation bigint;
 original_graph record; final_graph record;
 lifecycle jsonb; index_declarations jsonb; original_sources record; release record;
 lifecycle_policy bytea:=decode('','hex');
 index_policy bytea:=decode('','hex');
BEGIN
 FOREACH item IN ARRAY ARRAY[definition_bytes,input_bytes,candidate_bytes,
  obligation_bytes,group_bytes,documents_bytes,declarations_bytes,origin_bytes] LOOP
  IF item IS NULL OR octet_length(item) NOT BETWEEN 1 AND 1048576 THEN
   RAISE EXCEPTION 'bounded original catalog input required' USING ERRCODE='22023';
  END IF;
  total_bytes:=total_bytes+octet_length(item);
 END LOOP;
 IF octet_length(input_bytes)>16384 THEN
  RAISE EXCEPTION 'selected report input capacity exceeded' USING ERRCODE='54000';
 END IF;
 IF total_bytes>4194304 THEN
  RAISE EXCEPTION 'original declaration plan correspondence required' USING ERRCODE='22023';
 END IF;
 -- Reuse one actual admitted root; no admission or identity factory in this core.
 IF current_user::text IS DISTINCT FROM (CASE WHEN current_setting('role')='none'
  THEN session_user::text ELSE current_setting('role') END) THEN
  RAISE EXCEPTION 'original invoker actor boundary required' USING ERRCODE='55000';
 END IF;
 IF original_prestate IS NULL OR original_context IS NULL
  OR octet_length(original_prestate) NOT BETWEEN 1 AND 1048576
  OR octet_length(original_context) NOT BETWEEN 1 AND 1048576 THEN
  RAISE EXCEPTION 'bounded retained original admission required' USING ERRCODE='22023';
 END IF;
 IF (SELECT count(*) FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned()
   AND o.phase<>'application_finalized')<>1 THEN
  RAISE EXCEPTION 'sole current unfinished catalog operation required' USING ERRCODE='55000';
 END IF;
 SELECT o.original_writer_xid::text AS writer_xid,o.operation_ordinal::text AS ordinal,
  encode(o.original_context_bytes,'hex') AS context_hex INTO admitted
 FROM truss.row_home_operation o
 WHERE o.original_writer_xid=pg_current_xact_id_if_assigned()
  AND o.operation_ordinal=issued_ordinal AND o.operation_kind='catalog-acceptance'
  AND o.phase='admitted' AND o.effect_generation=0
  AND o.original_context_bytes=original_context
  AND o.original_definition_bytes=definition_bytes AND o.original_input_bytes=input_bytes
  AND o.original_prestate_bytes=original_prestate AND o.admitted_candidate_bytes=candidate_bytes
  AND o.effect_obligation_bytes=obligation_bytes AND o.original_group_custody_bytes=group_bytes;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'original stored catalog operation correspondence required' USING ERRCODE='55000';
 END IF;
 prestate:=original_prestate;
 CASE convert_from(original_context,'UTF8')::jsonb->>'interfaceVersion'
 WHEN 'truss-native-operation-context/0.2' THEN
  PERFORM * FROM truss.runtime_collect_catalog_original_context(admitted.writer_xid,admitted.ordinal,'0');
 WHEN 'truss-native-operation-context/0.4' THEN
  PERFORM * FROM truss.runtime_collect_catalog_epoch_context(admitted.writer_xid,admitted.ordinal,'0');
 ELSE
  RAISE EXCEPTION 'supported complete original context grammar required' USING ERRCODE='0A000';
 END CASE;
 IF NOT EXISTS(SELECT 1 FROM truss.schema_head h WHERE h.id=1 AND h.rev=0)
  OR EXISTS(SELECT 1 FROM truss.schema_rev r WHERE r.rev<>0)
  OR convert_from(prestate,'UTF8')::jsonb->>'interfaceVersion'
     IS DISTINCT FROM 'truss-native-catalog-prestate/0.1' THEN
  RAISE EXCEPTION 'original fresh catalog head and prestate required' USING ERRCODE='0A000';
 END IF;
 PERFORM truss.runtime_verify_new_catalog_prestate(1);
 IF convert_from(original_context,'UTF8')::jsonb->>'interfaceVersion'='truss-native-operation-context/0.4' THEN
  IF candidate_bytes IS NOT DISTINCT FROM declarations_bytes THEN
   RAISE EXCEPTION 'configured source envelope required' USING ERRCODE='22023';
  END IF;
  SELECT * INTO STRICT original_sources FROM truss.runtime_collect_catalog_source_candidate(candidate_bytes,declarations_bytes);
  SELECT * INTO STRICT release FROM truss.runtime_select_catalog_report_release(
   admitted.writer_xid,admitted.ordinal,'0','');
  IF encode(origin_bytes,'hex') IS DISTINCT FROM convert_from(original_context,'UTF8')::jsonb->>'assertedOriginUtf8Hex' THEN
   RAISE EXCEPTION 'original captured asserted origin correspondence required' USING ERRCODE='55000';
  END IF;
 ELSIF candidate_bytes IS DISTINCT FROM declarations_bytes THEN
  RAISE EXCEPTION 'original declaration plan correspondence required' USING ERRCODE='22023';
 END IF;
 input:=convert_from(input_bytes,'UTF8')::jsonb;
 declarations:=convert_from(declarations_bytes,'UTF8')::jsonb;
 documents:=convert_from(documents_bytes,'UTF8')::jsonb;
 origin:=convert_from(origin_bytes,'UTF8')::jsonb;
 IF input->'binding' IS DISTINCT FROM jsonb_build_object('state','absent')
  OR input->'transforms' IS DISTINCT FROM '[]'::jsonb
  OR jsonb_typeof(declarations) IS DISTINCT FROM 'array'
  OR jsonb_array_length(declarations)>4096
  OR jsonb_typeof(origin) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'selected original catalog staging profile required' USING ERRCODE='0A000';
 END IF;
 PERFORM truss.runtime_require_catalog_lifecycle_observers();
 IF convert_from(original_context,'UTF8')::jsonb->>'interfaceVersion'='truss-native-operation-context/0.4' THEN
  SELECT * INTO STRICT original_graph FROM truss.runtime_collect_configured_catalog_graph();
 ELSE
  SELECT * INTO STRICT original_graph FROM truss.runtime_collect_empty_catalog_graph();
 END IF;
 IF original_graph.writer_xid IS DISTINCT FROM admitted.writer_xid
  OR original_graph.operation_ordinal IS DISTINCT FROM admitted.ordinal
  OR original_graph.effect_generation IS DISTINCT FROM '0' THEN
  RAISE EXCEPTION 'original pre-effect graph cut required' USING ERRCODE='55000';
 END IF;
 PERFORM truss.runtime_require_catalog_input(input_bytes);
 PERFORM truss.runtime_require_catalog_document_carrier(documents);
 SELECT s.provisional_revision::int INTO STRICT revision
  FROM truss.runtime_stage_catalog_documents(documents,origin) s;
 SELECT coalesce(jsonb_agg(jsonb_build_object('documentId',r.value->>'documentId',
  'moduleId',r.value->>'moduleId','elementId',r.value->>'elementId')
  ORDER BY d.ord,r.ord),'[]'::jsonb) INTO candidates
  FROM jsonb_array_elements(declarations) WITH ORDINALITY d(value,ord)
  CROSS JOIN LATERAL jsonb_array_elements(d.value->'records') WITH ORDINALITY r(value,ord);
 types:='[]'::jsonb;
 IF jsonb_array_length(candidates)>0 THEN
  SELECT jsonb_agg(to_jsonb(t)) INTO types FROM truss.runtime_stage_new_types(revision,candidates) t;
 END IF;
 candidates:='[]'::jsonb;
 FOR doc IN SELECT value FROM jsonb_array_elements(declarations) LOOP
  IF jsonb_typeof(doc->'records') IS DISTINCT FROM 'array'
   OR jsonb_typeof(doc->'relationships') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'complete original declaration families required' USING ERRCODE='22023';
  END IF;
  FOR rec IN SELECT value FROM jsonb_array_elements(doc->'records') LOOP
   SELECT (t.value->>'type_id')::int INTO STRICT owner_id FROM jsonb_array_elements(types) t
    WHERE t.value->>'document_id'=rec->>'documentId'
     AND t.value->>'module_id'=rec->>'moduleId' AND t.value->>'element_id'=rec->>'elementId';
   IF jsonb_typeof(rec->'fields') IS DISTINCT FROM 'array'
    OR jsonb_typeof(rec->'keys') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'complete original Record plan required' USING ERRCODE='22023';
   END IF;
   FOR field IN SELECT value FROM jsonb_array_elements(rec->'fields') LOOP
    candidates:=candidates||jsonb_build_array(jsonb_build_object('ownerTypeId',owner_id::text,
     'fieldModule',field->>'fieldModule','field',field->'declaration','home','json'));
   END LOOP;
  END LOOP;
 END LOOP;
 properties:='[]'::jsonb;
 IF jsonb_array_length(candidates)>0 THEN
  SELECT jsonb_agg(to_jsonb(p)) INTO properties FROM truss.runtime_stage_new_properties(revision,candidates) p;
 END IF;
 candidates:='[]'::jsonb;
 FOR doc IN SELECT value FROM jsonb_array_elements(declarations) LOOP
  FOR rec IN SELECT value FROM jsonb_array_elements(doc->'records') LOOP
   SELECT (t.value->>'type_id')::int INTO STRICT owner_id FROM jsonb_array_elements(types) t
    WHERE t.value->>'document_id'=rec->>'documentId'
     AND t.value->>'module_id'=rec->>'moduleId' AND t.value->>'element_id'=rec->>'elementId';
   FOR key IN SELECT value FROM jsonb_array_elements(rec->'keys') LOOP
    SELECT array_agg((p.value->>'property_id')::int ORDER BY f.ord) INTO components
     FROM jsonb_array_elements(key->'fields') WITH ORDINALITY f(value,ord)
     JOIN jsonb_array_elements(properties) p ON p.value->>'owner_type_id'=owner_id::text
      AND p.value->>'field_module'=f.value->>'module' AND p.value->>'field_id'=f.value->>'element';
    IF cardinality(components) IS DISTINCT FROM jsonb_array_length(key->'fields') THEN
     RAISE EXCEPTION 'complete original key allocation required' USING ERRCODE='22023';
    END IF;
    candidates:=candidates||jsonb_build_array(jsonb_build_object(
     'ownerTypeId',owner_id::text,'keyId',key->>'id','primary',coalesce(key->'primary','false'::jsonb),
     'propertyIds',(SELECT jsonb_agg(c::text) FROM unnest(components) c)));
   END LOOP;
  END LOOP;
  relationships:=relationships||(doc->'relationships');
 END LOOP;
 IF jsonb_array_length(candidates)>0 THEN
  PERFORM * FROM truss.runtime_stage_new_keys(revision,candidates);
 END IF;
 FOR rel IN SELECT value FROM jsonb_array_elements(relationships)
  ORDER BY (value->>'documentId') COLLATE "C",(value->>'moduleId') COLLATE "C",
   (value->'declaration'->>'id') COLLATE "C" LOOP
   SELECT array_agg((t.value->>'type_id')::int ORDER BY f.ord) INTO source_ids
    FROM jsonb_array_elements(rel->'declaration'->'source') WITH ORDINALITY f(value,ord)
    JOIN jsonb_array_elements(types) t ON t.value->>'document_id'=rel->>'documentId'
     AND t.value->>'module_id'=f.value->>'module' AND t.value->>'element_id'=f.value->>'element';
   SELECT array_agg((t.value->>'type_id')::int ORDER BY f.ord) INTO target_ids
    FROM jsonb_array_elements(rel->'declaration'->'target') WITH ORDINALITY f(value,ord)
    JOIN jsonb_array_elements(types) t ON t.value->>'document_id'=rel->>'documentId'
     AND t.value->>'module_id'=f.value->>'module' AND t.value->>'element_id'=f.value->>'element';
   IF cardinality(source_ids) IS DISTINCT FROM jsonb_array_length(rel->'declaration'->'source')
    OR cardinality(target_ids) IS DISTINCT FROM jsonb_array_length(rel->'declaration'->'target') THEN
    RAISE EXCEPTION 'complete original endpoint allocation required' USING ERRCODE='22023';
   END IF;
   PERFORM truss.runtime_stage_new_relationship(revision,rel->>'documentId',rel->>'moduleId',
    rel->'declaration',source_ids,target_ids);
 END LOOP;
 PERFORM truss.runtime_verify_new_catalog_prestate(revision);
 PERFORM truss.edge_limit_verify_current_scope();
 IF truss.runtime_require_empty_provisional_catalog(revision) IS DISTINCT FROM '0' THEN
  RAISE EXCEPTION 'original empty provisional inventory required' USING ERRCODE='55000';
 END IF;
 IF EXISTS(SELECT 1 FROM truss.prop_def p WHERE p.since_rev=revision AND p.home IS DISTINCT FROM 'json')
  OR (SELECT count(*) FROM truss.prop_def p WHERE p.since_rev=revision)<>jsonb_array_length(properties) THEN
  RAISE EXCEPTION 'complete original JSON home allocation required' USING ERRCODE='55000';
 END IF;
 SELECT o.effect_generation INTO STRICT final_generation FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned()
   AND o.operation_ordinal=issued_ordinal AND o.phase='admitted';
 SELECT jsonb_build_object('interfaceVersion','truss-native-provisional-catalog/0.2',
  'revision',revision::text,'writerXid',admitted.writer_xid,'ordinal',admitted.ordinal,
  'effectGeneration',o.effect_generation::text,'accepted',false,
  'inventory',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.family COLLATE "C",i.identity::text COLLATE "C"),'[]'::jsonb)
   FROM truss.runtime_collect_new_catalog_inventory(revision) i),
  'documents',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.ord::int),'[]'::jsonb) FROM truss.runtime_collect_report_documents(revision) d),
  'counts',(SELECT to_jsonb(c) FROM truss.runtime_collect_new_catalog_counts(revision) c)) INTO STRICT result
  FROM truss.row_home_operation o WHERE o.original_writer_xid=pg_current_xact_id_if_assigned()
   AND o.operation_ordinal=issued_ordinal AND o.phase='admitted';
 lifecycle:=truss.runtime_collect_fresh_catalog_lifecycle(
  admitted.writer_xid,admitted.ordinal,final_generation::text,revision,lifecycle_policy);
 index_declarations:=truss.runtime_collect_absent_binding_index_declarations(
  admitted.writer_xid,admitted.ordinal,final_generation::text,revision,index_policy);
 IF convert_from(original_context,'UTF8')::jsonb->>'interfaceVersion'='truss-native-operation-context/0.4' THEN
  SELECT * INTO STRICT final_graph FROM truss.runtime_collect_configured_catalog_graph();
  IF final_graph.metadata_source IS DISTINCT FROM original_graph.metadata_source THEN
   RAISE EXCEPTION 'original configured metadata source cut required' USING ERRCODE='55000';
  END IF;
 ELSE
  SELECT * INTO STRICT final_graph FROM truss.runtime_collect_empty_catalog_graph();
 END IF;
 IF final_graph.writer_xid IS DISTINCT FROM original_graph.writer_xid
  OR final_graph.operation_ordinal IS DISTINCT FROM original_graph.operation_ordinal
  OR final_graph.empty_scope IS DISTINCT FROM original_graph.empty_scope
  OR final_graph.effect_generation IS DISTINCT FROM final_generation::text THEN
  RAISE EXCEPTION 'original final graph cut required' USING ERRCODE='55000';
 END IF;
 result:=result||jsonb_build_object('reportSources',jsonb_build_object(
  'start',to_jsonb(original_graph),'end',to_jsonb(final_graph),
  'lifecycle',lifecycle,'indexDeclarations',index_declarations));
 original_result:=convert_to(result::text,'UTF8');
 IF NOT EXISTS(SELECT 1 FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned()
   AND o.operation_ordinal=issued_ordinal AND o.phase='admitted'
   AND o.effect_generation=final_generation AND o.operation_kind='catalog-acceptance'
   AND o.original_context_bytes=decode(admitted.context_hex,'hex')
   AND o.original_definition_bytes=definition_bytes AND o.original_input_bytes=input_bytes
   AND o.original_prestate_bytes=prestate AND o.admitted_candidate_bytes=candidate_bytes
   AND o.effect_obligation_bytes=obligation_bytes AND o.original_group_custody_bytes=group_bytes) THEN
  RAISE EXCEPTION 'stale original catalog result cut' USING ERRCODE='55000';
 END IF;
 IF octet_length(original_result)>131072 THEN
  RAISE EXCEPTION 'selected provisional response capacity exceeded' USING ERRCODE='54000';
 END IF;
 RETURN QUERY SELECT admitted.writer_xid,admitted.ordinal,admitted.context_hex,encode(original_result,'hex');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_stage_catalog_documents(documents jsonb, original_origin jsonb)
 RETURNS TABLE(provisional_revision text, document_count text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  op truss.row_home_operation%ROWTYPE;
  item jsonb;
  revision bigint;
  ordinal int:=0;
  total_bytes bigint:=0;
  distinct_ids bigint;
BEGIN
  SELECT * INTO STRICT op FROM truss.row_home_operation o
    WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.phase<>'application_finalized' FOR UPDATE;
  IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted'
      OR documents IS NULL OR jsonb_typeof(documents)<>'array'
      OR jsonb_array_length(documents) NOT BETWEEN 1 AND 512
      OR octet_length(documents::text)>4194304
      OR original_origin IS NULL OR jsonb_typeof(original_origin)<>'object' THEN
    RAISE EXCEPTION 'original document set admission required' USING ERRCODE='22023';
  END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(documents) LOOP
    IF jsonb_typeof(item)<>'object' OR NOT item ?& ARRAY['documentId','revision','umfVersion','originalText','validation']
        OR (SELECT count(*) FROM jsonb_object_keys(item))<>5
        OR EXISTS(SELECT 1 FROM jsonb_each(item) e WHERE e.key IN ('documentId','revision','umfVersion','originalText') AND jsonb_typeof(e.value)<>'string')
        OR octet_length(item->>'documentId') NOT BETWEEN 1 AND 4096
        OR octet_length(item->>'revision') NOT BETWEEN 1 AND 4096
        OR item->>'umfVersion' NOT IN ('0.7.0','0.8.0')
        OR octet_length(item->>'originalText') NOT BETWEEN 1 AND 1048576
        OR jsonb_typeof(item->'validation')<>'object' THEN
      RAISE EXCEPTION 'original document set carrier' USING ERRCODE='22023';
    END IF;
    total_bytes:=total_bytes+octet_length(item->>'originalText');
  END LOOP;
  IF total_bytes>4194304 THEN RAISE EXCEPTION 'document set bytes exhausted' USING ERRCODE='54000'; END IF;
  SELECT count(DISTINCT value->>'documentId') INTO distinct_ids FROM jsonb_array_elements(documents);
  IF distinct_ids<>jsonb_array_length(documents) THEN RAISE EXCEPTION 'duplicate original document' USING ERRCODE='22023'; END IF;
  LOCK TABLE truss.schema_head IN EXCLUSIVE MODE;
  SELECT coalesce(max(r.rev)::bigint,0)+1 INTO revision FROM truss.schema_rev r;
  IF revision>2147483647 THEN RAISE EXCEPTION 'catalog revision exhausted' USING ERRCODE='54000'; END IF;
  INSERT INTO truss.schema_rev(rev,origin) VALUES(revision::int,original_origin);
  FOR item IN SELECT value FROM jsonb_array_elements(documents) LOOP
    INSERT INTO truss.schema_doc(rev,ord,doc_id,doc_revision,umf_version,content_sha256,document,validation)
    VALUES(revision::int,ordinal,item->>'documentId',item->>'revision',item->>'umfVersion',
      encode(sha256(convert_to(item->>'originalText','UTF8')),'hex'),item->>'originalText',item->'validation');
    ordinal:=ordinal+1;
  END LOOP;
  RETURN QUERY SELECT revision::text,ordinal::text;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_stage_catalog_issued(issued_ordinal bigint, definition_bytes bytea, input_bytes bytea, candidate_bytes bytea, obligation_bytes bytea, group_bytes bytea, documents_bytes bytea, declarations_bytes bytea, origin_bytes bytea)
 RETURNS TABLE(writer_xid text, ordinal text, context_hex text, provisional_result_hex text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE prestate bytea; admitted record; item bytea; total_bytes bigint:=0;
 input jsonb; declarations jsonb; documents jsonb; origin jsonb;
BEGIN
 FOREACH item IN ARRAY ARRAY[definition_bytes,input_bytes,candidate_bytes,
  obligation_bytes,group_bytes,documents_bytes,declarations_bytes,origin_bytes] LOOP
  IF item IS NULL OR octet_length(item) NOT BETWEEN 1 AND 1048576 THEN
   RAISE EXCEPTION 'bounded original catalog input required' USING ERRCODE='22023';
  END IF;
  total_bytes:=total_bytes+octet_length(item);
 END LOOP;
 IF octet_length(input_bytes)>16384 THEN
  RAISE EXCEPTION 'selected report input capacity exceeded' USING ERRCODE='54000';
 END IF;
 IF total_bytes>4194304 OR candidate_bytes IS DISTINCT FROM declarations_bytes THEN
  RAISE EXCEPTION 'original declaration plan correspondence required' USING ERRCODE='22023';
 END IF;
 input:=convert_from(input_bytes,'UTF8')::jsonb;
 declarations:=convert_from(declarations_bytes,'UTF8')::jsonb;
 documents:=convert_from(documents_bytes,'UTF8')::jsonb;
 origin:=convert_from(origin_bytes,'UTF8')::jsonb;
 IF input->'binding' IS DISTINCT FROM jsonb_build_object('state','absent')
  OR input->'transforms' IS DISTINCT FROM '[]'::jsonb
  OR jsonb_typeof(declarations) IS DISTINCT FROM 'array'
  OR jsonb_array_length(declarations)>4096
  OR jsonb_typeof(origin) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'selected original catalog staging profile required' USING ERRCODE='0A000';
 END IF;
 prestate:=decode(truss.runtime_capture_catalog_prestate(),'hex');
 SELECT a.* INTO STRICT admitted FROM truss.runtime_admit_operation(
  issued_ordinal,'catalog-acceptance',definition_bytes,input_bytes,prestate,
  candidate_bytes,obligation_bytes,group_bytes) a;
 RETURN QUERY SELECT * FROM truss.runtime_stage_catalog_admitted(
  issued_ordinal,definition_bytes,input_bytes,candidate_bytes,obligation_bytes,group_bytes,
  documents_bytes,declarations_bytes,origin_bytes,prestate,decode(admitted.context_hex,'hex'));
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_stage_catalog_with_release(issued_ordinal bigint, definition_bytes bytea, input_bytes bytea, candidate_bytes bytea, obligation_bytes bytea, group_bytes bytea, documents_bytes bytea, declarations_bytes bytea, origin_bytes bytea, original_prestate bytea, original_context bytea, configuration_profile bytea)
 RETURNS TABLE(writer_xid text, ordinal text, context_hex text, provisional_result_hex text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE before_release record; after_release record; staged record; result jsonb;
 response bytea; total_bytes bigint; before_resources jsonb; after_resources jsonb; final_graph record;
BEGIN
 IF original_context IS NULL OR octet_length(original_context) NOT BETWEEN 1 AND 1048576
  OR configuration_profile IS NULL OR octet_length(configuration_profile) NOT BETWEEN 1 AND 65536
  OR convert_from(original_context,'UTF8')::jsonb->>'interfaceVersion'
     IS DISTINCT FROM 'truss-native-operation-context/0.4' THEN
  RAISE EXCEPTION 'bounded original configured stage context required' USING ERRCODE='22023';
 END IF;
 SELECT sum(octet_length(a)) INTO total_bytes FROM unnest(ARRAY[definition_bytes,input_bytes,
  candidate_bytes,obligation_bytes,group_bytes,documents_bytes,declarations_bytes,origin_bytes,
  configuration_profile]) a;
 IF total_bytes>4194304 THEN
  RAISE EXCEPTION 'configured catalog artifact aggregate capacity exceeded' USING ERRCODE='54000';
 END IF;
 PERFORM truss.runtime_require_selected_archive_write_fence();
 -- Select and acquire the archive cut before any catalog business effect.
 SELECT * INTO STRICT before_release FROM truss.runtime_select_catalog_report_release(
  pg_current_xact_id()::text,issued_ordinal::text,'0',encode(configuration_profile,'hex'));
 before_resources:=truss.runtime_select_catalog_report_resources(
  pg_current_xact_id()::text,issued_ordinal::text,'0',encode(configuration_profile,'hex'));
 SELECT * INTO STRICT staged FROM truss.runtime_stage_catalog_admitted(
  issued_ordinal,definition_bytes,input_bytes,candidate_bytes,obligation_bytes,group_bytes,
  documents_bytes,declarations_bytes,origin_bytes,original_prestate,original_context);
 result:=convert_from(decode(staged.provisional_result_hex,'hex'),'UTF8')::jsonb;
 PERFORM truss.runtime_require_selected_archive_write_fence();
 SELECT * INTO STRICT after_release FROM truss.runtime_select_catalog_report_release(
  staged.writer_xid,staged.ordinal,result->>'effectGeneration',encode(configuration_profile,'hex'));
 IF to_jsonb(before_release) IS DISTINCT FROM to_jsonb(after_release) THEN
  RAISE EXCEPTION 'same original release source through catalog effects required' USING ERRCODE='55000';
 END IF;
 after_resources:=truss.runtime_select_catalog_report_resources(
  staged.writer_xid,staged.ordinal,result->>'effectGeneration',encode(configuration_profile,'hex'));
 IF after_resources IS DISTINCT FROM before_resources THEN
  RAISE EXCEPTION 'same original report resource inputs through catalog effects required' USING ERRCODE='55000';
 END IF;
 -- The extra release/resource collectors must not extend use beyond the core's checked
 -- cut. Recollect the complete metadata/graph and original operation afterward.
 SELECT * INTO STRICT final_graph FROM truss.runtime_collect_configured_catalog_graph();
 IF to_jsonb(final_graph) IS DISTINCT FROM result->'reportSources'->'end'
  OR NOT EXISTS(SELECT 1 FROM truss.row_home_operation o
   WHERE o.original_writer_xid=pg_current_xact_id_if_assigned()
    AND o.original_writer_xid::text=staged.writer_xid AND o.operation_ordinal=issued_ordinal
    AND o.operation_ordinal::text=staged.ordinal AND o.phase='admitted'
    AND o.effect_generation::text=result->>'effectGeneration'
    AND o.operation_kind='catalog-acceptance' AND o.original_context_bytes=original_context
    AND o.original_context_bytes=decode(staged.context_hex,'hex')
    AND o.original_definition_bytes=definition_bytes AND o.original_input_bytes=input_bytes
    AND o.original_prestate_bytes=original_prestate AND o.admitted_candidate_bytes=candidate_bytes
    AND o.effect_obligation_bytes=obligation_bytes AND o.original_group_custody_bytes=group_bytes) THEN
  RAISE EXCEPTION 'original configured release final cut required' USING ERRCODE='55000';
 END IF;
 result:=jsonb_set(result,'{reportSources,catalogResources}',before_resources);
 result:=jsonb_set(result,'{interfaceVersion}','"truss-native-provisional-catalog/0.4"'::jsonb);
 result:=jsonb_set(result,'{reportSources,catalogRelease}',jsonb_build_object(
  'interfaceVersion','truss-configured-catalog-release/0.1','writerXid',staged.writer_xid,
  'operationOrdinal',staged.ordinal,'initialEffectGeneration','0',
  'effectGeneration',result->>'effectGeneration',
  'configurationGeneration',after_release.configuration_generation,
  'policyHex',after_release.policy_hex,'policySha256',after_release.policy_sha256,
  'scope','original_configured_release_at_native_call_only'));
 response:=convert_to(result::text,'UTF8');
 IF octet_length(response)>131072 THEN
  RAISE EXCEPTION 'selected configured provisional response capacity exceeded' USING ERRCODE='54000';
 END IF;
 RETURN QUERY SELECT staged.writer_xid,staged.ordinal,staged.context_hex,encode(response,'hex');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_stage_custody_catalog_admitted_candidate(issued_ordinal bigint, definition_bytes bytea, input_bytes bytea, candidate_bytes bytea, obligation_bytes bytea, group_bytes bytea, documents_bytes bytea, declarations_bytes bytea, origin_bytes bytea, original_prestate bytea, original_context bytea)
 RETURNS TABLE(writer_xid text, ordinal text, context_hex text, provisional_result_hex text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
 item bytea; total_bytes bigint:=0; input jsonb; declarations jsonb;
 documents jsonb; origin jsonb; prestate bytea; admitted record;
 doc jsonb; rec jsonb; field jsonb; key jsonb; rel jsonb;
 types jsonb; properties jsonb; candidates jsonb; relationships jsonb:='[]'::jsonb; revision int;
 owner_id int; components int[]; source_ids int[]; target_ids int[];
 result jsonb; original_result bytea; final_generation bigint;
 original_graph record; final_graph record;
 lifecycle jsonb; index_declarations jsonb; original_sources record; release record;
 lifecycle_policy bytea:=decode('','hex');
 index_policy bytea:=decode('','hex');
BEGIN
 FOREACH item IN ARRAY ARRAY[definition_bytes,input_bytes,candidate_bytes,
  obligation_bytes,group_bytes,documents_bytes,declarations_bytes,origin_bytes] LOOP
  IF item IS NULL OR octet_length(item) NOT BETWEEN 1 AND 1048576 THEN
   RAISE EXCEPTION 'bounded original catalog input required' USING ERRCODE='22023';
  END IF;
  total_bytes:=total_bytes+octet_length(item);
 END LOOP;
 IF octet_length(input_bytes)>16384 THEN
  RAISE EXCEPTION 'selected report input capacity exceeded' USING ERRCODE='54000';
 END IF;
 IF total_bytes>4194304 THEN
  RAISE EXCEPTION 'original declaration plan correspondence required' USING ERRCODE='22023';
 END IF;
 -- Reuse one actual admitted root; no admission or identity factory in this core.
 IF current_user::text IS DISTINCT FROM (CASE WHEN current_setting('role')='none'
  THEN session_user::text ELSE current_setting('role') END) THEN
  RAISE EXCEPTION 'original invoker actor boundary required' USING ERRCODE='55000';
 END IF;
 IF original_prestate IS NULL OR original_context IS NULL
  OR octet_length(original_prestate) NOT BETWEEN 1 AND 1048576
  OR octet_length(original_context) NOT BETWEEN 1 AND 1048576 THEN
  RAISE EXCEPTION 'bounded retained original admission required' USING ERRCODE='22023';
 END IF;
 IF (SELECT count(*) FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned()
   AND o.phase<>'application_finalized')<>1 THEN
  RAISE EXCEPTION 'sole current unfinished catalog operation required' USING ERRCODE='55000';
 END IF;
 SELECT o.original_writer_xid::text AS writer_xid,o.operation_ordinal::text AS ordinal,
  encode(o.original_context_bytes,'hex') AS context_hex INTO admitted
 FROM truss.row_home_operation o
 WHERE o.original_writer_xid=pg_current_xact_id_if_assigned()
  AND o.operation_ordinal=issued_ordinal AND o.operation_kind='catalog-acceptance'
  AND o.phase='admitted' AND o.effect_generation=0
  AND o.original_context_bytes=original_context
  AND o.original_definition_bytes=definition_bytes AND o.original_input_bytes=input_bytes
  AND o.original_prestate_bytes=original_prestate AND o.admitted_candidate_bytes=candidate_bytes
  AND o.effect_obligation_bytes=obligation_bytes AND o.original_group_custody_bytes=group_bytes;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'original stored catalog operation correspondence required' USING ERRCODE='55000';
 END IF;
 prestate:=original_prestate;
 CASE convert_from(original_context,'UTF8')::jsonb->>'interfaceVersion'
 WHEN 'truss-native-operation-context/0.2' THEN
  PERFORM * FROM truss.runtime_collect_catalog_original_context(admitted.writer_xid,admitted.ordinal,'0');
 WHEN 'truss-native-operation-context/0.4' THEN
  PERFORM * FROM truss.runtime_collect_catalog_epoch_context(admitted.writer_xid,admitted.ordinal,'0');
 ELSE
  RAISE EXCEPTION 'supported complete original context grammar required' USING ERRCODE='0A000';
 END CASE;
 IF NOT EXISTS(SELECT 1 FROM truss.schema_head h WHERE h.id=1 AND h.rev=0)
  OR EXISTS(SELECT 1 FROM truss.schema_rev r WHERE r.rev<>0)
  OR convert_from(prestate,'UTF8')::jsonb->>'interfaceVersion'
     IS DISTINCT FROM 'truss-native-catalog-prestate/0.1' THEN
  RAISE EXCEPTION 'original fresh catalog head and prestate required' USING ERRCODE='0A000';
 END IF;
 PERFORM truss.runtime_verify_new_catalog_prestate(1);
 IF convert_from(original_context,'UTF8')::jsonb->>'interfaceVersion'='truss-native-operation-context/0.4' THEN
  IF candidate_bytes IS NOT DISTINCT FROM declarations_bytes THEN
   RAISE EXCEPTION 'configured source envelope required' USING ERRCODE='22023';
  END IF;
  SELECT * INTO STRICT original_sources FROM truss.runtime_collect_catalog_source_candidate(candidate_bytes,declarations_bytes);
  SELECT * INTO STRICT release FROM truss.runtime_select_catalog_report_release(
   admitted.writer_xid,admitted.ordinal,'0','');
  IF encode(origin_bytes,'hex') IS DISTINCT FROM convert_from(original_context,'UTF8')::jsonb->>'assertedOriginUtf8Hex' THEN
   RAISE EXCEPTION 'original captured asserted origin correspondence required' USING ERRCODE='55000';
  END IF;
 ELSIF candidate_bytes IS DISTINCT FROM declarations_bytes THEN
  RAISE EXCEPTION 'original declaration plan correspondence required' USING ERRCODE='22023';
 END IF;
 input:=convert_from(input_bytes,'UTF8')::jsonb;
 declarations:=convert_from(declarations_bytes,'UTF8')::jsonb;
 documents:=convert_from(documents_bytes,'UTF8')::jsonb;
 origin:=convert_from(origin_bytes,'UTF8')::jsonb;
 IF input->'binding' IS DISTINCT FROM jsonb_build_object('state','absent')
  OR input->'transforms' IS DISTINCT FROM '[]'::jsonb
  OR jsonb_typeof(declarations) IS DISTINCT FROM 'array'
  OR jsonb_array_length(declarations)>4096
  OR jsonb_typeof(origin) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'selected original catalog staging profile required' USING ERRCODE='0A000';
 END IF;
 PERFORM truss.runtime_require_catalog_lifecycle_observers();
 IF convert_from(original_context,'UTF8')::jsonb->>'interfaceVersion'='truss-native-operation-context/0.4' THEN
  SELECT * INTO STRICT original_graph FROM truss.runtime_collect_custody_catalog_graph_candidate();
 ELSE
  SELECT * INTO STRICT original_graph FROM truss.runtime_collect_empty_catalog_graph();
 END IF;
 IF original_graph.writer_xid IS DISTINCT FROM admitted.writer_xid
  OR original_graph.operation_ordinal IS DISTINCT FROM admitted.ordinal
  OR original_graph.effect_generation IS DISTINCT FROM '0' THEN
  RAISE EXCEPTION 'original pre-effect graph cut required' USING ERRCODE='55000';
 END IF;
 PERFORM truss.runtime_require_catalog_input(input_bytes);
 PERFORM truss.runtime_require_catalog_document_carrier(documents);
 SELECT s.provisional_revision::int INTO STRICT revision
  FROM truss.runtime_stage_catalog_documents(documents,origin) s;
 SELECT coalesce(jsonb_agg(jsonb_build_object('documentId',r.value->>'documentId',
  'moduleId',r.value->>'moduleId','elementId',r.value->>'elementId')
  ORDER BY d.ord,r.ord),'[]'::jsonb) INTO candidates
  FROM jsonb_array_elements(declarations) WITH ORDINALITY d(value,ord)
  CROSS JOIN LATERAL jsonb_array_elements(d.value->'records') WITH ORDINALITY r(value,ord);
 types:='[]'::jsonb;
 IF jsonb_array_length(candidates)>0 THEN
  SELECT jsonb_agg(to_jsonb(t)) INTO types FROM truss.runtime_stage_new_types(revision,candidates) t;
 END IF;
 candidates:='[]'::jsonb;
 FOR doc IN SELECT value FROM jsonb_array_elements(declarations) LOOP
  IF jsonb_typeof(doc->'records') IS DISTINCT FROM 'array'
   OR jsonb_typeof(doc->'relationships') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'complete original declaration families required' USING ERRCODE='22023';
  END IF;
  FOR rec IN SELECT value FROM jsonb_array_elements(doc->'records') LOOP
   SELECT (t.value->>'type_id')::int INTO STRICT owner_id FROM jsonb_array_elements(types) t
    WHERE t.value->>'document_id'=rec->>'documentId'
     AND t.value->>'module_id'=rec->>'moduleId' AND t.value->>'element_id'=rec->>'elementId';
   IF jsonb_typeof(rec->'fields') IS DISTINCT FROM 'array'
    OR jsonb_typeof(rec->'keys') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'complete original Record plan required' USING ERRCODE='22023';
   END IF;
   FOR field IN SELECT value FROM jsonb_array_elements(rec->'fields') LOOP
    candidates:=candidates||jsonb_build_array(jsonb_build_object('ownerTypeId',owner_id::text,
     'fieldModule',field->>'fieldModule','field',field->'declaration','home','json'));
   END LOOP;
  END LOOP;
 END LOOP;
 properties:='[]'::jsonb;
 IF jsonb_array_length(candidates)>0 THEN
  SELECT jsonb_agg(to_jsonb(p)) INTO properties FROM truss.runtime_stage_new_properties(revision,candidates) p;
 END IF;
 candidates:='[]'::jsonb;
 FOR doc IN SELECT value FROM jsonb_array_elements(declarations) LOOP
  FOR rec IN SELECT value FROM jsonb_array_elements(doc->'records') LOOP
   SELECT (t.value->>'type_id')::int INTO STRICT owner_id FROM jsonb_array_elements(types) t
    WHERE t.value->>'document_id'=rec->>'documentId'
     AND t.value->>'module_id'=rec->>'moduleId' AND t.value->>'element_id'=rec->>'elementId';
   FOR key IN SELECT value FROM jsonb_array_elements(rec->'keys') LOOP
    SELECT array_agg((p.value->>'property_id')::int ORDER BY f.ord) INTO components
     FROM jsonb_array_elements(key->'fields') WITH ORDINALITY f(value,ord)
     JOIN jsonb_array_elements(properties) p ON p.value->>'owner_type_id'=owner_id::text
      AND p.value->>'field_module'=f.value->>'module' AND p.value->>'field_id'=f.value->>'element';
    IF cardinality(components) IS DISTINCT FROM jsonb_array_length(key->'fields') THEN
     RAISE EXCEPTION 'complete original key allocation required' USING ERRCODE='22023';
    END IF;
    candidates:=candidates||jsonb_build_array(jsonb_build_object(
     'ownerTypeId',owner_id::text,'keyId',key->>'id','primary',coalesce(key->'primary','false'::jsonb),
     'propertyIds',(SELECT jsonb_agg(c::text) FROM unnest(components) c)));
   END LOOP;
  END LOOP;
  relationships:=relationships||(doc->'relationships');
 END LOOP;
 IF jsonb_array_length(candidates)>0 THEN
  PERFORM * FROM truss.runtime_stage_new_keys(revision,candidates);
 END IF;
 FOR rel IN SELECT value FROM jsonb_array_elements(relationships)
  ORDER BY (value->>'documentId') COLLATE "C",(value->>'moduleId') COLLATE "C",
   (value->'declaration'->>'id') COLLATE "C" LOOP
   SELECT array_agg((t.value->>'type_id')::int ORDER BY f.ord) INTO source_ids
    FROM jsonb_array_elements(rel->'declaration'->'source') WITH ORDINALITY f(value,ord)
    JOIN jsonb_array_elements(types) t ON t.value->>'document_id'=rel->>'documentId'
     AND t.value->>'module_id'=f.value->>'module' AND t.value->>'element_id'=f.value->>'element';
   SELECT array_agg((t.value->>'type_id')::int ORDER BY f.ord) INTO target_ids
    FROM jsonb_array_elements(rel->'declaration'->'target') WITH ORDINALITY f(value,ord)
    JOIN jsonb_array_elements(types) t ON t.value->>'document_id'=rel->>'documentId'
     AND t.value->>'module_id'=f.value->>'module' AND t.value->>'element_id'=f.value->>'element';
   IF cardinality(source_ids) IS DISTINCT FROM jsonb_array_length(rel->'declaration'->'source')
    OR cardinality(target_ids) IS DISTINCT FROM jsonb_array_length(rel->'declaration'->'target') THEN
    RAISE EXCEPTION 'complete original endpoint allocation required' USING ERRCODE='22023';
   END IF;
   PERFORM truss.runtime_stage_new_relationship(revision,rel->>'documentId',rel->>'moduleId',
    rel->'declaration',source_ids,target_ids);
 END LOOP;
 PERFORM truss.runtime_verify_new_catalog_prestate(revision);
 PERFORM truss.edge_limit_verify_current_scope();
 IF truss.runtime_require_empty_provisional_catalog(revision) IS DISTINCT FROM '0' THEN
  RAISE EXCEPTION 'original empty provisional inventory required' USING ERRCODE='55000';
 END IF;
 IF EXISTS(SELECT 1 FROM truss.prop_def p WHERE p.since_rev=revision AND p.home IS DISTINCT FROM 'json')
  OR (SELECT count(*) FROM truss.prop_def p WHERE p.since_rev=revision)<>jsonb_array_length(properties) THEN
  RAISE EXCEPTION 'complete original JSON home allocation required' USING ERRCODE='55000';
 END IF;
 SELECT o.effect_generation INTO STRICT final_generation FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned()
   AND o.operation_ordinal=issued_ordinal AND o.phase='admitted';
 SELECT jsonb_build_object('interfaceVersion','truss-native-provisional-catalog/0.2',
  'revision',revision::text,'writerXid',admitted.writer_xid,'ordinal',admitted.ordinal,
  'effectGeneration',o.effect_generation::text,'accepted',false,
  'inventory',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.family COLLATE "C",i.identity::text COLLATE "C"),'[]'::jsonb)
   FROM truss.runtime_collect_new_catalog_inventory(revision) i),
  'documents',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.ord::int),'[]'::jsonb) FROM truss.runtime_collect_report_documents(revision) d),
  'counts',(SELECT to_jsonb(c) FROM truss.runtime_collect_new_catalog_counts(revision) c)) INTO STRICT result
  FROM truss.row_home_operation o WHERE o.original_writer_xid=pg_current_xact_id_if_assigned()
   AND o.operation_ordinal=issued_ordinal AND o.phase='admitted';
 lifecycle:=truss.runtime_collect_custody_catalog_lifecycle_candidate(
  admitted.writer_xid,admitted.ordinal,final_generation::text,revision,lifecycle_policy);
 index_declarations:=truss.runtime_collect_absent_binding_index_declarations(
  admitted.writer_xid,admitted.ordinal,final_generation::text,revision,index_policy);
 IF convert_from(original_context,'UTF8')::jsonb->>'interfaceVersion'='truss-native-operation-context/0.4' THEN
  SELECT * INTO STRICT final_graph FROM truss.runtime_collect_custody_catalog_graph_candidate();
  IF final_graph.metadata_source IS DISTINCT FROM original_graph.metadata_source THEN
   RAISE EXCEPTION 'original configured metadata source cut required' USING ERRCODE='55000';
  END IF;
 ELSE
  SELECT * INTO STRICT final_graph FROM truss.runtime_collect_empty_catalog_graph();
 END IF;
 IF final_graph.writer_xid IS DISTINCT FROM original_graph.writer_xid
  OR final_graph.operation_ordinal IS DISTINCT FROM original_graph.operation_ordinal
  OR final_graph.empty_scope IS DISTINCT FROM original_graph.empty_scope
  OR final_graph.effect_generation IS DISTINCT FROM final_generation::text THEN
  RAISE EXCEPTION 'original final graph cut required' USING ERRCODE='55000';
 END IF;
 result:=result||jsonb_build_object('reportSources',jsonb_build_object(
  'start',to_jsonb(original_graph),'end',to_jsonb(final_graph),
  'lifecycle',lifecycle,'indexDeclarations',index_declarations));
 original_result:=convert_to(result::text,'UTF8');
 IF NOT EXISTS(SELECT 1 FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned()
   AND o.operation_ordinal=issued_ordinal AND o.phase='admitted'
   AND o.effect_generation=final_generation AND o.operation_kind='catalog-acceptance'
   AND o.original_context_bytes=decode(admitted.context_hex,'hex')
   AND o.original_definition_bytes=definition_bytes AND o.original_input_bytes=input_bytes
   AND o.original_prestate_bytes=prestate AND o.admitted_candidate_bytes=candidate_bytes
   AND o.effect_obligation_bytes=obligation_bytes AND o.original_group_custody_bytes=group_bytes) THEN
  RAISE EXCEPTION 'stale original catalog result cut' USING ERRCODE='55000';
 END IF;
 IF octet_length(original_result)>131072 THEN
  RAISE EXCEPTION 'selected provisional response capacity exceeded' USING ERRCODE='54000';
 END IF;
 RETURN QUERY SELECT admitted.writer_xid,admitted.ordinal,admitted.context_hex,encode(original_result,'hex');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_stage_custody_catalog_with_release_candidate(issued_ordinal bigint, definition_bytes bytea, input_bytes bytea, candidate_bytes bytea, obligation_bytes bytea, group_bytes bytea, documents_bytes bytea, declarations_bytes bytea, origin_bytes bytea, original_prestate bytea, original_context bytea, configuration_profile bytea)
 RETURNS TABLE(writer_xid text, ordinal text, context_hex text, provisional_result_hex text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE before_release record; after_release record; staged record; result jsonb;
 response bytea; total_bytes bigint; before_resources jsonb; after_resources jsonb; final_graph record;
BEGIN
 IF original_context IS NULL OR octet_length(original_context) NOT BETWEEN 1 AND 1048576
  OR configuration_profile IS NULL OR octet_length(configuration_profile) NOT BETWEEN 1 AND 65536
  OR convert_from(original_context,'UTF8')::jsonb->>'interfaceVersion'
     IS DISTINCT FROM 'truss-native-operation-context/0.4' THEN
  RAISE EXCEPTION 'bounded original configured stage context required' USING ERRCODE='22023';
 END IF;
 SELECT sum(octet_length(a)) INTO total_bytes FROM unnest(ARRAY[definition_bytes,input_bytes,
  candidate_bytes,obligation_bytes,group_bytes,documents_bytes,declarations_bytes,origin_bytes,
  configuration_profile]) a;
 IF total_bytes>4194304 THEN
  RAISE EXCEPTION 'configured catalog artifact aggregate capacity exceeded' USING ERRCODE='54000';
 END IF;
 PERFORM truss.runtime_require_selected_archive_write_fence();
 -- Select and acquire the archive cut before any catalog business effect.
 SELECT * INTO STRICT before_release FROM truss.runtime_select_catalog_report_release(
  pg_current_xact_id()::text,issued_ordinal::text,'0',encode(configuration_profile,'hex'));
 before_resources:=truss.runtime_select_catalog_report_resources(
  pg_current_xact_id()::text,issued_ordinal::text,'0',encode(configuration_profile,'hex'));
 SELECT * INTO STRICT staged FROM truss.runtime_stage_custody_catalog_admitted_candidate(
  issued_ordinal,definition_bytes,input_bytes,candidate_bytes,obligation_bytes,group_bytes,
  documents_bytes,declarations_bytes,origin_bytes,original_prestate,original_context);
 result:=convert_from(decode(staged.provisional_result_hex,'hex'),'UTF8')::jsonb;
 PERFORM truss.runtime_require_selected_archive_write_fence();
 SELECT * INTO STRICT after_release FROM truss.runtime_select_catalog_report_release(
  staged.writer_xid,staged.ordinal,result->>'effectGeneration',encode(configuration_profile,'hex'));
 IF to_jsonb(before_release) IS DISTINCT FROM to_jsonb(after_release) THEN
  RAISE EXCEPTION 'same original release source through catalog effects required' USING ERRCODE='55000';
 END IF;
 after_resources:=truss.runtime_select_catalog_report_resources(
  staged.writer_xid,staged.ordinal,result->>'effectGeneration',encode(configuration_profile,'hex'));
 IF after_resources IS DISTINCT FROM before_resources THEN
  RAISE EXCEPTION 'same original report resource inputs through catalog effects required' USING ERRCODE='55000';
 END IF;
 -- The extra release/resource collectors must not extend use beyond the core's checked
 -- cut. Recollect the complete metadata/graph and original operation afterward.
 SELECT * INTO STRICT final_graph FROM truss.runtime_collect_custody_catalog_graph_candidate();
 IF to_jsonb(final_graph) IS DISTINCT FROM result->'reportSources'->'end'
  OR NOT EXISTS(SELECT 1 FROM truss.row_home_operation o
   WHERE o.original_writer_xid=pg_current_xact_id_if_assigned()
    AND o.original_writer_xid::text=staged.writer_xid AND o.operation_ordinal=issued_ordinal
    AND o.operation_ordinal::text=staged.ordinal AND o.phase='admitted'
    AND o.effect_generation::text=result->>'effectGeneration'
    AND o.operation_kind='catalog-acceptance' AND o.original_context_bytes=original_context
    AND o.original_context_bytes=decode(staged.context_hex,'hex')
    AND o.original_definition_bytes=definition_bytes AND o.original_input_bytes=input_bytes
    AND o.original_prestate_bytes=original_prestate AND o.admitted_candidate_bytes=candidate_bytes
    AND o.effect_obligation_bytes=obligation_bytes AND o.original_group_custody_bytes=group_bytes) THEN
  RAISE EXCEPTION 'original configured release final cut required' USING ERRCODE='55000';
 END IF;
 result:=jsonb_set(result,'{reportSources,catalogResources}',before_resources);
 result:=jsonb_set(result,'{interfaceVersion}','"truss-native-provisional-catalog/0.4"'::jsonb);
 result:=jsonb_set(result,'{reportSources,catalogRelease}',jsonb_build_object(
  'interfaceVersion','truss-configured-catalog-release/0.1','writerXid',staged.writer_xid,
  'operationOrdinal',staged.ordinal,'initialEffectGeneration','0',
  'effectGeneration',result->>'effectGeneration',
  'configurationGeneration',after_release.configuration_generation,
  'policyHex',after_release.policy_hex,'policySha256',after_release.policy_sha256,
  'scope','original_configured_release_at_native_call_only'));
 response:=convert_to(result::text,'UTF8');
 IF octet_length(response)>131072 THEN
  RAISE EXCEPTION 'selected configured provisional response capacity exceeded' USING ERRCODE='54000';
 END IF;
 RETURN QUERY SELECT staged.writer_xid,staged.ordinal,staged.context_hex,encode(response,'hex');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_stage_new_key(revision integer, owner_id integer, original_key_id text, ordered_property_ids integer[], primary_key boolean)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  op truss.row_home_operation%ROWTYPE;
  owner truss.type_def%ROWTYPE;
  next_number bigint;
  component int;
  original_keys jsonb;
  original_key jsonb;
  original_field jsonb;
  component_ordinal int;
  matched record;
BEGIN
  SELECT * INTO STRICT op FROM truss.row_home_operation o
    WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.phase<>'application_finalized' FOR UPDATE;
  IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted' OR revision IS NULL OR owner_id IS NULL
      OR original_key_id IS NULL OR octet_length(original_key_id) NOT BETWEEN 1 AND 4096
      OR primary_key IS NULL OR ordered_property_ids IS NULL
      OR array_ndims(ordered_property_ids)<>1 OR array_lower(ordered_property_ids,1)<>1
      OR cardinality(ordered_property_ids) NOT BETWEEN 1 AND 256
      OR array_position(ordered_property_ids,NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'original ordered key input required' USING ERRCODE='22023';
  END IF;
  LOCK TABLE truss.schema_head IN EXCLUSIVE MODE;
  SELECT * INTO STRICT owner FROM truss.type_def t WHERE t.type_id=owner_id;
  IF owner.since_rev<>revision OR owner.retired_rev IS NOT NULL OR owner.doc_ord IS NULL THEN
    RAISE EXCEPTION 'original key owner correspondence required' USING ERRCODE='55000';
  END IF;
  IF (SELECT count(DISTINCT p) FROM unnest(ordered_property_ids) p)<>cardinality(ordered_property_ids) THEN
    RAISE EXCEPTION 'duplicate ordered key component' USING ERRCODE='22023';
  END IF;
  FOREACH component IN ARRAY ordered_property_ids LOOP
    PERFORM 1 FROM truss.prop_def p WHERE p.prop_id=component AND p.type_id=owner_id AND p.retired_rev IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'foreign or missing key component' USING ERRCODE='55000'; END IF;
  END LOOP;
  SELECT jsonb_agg(k.value) INTO original_keys FROM truss.schema_doc d
    CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') m
    CROSS JOIN LATERAL jsonb_array_elements(m.value->'elements') e
    CROSS JOIN LATERAL jsonb_array_elements(e.value->'keys') k
    WHERE d.rev=revision AND d.ord=owner.doc_ord AND d.doc_id=owner.document_id
      AND m.value->>'id'=owner.module AND e.value->>'id'=owner.element
      AND e.value->>'kind'='record' AND k.value->>'id'=original_key_id;
  IF original_keys IS NULL OR jsonb_array_length(original_keys)<>1 THEN
    RAISE EXCEPTION 'key does not match original owner declaration' USING ERRCODE='55000';
  END IF;
  original_key:=original_keys->0;
  IF coalesce((original_key->>'primary')::boolean,false)<>primary_key
      OR jsonb_array_length(original_key->'fields')<>cardinality(ordered_property_ids) THEN
    RAISE EXCEPTION 'original key flag or component count mismatch' USING ERRCODE='55000';
  END IF;
  FOR component_ordinal IN 1..cardinality(ordered_property_ids) LOOP
    original_field:=original_key->'fields'->(component_ordinal-1);
    PERFORM 1 FROM truss.prop_def p WHERE p.prop_id=ordered_property_ids[component_ordinal]
      AND p.type_id=owner_id AND p.element COLLATE "C"= (original_field->>'element') COLLATE "C"
      AND p.declaration_module COLLATE "C"=(original_field->>'module') COLLATE "C"
      AND p.definition_document_id=owner.document_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'original ordered key field correspondence' USING ERRCODE='55000'; END IF;
  END LOOP;
  SELECT * INTO STRICT matched FROM truss.runtime_match_key_identity(revision,owner_id,original_key_id);
  IF matched.match_state<>'new' OR EXISTS(SELECT 1 FROM truss.key_def k WHERE k.type_id=owner_id AND primary_key AND k.is_primary AND k.retired_rev IS NULL) THEN
    RAISE EXCEPTION 'existing key requires original matching' USING ERRCODE='55000';
  END IF;
  SELECT greatest(coalesce(max(k.key_num)::bigint,0),0)+1 INTO next_number FROM truss.key_def k WHERE k.type_id=owner_id;
  IF next_number>32767 THEN RAISE EXCEPTION 'owner key number exhausted' USING ERRCODE='54000'; END IF;
  INSERT INTO truss.key_def(type_id,key_id,key_num,prop_ids,is_primary,since_rev,definition_source_kind,
      definition_rev,definition_doc_ord,definition_document_id)
  VALUES(owner_id,original_key_id,next_number::smallint,ordered_property_ids,primary_key,revision,
      'accepted_document',revision,owner.doc_ord,owner.document_id);
  RETURN next_number::text;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_stage_new_keys(revision integer, candidates jsonb)
 RETURNS TABLE(owner_type_id text, key_id text, key_number text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  candidate jsonb;
  components int[];
  assigned text;
BEGIN
  IF revision IS NULL OR candidates IS NULL OR jsonb_typeof(candidates)<>'array'
      OR jsonb_array_length(candidates) NOT BETWEEN 1 AND 4096
      OR octet_length(candidates::text)>1048576 THEN
    RAISE EXCEPTION 'original key batch required' USING ERRCODE='22023';
  END IF;
  FOR candidate IN SELECT value FROM jsonb_array_elements(candidates) LOOP
    IF jsonb_typeof(candidate)<>'object' OR NOT candidate ?& ARRAY['ownerTypeId','keyId','propertyIds','primary']
        OR (SELECT count(*) FROM jsonb_object_keys(candidate))<>4
        OR jsonb_typeof(candidate->'ownerTypeId')<>'string'
        OR candidate->>'ownerTypeId' !~ '^[1-9][0-9]{0,9}$'
        OR (candidate->>'ownerTypeId')::bigint>2147483647
        OR jsonb_typeof(candidate->'keyId')<>'string'
        OR octet_length(candidate->>'keyId') NOT BETWEEN 1 AND 4096
        OR jsonb_typeof(candidate->'primary')<>'boolean'
        OR jsonb_typeof(candidate->'propertyIds')<>'array' THEN
      RAISE EXCEPTION 'original key batch carrier' USING ERRCODE='22023';
    END IF;
    IF jsonb_array_length(candidate->'propertyIds') NOT BETWEEN 1 AND 256 THEN
      RAISE EXCEPTION 'original key component bound' USING ERRCODE='22023';
    END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(candidate->'propertyIds') p WHERE
        jsonb_typeof(p)<>'string' OR p #>> '{}' !~ '^[1-9][0-9]{0,9}$') THEN
      RAISE EXCEPTION 'original key component carrier' USING ERRCODE='22023';
    END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(candidate->'propertyIds') p WHERE p::bigint>2147483647) THEN
      RAISE EXCEPTION 'original key component capacity' USING ERRCODE='22023';
    END IF;
  END LOOP;
  IF (SELECT count(*) FROM (SELECT DISTINCT value->>'ownerTypeId',value->>'keyId' FROM jsonb_array_elements(candidates)) q)<>jsonb_array_length(candidates) THEN
    RAISE EXCEPTION 'duplicate owner key declaration' USING ERRCODE='22023';
  END IF;
  -- Resolve/check every owner through the scalar producer; never drop a missing owner in a join.
  FOR candidate IN SELECT value FROM jsonb_array_elements(candidates)
      ORDER BY (value->>'ownerTypeId')::int,(value->>'keyId') COLLATE "C" LOOP
    SELECT array_agg(p.value::int ORDER BY p.ordinality) INTO components
      FROM jsonb_array_elements_text(candidate->'propertyIds') WITH ORDINALITY p(value,ordinality);
    assigned:=truss.runtime_stage_new_key(revision,(candidate->>'ownerTypeId')::int,
      candidate->>'keyId',components,(candidate->>'primary')::boolean);
    RETURN QUERY SELECT candidate->>'ownerTypeId',candidate->>'keyId',assigned;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_stage_new_properties(revision integer, candidates jsonb)
 RETURNS TABLE(owner_type_id text, field_module text, field_id text, property_id text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  op truss.row_home_operation%ROWTYPE;
  candidate jsonb;
  owner truss.type_def%ROWTYPE;
  high_water bigint;
  assigned bigint;
  total_new bigint;
  source_matches bigint;
  original_field_module text;
  matched record;
BEGIN
  SELECT * INTO STRICT op FROM truss.row_home_operation o
    WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.phase<>'application_finalized' FOR UPDATE;
  IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted' OR revision IS NULL
      OR candidates IS NULL OR jsonb_typeof(candidates)<>'array'
      OR jsonb_array_length(candidates) NOT BETWEEN 1 AND 4096 OR octet_length(candidates::text)>1048576 THEN
    RAISE EXCEPTION 'original property batch admission required' USING ERRCODE='22023';
  END IF;
  LOCK TABLE truss.schema_head IN EXCLUSIVE MODE;
  FOR candidate IN SELECT value FROM jsonb_array_elements(candidates) LOOP
    IF jsonb_typeof(candidate)<>'object' OR NOT candidate ?& ARRAY['ownerTypeId','fieldModule','field','home']
        OR (SELECT count(*) FROM jsonb_object_keys(candidate))<>4
        OR jsonb_typeof(candidate->'fieldModule')<>'string'
        OR octet_length(candidate->>'fieldModule') NOT BETWEEN 1 AND 65536
        OR jsonb_typeof(candidate->'ownerTypeId')<>'string'
        OR candidate->>'ownerTypeId' !~ '^[1-9][0-9]{0,9}$'
        OR (candidate->>'ownerTypeId')::bigint>2147483647
        OR candidate->>'home' NOT IN ('json','row') OR candidate->>'home' IS NULL
        OR jsonb_typeof(candidate->'field')<>'object' THEN
      RAISE EXCEPTION 'original property candidate shape' USING ERRCODE='22023';
    END IF;
    IF NOT (candidate->'field') ?& ARRAY['id','name','kind','nullability','cardinality']
        OR candidate->'field'->>'kind'<>'field'
        OR EXISTS(SELECT 1 FROM jsonb_each(candidate->'field') e WHERE e.key IN ('id','name','kind','nullability','cardinality','scalarType') AND (jsonb_typeof(e.value)<>'string' OR octet_length(e.value #>> '{}') NOT BETWEEN 1 AND 4096)) THEN
      RAISE EXCEPTION 'original field carrier' USING ERRCODE='22023';
    END IF;
    SELECT * INTO STRICT owner FROM truss.type_def t WHERE t.type_id=(candidate->>'ownerTypeId')::int;
    IF owner.since_rev<>revision OR owner.retired_rev IS NOT NULL OR owner.doc_ord IS NULL THEN
      RAISE EXCEPTION 'new property owner correspondence required' USING ERRCODE='55000';
    END IF;
    IF EXISTS(SELECT 1 FROM truss.prop_def p WHERE p.type_id=owner.type_id AND
      p.name=candidate->'field'->>'name' AND NOT (p.declaration_module=candidate->>'fieldModule' AND p.element=candidate->'field'->>'id')) THEN
      RAISE EXCEPTION 'existing property requires original matching' USING ERRCODE='55000';
    END IF;
  END LOOP;
  SELECT count(*) INTO total_new FROM (SELECT DISTINCT value->>'ownerTypeId',value->>'fieldModule',value->'field'->>'id' FROM jsonb_array_elements(candidates)) q;
  IF total_new<>jsonb_array_length(candidates) THEN RAISE EXCEPTION 'duplicate owner field' USING ERRCODE='22023'; END IF;
  SELECT count(*) INTO total_new FROM (SELECT DISTINCT value->>'ownerTypeId',value->'field'->>'name' FROM jsonb_array_elements(candidates)) q;
  IF total_new<>jsonb_array_length(candidates) THEN RAISE EXCEPTION 'duplicate owner field name' USING ERRCODE='22023'; END IF;
  -- Complete original membership/definition preflight precedes every allocation.
  -- JSON extraction checks correspondence; UMF validity remains the owner's check.
  FOR candidate IN SELECT value FROM jsonb_array_elements(candidates) LOOP
    SELECT * INTO STRICT owner FROM truss.type_def t WHERE t.type_id=(candidate->>'ownerTypeId')::int;
    SELECT count(*),min(fm.value->>'id') INTO source_matches,original_field_module FROM truss.schema_doc d
        CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') m
        CROSS JOIN LATERAL jsonb_array_elements(m.value->'elements') r
        CROSS JOIN LATERAL jsonb_array_elements(r.value->'members') member
        CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') fm
        CROSS JOIN LATERAL jsonb_array_elements(fm.value->'elements') f
        WHERE d.rev=revision AND d.ord=owner.doc_ord AND d.doc_id=owner.document_id
          AND m.value->>'id'=owner.module AND r.value->>'id'=owner.element AND r.value->>'kind'='record'
          AND fm.value->>'id'=member.value->>'module' AND f.value->>'id'=member.value->>'element'
          AND fm.value->>'id'=candidate->>'fieldModule' AND f.value=candidate->'field';
    IF source_matches<>1 THEN
      RAISE EXCEPTION 'property does not match original owner member and Field definition' USING ERRCODE='55000';
    END IF;
    SELECT * INTO STRICT matched FROM truss.runtime_match_property_identity(revision,owner.type_id,candidate->>'fieldModule',candidate->'field'->>'id');
    IF matched.match_state<>'new' THEN
      RAISE EXCEPTION 'retained property requires complete matching/lifecycle admission' USING ERRCODE='55000';
    END IF;
  END LOOP;
  SELECT greatest(coalesce(max(p.prop_id)::bigint,0),0) INTO high_water FROM truss.prop_def p;
  IF high_water+total_new>2147483647 THEN RAISE EXCEPTION 'property capacity exhausted' USING ERRCODE='54000'; END IF;
  assigned:=high_water;
  FOR candidate IN SELECT v.value FROM jsonb_array_elements(candidates) v
      JOIN truss.type_def t ON t.type_id=(v.value->>'ownerTypeId')::int
      ORDER BY t.document_id COLLATE "C",t.module COLLATE "C",t.element COLLATE "C",(v.value->>'fieldModule') COLLATE "C",(v.value->'field'->>'id') COLLATE "C" LOOP
    assigned:=assigned+1;
    SELECT * INTO STRICT owner FROM truss.type_def t WHERE t.type_id=(candidate->>'ownerTypeId')::int;
    SELECT fm.value->>'id' INTO STRICT original_field_module FROM truss.schema_doc d
      CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') fm
      CROSS JOIN LATERAL jsonb_array_elements(fm.value->'elements') f
      WHERE d.rev=revision AND d.ord=owner.doc_ord AND d.doc_id=owner.document_id
        AND fm.value->>'id'=candidate->>'fieldModule' AND f.value=candidate->'field';
    INSERT INTO truss.prop_def(prop_id,type_id,element,declaration_module,name,scalar_type,nullability,cardinality,facets,item,home,
      since_rev,doc_ord,definition_source_kind,definition_rev,definition_doc_ord,definition_document_id)
    VALUES(assigned::int,owner.type_id,candidate->'field'->>'id',original_field_module,candidate->'field'->>'name',candidate->'field'->>'scalarType',
      candidate->'field'->>'nullability',candidate->'field'->>'cardinality',candidate->'field'->'facets',candidate->'field'->'itemType',candidate->>'home',
      revision,owner.doc_ord,'accepted_document',revision,owner.doc_ord,owner.document_id);
    RETURN QUERY SELECT owner.type_id::text,original_field_module,candidate->'field'->>'id',assigned::text;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_stage_new_relationship(revision integer, document_id text, module_id text, relationship jsonb, source_ids integer[], target_ids integer[])
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  op truss.row_home_operation%ROWTYPE;
  doc_ordinal int;
  assigned bigint;
  endpoint int;
  bound jsonb;
  target_key text;
  original_document jsonb;
  original_endpoint jsonb;
  endpoint_ordinal int;
  identity_profile constant text := 'truss-relationship-lineage-bytes/0.1.0';
  identity_bytes bytea;
  matched record;
BEGIN
  SELECT * INTO STRICT op FROM truss.row_home_operation o
    WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.phase<>'application_finalized' FOR UPDATE;
  IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted' OR revision IS NULL
      OR document_id IS NULL OR octet_length(document_id) NOT BETWEEN 1 AND 4096
      OR module_id IS NULL OR octet_length(module_id) NOT BETWEEN 1 AND 4096
      OR relationship IS NULL OR jsonb_typeof(relationship)<>'object'
      OR octet_length(relationship::text)>1048576 THEN
    RAISE EXCEPTION 'original relationship admission required' USING ERRCODE='22023';
  END IF;
  IF NOT relationship ?& ARRAY['id','name','source','target','sourceMultiplicity','targetMultiplicity','targetLifecycle','directed']
      OR EXISTS(SELECT 1 FROM jsonb_object_keys(relationship) k WHERE k NOT IN
        ('id','name','source','target','sourceMultiplicity','targetMultiplicity','targetLifecycle','directed','extensions'))
      OR EXISTS(SELECT 1 FROM jsonb_each(relationship) e WHERE e.key IN ('id','name','targetLifecycle')
        AND (jsonb_typeof(e.value)<>'string' OR octet_length(e.value #>> '{}') NOT BETWEEN 1 AND 4096))
      OR jsonb_typeof(relationship->'directed')<>'boolean'
      OR jsonb_typeof(relationship->'source')<>'array' OR jsonb_typeof(relationship->'target')<>'array' THEN
    RAISE EXCEPTION 'unsupported or invalid original relationship carrier' USING ERRCODE='22023';
  END IF;
  FOREACH bound IN ARRAY ARRAY[relationship->'sourceMultiplicity',relationship->'targetMultiplicity'] LOOP
    IF jsonb_typeof(bound)<>'object' OR NOT bound ?& ARRAY['min','max']
        OR (SELECT count(*) FROM jsonb_object_keys(bound))<>2
        OR jsonb_typeof(bound->'min')<>'number'
        OR jsonb_typeof(bound->'max') NOT IN ('number','string')
        OR NOT (jsonb_typeof(bound->'max')='number' OR bound->>'max'='*')
        OR bound->>'min' !~ '^(0|[1-9][0-9]{0,9})$'
        OR bound->>'max' !~ '^(\*|0|[1-9][0-9]{0,9})$' THEN
      RAISE EXCEPTION 'original relationship multiplicity carrier' USING ERRCODE='22023';
    END IF;
    IF (bound->>'min')::bigint>2147483647 OR
        (bound->>'max'<>'*' AND ((bound->>'max')::bigint>2147483647 OR (bound->>'max')::bigint<(bound->>'min')::bigint)) THEN
      RAISE EXCEPTION 'original relationship multiplicity capacity' USING ERRCODE='22023';
    END IF;
  END LOOP;
  IF source_ids IS NULL OR target_ids IS NULL
      OR cardinality(source_ids) NOT BETWEEN 1 AND 256 OR cardinality(target_ids) NOT BETWEEN 1 AND 256
      OR array_ndims(source_ids)<>1 OR array_ndims(target_ids)<>1
      OR array_lower(source_ids,1)<>1 OR array_lower(target_ids,1)<>1
      OR array_position(source_ids,NULL) IS NOT NULL OR array_position(target_ids,NULL) IS NOT NULL
      OR cardinality(source_ids)<>jsonb_array_length(relationship->'source')
      OR cardinality(target_ids)<>jsonb_array_length(relationship->'target') THEN
    RAISE EXCEPTION 'complete original endpoint correspondence required' USING ERRCODE='22023';
  END IF;
  IF (SELECT count(DISTINCT p) FROM unnest(source_ids) p)<>cardinality(source_ids)
      OR (SELECT count(DISTINCT p) FROM unnest(target_ids) p)<>cardinality(target_ids) THEN
    RAISE EXCEPTION 'duplicate resolved endpoint' USING ERRCODE='22023';
  END IF;
  LOCK TABLE truss.schema_head IN EXCLUSIVE MODE;
  SELECT d.ord INTO STRICT doc_ordinal FROM truss.schema_doc d WHERE d.rev=revision AND d.doc_id=runtime_stage_new_relationship.document_id;
  SELECT d.document::jsonb INTO STRICT original_document FROM truss.schema_doc d
    WHERE d.rev=revision AND d.ord=doc_ordinal;
  IF (SELECT count(*) FROM jsonb_array_elements(original_document->'modules') m
      CROSS JOIN LATERAL jsonb_array_elements(m.value->'relationships') r
      WHERE m.value->>'id'=module_id AND r.value=relationship)<>1 THEN
    RAISE EXCEPTION 'relationship does not match original declaring module source' USING ERRCODE='55000';
  END IF;
  identity_bytes:=truss.runtime_catalog_lineage(revision,'authored',document_id,module_id,relationship->>'id');
  -- This JSON-source profile resolves UMF module/element references inside their
  -- original document. Cross-document resolution requires an explicit later profile.
  FOR endpoint_ordinal IN 1..cardinality(source_ids) LOOP
    original_endpoint:=relationship->'source'->(endpoint_ordinal-1);
    PERFORM 1 FROM truss.type_def t WHERE t.type_id=source_ids[endpoint_ordinal]
      AND t.document_id=runtime_stage_new_relationship.document_id
      AND t.module=original_endpoint->>'module' AND t.element=original_endpoint->>'element';
    IF NOT FOUND THEN RAISE EXCEPTION 'original source endpoint correspondence' USING ERRCODE='55000'; END IF;
    PERFORM 1 FROM truss.key_def k WHERE k.type_id=source_ids[endpoint_ordinal] AND k.retired_rev IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'original source endpoint key required' USING ERRCODE='55000'; END IF;
  END LOOP;
  FOR endpoint_ordinal IN 1..cardinality(target_ids) LOOP
    original_endpoint:=relationship->'target'->(endpoint_ordinal-1);
    PERFORM 1 FROM truss.type_def t WHERE t.type_id=target_ids[endpoint_ordinal]
      AND t.document_id=runtime_stage_new_relationship.document_id
      AND t.module=original_endpoint->>'module' AND t.element=original_endpoint->>'element';
    IF NOT FOUND THEN RAISE EXCEPTION 'original target endpoint correspondence' USING ERRCODE='55000'; END IF;
  END LOOP;
  SELECT * INTO STRICT matched FROM truss.runtime_match_relationship_identity(revision,document_id,module_id,relationship->>'id');
  IF matched.match_state<>'new'
      OR EXISTS(SELECT 1 FROM truss.relationship_lineage l WHERE l.identity_profile='truss-relationship-lineage-bytes/0.1.0' AND l.original_identity_bytes=identity_bytes) THEN
    RAISE EXCEPTION 'existing relationship requires original matching' USING ERRCODE='55000';
  END IF;
  FOREACH endpoint IN ARRAY source_ids || target_ids LOOP
    PERFORM 1 FROM truss.type_def t WHERE t.type_id=endpoint AND t.kind='record' AND NOT t.provisional AND t.retired_rev IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'missing active original endpoint' USING ERRCODE='55000'; END IF;
  END LOOP;
  -- Baseline storage has one target-key column; heterogeneous authored keys refuse.
  IF (SELECT count(DISTINCT coalesce(value->>'key','')) FROM jsonb_array_elements(relationship->'target'))>1 THEN
    RAISE EXCEPTION 'heterogeneous target keys require another admitted storage profile' USING ERRCODE='0A000';
  END IF;
  target_key:=relationship->'target'->0->>'key';
  IF target_key IS NOT NULL THEN
    FOREACH endpoint IN ARRAY target_ids LOOP
      PERFORM 1 FROM truss.key_def k WHERE k.type_id=endpoint AND k.key_id=target_key AND k.retired_rev IS NULL;
      IF NOT FOUND THEN RAISE EXCEPTION 'missing active target key' USING ERRCODE='55000'; END IF;
    END LOOP;
  END IF;
  SELECT greatest(coalesce(max(r.rel_type_id)::bigint,0),0)+1 INTO assigned FROM truss.rel_def r;
  IF assigned>2147483647 THEN RAISE EXCEPTION 'relationship capacity exhausted' USING ERRCODE='54000'; END IF;
  INSERT INTO truss.rel_def(document_id,rel_type_id,module,rel_id,name,source_min,source_max,target_min,target_max,
    lifecycle,directed,target_key,composition,since_rev,doc_ord,definition_source_kind,definition_rev,definition_doc_ord,definition_document_id)
  VALUES(document_id,assigned::int,module_id,relationship->>'id',relationship->>'name',
    (relationship->'sourceMultiplicity'->>'min')::int,nullif(relationship->'sourceMultiplicity'->>'max','*')::int,
    (relationship->'targetMultiplicity'->>'min')::int,nullif(relationship->'targetMultiplicity'->>'max','*')::int,
    relationship->>'targetLifecycle',(relationship->>'directed')::boolean,target_key,false,revision,doc_ordinal,
    'accepted_document',revision,doc_ordinal,document_id);
  INSERT INTO truss.relationship_lineage(rel_type_id,lineage_category,identity_profile,original_identity_bytes)
    VALUES(assigned::int,'authored',identity_profile,identity_bytes);
  INSERT INTO truss.rel_endpoint(rel_type_id,source_type,target_type)
    SELECT assigned::int,s,t FROM unnest(source_ids) s CROSS JOIN unnest(target_ids) t;
  RETURN assigned::text;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_stage_new_types(revision integer, candidates jsonb)
 RETURNS TABLE(document_id text, module_id text, element_id text, type_id text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  actual_xid xid8 := pg_current_xact_id_if_assigned();
  op truss.row_home_operation%ROWTYPE;
  candidate jsonb;
  count_new bigint;
  high_water bigint;
  assigned bigint;
  doc_ordinal int;
  matched record;
BEGIN
  SELECT * INTO STRICT op FROM truss.row_home_operation AS o
    WHERE o.original_writer_xid=actual_xid AND o.phase<>'application_finalized' FOR UPDATE;
  IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted'
      OR revision IS NULL OR candidates IS NULL OR jsonb_typeof(candidates)<>'array'
      OR jsonb_array_length(candidates) NOT BETWEEN 1 AND 4096
      OR octet_length(candidates::text)>1048576 THEN
    RAISE EXCEPTION 'original catalog batch admission required' USING ERRCODE='22023';
  END IF;
  LOCK TABLE truss.schema_head IN EXCLUSIVE MODE;
  PERFORM 1 FROM truss.schema_rev AS r WHERE r.rev=revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'missing original revision' USING ERRCODE='55000'; END IF;
  FOR candidate IN SELECT value FROM jsonb_array_elements(candidates) LOOP
    IF jsonb_typeof(candidate)<>'object' OR NOT candidate ?& ARRAY['documentId','moduleId','elementId']
        OR (SELECT count(*) FROM jsonb_object_keys(candidate))<>3 THEN
      RAISE EXCEPTION 'original type candidate shape' USING ERRCODE='22023';
    END IF;
    IF EXISTS(SELECT 1 FROM jsonb_each(candidate) e WHERE jsonb_typeof(e.value)<>'string' OR octet_length(e.value #>> '{}') NOT BETWEEN 1 AND 65536) THEN
      RAISE EXCEPTION 'original type candidate carrier' USING ERRCODE='22023';
    END IF;
    PERFORM 1 FROM truss.schema_doc d WHERE d.rev=revision AND d.doc_id=candidate->>'documentId';
    IF NOT FOUND THEN RAISE EXCEPTION 'missing original document' USING ERRCODE='55000'; END IF;
    SELECT * INTO STRICT matched FROM truss.runtime_match_record_identity(revision,candidate->>'documentId',candidate->>'moduleId',candidate->>'elementId');
    IF matched.match_state<>'new' THEN
      RAISE EXCEPTION 'retained identity requires full matching/lifecycle admission, not new allocation' USING ERRCODE='55000';
    END IF;
  END LOOP;
  SELECT count(*) INTO count_new FROM (SELECT DISTINCT value->>'documentId',value->>'moduleId',value->>'elementId' FROM jsonb_array_elements(candidates)) q;
  IF count_new<>jsonb_array_length(candidates) THEN RAISE EXCEPTION 'duplicate qualified candidate' USING ERRCODE='22023'; END IF;
  SELECT greatest(coalesce(max(t.type_id)::bigint,0),0) INTO high_water FROM truss.type_def t;
  IF high_water+count_new>2147483647 THEN RAISE EXCEPTION 'catalog type capacity exhausted' USING ERRCODE='54000'; END IF;
  assigned:=high_water;
  FOR candidate IN SELECT value FROM jsonb_array_elements(candidates)
      ORDER BY (value->>'documentId') COLLATE "C",(value->>'moduleId') COLLATE "C",(value->>'elementId') COLLATE "C" LOOP
    assigned:=assigned+1;
    SELECT d.ord INTO STRICT doc_ordinal FROM truss.schema_doc d WHERE d.rev=revision AND d.doc_id=candidate->>'documentId';
    INSERT INTO truss.type_def(document_id,type_id,module,element,kind,provisional,since_rev,doc_ord,
      lineage_profile,lineage_bytes,definition_source_kind,definition_rev,definition_doc_ord,definition_document_id)
    VALUES(candidate->>'documentId',assigned::int,candidate->>'moduleId',candidate->>'elementId','record',false,
      revision,doc_ordinal,'truss-type-lineage/0.1.0',
      truss.runtime_catalog_lineage(revision,'record',candidate->>'documentId',candidate->>'moduleId',candidate->>'elementId'),
      'accepted_document',revision,doc_ordinal,candidate->>'documentId');
    RETURN QUERY SELECT candidate->>'documentId',candidate->>'moduleId',candidate->>'elementId',assigned::text;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_verify_catalog_document(revision integer, document_id text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE source truss.schema_doc%ROWTYPE; source_count bigint;
BEGIN
 SELECT count(*) INTO source_count FROM truss.schema_doc d
  WHERE d.rev=revision AND d.doc_id COLLATE "C"=document_id COLLATE "C";
 IF source_count<>1 THEN
  RAISE EXCEPTION 'unique original document archive required' USING ERRCODE='55000';
 END IF;
 SELECT d.* INTO STRICT source FROM truss.schema_doc d
  WHERE d.rev=revision AND d.doc_id COLLATE "C"=document_id COLLATE "C";
 IF source.document IS NULL OR octet_length(source.document) NOT BETWEEN 1 AND 1048576 THEN
  RAISE EXCEPTION 'bounded original document archive required' USING ERRCODE='55000';
 END IF;
 IF source.content_sha256 IS NULL OR source.content_sha256 COLLATE "C"
   IS DISTINCT FROM encode(sha256(convert_to(source.document,'UTF8')),'hex') COLLATE "C" THEN
  RAISE EXCEPTION 'original document archive digest mismatch' USING ERRCODE='55000';
 END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_verify_new_catalog_prestate(original_revision integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; original jsonb; actual jsonb; profile text; retained_bindings jsonb;
BEGIN
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.phase<>'application_finalized' FOR UPDATE;
 IF op.operation_kind<>'catalog-acceptance' OR op.phase<>'admitted' OR original_revision IS NULL OR original_revision<=0
  OR octet_length(op.original_prestate_bytes)>1048576 THEN RAISE EXCEPTION 'original bounded catalog prestate required' USING ERRCODE='55000'; END IF;
 LOCK TABLE truss.schema_head IN EXCLUSIVE MODE;
 original:=convert_from(op.original_prestate_bytes,'UTF8')::jsonb;
 profile:=original->>'interfaceVersion';
 IF profile NOT IN ('truss-native-catalog-prestate/0.1','truss-native-catalog-prestate/0.2-binding-custody') OR profile IS NULL THEN
  RAISE EXCEPTION 'original prestate format unavailable' USING ERRCODE='0A000';
 END IF;
 IF (profile='truss-native-catalog-prestate/0.1' AND to_regclass('truss.catalog_binding_archive') IS NOT NULL)
  OR (profile='truss-native-catalog-prestate/0.2-binding-custody' AND to_regclass('truss.catalog_binding_archive') IS NULL) THEN
  RAISE EXCEPTION 'original prestate archive profile correspondence required' USING ERRCODE='55000';
 END IF;
 actual:=jsonb_build_object('interfaceVersion',profile,
  'head',(SELECT to_jsonb(h) FROM truss.schema_head h WHERE h.id=1),
  'revisions',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.rev),'[]'::jsonb) FROM truss.schema_rev r WHERE r.rev<>original_revision),
  'documents',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.rev,d.ord),'[]'::jsonb) FROM truss.schema_doc d WHERE d.rev<>original_revision),
  'types',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.type_id),'[]'::jsonb) FROM truss.type_def t WHERE t.since_rev<>original_revision),
  'properties',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.prop_id),'[]'::jsonb) FROM truss.prop_def p WHERE p.since_rev<>original_revision),
  'keys',(SELECT coalesce(jsonb_agg(to_jsonb(k) ORDER BY k.type_id,k.key_num),'[]'::jsonb) FROM truss.key_def k WHERE k.since_rev<>original_revision),
  'keyHistory',(SELECT coalesce(jsonb_agg(to_jsonb(k) ORDER BY to_jsonb(k)::text COLLATE "C"),'[]'::jsonb) FROM truss.key_lifecycle_history k),
  'relationships',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.rel_type_id),'[]'::jsonb) FROM truss.rel_def r WHERE r.since_rev<>original_revision),
  'relationshipLineage',(SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.rel_type_id),'[]'::jsonb) FROM truss.relationship_lineage l JOIN truss.rel_def r ON r.rel_type_id=l.rel_type_id WHERE r.since_rev<>original_revision),
  'endpoints',(SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.rel_type_id,e.source_type,e.target_type),'[]'::jsonb) FROM truss.rel_endpoint e JOIN truss.rel_def r ON r.rel_type_id=e.rel_type_id WHERE r.since_rev<>original_revision),
  'reports',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.rev),'[]'::jsonb) FROM truss.catalog_acceptance_report r));
 IF profile='truss-native-catalog-prestate/0.2-binding-custody' THEN
  EXECUTE 'SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.revision),''[]''::jsonb) FROM truss.catalog_binding_archive a WHERE a.revision<>$1'
   INTO retained_bindings USING original_revision;
  actual:=actual||jsonb_build_object('bindings',retained_bindings);
 END IF;
 IF actual IS DISTINCT FROM original THEN
  RAISE EXCEPTION 'retained catalog differs from original new-only prestate' USING ERRCODE='55000';
 END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_write_catalog_report_and_register_revision_candidate(expected_writer text, expected_ordinal text, expected_generation text, registration_identity text, original_registration bytea, lifecycle_policy bytea, index_policy bytea)
 RETURNS TABLE(writer_xid text, operation_ordinal text, effect_generation text, report_utf8_hex text, revision_payload_utf8_hex text, parent_record_hex text, member_record_hex text, scope text, accepted_report_qualified boolean, feed_qualified boolean)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET bytea_output TO 'hex'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; final_op truss.row_home_operation%ROWTYPE;
 original_configuration truss.operation_configuration%ROWTYPE; final_configuration truss.operation_configuration%ROWTYPE; original_configuration_record bytea;
 context jsonb; profile_bytes bytea; profile jsonb; identity text;
 source_sql jsonb:='{}'::jsonb; source_name text; source_bytes bytea;
 identities text[]; archive_before jsonb; archive_after jsonb;
 report_result record; before_graph record; resources_before jsonb; resources_after jsonb;
 metadata_before bytea; metadata_after bytea; relation_before jsonb; relation_after jsonb;
 catalog_before jsonb:='{}'::jsonb; catalog_after jsonb:='{}'::jsonb;
 name text; populated boolean; rows_json jsonb; graph_scope jsonb; census_before jsonb; census_after jsonb;
 planned_parent truss.feed_tx%ROWTYPE; planned_member truss.feed_member%ROWTYPE;
 returned record; expected_snapshot jsonb; revision int; revision_row truss.schema_rev%ROWTYPE;
 documents jsonb; original_op_record bytea; original_revision_record bytea; original_document_records bytea[]; original_document_record bytea; aggregate_original_bytes bigint; total_chunks int; owner_bytes bytea; manifest_bytes bytea; key_profile bytea;
 payload_profile bytea; clock_bytes bytea; original_write_at timestamptz;
 payload bytea; report bytea; persisted_report bytea;
BEGIN
 PERFORM truss.runtime_require_catalog_observation(expected_writer,expected_ordinal,expected_generation);
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.operation_ordinal::text=expected_ordinal FOR UPDATE;
 IF (SELECT count(*) FROM truss.row_home_operation)<>1 THEN
  RAISE EXCEPTION 'single original fresh catalog operation required' USING ERRCODE='55000'; END IF;
 context:=convert_from(op.original_context_bytes,'UTF8')::jsonb;
 -- Establish complete first-use absence before the report's first effect.
 SELECT * INTO STRICT before_graph FROM truss.runtime_collect_configured_catalog_graph();
 LOCK TABLE truss.installation_archive IN SHARE MODE NOWAIT;
 PERFORM truss.runtime_require_selected_archive_write_fence();
 identity:='packages/python/src/truss/_profiles/catalog-revision-registration-candidate.json';
 IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=context->>'installationId'
  AND a.artifact_role='input' AND a.artifact_identity=identity)<>1 THEN
  RAISE EXCEPTION 'unique original revision registration recipe required' USING ERRCODE='55000'; END IF;
 SELECT a.artifact_bytes INTO STRICT profile_bytes FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=identity
   AND a.artifact_sha256=sha256(a.artifact_bytes)
   AND a.artifact_sha256=decode('a32febdea06ee57405d856038ede3b503430a4f823226e0dfa65b072fae2f725','hex')
   AND a.artifact_identity_sha256=sha256(convert_to(a.artifact_identity,'UTF8')) FOR SHARE NOWAIT;
 profile:=convert_from(profile_bytes,'UTF8')::jsonb;identities:=ARRAY[identity];
 FOREACH source_name IN ARRAY ARRAY['create','reserve','insert'] LOOP
  identity:=profile->'sources'->source_name->>'path';
  IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=context->>'installationId'
   AND a.artifact_role='input' AND a.artifact_identity=identity)<>1 THEN
   RAISE EXCEPTION 'unique original registration statement source required' USING ERRCODE='55000'; END IF;
  SELECT a.artifact_bytes INTO STRICT source_bytes FROM truss.installation_archive a
   WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=identity
    AND a.artifact_sha256=sha256(a.artifact_bytes)
    AND encode(a.artifact_sha256,'hex')=profile->'sources'->source_name->>'sha256'
    AND a.artifact_identity_sha256=sha256(convert_to(a.artifact_identity,'UTF8')) FOR SHARE NOWAIT;
  IF octet_length(source_bytes)>16384 THEN RAISE EXCEPTION 'registration statement capacity' USING ERRCODE='54000'; END IF;
  source_sql:=source_sql||jsonb_build_object(source_name,convert_from(source_bytes,'UTF8'));
  identities:=array_append(identities,identity);
 END LOOP;
 identity:=profile->'payloadProfile'->>'path';
 SELECT a.artifact_bytes INTO STRICT payload_profile FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=identity
   AND a.artifact_sha256=sha256(a.artifact_bytes)
   AND encode(a.artifact_sha256,'hex')=profile->'payloadProfile'->>'sha256';
 identities:=array_append(identities,identity);
 SELECT jsonb_agg(to_jsonb(a) ORDER BY a.archive_row_id) INTO archive_before FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=ANY(identities);
 -- Preserve the admission capsule before the report producer, not a later cut.
 PERFORM truss.runtime_require_operation_configuration_current(expected_writer,expected_ordinal,expected_generation);
 SELECT c.* INTO STRICT original_configuration FROM truss.operation_configuration c
  WHERE c.original_writer_xid=op.original_writer_xid AND c.operation_ordinal=op.operation_ordinal;
 original_configuration_record:=record_send(original_configuration);
 -- The payload is obtained only by this direct native producer call.
 SELECT * INTO STRICT report_result FROM truss.runtime_write_catalog_report_candidate(
  expected_writer,expected_ordinal,expected_generation,registration_identity,original_registration,lifecycle_policy,index_policy);
 IF report_result.writer_xid IS DISTINCT FROM expected_writer OR report_result.operation_ordinal IS DISTINCT FROM expected_ordinal
  OR report_result.effect_generation IS DISTINCT FROM (op.effect_generation+1)::text OR report_result.scope IS DISTINCT FROM 'administrative_rollback_only_report_write'
  OR report_result.report_utf8_hex IS NULL OR report_result.revision_payload_utf8_hex IS NULL
  OR report_result.accepted_report_qualified IS DISTINCT FROM false THEN
  RAISE EXCEPTION 'original candidate report result required' USING ERRCODE='55000'; END IF;
 payload:=decode(report_result.revision_payload_utf8_hex,'hex');report:=decode(report_result.report_utf8_hex,'hex');
 revision:=(convert_from(payload,'UTF8')::jsonb->>'revision')::int;
 SELECT r.report_bytes INTO STRICT persisted_report FROM truss.catalog_acceptance_report r WHERE r.rev=revision;
 IF persisted_report IS DISTINCT FROM report THEN
  RAISE EXCEPTION 'original returned report persisted byte correspondence required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT before_graph FROM truss.runtime_collect_configured_catalog_graph();
 graph_scope:=before_graph.empty_scope::jsonb->'businessRelations';
 metadata_before:=decode(before_graph.empty_scope::jsonb->>'metadataUtf8Hex','hex');
 resources_before:=truss.runtime_select_catalog_report_resources(expected_writer,expected_ordinal,report_result.effect_generation,
  (SELECT encode(c.admission_profile_bytes,'hex') FROM truss.operation_configuration c WHERE c.original_writer_xid=op.original_writer_xid AND c.operation_ordinal=op.operation_ordinal));
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o WHERE o.original_writer_xid=pg_current_xact_id_if_assigned();
 SELECT jsonb_agg(to_jsonb(c) ORDER BY c.oid) INTO relation_before FROM pg_class c
  JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='truss';
 SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.inhrelid,i.inhseqno),'[]'::jsonb) INTO census_before FROM pg_inherits i
  WHERE i.inhparent IN (SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='truss')
   OR i.inhrelid IN (SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='truss');
 FOREACH name IN ARRAY ARRAY['schema_head','schema_rev','schema_doc','type_def','prop_def','key_def','rel_def','relationship_lineage','rel_endpoint','catalog_acceptance_report'] LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(encode(record_send(t),''hex'') ORDER BY encode(record_send(t),''hex'') COLLATE "C"),''[]''::jsonb) FROM truss.%I t',name) INTO rows_json;
  catalog_before:=jsonb_set(catalog_before,ARRAY[name],rows_json);
 END LOOP;
 revision:=(convert_from(payload,'UTF8')::jsonb->>'revision')::int;
 SELECT r.* INTO STRICT revision_row FROM truss.schema_rev r WHERE r.rev=revision;
 -- Capture required originals once; aggregate accounting precedes any hex expansion.
 original_op_record:=record_send(op);original_revision_record:=record_send(revision_row);
 SELECT array_agg(record_send(d) ORDER BY d.ord) INTO original_document_records FROM truss.schema_doc d WHERE d.rev=revision;
 IF original_op_record IS NULL OR op.original_context_bytes IS NULL OR original_revision_record IS NULL
  OR original_document_records IS NULL OR cardinality(original_document_records) NOT BETWEEN 1 AND 512 THEN
  RAISE EXCEPTION 'complete original owner custody inventory required' USING ERRCODE='55000'; END IF;
 aggregate_original_bytes:=octet_length(original_configuration_record)::bigint+octet_length(original_op_record)::bigint+octet_length(op.original_context_bytes)+octet_length(original_revision_record);
 total_chunks:=((octet_length(original_configuration_record)+32767)/32768)+((octet_length(original_op_record)+32767)/32768)+((octet_length(op.original_context_bytes)+32767)/32768)+((octet_length(original_revision_record)+32767)/32768);
 FOREACH original_document_record IN ARRAY original_document_records LOOP
  IF original_document_record IS NULL THEN RAISE EXCEPTION 'original document byte custody required' USING ERRCODE='55000'; END IF;
  aggregate_original_bytes:=aggregate_original_bytes+octet_length(original_document_record);
  total_chunks:=total_chunks+((octet_length(original_document_record)+32767)/32768);
 END LOOP;
 IF aggregate_original_bytes>786432 OR total_chunks>1024 THEN
  RAISE EXCEPTION 'aggregate original registration owner capacity' USING ERRCODE='54000'; END IF;
 documents:='[]'::jsonb;
 FOREACH original_document_record IN ARRAY original_document_records LOOP
  documents:=documents||jsonb_build_array(truss.runtime_registration_original_hex_chunks(original_document_record));
 END LOOP;
 owner_bytes:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'scope','administrative_single_original_operation_fresh_catalog_rollback_only',
  'originalConfigurationRecordHexChunks',truss.runtime_registration_original_hex_chunks(original_configuration_record),
  'originalOperationRecordHexChunks',truss.runtime_registration_original_hex_chunks(original_op_record),
  'originalContextHexChunks',truss.runtime_registration_original_hex_chunks(op.original_context_bytes),
  'originalRevisionRecordHexChunks',truss.runtime_registration_original_hex_chunks(original_revision_record),
  'originalDocumentRecordHexChunks',documents)));
 manifest_bytes:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(profile->'manifestProfile'));
 key_profile:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(profile->'keyProfile'));
 planned_parent.source_epoch:=context->>'sourceEpoch';planned_parent.feed_profile:=profile->>'identity';
 planned_parent.original_writer_xid:=op.original_writer_xid;planned_parent.registration_counter:=0;
 planned_parent.prerequisite_registration_counter:=0;planned_parent.configuration_registration_counter:=0;
 planned_parent.membership_generation:=0;planned_parent.original_context_bytes:=op.original_context_bytes;
 planned_parent.manifest_profile_bytes:=manifest_bytes;
 EXECUTE source_sql->>'create' INTO STRICT returned USING planned_parent.source_epoch,planned_parent.feed_profile,op.original_context_bytes,manifest_bytes;
 expected_snapshot:=jsonb_build_object('source_epoch',planned_parent.source_epoch,'feed_profile',planned_parent.feed_profile,
  'original_writer_xid',op.original_writer_xid::text,'registration_counter','0','prerequisite_registration_counter','0',
  'configuration_registration_counter','0','membership_generation','0','finalized_generation',NULL,
  'original_context_bytes_hex',encode(op.original_context_bytes,'hex'),'manifest_profile_bytes_hex',encode(manifest_bytes,'hex'),
  'manifest_bytes_hex',NULL,'manifest_sha256_hex',NULL);
 IF to_jsonb(returned) IS DISTINCT FROM expected_snapshot
  OR (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(planned_parent)) THEN
  RAISE EXCEPTION 'original pending parent insert readback required' USING ERRCODE='55000'; END IF;
 planned_parent.registration_counter:=1;planned_parent.membership_generation:=1;
 EXECUTE source_sql->>'reserve' INTO STRICT returned USING planned_parent.source_epoch,planned_parent.feed_profile,0::bigint,0::bigint,op.original_context_bytes,manifest_bytes;
 expected_snapshot:=jsonb_set(jsonb_set(expected_snapshot,'{registration_counter}','"1"'),'{membership_generation}','"1"');
 IF to_jsonb(returned) IS DISTINCT FROM expected_snapshot
  OR (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(planned_parent)) THEN
  RAISE EXCEPTION 'original parent reservation readback required' USING ERRCODE='55000'; END IF;
 planned_member.source_epoch:=planned_parent.source_epoch;planned_member.feed_profile:=planned_parent.feed_profile;
 planned_member.original_writer_xid:=op.original_writer_xid;planned_member.registration_address:=1;
 planned_member.fact_kind:='revision';planned_member.original_fact_key_bytes:=truss.runtime_canonical_tree_bytes(
  truss.runtime_catalog_report_native_tree(jsonb_build_object('kind','revision','revision',revision::text)));
 planned_member.original_fact_key_profile_bytes:=key_profile;planned_member.original_payload_bytes:=payload;
 planned_member.original_payload_profile_bytes:=payload_profile;planned_member.original_payload_sha256:=sha256(payload);
 planned_member.original_owner_context_bytes:=owner_bytes;
 -- All source interpretation precedes the one original insertion clock capture.
 original_write_at:=clock_timestamp();
 IF NOT isfinite(original_write_at) OR extract(year FROM original_write_at AT TIME ZONE 'UTC') NOT BETWEEN 1 AND 9999 THEN
  RAISE EXCEPTION 'finite native member write clock required' USING ERRCODE='55000'; END IF;
 clock_bytes:=truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'profile',profile->'clockProfile','originalWriteAt',to_char(original_write_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))));
 planned_member.original_write_at:=original_write_at;planned_member.original_fact_clock_bytes:=clock_bytes;
 EXECUTE source_sql->>'insert' INTO STRICT returned USING planned_parent.source_epoch,planned_parent.feed_profile,1::bigint,1::bigint,
  'revision',planned_member.original_fact_key_bytes,key_profile,payload,payload_profile,sha256(payload),owner_bytes,
  original_write_at,clock_bytes,op.original_context_bytes,manifest_bytes;
 expected_snapshot:=jsonb_build_object('source_epoch',planned_member.source_epoch,'feed_profile',planned_member.feed_profile,
  'original_writer_xid',op.original_writer_xid::text,'registration_address','1','fact_kind','revision',
  'original_fact_key_bytes_hex',encode(planned_member.original_fact_key_bytes,'hex'),'original_fact_key_profile_bytes_hex',encode(key_profile,'hex'),
  'original_payload_bytes_hex',encode(payload,'hex'),'original_payload_profile_bytes_hex',encode(payload_profile,'hex'),
  'original_payload_sha256_hex',encode(sha256(payload),'hex'),'original_owner_context_bytes_hex',encode(owner_bytes,'hex'),
  'original_write_at',original_write_at::text,'original_fact_clock_bytes_hex',encode(clock_bytes,'hex'),'delivery_ordinal',NULL);
 IF to_jsonb(returned) IS DISTINCT FROM expected_snapshot THEN
  RAISE EXCEPTION 'original revision member returned snapshot required' USING ERRCODE='55000'; END IF;
 -- Independent final observations, preserving all original non-feed cuts.
 resources_after:=truss.runtime_select_catalog_report_resources(expected_writer,expected_ordinal,report_result.effect_generation,
  (SELECT encode(c.admission_profile_bytes,'hex') FROM truss.operation_configuration c WHERE c.original_writer_xid=op.original_writer_xid AND c.operation_ordinal=op.operation_ordinal));
 metadata_after:=truss.runtime_capture_catalog_metadata_cut(expected_writer,expected_ordinal,report_result.effect_generation);
 PERFORM truss.runtime_require_selected_archive_write_fence();
 SELECT jsonb_agg(to_jsonb(a) ORDER BY a.archive_row_id) INTO archive_after FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=ANY(identities);
 SELECT jsonb_agg(to_jsonb(c) ORDER BY c.oid) INTO relation_after FROM pg_class c
  JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='truss';
 SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.inhrelid,i.inhseqno),'[]'::jsonb) INTO census_after FROM pg_inherits i
  WHERE i.inhparent IN (SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='truss')
   OR i.inhrelid IN (SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='truss');
 FOR name IN SELECT jsonb_array_elements_text(graph_scope) LOOP
  IF name IN ('feed_tx','feed_member') THEN CONTINUE; END IF;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM truss.%I)',name) INTO populated;
  IF populated THEN RAISE EXCEPTION 'original non-feed graph must remain empty' USING ERRCODE='55000'; END IF;
 END LOOP;
 FOREACH name IN ARRAY ARRAY['schema_head','schema_rev','schema_doc','type_def','prop_def','key_def','rel_def','relationship_lineage','rel_endpoint','catalog_acceptance_report'] LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(encode(record_send(t),''hex'') ORDER BY encode(record_send(t),''hex'') COLLATE "C"),''[]''::jsonb) FROM truss.%I t',name) INTO rows_json;
  catalog_after:=jsonb_set(catalog_after,ARRAY[name],rows_json);
 END LOOP;
 SELECT o.* INTO STRICT final_op FROM truss.row_home_operation o WHERE o.original_writer_xid=pg_current_xact_id_if_assigned();
 SELECT c.* INTO STRICT final_configuration FROM truss.operation_configuration c
  WHERE c.original_writer_xid=op.original_writer_xid AND c.operation_ordinal=op.operation_ordinal;
 IF record_send(final_configuration) IS DISTINCT FROM original_configuration_record THEN
  RAISE EXCEPTION 'complete original pre-report configuration custody required' USING ERRCODE='55000'; END IF;
 IF resources_after IS DISTINCT FROM resources_before OR metadata_after IS DISTINCT FROM metadata_before
  OR archive_after IS DISTINCT FROM archive_before OR relation_after IS DISTINCT FROM relation_before
  OR census_after IS DISTINCT FROM census_before OR catalog_after IS DISTINCT FROM catalog_before
  OR record_send(final_op) IS DISTINCT FROM record_send(op)
  OR (SELECT count(*) FROM truss.row_home_operation)<>1
  OR (SELECT count(*) FROM truss.feed_tx)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_tx t WHERE record_send(t)=record_send(planned_parent))
  OR (SELECT count(*) FROM truss.feed_member)<>1 OR NOT EXISTS(SELECT 1 FROM truss.feed_member m WHERE record_send(m)=record_send(planned_member))
  OR EXISTS(SELECT 1 FROM truss.feed_prerequisite) OR EXISTS(SELECT 1 FROM truss.feed_configuration_prerequisite) THEN
  RAISE EXCEPTION 'complete original pending revision registration delta required' USING ERRCODE='55000'; END IF;
 RETURN QUERY SELECT expected_writer,expected_ordinal,report_result.effect_generation,report_result.report_utf8_hex,
  report_result.revision_payload_utf8_hex,encode(record_send(planned_parent),'hex'),encode(record_send(planned_member),'hex'),
  'administrative_single_original_operation_fresh_catalog_rollback_only'::text,false,false;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_write_catalog_report_candidate(expected_writer text, expected_ordinal text, expected_generation text, registration_identity text, original_registration bytea, lifecycle_policy bytea, index_policy bytea)
 RETURNS TABLE(writer_xid text, operation_ordinal text, effect_generation text, report_utf8_hex text, scope text, accepted_report_qualified boolean, revision_payload_utf8_hex text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET bytea_output TO 'hex'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; current_op truss.row_home_operation%ROWTYPE;
 revision_row truss.schema_rev%ROWTYPE; revision_tree jsonb; revision_payload bytea; accepted_at_text text; report_identity text;
 context jsonb; input jsonb; registration jsonb; source record; before_graph record; after_graph record;
 revision int; documents jsonb; counts jsonb; lifecycle jsonb; indexes jsonb;
 origin jsonb; execution jsonb; execution_tree jsonb; origin_envelope jsonb; journal_envelope jsonb; fields jsonb; tree jsonb; members jsonb; assertion_tree jsonb;
 assertion_digest text; assertions jsonb; member jsonb; pin_name text; pin jsonb;
 original_report bytea; returned_report bytea; recipe_bytes bytea; recipe jsonb; artifact bytea; selected_artifact_identity text; profile_rows jsonb; final_profile_rows jsonb; identities text[]; catalog_before jsonb; catalog_after jsonb; table_name text; table_rows jsonb; schema_registry jsonb:='{}'::jsonb; schema_name text; schema_value jsonb; report_tree jsonb; before_resources jsonb; after_resources jsonb; original_registration_id bigint; count_rows bigint;
BEGIN
 IF expected_writer IS NULL OR expected_ordinal IS NULL OR expected_generation IS NULL
  OR registration_identity IS NULL OR octet_length(registration_identity) NOT BETWEEN 1 AND 4096
  OR original_registration IS NULL OR octet_length(original_registration) NOT BETWEEN 1 AND 65536 THEN
  RAISE EXCEPTION 'bounded original candidate registration required' USING ERRCODE='22023'; END IF;
 PERFORM truss.runtime_require_catalog_observation(expected_writer,expected_ordinal,expected_generation);
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.operation_ordinal::text=expected_ordinal
   AND o.phase='admitted' AND o.operation_kind='catalog-acceptance' FOR UPDATE;
 context:=convert_from(op.original_context_bytes,'UTF8')::jsonb;
 IF context->>'interfaceVersion' IS DISTINCT FROM 'truss-native-operation-context/0.4' THEN
  RAISE EXCEPTION 'original configured candidate context required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT before_graph FROM truss.runtime_collect_configured_catalog_graph();
 -- This registration is explicitly candidate-only. It is NOT one of the four
 -- original production authority sources, even when all profile pins match.
 PERFORM truss.runtime_require_unique_source_json(convert_from(original_registration,'UTF8')::json);
 registration:=convert_from(original_registration,'UTF8')::jsonb;
 IF jsonb_typeof(registration) IS DISTINCT FROM 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(registration))<>8
  OR NOT registration ?& ARRAY['interfaceVersion','scope','layoutProfile','reportProfile',
      'captureProfile','originMappingProfile','enforcementProfile','composition']
  OR registration->>'interfaceVersion' IS DISTINCT FROM 'truss-catalog-report-candidate-registration/0.1'
  OR registration->>'scope' IS DISTINCT FROM 'administrative_rollback_only_report_write' THEN
  RAISE EXCEPTION 'explicit administrative candidate registration required' USING ERRCODE='55000'; END IF;
 FOREACH pin_name IN ARRAY ARRAY['layoutProfile','reportProfile','captureProfile','originMappingProfile','enforcementProfile'] LOOP
  pin:=registration->pin_name;
  IF jsonb_typeof(pin) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(pin))<>3
   OR NOT pin ?& ARRAY['identity','version','sha256']
   OR EXISTS(SELECT 1 FROM jsonb_each(pin) e WHERE jsonb_typeof(e.value) IS DISTINCT FROM 'string' OR octet_length(e.value #>> '{}') NOT BETWEEN 1 AND 4096)
   OR pin->>'sha256' !~ '^[0-9a-f]{64}$' THEN
   RAISE EXCEPTION 'complete candidate profile pins required' USING ERRCODE='55000'; END IF;
 END LOOP;
 IF registration->'enforcementProfile' IS DISTINCT FROM jsonb_build_object(
  'identity','truss-catalog-enforcement-projection','version','0.1.0',
  'sha256','678e52ea00fa984b19162441a33b33ab3d822b58f8ae2c69195dc1d5d658c4b1') THEN
  RAISE EXCEPTION 'selected candidate enforcement projection required' USING ERRCODE='55000'; END IF;
 SELECT count(*) INTO count_rows FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input'
   AND convert_to(a.artifact_identity,'UTF8')=convert_to(registration_identity,'UTF8');
 IF count_rows<>1 THEN RAISE EXCEPTION 'unique original candidate registration archive required' USING ERRCODE='55000'; END IF;
 SELECT a.archive_row_id INTO STRICT original_registration_id FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input'
   AND convert_to(a.artifact_identity,'UTF8')=convert_to(registration_identity,'UTF8')
   AND a.artifact_bytes=original_registration AND a.artifact_sha256=sha256(original_registration)
   AND a.artifact_identity_sha256=sha256(convert_to(registration_identity,'UTF8')) FOR SHARE NOWAIT;
 IF registration->'composition' IS DISTINCT FROM jsonb_build_object('identity','packages/python/src/truss/_profiles/catalog-report-composition-candidate.json','sha256','3f5f83a5b827451bdf29a018eca85b0bdac3811a37ec8efcbadafc1a79fd10fe') THEN
  RAISE EXCEPTION 'recognized full candidate composition recipe required' USING ERRCODE='55000'; END IF;
 identities:=ARRAY[registration_identity,'packages/python/src/truss/_profiles/catalog-report-composition-candidate.json'];
 IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=context->>'installationId'
  AND a.artifact_role='input' AND a.artifact_identity='packages/python/src/truss/_profiles/catalog-report-composition-candidate.json')<>1 THEN
  RAISE EXCEPTION 'unique original candidate recipe archive required' USING ERRCODE='55000'; END IF;
 SELECT a.artifact_bytes INTO STRICT recipe_bytes FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity='packages/python/src/truss/_profiles/catalog-report-composition-candidate.json'
   AND a.artifact_sha256=sha256(a.artifact_bytes) AND a.artifact_sha256=decode('3f5f83a5b827451bdf29a018eca85b0bdac3811a37ec8efcbadafc1a79fd10fe','hex')
   AND a.artifact_identity_sha256=sha256(convert_to(a.artifact_identity,'UTF8')) FOR SHARE NOWAIT;
 recipe:=convert_from(recipe_bytes,'UTF8')::jsonb;
 FOREACH pin_name IN ARRAY ARRAY['reportProfile','captureProfile','originMappingProfile','enforcementProfile'] LOOP
  selected_artifact_identity:=recipe->'profileArtifacts'->pin_name->>'path';
  identities:=array_append(identities,selected_artifact_identity);
  IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=context->>'installationId'
    AND a.artifact_role='input' AND convert_to(a.artifact_identity,'UTF8')=convert_to(selected_artifact_identity,'UTF8'))<>1 THEN
   RAISE EXCEPTION 'unique full candidate profile archive required' USING ERRCODE='55000'; END IF;
  SELECT a.artifact_bytes INTO STRICT artifact FROM truss.installation_archive a
   WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input'
    AND convert_to(a.artifact_identity,'UTF8')=convert_to(selected_artifact_identity,'UTF8')
    AND a.artifact_sha256=sha256(a.artifact_bytes)
    AND a.artifact_sha256=decode(recipe->'profileArtifacts'->pin_name->>'sha256','hex')
    AND a.artifact_identity_sha256=sha256(convert_to(selected_artifact_identity,'UTF8')) FOR SHARE NOWAIT;
  pin:=convert_from(artifact,'UTF8')::jsonb;
  IF registration->pin_name IS DISTINCT FROM jsonb_build_object('identity',pin->>'identity','version',pin->>'version',
     'sha256',encode(sha256(artifact),'hex'))
   OR (pin_name='captureProfile' AND encode(artifact,'hex') IS DISTINCT FROM context->>'assertedOriginCaptureProfileHex') THEN
   RAISE EXCEPTION 'original full candidate profile correspondence required' USING ERRCODE='55000'; END IF;
 END LOOP;
 before_resources:=truss.runtime_select_catalog_report_resources(expected_writer,expected_ordinal,expected_generation,
  (SELECT encode(c.admission_profile_bytes,'hex') FROM truss.operation_configuration c
   WHERE c.original_writer_xid=op.original_writer_xid AND c.operation_ordinal=op.operation_ordinal));
 FOREACH schema_name IN ARRAY ARRAY['exact-value-v0.1.schema.json','history-record-v0.1.schema.json','history-event-v0.1.schema.json',
  'acceptance-input-v0.1.schema.json','acceptance-rejection-v0.1.schema.json','enforcement-report-v0.1.schema.json',
  'acceptance-report-v0.1.schema.json','history-retain-payload-v0.1.proposal.schema.json','history-event-v0.2.proposal.schema.json',
  'acceptance-report-v0.3.proposal.schema.json'] LOOP
  selected_artifact_identity:='packages/python/src/truss/_report_schemas/'||schema_name;
  SELECT convert_from(a.artifact_bytes,'UTF8')::jsonb INTO STRICT schema_value FROM truss.installation_archive a
   WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=selected_artifact_identity;
  IF schema_registry ? (schema_value->>'$id') THEN RAISE EXCEPTION 'unique selected report schema identity required' USING ERRCODE='55000'; END IF;
  schema_registry:=schema_registry||jsonb_build_object(schema_value->>'$id',schema_value);
  identities:=array_append(identities,selected_artifact_identity);
 END LOOP;
 -- The revision composition is independently selected source semantics, not authority.
 selected_artifact_identity:='packages/python/src/truss/_profiles/catalog-revision-composition-candidate.json';
 IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=context->>'installationId'
  AND a.artifact_role='input' AND a.artifact_identity=selected_artifact_identity)<>1 THEN
  RAISE EXCEPTION 'unique original revision composition archive required' USING ERRCODE='55000'; END IF;
 SELECT a.artifact_bytes INTO STRICT artifact FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=selected_artifact_identity
   AND a.artifact_sha256=sha256(a.artifact_bytes) AND a.artifact_sha256=decode('6e22d1e2393935f8d15fcade4ca5ac22a6f81b3a0ff47836d24741068d215e57','hex')
   AND a.artifact_identity_sha256=sha256(convert_to(a.artifact_identity,'UTF8')) FOR SHARE NOWAIT;
 identities:=array_append(identities,selected_artifact_identity);
 SELECT jsonb_agg(to_jsonb(a) ORDER BY a.archive_row_id) INTO profile_rows FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=ANY(identities);
 catalog_before:='{}'::jsonb;
 FOREACH table_name IN ARRAY ARRAY['schema_head','schema_rev','schema_doc','type_def','prop_def','key_def','rel_def','relationship_lineage','rel_endpoint'] LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C"),''[]''::jsonb) FROM truss.%I t',table_name) INTO table_rows;
  catalog_before:=jsonb_set(catalog_before,ARRAY[table_name],table_rows);
 END LOOP;
 IF octet_length(catalog_before::text)>4194304 THEN RAISE EXCEPTION 'candidate catalog comparison capacity' USING ERRCODE='54000'; END IF;
 PERFORM truss.runtime_require_catalog_input(op.original_input_bytes);
 input:=convert_from(op.original_input_bytes,'UTF8')::jsonb;
 IF registration->'layoutProfile' IS DISTINCT FROM input->'layoutProfile' THEN
  RAISE EXCEPTION 'original input layout candidate correspondence required' USING ERRCODE='55000'; END IF;
 IF (SELECT count(*) FROM truss.schema_rev WHERE rev>0)<>1
  OR NOT EXISTS(SELECT 1 FROM truss.schema_head WHERE id=1 AND rev=0)
  OR EXISTS(SELECT 1 FROM truss.catalog_acceptance_report) THEN
  RAISE EXCEPTION 'unpublished first revision candidate required' USING ERRCODE='55000'; END IF;
 SELECT rev INTO STRICT revision FROM truss.schema_rev WHERE rev>0;
 SELECT * INTO STRICT source FROM truss.runtime_collect_catalog_source_candidate(
  op.admitted_candidate_bytes,decode(convert_from(op.admitted_candidate_bytes,'UTF8')::jsonb->>'declarationsUtf8Hex','hex'));
 PERFORM * FROM truss.runtime_collect_new_catalog_inventory(revision);
 SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.ord::int),'[]'::jsonb) INTO documents
  FROM truss.runtime_collect_report_documents(revision) d;
 SELECT to_jsonb(c) INTO STRICT counts FROM truss.runtime_collect_new_catalog_counts(revision) c;
 lifecycle:=truss.runtime_collect_fresh_catalog_lifecycle(expected_writer,expected_ordinal,expected_generation,revision,lifecycle_policy);
 indexes:=truss.runtime_collect_absent_binding_index_declarations(expected_writer,expected_ordinal,expected_generation,revision,index_policy);
 origin:=truss.runtime_catalog_report_original_tree(decode(context->>'assertedOriginUtf8Hex','hex'));
 execution:=jsonb_build_object('installationId',context->>'installationId','sourceEpoch',context->>'sourceEpoch',
  'origin',jsonb_build_object('databaseRole',context->>'actingUser'),
  'journalOrigin',jsonb_build_object('databaseRole',context->>'actingUser'),
  'originMappingProfile',registration->'originMappingProfile','captureProfile',registration->'captureProfile',
  'contextEvidence',jsonb_build_object('identity','truss.original-native-operation-context4/'||expected_writer||'/'||expected_ordinal,
   'bytesBase64',replace(encode(op.original_context_bytes,'base64'),chr(10),''),
   'sha256',encode(sha256(op.original_context_bytes),'hex')));
 execution_tree:=truss.runtime_catalog_report_native_tree(execution);
 origin_envelope:=truss.runtime_catalog_report_native_tree(jsonb_build_object('databaseRole',context->>'actingUser'));
 journal_envelope:=jsonb_set(origin_envelope,'{members}',origin_envelope->'members'||jsonb_build_array(jsonb_build_object(
  'keyUtf8Hex','6173736572746564','node',truss.runtime_catalog_report_map_origin_tree(origin))));
 origin_envelope:=jsonb_set(origin_envelope,'{members}',origin_envelope->'members'||jsonb_build_array(jsonb_build_object(
  'keyUtf8Hex','6173736572746564','node',origin)));
 SELECT jsonb_agg(CASE m->>'keyUtf8Hex' WHEN '6f726967696e' THEN jsonb_set(m,'{node}',origin_envelope)
  WHEN '6a6f75726e616c4f726967696e' THEN jsonb_set(m,'{node}',journal_envelope) ELSE m END)
  INTO members FROM jsonb_array_elements(execution_tree->'members') m;
 execution_tree:=jsonb_set(execution_tree,'{members}',members);
 fields:=jsonb_build_object('interfaceVersion','truss-acceptance-report/0.3.0-proposal',
  'reportProfile',registration->'reportProfile','rev',revision::text,
  'acceptedInput',input,'documents',documents,'counts',jsonb_build_object(
   'typesAdded',counts->'types_added','propertiesAdded',counts->'properties_added','keysAdded',counts->'keys_added',
   'relationshipsAdded',counts->'relationships_added','endpointsAdded',counts->'endpoints_added','elementsRetired',counts->'elements_retired'),
  'provisional','[]'::jsonb,'rebinds','[]'::jsonb,'pending_indexes',indexes->'declaredJobs',
  'lifecycleProfile',lifecycle->'lifecycleProfile','reactivations',lifecycle->'reactivations');
 tree:=truss.runtime_catalog_report_native_tree(fields); members:=tree->'members'||jsonb_build_array(jsonb_build_object('keyUtf8Hex','6f726967696e616c457865637574696f6e','node',execution_tree));
 FOR member IN SELECT value FROM jsonb_array_elements(source.host_sources->'members') LOOP
  IF member->>'keyUtf8Hex'=encode(convert_to('assertionEntries','UTF8'),'hex') THEN assertion_tree:=member->'node';
  ELSE members:=members||jsonb_build_array(member); END IF;
 END LOOP;
 IF assertion_tree IS NULL OR assertion_tree->>'kind' IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'original complete candidate assertion inventory required' USING ERRCODE='55000'; END IF;
 FOR member IN SELECT value FROM jsonb_array_elements(assertion_tree->'items') LOOP
  IF member->>'kind' IS DISTINCT FROM 'object' OR jsonb_typeof(member->'members') IS DISTINCT FROM 'array'
   OR jsonb_array_length(member->'members')<>6
   OR (SELECT count(*) FROM jsonb_array_elements(member->'members') m WHERE decode(m->>'keyUtf8Hex','hex')
    IN (convert_to('assertion','UTF8'),convert_to('source','UTF8'),convert_to('ruleName','UTF8'),convert_to('ruleNameOrigin','UTF8'),convert_to('enforcement','UTF8'),convert_to('reason','UTF8')))<>6
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(member->'members') m WHERE m->>'keyUtf8Hex'=encode(convert_to('enforcement','UTF8'),'hex')
    AND m->'node'=jsonb_build_object('kind','string','utf8Hex',encode(convert_to('none','UTF8'),'hex')))
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(member->'members') m WHERE m->>'keyUtf8Hex'=encode(convert_to('reason','UTF8'),'hex')
    AND m->'node'=jsonb_build_object('kind','string','utf8Hex',encode(convert_to('unqualified','UTF8'),'hex'))) THEN
   RAISE EXCEPTION 'selected six-field none unqualified assertion projection required' USING ERRCODE='55000'; END IF;
 END LOOP;
 assertion_digest:=encode(sha256(convert_to('truss-canonical/0.1.0'||chr(10)||'truss-catalog-assertion-inventory/0.1.0'||chr(10),'UTF8')
   ||truss.runtime_canonical_tree_bytes(assertion_tree)),'hex');
 assertions:=truss.runtime_catalog_report_native_tree(jsonb_build_object('interfaceVersion','truss-enforcement-report/0.1.0',
  'catalogRevision',revision::text,'reportProfile',registration->'enforcementProfile','layoutProfile',input->'layoutProfile',
  'scope',jsonb_build_object('kind','complete'),'assertionInventorySha256',assertion_digest));
 assertions:=jsonb_set(assertions,'{members}',assertions->'members'||jsonb_build_array(jsonb_build_object(
  'keyUtf8Hex',encode(convert_to('entries','UTF8'),'hex'),'node',assertion_tree)));
 members:=members||jsonb_build_array(jsonb_build_object('keyUtf8Hex',encode(convert_to('assertions','UTF8'),'hex'),'node',assertions));
 IF jsonb_array_length(members)<>19 THEN RAISE EXCEPTION 'complete nineteen-field candidate report required' USING ERRCODE='55000'; END IF;
 report_tree:=jsonb_build_object('kind','object','members',members);
 original_report:=truss.runtime_canonical_tree_bytes(report_tree);
 IF NOT truss.runtime_catalog_report_shape_matches(report_tree,schema_registry->'urn:truss:proposal:acceptance-report:0.3.0',
  schema_registry,'urn:truss:proposal:acceptance-report:0.3.0') THEN
  RAISE EXCEPTION 'complete selected candidate report shape required' USING ERRCODE='22023'; END IF;
 -- Only an administrative algorithm fixture calls this. No public assembly
 -- selection, accepted result, head transition or commit seal is issued here.
 INSERT INTO truss.catalog_acceptance_report(rev,report_bytes) VALUES(revision,original_report)
  RETURNING report_bytes INTO STRICT returned_report;
 IF returned_report IS DISTINCT FROM original_report OR NOT EXISTS(
  SELECT 1 FROM truss.catalog_acceptance_report r WHERE r.rev=revision AND r.report_bytes=original_report)
  OR (SELECT count(*) FROM truss.catalog_acceptance_report)<>1 THEN
  RAISE EXCEPTION 'original report insert and independent byte readback required' USING ERRCODE='55000'; END IF;
 -- Build the revision wire from the same retained originals, never a later
 -- caller-supplied report or a fresh acceptance clock.
 SELECT r.* INTO STRICT revision_row FROM truss.schema_rev r WHERE r.rev=revision;
 IF truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(revision_row.origin))
  IS DISTINCT FROM truss.runtime_canonical_tree_bytes(origin) THEN
  RAISE EXCEPTION 'original revision parent origin correspondence required' USING ERRCODE='55000'; END IF;
 IF NOT isfinite(revision_row.accepted_at)
  OR extract(year FROM revision_row.accepted_at AT TIME ZONE 'UTC') NOT BETWEEN 1 AND 9999 THEN
  RAISE EXCEPTION 'finite selected revision acceptance timestamp required' USING ERRCODE='22023'; END IF;
 accepted_at_text:=to_char(revision_row.accepted_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
 report_identity:='truss.candidate.catalog-report/'||encode(convert_to(context->>'installationId','UTF8'),'hex')
  ||'/'||encode(convert_to(context->>'sourceEpoch','UTF8'),'hex')||'/'||revision::text;
 IF ((octet_length(original_report)::bigint+2)/3)*4>65536 THEN
  RAISE EXCEPTION 'revision report artifact scalar capacity' USING ERRCODE='54000'; END IF;
 IF octet_length(original_report)>4194304 OR octet_length(op.original_input_bytes)>1048576
  OR ((octet_length(original_report)::bigint+2)/3)*4+octet_length(op.original_input_bytes)>4194304 THEN
  RAISE EXCEPTION 'revision wire expansion capacity' USING ERRCODE='54000'; END IF;
 revision_tree:=truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'interfaceVersion','truss-feed-revision/0.1.0','revision',revision::text,'acceptedAt',accepted_at_text,
  'input',input,'report',jsonb_build_object('identity',report_identity,
   'bytesBase64',replace(encode(original_report,'base64'),chr(10),''),
   'sha256',encode(sha256(original_report),'hex'))));
 revision_tree:=jsonb_set(revision_tree,'{members}',revision_tree->'members'||jsonb_build_array(
  jsonb_build_object('keyUtf8Hex','6f726967696e','node',journal_envelope)));
 IF octet_length(revision_tree::text)>4194304 THEN
  RAISE EXCEPTION 'revision tagged tree capacity' USING ERRCODE='54000'; END IF;
 revision_payload:=truss.runtime_canonical_tree_bytes(revision_tree);
 IF octet_length(revision_payload)>4194304 THEN
  RAISE EXCEPTION 'revision payload capacity' USING ERRCODE='54000'; END IF;
 SELECT jsonb_agg(to_jsonb(a) ORDER BY a.archive_row_id) INTO final_profile_rows FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=ANY(identities);
 catalog_after:='{}'::jsonb;
 FOREACH table_name IN ARRAY ARRAY['schema_head','schema_rev','schema_doc','type_def','prop_def','key_def','rel_def','relationship_lineage','rel_endpoint'] LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C"),''[]''::jsonb) FROM truss.%I t',table_name) INTO table_rows;
  catalog_after:=jsonb_set(catalog_after,ARRAY[table_name],table_rows);
 END LOOP;
 after_resources:=truss.runtime_select_catalog_report_resources(expected_writer,expected_ordinal,(op.effect_generation+1)::text,
  (SELECT encode(c.admission_profile_bytes,'hex') FROM truss.operation_configuration c
   WHERE c.original_writer_xid=op.original_writer_xid AND c.operation_ordinal=op.operation_ordinal));
 IF after_resources IS DISTINCT FROM before_resources THEN
  RAISE EXCEPTION 'original complete report resource final cut required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT after_graph FROM truss.runtime_collect_configured_catalog_graph();
 SELECT o.* INTO STRICT current_op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.operation_ordinal=op.operation_ordinal;
 IF current_op.effect_generation<>op.effect_generation+1
  OR catalog_after IS DISTINCT FROM catalog_before OR final_profile_rows IS DISTINCT FROM profile_rows
  OR (to_jsonb(current_op)-'effect_generation') IS DISTINCT FROM (to_jsonb(op)-'effect_generation')
  OR (to_jsonb(after_graph)-'effect_generation') IS DISTINCT FROM (to_jsonb(before_graph)-'effect_generation')
  OR NOT EXISTS(SELECT 1 FROM truss.installation_archive a WHERE a.archive_row_id=original_registration_id
    AND a.artifact_bytes=original_registration AND a.artifact_sha256=sha256(original_registration)) THEN
  RAISE EXCEPTION 'original candidate report final source cut required' USING ERRCODE='55000'; END IF;
 RETURN QUERY SELECT op.original_writer_xid::text,op.operation_ordinal::text,current_op.effect_generation::text,
  encode(original_report,'hex'),'administrative_rollback_only_report_write'::text,false,encode(revision_payload,'hex');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_write_catalog_report_wide_candidate(expected_writer text, expected_ordinal text, expected_generation text, registration_identity text, original_registration bytea, lifecycle_policy bytea, index_policy bytea)
 RETURNS TABLE(writer_xid text, operation_ordinal text, effect_generation text, report_utf8_hex text, scope text, accepted_report_qualified boolean, revision_payload_utf8_hex text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET bytea_output TO 'hex'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; current_op truss.row_home_operation%ROWTYPE;
 revision_row truss.schema_rev%ROWTYPE; revision_tree jsonb; revision_payload bytea; accepted_at_text text; report_identity text;
 context jsonb; input jsonb; registration jsonb; source record; before_graph record; after_graph record;
 revision int; documents jsonb; counts jsonb; lifecycle jsonb; indexes jsonb;
 origin jsonb; execution jsonb; execution_tree jsonb; origin_envelope jsonb; journal_envelope jsonb; fields jsonb; tree jsonb; members jsonb; assertion_tree jsonb;
 assertion_digest text; assertions jsonb; member jsonb; pin_name text; pin jsonb;
 original_report bytea; returned_report bytea; recipe_bytes bytea; recipe jsonb; artifact bytea; selected_artifact_identity text; profile_rows jsonb; final_profile_rows jsonb; identities text[]; catalog_before jsonb; catalog_after jsonb; table_name text; table_rows jsonb; schema_registry jsonb:='{}'::jsonb; schema_name text; schema_value jsonb; report_tree jsonb; before_resources jsonb; after_resources jsonb; original_registration_id bigint; count_rows bigint;
BEGIN
 IF expected_writer IS NULL OR expected_ordinal IS NULL OR expected_generation IS NULL
  OR registration_identity IS NULL OR octet_length(registration_identity) NOT BETWEEN 1 AND 4096
  OR original_registration IS NULL OR octet_length(original_registration) NOT BETWEEN 1 AND 65536 THEN
  RAISE EXCEPTION 'bounded original candidate registration required' USING ERRCODE='22023'; END IF;
 PERFORM truss.runtime_require_catalog_observation(expected_writer,expected_ordinal,expected_generation);
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.operation_ordinal::text=expected_ordinal
   AND o.phase='admitted' AND o.operation_kind='catalog-acceptance' FOR UPDATE;
 context:=convert_from(op.original_context_bytes,'UTF8')::jsonb;
 IF context->>'interfaceVersion' IS DISTINCT FROM 'truss-native-operation-context/0.4' THEN
  RAISE EXCEPTION 'original configured candidate context required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT before_graph FROM truss.runtime_collect_configured_catalog_graph();
 -- This registration is explicitly candidate-only. It is NOT one of the four
 -- original production authority sources, even when all profile pins match.
 PERFORM truss.runtime_require_unique_source_json(convert_from(original_registration,'UTF8')::json);
 registration:=convert_from(original_registration,'UTF8')::jsonb;
 IF jsonb_typeof(registration) IS DISTINCT FROM 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(registration))<>8
  OR NOT registration ?& ARRAY['interfaceVersion','scope','layoutProfile','reportProfile',
      'captureProfile','originMappingProfile','enforcementProfile','composition']
  OR registration->>'interfaceVersion' IS DISTINCT FROM 'truss-catalog-report-candidate-registration/0.1'
  OR registration->>'scope' IS DISTINCT FROM 'administrative_rollback_only_report_write' THEN
  RAISE EXCEPTION 'explicit administrative candidate registration required' USING ERRCODE='55000'; END IF;
 FOREACH pin_name IN ARRAY ARRAY['layoutProfile','reportProfile','captureProfile','originMappingProfile','enforcementProfile'] LOOP
  pin:=registration->pin_name;
  IF jsonb_typeof(pin) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(pin))<>3
   OR NOT pin ?& ARRAY['identity','version','sha256']
   OR EXISTS(SELECT 1 FROM jsonb_each(pin) e WHERE jsonb_typeof(e.value) IS DISTINCT FROM 'string' OR octet_length(e.value #>> '{}') NOT BETWEEN 1 AND 4096)
   OR pin->>'sha256' !~ '^[0-9a-f]{64}$' THEN
   RAISE EXCEPTION 'complete candidate profile pins required' USING ERRCODE='55000'; END IF;
 END LOOP;
 IF registration->'enforcementProfile' IS DISTINCT FROM jsonb_build_object(
  'identity','truss-catalog-enforcement-projection','version','0.1.0',
  'sha256','678e52ea00fa984b19162441a33b33ab3d822b58f8ae2c69195dc1d5d658c4b1') THEN
  RAISE EXCEPTION 'selected candidate enforcement projection required' USING ERRCODE='55000'; END IF;
 SELECT count(*) INTO count_rows FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input'
   AND convert_to(a.artifact_identity,'UTF8')=convert_to(registration_identity,'UTF8');
 IF count_rows<>1 THEN RAISE EXCEPTION 'unique original candidate registration archive required' USING ERRCODE='55000'; END IF;
 SELECT a.archive_row_id INTO STRICT original_registration_id FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input'
   AND convert_to(a.artifact_identity,'UTF8')=convert_to(registration_identity,'UTF8')
   AND a.artifact_bytes=original_registration AND a.artifact_sha256=sha256(original_registration)
   AND a.artifact_identity_sha256=sha256(convert_to(registration_identity,'UTF8')) FOR SHARE NOWAIT;
 IF registration->'composition' IS DISTINCT FROM jsonb_build_object('identity','packages/python/src/truss/_profiles/catalog-report-wide-composition-candidate.json','sha256','d77cf6b399774166da481f0f0e7850271243e8911175b2bb225f9a628d418aba') THEN
  RAISE EXCEPTION 'recognized full candidate composition recipe required' USING ERRCODE='55000'; END IF;
 identities:=ARRAY[registration_identity,'packages/python/src/truss/_profiles/catalog-report-wide-composition-candidate.json'];
 IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=context->>'installationId'
  AND a.artifact_role='input' AND a.artifact_identity='packages/python/src/truss/_profiles/catalog-report-wide-composition-candidate.json')<>1 THEN
  RAISE EXCEPTION 'unique original candidate recipe archive required' USING ERRCODE='55000'; END IF;
 SELECT a.artifact_bytes INTO STRICT recipe_bytes FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity='packages/python/src/truss/_profiles/catalog-report-wide-composition-candidate.json'
   AND a.artifact_sha256=sha256(a.artifact_bytes) AND a.artifact_sha256=decode('d77cf6b399774166da481f0f0e7850271243e8911175b2bb225f9a628d418aba','hex')
   AND a.artifact_identity_sha256=sha256(convert_to(a.artifact_identity,'UTF8')) FOR SHARE NOWAIT;
 recipe:=convert_from(recipe_bytes,'UTF8')::jsonb;
 FOREACH pin_name IN ARRAY ARRAY['reportProfile','captureProfile','originMappingProfile','enforcementProfile'] LOOP
  selected_artifact_identity:=recipe->'profileArtifacts'->pin_name->>'path';
  identities:=array_append(identities,selected_artifact_identity);
  IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=context->>'installationId'
    AND a.artifact_role='input' AND convert_to(a.artifact_identity,'UTF8')=convert_to(selected_artifact_identity,'UTF8'))<>1 THEN
   RAISE EXCEPTION 'unique full candidate profile archive required' USING ERRCODE='55000'; END IF;
  SELECT a.artifact_bytes INTO STRICT artifact FROM truss.installation_archive a
   WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input'
    AND convert_to(a.artifact_identity,'UTF8')=convert_to(selected_artifact_identity,'UTF8')
    AND a.artifact_sha256=sha256(a.artifact_bytes)
    AND a.artifact_sha256=decode(recipe->'profileArtifacts'->pin_name->>'sha256','hex')
    AND a.artifact_identity_sha256=sha256(convert_to(selected_artifact_identity,'UTF8')) FOR SHARE NOWAIT;
  pin:=convert_from(artifact,'UTF8')::jsonb;
  IF registration->pin_name IS DISTINCT FROM jsonb_build_object('identity',pin->>'identity','version',pin->>'version',
     'sha256',encode(sha256(artifact),'hex'))
   OR (pin_name='captureProfile' AND encode(artifact,'hex') IS DISTINCT FROM context->>'assertedOriginCaptureProfileHex') THEN
   RAISE EXCEPTION 'original full candidate profile correspondence required' USING ERRCODE='55000'; END IF;
 END LOOP;
 before_resources:=truss.runtime_select_catalog_report_resources(expected_writer,expected_ordinal,expected_generation,
  (SELECT encode(c.admission_profile_bytes,'hex') FROM truss.operation_configuration c
   WHERE c.original_writer_xid=op.original_writer_xid AND c.operation_ordinal=op.operation_ordinal));
 FOREACH schema_name IN ARRAY ARRAY['exact-value-v0.1.schema.json','history-record-v0.1.schema.json','history-event-v0.1.schema.json',
  'acceptance-input-v0.1.schema.json','acceptance-rejection-v0.1.schema.json','enforcement-report-v0.1.schema.json',
  'acceptance-report-v0.1.schema.json','history-retain-payload-v0.1.proposal.schema.json','history-event-v0.2.proposal.schema.json',
  'acceptance-report-v0.3.proposal.schema.json'] LOOP
  selected_artifact_identity:='packages/python/src/truss/_report_schemas/'||schema_name;
  SELECT convert_from(a.artifact_bytes,'UTF8')::jsonb INTO STRICT schema_value FROM truss.installation_archive a
   WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=selected_artifact_identity;
  IF schema_registry ? (schema_value->>'$id') THEN RAISE EXCEPTION 'unique selected report schema identity required' USING ERRCODE='55000'; END IF;
  schema_registry:=schema_registry||jsonb_build_object(schema_value->>'$id',schema_value);
  identities:=array_append(identities,selected_artifact_identity);
 END LOOP;
 -- The revision composition is independently selected source semantics, not authority.
 selected_artifact_identity:='packages/python/src/truss/_profiles/catalog-revision-wide-report-composition-candidate.json';
 IF (SELECT count(*) FROM truss.installation_archive a WHERE a.installation_id=context->>'installationId'
  AND a.artifact_role='input' AND a.artifact_identity=selected_artifact_identity)<>1 THEN
  RAISE EXCEPTION 'unique original revision composition archive required' USING ERRCODE='55000'; END IF;
 SELECT a.artifact_bytes INTO STRICT artifact FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=selected_artifact_identity
   AND a.artifact_sha256=sha256(a.artifact_bytes) AND a.artifact_sha256=decode('9269939c2151779c919826ef30beccfea51269f06da1d6241e8f6bb6d80e6253','hex')
   AND a.artifact_identity_sha256=sha256(convert_to(a.artifact_identity,'UTF8')) FOR SHARE NOWAIT;
 identities:=array_append(identities,selected_artifact_identity);
 SELECT jsonb_agg(to_jsonb(a) ORDER BY a.archive_row_id) INTO profile_rows FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=ANY(identities);
 catalog_before:='{}'::jsonb;
 FOREACH table_name IN ARRAY ARRAY['schema_head','schema_rev','schema_doc','type_def','prop_def','key_def','rel_def','relationship_lineage','rel_endpoint'] LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C"),''[]''::jsonb) FROM truss.%I t',table_name) INTO table_rows;
  catalog_before:=jsonb_set(catalog_before,ARRAY[table_name],table_rows);
 END LOOP;
 IF octet_length(catalog_before::text)>4194304 THEN RAISE EXCEPTION 'candidate catalog comparison capacity' USING ERRCODE='54000'; END IF;
 PERFORM truss.runtime_require_catalog_input(op.original_input_bytes);
 input:=convert_from(op.original_input_bytes,'UTF8')::jsonb;
 IF registration->'layoutProfile' IS DISTINCT FROM input->'layoutProfile' THEN
  RAISE EXCEPTION 'original input layout candidate correspondence required' USING ERRCODE='55000'; END IF;
 IF (SELECT count(*) FROM truss.schema_rev WHERE rev>0)<>1
  OR NOT EXISTS(SELECT 1 FROM truss.schema_head WHERE id=1 AND rev=0)
  OR EXISTS(SELECT 1 FROM truss.catalog_acceptance_report) THEN
  RAISE EXCEPTION 'unpublished first revision candidate required' USING ERRCODE='55000'; END IF;
 SELECT rev INTO STRICT revision FROM truss.schema_rev WHERE rev>0;
 SELECT * INTO STRICT source FROM truss.runtime_collect_catalog_source_candidate(
  op.admitted_candidate_bytes,decode(convert_from(op.admitted_candidate_bytes,'UTF8')::jsonb->>'declarationsUtf8Hex','hex'));
 PERFORM * FROM truss.runtime_collect_new_catalog_inventory(revision);
 SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.ord::int),'[]'::jsonb) INTO documents
  FROM truss.runtime_collect_report_documents(revision) d;
 SELECT to_jsonb(c) INTO STRICT counts FROM truss.runtime_collect_new_catalog_counts(revision) c;
 lifecycle:=truss.runtime_collect_fresh_catalog_lifecycle(expected_writer,expected_ordinal,expected_generation,revision,lifecycle_policy);
 indexes:=truss.runtime_collect_absent_binding_index_declarations(expected_writer,expected_ordinal,expected_generation,revision,index_policy);
 origin:=truss.runtime_catalog_report_original_tree(decode(context->>'assertedOriginUtf8Hex','hex'));
 execution:=jsonb_build_object('installationId',context->>'installationId','sourceEpoch',context->>'sourceEpoch',
  'origin',jsonb_build_object('databaseRole',context->>'actingUser'),
  'journalOrigin',jsonb_build_object('databaseRole',context->>'actingUser'),
  'originMappingProfile',registration->'originMappingProfile','captureProfile',registration->'captureProfile',
  'contextEvidence',jsonb_build_object('identity','truss.original-native-operation-context4/'||expected_writer||'/'||expected_ordinal,
   'bytesBase64',replace(encode(op.original_context_bytes,'base64'),chr(10),''),
   'sha256',encode(sha256(op.original_context_bytes),'hex')));
 execution_tree:=truss.runtime_catalog_report_native_tree(execution);
 origin_envelope:=truss.runtime_catalog_report_native_tree(jsonb_build_object('databaseRole',context->>'actingUser'));
 journal_envelope:=jsonb_set(origin_envelope,'{members}',origin_envelope->'members'||jsonb_build_array(jsonb_build_object(
  'keyUtf8Hex','6173736572746564','node',truss.runtime_catalog_report_map_origin_tree(origin))));
 origin_envelope:=jsonb_set(origin_envelope,'{members}',origin_envelope->'members'||jsonb_build_array(jsonb_build_object(
  'keyUtf8Hex','6173736572746564','node',origin)));
 SELECT jsonb_agg(CASE m->>'keyUtf8Hex' WHEN '6f726967696e' THEN jsonb_set(m,'{node}',origin_envelope)
  WHEN '6a6f75726e616c4f726967696e' THEN jsonb_set(m,'{node}',journal_envelope) ELSE m END)
  INTO members FROM jsonb_array_elements(execution_tree->'members') m;
 execution_tree:=jsonb_set(execution_tree,'{members}',members);
 fields:=jsonb_build_object('interfaceVersion','truss-acceptance-report/0.3.0-proposal',
  'reportProfile',registration->'reportProfile','rev',revision::text,
  'acceptedInput',input,'documents',documents,'counts',jsonb_build_object(
   'typesAdded',counts->'types_added','propertiesAdded',counts->'properties_added','keysAdded',counts->'keys_added',
   'relationshipsAdded',counts->'relationships_added','endpointsAdded',counts->'endpoints_added','elementsRetired',counts->'elements_retired'),
  'provisional','[]'::jsonb,'rebinds','[]'::jsonb,'pending_indexes',indexes->'declaredJobs',
  'lifecycleProfile',lifecycle->'lifecycleProfile','reactivations',lifecycle->'reactivations');
 tree:=truss.runtime_catalog_report_native_tree(fields); members:=tree->'members'||jsonb_build_array(jsonb_build_object('keyUtf8Hex','6f726967696e616c457865637574696f6e','node',execution_tree));
 FOR member IN SELECT value FROM jsonb_array_elements(source.host_sources->'members') LOOP
  IF member->>'keyUtf8Hex'=encode(convert_to('assertionEntries','UTF8'),'hex') THEN assertion_tree:=member->'node';
  ELSE members:=members||jsonb_build_array(member); END IF;
 END LOOP;
 IF assertion_tree IS NULL OR assertion_tree->>'kind' IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'original complete candidate assertion inventory required' USING ERRCODE='55000'; END IF;
 FOR member IN SELECT value FROM jsonb_array_elements(assertion_tree->'items') LOOP
  IF member->>'kind' IS DISTINCT FROM 'object' OR jsonb_typeof(member->'members') IS DISTINCT FROM 'array'
   OR jsonb_array_length(member->'members')<>6
   OR (SELECT count(*) FROM jsonb_array_elements(member->'members') m WHERE decode(m->>'keyUtf8Hex','hex')
    IN (convert_to('assertion','UTF8'),convert_to('source','UTF8'),convert_to('ruleName','UTF8'),convert_to('ruleNameOrigin','UTF8'),convert_to('enforcement','UTF8'),convert_to('reason','UTF8')))<>6
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(member->'members') m WHERE m->>'keyUtf8Hex'=encode(convert_to('enforcement','UTF8'),'hex')
    AND m->'node'=jsonb_build_object('kind','string','utf8Hex',encode(convert_to('none','UTF8'),'hex')))
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(member->'members') m WHERE m->>'keyUtf8Hex'=encode(convert_to('reason','UTF8'),'hex')
    AND m->'node'=jsonb_build_object('kind','string','utf8Hex',encode(convert_to('unqualified','UTF8'),'hex'))) THEN
   RAISE EXCEPTION 'selected six-field none unqualified assertion projection required' USING ERRCODE='55000'; END IF;
 END LOOP;
 assertion_digest:=encode(sha256(convert_to('truss-canonical/0.1.0'||chr(10)||'truss-catalog-assertion-inventory/0.1.0'||chr(10),'UTF8')
   ||truss.runtime_canonical_tree_bytes(assertion_tree)),'hex');
 assertions:=truss.runtime_catalog_report_native_tree(jsonb_build_object('interfaceVersion','truss-enforcement-report/0.1.0',
  'catalogRevision',revision::text,'reportProfile',registration->'enforcementProfile','layoutProfile',input->'layoutProfile',
  'scope',jsonb_build_object('kind','complete'),'assertionInventorySha256',assertion_digest));
 assertions:=jsonb_set(assertions,'{members}',assertions->'members'||jsonb_build_array(jsonb_build_object(
  'keyUtf8Hex',encode(convert_to('entries','UTF8'),'hex'),'node',assertion_tree)));
 members:=members||jsonb_build_array(jsonb_build_object('keyUtf8Hex',encode(convert_to('assertions','UTF8'),'hex'),'node',assertions));
 IF jsonb_array_length(members)<>19 THEN RAISE EXCEPTION 'complete nineteen-field candidate report required' USING ERRCODE='55000'; END IF;
 report_tree:=jsonb_build_object('kind','object','members',members);
 original_report:=truss.runtime_canonical_tree_bytes(report_tree);
 IF NOT truss.runtime_catalog_report_shape_matches(report_tree,schema_registry->'urn:truss:proposal:acceptance-report:0.3.0',
  schema_registry,'urn:truss:proposal:acceptance-report:0.3.0') THEN
  RAISE EXCEPTION 'complete selected candidate report shape required' USING ERRCODE='22023'; END IF;
 -- Only an administrative algorithm fixture calls this. No public assembly
 -- selection, accepted result, head transition or commit seal is issued here.
 INSERT INTO truss.catalog_acceptance_report(rev,report_bytes) VALUES(revision,original_report)
  RETURNING report_bytes INTO STRICT returned_report;
 IF returned_report IS DISTINCT FROM original_report OR NOT EXISTS(
  SELECT 1 FROM truss.catalog_acceptance_report r WHERE r.rev=revision AND r.report_bytes=original_report)
  OR (SELECT count(*) FROM truss.catalog_acceptance_report)<>1 THEN
  RAISE EXCEPTION 'original report insert and independent byte readback required' USING ERRCODE='55000'; END IF;
 -- Build the revision wire from the same retained originals, never a later
 -- caller-supplied report or a fresh acceptance clock.
 SELECT r.* INTO STRICT revision_row FROM truss.schema_rev r WHERE r.rev=revision;
 IF truss.runtime_canonical_tree_bytes(truss.runtime_catalog_report_native_tree(revision_row.origin))
  IS DISTINCT FROM truss.runtime_canonical_tree_bytes(origin) THEN
  RAISE EXCEPTION 'original revision parent origin correspondence required' USING ERRCODE='55000'; END IF;
 IF NOT isfinite(revision_row.accepted_at)
  OR extract(year FROM revision_row.accepted_at AT TIME ZONE 'UTC') NOT BETWEEN 1 AND 9999 THEN
  RAISE EXCEPTION 'finite selected revision acceptance timestamp required' USING ERRCODE='22023'; END IF;
 accepted_at_text:=to_char(revision_row.accepted_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
 report_identity:='truss.candidate.catalog-report/'||encode(convert_to(context->>'installationId','UTF8'),'hex')
  ||'/'||encode(convert_to(context->>'sourceEpoch','UTF8'),'hex')||'/'||revision::text;
 IF ((octet_length(original_report)::bigint+2)/3)*4>1048576 THEN
  RAISE EXCEPTION 'revision report artifact scalar capacity' USING ERRCODE='54000'; END IF;
 IF octet_length(original_report)>4194304 OR octet_length(op.original_input_bytes)>1048576
  OR ((octet_length(original_report)::bigint+2)/3)*4+octet_length(op.original_input_bytes)>4194304 THEN
  RAISE EXCEPTION 'revision wire expansion capacity' USING ERRCODE='54000'; END IF;
 revision_tree:=truss.runtime_catalog_report_native_tree(jsonb_build_object(
  'interfaceVersion','truss-feed-revision/0.1.0','revision',revision::text,'acceptedAt',accepted_at_text,
  'input',input,'report',jsonb_build_object('identity',report_identity,
   'bytesBase64',replace(encode(original_report,'base64'),chr(10),''),
   'sha256',encode(sha256(original_report),'hex'))));
 revision_tree:=jsonb_set(revision_tree,'{members}',revision_tree->'members'||jsonb_build_array(
  jsonb_build_object('keyUtf8Hex','6f726967696e','node',journal_envelope)));
 IF octet_length(revision_tree::text)>4194304 THEN
  RAISE EXCEPTION 'revision tagged tree capacity' USING ERRCODE='54000'; END IF;
 revision_payload:=truss.runtime_revision_report_tree_bytes_wide_candidate(revision_tree,original_report);
 IF octet_length(revision_payload)>4194304 THEN
  RAISE EXCEPTION 'revision payload capacity' USING ERRCODE='54000'; END IF;
 SELECT jsonb_agg(to_jsonb(a) ORDER BY a.archive_row_id) INTO final_profile_rows FROM truss.installation_archive a
  WHERE a.installation_id=context->>'installationId' AND a.artifact_role='input' AND a.artifact_identity=ANY(identities);
 catalog_after:='{}'::jsonb;
 FOREACH table_name IN ARRAY ARRAY['schema_head','schema_rev','schema_doc','type_def','prop_def','key_def','rel_def','relationship_lineage','rel_endpoint'] LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C"),''[]''::jsonb) FROM truss.%I t',table_name) INTO table_rows;
  catalog_after:=jsonb_set(catalog_after,ARRAY[table_name],table_rows);
 END LOOP;
 after_resources:=truss.runtime_select_catalog_report_resources(expected_writer,expected_ordinal,(op.effect_generation+1)::text,
  (SELECT encode(c.admission_profile_bytes,'hex') FROM truss.operation_configuration c
   WHERE c.original_writer_xid=op.original_writer_xid AND c.operation_ordinal=op.operation_ordinal));
 IF after_resources IS DISTINCT FROM before_resources THEN
  RAISE EXCEPTION 'original complete report resource final cut required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT after_graph FROM truss.runtime_collect_configured_catalog_graph();
 SELECT o.* INTO STRICT current_op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.operation_ordinal=op.operation_ordinal;
 IF current_op.effect_generation<>op.effect_generation+1
  OR catalog_after IS DISTINCT FROM catalog_before OR final_profile_rows IS DISTINCT FROM profile_rows
  OR (to_jsonb(current_op)-'effect_generation') IS DISTINCT FROM (to_jsonb(op)-'effect_generation')
  OR (to_jsonb(after_graph)-'effect_generation') IS DISTINCT FROM (to_jsonb(before_graph)-'effect_generation')
  OR NOT EXISTS(SELECT 1 FROM truss.installation_archive a WHERE a.archive_row_id=original_registration_id
    AND a.artifact_bytes=original_registration AND a.artifact_sha256=sha256(original_registration)) THEN
  RAISE EXCEPTION 'original candidate report final source cut required' USING ERRCODE='55000'; END IF;
 RETURN QUERY SELECT op.original_writer_xid::text,op.operation_ordinal::text,current_op.effect_generation::text,
  encode(original_report,'hex'),'administrative_rollback_only_report_write'::text,false,encode(revision_payload,'hex');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_write_custody_catalog_report_candidate(expected_writer text, expected_ordinal text, expected_generation text, registration_identity text, original_registration bytea, lifecycle_policy bytea, index_policy bytea)
 RETURNS TABLE(writer_xid text, operation_ordinal text, effect_generation text, report_utf8_hex text, scope text, accepted_report_qualified boolean, revision_payload_utf8_hex text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET bytea_output TO 'hex'
AS $function$
DECLARE op truss.row_home_operation%ROWTYPE; current_op truss.row_home_operation%ROWTYPE;
 revision_row truss.schema_rev%ROWTYPE; revision_tree jsonb; revision_payload bytea; accepted_at_text text; report_identity text;
 context jsonb; input jsonb; registration jsonb; source record; before_graph record; after_graph record;
 revision int; documents jsonb; counts jsonb; lifecycle jsonb; indexes jsonb;
 origin jsonb; execution jsonb; execution_tree jsonb; origin_envelope jsonb; journal_envelope jsonb; fields jsonb; tree jsonb; members jsonb; assertion_tree jsonb;
 assertion_digest text; assertions jsonb; member jsonb; pin_name text; pin jsonb;
 original_report bytea; returned_report bytea; recipe_bytes bytea; recipe jsonb; artifact bytea; selected_artifact_identity text; profile_rows jsonb; final_profile_rows jsonb; identities text[]; catalog_before jsonb; catalog_after jsonb; table_name text; table_rows jsonb; schema_registry jsonb:='{}'::jsonb; schema_name text; schema_value jsonb; report_tree jsonb; before_resources jsonb; after_resources jsonb; original_registration_id bigint; count_rows bigint;
BEGIN
 IF expected_writer IS NULL OR expected_ordinal IS NULL OR expected_generation IS NULL
  OR registration_identity IS NULL OR octet_length(registration_identity) NOT BETWEEN 1 AND 4096
  OR original_registration IS NULL OR octet_length(original_registration) NOT BETWEEN 1 AND 65536 THEN
  RAISE EXCEPTION 'bounded original candidate registration required' USING ERRCODE='22023'; END IF;
 PERFORM truss.runtime_require_catalog_observation(expected_writer,expected_ordinal,expected_generation);
 SELECT o.* INTO STRICT op FROM truss.row_home_operation o
  WHERE o.original_writer_xid=pg_current_xact_id_if_assigned() AND o.operation_ordinal::text=expected_ordinal
   AND o.phase='admitted' AND o.operation_kind='catalog-acceptance' FOR UPDATE;
 context:=convert_from(op.original_context_bytes,'UTF8')::jsonb;
 IF context->>'interfaceVersion' IS DISTINCT FROM 'truss-native-operation-context/0.4' THEN
  RAISE EXCEPTION 'original configured candidate context required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT before_graph FROM truss.runtime_collect_custody_catalog_graph_candidate();
 -- This registration is explicitly candidate-only. It is NOT one of the four
 -- original production authority sources, even when all profile pins match.
 PERFORM truss.runtime_require_unique_source_json(convert_from(original_registration,'UTF8')::json);
 registration:=convert_from(original_registration,'UTF8')::jsonb;
 IF jsonb_typeof(registration) IS DISTINCT FROM 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(registration))<>8
  OR NOT registration ?& ARRAY['interfaceVersion','scope','layoutProfile','reportProfile',
      'captureProfile','originMappingProfile','enforcementProfile','composition']
  OR registration->>'interfaceVersion' IS DISTINCT FROM 'truss-catalog-report-candidate-registration/0.1'
  OR registration->>'scope' IS DISTINCT FROM 'administrative_rollback_only_report_write' THEN
  RAISE EXCEPTION 'explicit administrative candidate registration required' USING ERRCODE='55000'; END IF;
 FOREACH pin_name IN ARRAY ARRAY['layoutProfile','reportProfile','captureProfile','originMappingProfile','enforcementProfile'] LOOP
  pin:=registration->pin_name;
  IF jsonb_typeof(pin) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(pin))<>3
   OR NOT pin ?& ARRAY['identity','version','sha256']
   OR EXISTS(SELECT 1 FROM jsonb_each(pin) e WHERE jsonb_typeof(e.value) IS DISTINCT FROM 'string' OR octet_length(e.value #>> '{}') NOT BETWEEN 1 AND 4096)
   OR pin->>'sha256' !~ '^[0-9a-f]{64}$' THEN
   RAISE EXCEPTION 'complete candidate profile pins required' USING ERRCODE='55000'; END IF;
 END LOOP;
 IF registration->'enforcementProfile' IS DISTINCT FROM jsonb_build_object(
  'identity','truss-catalog-enforcement-projection','version','0.1.0',
  'sha256','678e52ea00fa984b19162441a33b33ab3d822b58f8ae2c69195dc1d5d658c4b1') THEN
